local _, addonTable = ...
addonTable.gossip_hashed = addonTable.gossip_hashed or { version = 1, rows = {} }
local rows = {
    [1765777794] = {
        ["english"] = { [1] = "Are ye really askin' me where the Blacksmith is?  Have ye not heard of The Great Forge!?  All our best blacksmiths gather there to craft their weapons and armor!  \010\010It's dead smack in the middle of Ironforge, and that's where you'll find one of our most brilliant blacksmiths, Bengus Deepforge.  " },
        ["text"] = "Ти справді питаєш мене, де коваль? Невже не чув про Велику Кузню!? Там збираються всі наші найкращі ковалі, щоб кувати зброю й обладунки!  \010\010Вона просто в самому центрі Стальгорна, і там ти знайдеш одного з найвидатніших наших ковалів — Бенґуса Глибококовача.  ",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1463998933] = {
        ["english"] = { [1] = "Butcher you say?  Oh, First Aid Trainer!  Same thing.  When you see Nurse Neela standing just inside the Gallows' End Tavern on the southeast side of town you'll know why." },
        ["text"] = "М'ясник, кажеш? А, наставник першої допомоги! Те саме. Коли побачиш медсестру Нілу одразу всередині таверни «Кінець Шибеника» на південно-східному боці містечка, зрозумієш чому.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3679849670] = {
        ["english"] = { [1] = "Alas, only the esteemed champions of Silvermoon City may purchase what I have to offer." },
        ["text"] = "На жаль, лише шановані чемпіони Срібномісяця можуть купувати мої товари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1894569409] = {
        ["english"] = { [1] = "$N, you are ready for the ultimate task.  The fiery runes etched on the floor of the molten core are conduits to the realm of fire, and their presence is both an affront to us and a source of power for the Firelords.  They must be extinguished!$B$BTo extinguish a rune, take a vial of aqual quintessence.  Pour it on the rune and its flame will go out, rendering it useless and weakening our enemy!" },
        ["text"] = "$N, ти готовий до найважливішого завдання. Вогняні руни, викарбувані на підлозі Вогняних Надр, — це провідники до царства вогню. Їхня присутність є для нас образою й водночас джерелом сили для Володарів вогню. Їх треба погасити!$B$BЩоб погасити руну, візьми флакон водної квінтесенції. Вилий її на руну — полум'я згасне, руна стане марною, а наш ворог ослабне!",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["greeting"] = true },
    },
    [2775365249] = {
        ["english"] = { [1] = "Can you give me directions?" },
        ["text"] = "Підкажеш дорогу?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3041319677] = {
        ["english"] = { [1] = "Bow" },
        ["text"] = "Лук",
        ["npcs"] = { [1] = 11865, [2] = 11867, [3] = 11869, [4] = 11870, [5] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [1086977409] = {
        ["english"] = { [1] = "$N, it is good to see you again.$B$BRemember to stay focused on your learning.  You represent our future, and should you falter our future will be dark indeed." },
        ["text"] = "$N, радий знову тебе бачити.$B$BНе втрачай зосередженості в навчанні. Ти — наше майбутнє, і якщо оступишся, воно справді стане похмурим.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4246054607] = {
        ["english"] = { [1] = "A budding herbalist are we?  Then you should visit with Firodren Mooncaller over in the Temple Gardens.  He may have some tricks of the trade to impart with you." },
        ["text"] = "Початківець-травник, еге ж? Тоді навідайся до Фіродрена Місячного Закликача в Храмових садах. Можливо, він навчить тебе кількох хитрощів ремесла.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1457786268] = {
        ["english"] = { [1] = "A Cooking trainer is it?  Well then, get yerself over to the Bronze Kettle on the northeastern side of The Great Forge.  Daryl Riknussun will teach ye to make a mighty fine dish that's sure to put the life back in ye!" },
        ["text"] = "Шукаєш наставника кулінарії? Тоді мерщій до Бронзового Казана на північно-східному боці Великої Кузні. Деріл Рікнуссун навчить тебе готувати чудову страву, що неодмінно поверне сили!",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2006225776] = {
        ["english"] = { [1] = "\"Great job collecting resources for the war,\" they said, \"Have a promotion,\" they said.  What they really meant is \"You're stationed outside a bughive in Silithus with a bunch of sweaty dwarves, Carnes!\"$B$BThanks for the promotion, Captain!" },
        ["text"] = "\"Чудова робота зі збору припасів для війни\", — казали вони. \"Ось тобі підвищення\", — казали вони. А насправді це означало: \"Тебе поставили біля лігва жуків у Силітусі з купою спітнілих дворфів, Карнесе!\"$B$BДякую за підвищення, капітане!",
        ["npcs"] = { [1] = 15903 },
        ["roles"] = { ["greeting"] = true },
    },
    [1246989960] = {
        ["english"] = { [1] = "[In broken Common] Stillpine be ready! Many thanks!" },
        ["text"] = "[Ламаною повселюдною] Тихохвойні готові! Велика дяка!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4063879795] = {
        ["english"] = { [1] = "Darling, those shoes are to die for!  I mean that literally.  Who did you kill for them?" },
        ["text"] = "Любчику, заради таких черевичків можна й померти! Я буквально. Кого ти за них убив?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2869464893] = {
        ["english"] = { [1] = "Anything else I should know about the Earthen?" },
        ["text"] = "Щось іще мені варто знати про земельників?",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [1468987101] = {
        ["english"] = { [1] = "Ah, here's the $g hero : heroine; of the hour now! Good to see you again, $N! I trust that you're still destroying the Scourge wherever you find them?" },
        ["text"] = "А ось і $g герой : героїня; дня! Радий знову тебе бачити, $N! Сподіваюся, ти й досі винищуєш Скверну скрізь, де її зустрінеш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1665994397] = {
        ["english"] = { [1] = "<Overlord Mor'ghor salutes.>" },
        ["text"] = "<Повелитель Мор'ґор віддає честь.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2041588848] = {
        ["english"] = { [1] = "300? So the Dark Irons killed him and dragged him into the Depths?" },
        ["text"] = "300? То Темне Залізо вбило його й затягло в Надра?",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [3829103347] = {
        ["english"] = { [1] = "After all these years of fighting, now everyone's falling in love!" },
        ["text"] = "Після стількох років війни тепер усі раптом закохуються!",
        ["npcs"] = { [1] = 5610, [2] = 9317 },
        ["roles"] = { ["greeting"] = true },
    },
    [461420084] = {
        ["english"] = { [1] = "Anywhere but here..." },
        ["text"] = "Куди завгодно, аби не тут...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3003532119] = {
        ["english"] = { [1] = "Aye $g lad : lass; are ye ready to head to Alterac Valley and give the Horde a taste o' what they been asking for?" },
        ["text"] = "Так, $g хлопче : дівчино;, готовий вирушити до Альтерацької долини й дати Орді скуштувати те, чого вони так добивалися?",
        ["npcs"] = { [1] = 5118 },
        ["roles"] = { ["greeting"] = true },
    },
    [2026454591] = {
        ["english"] = { [1] = "Da spirits be strong wit you, mon. What kin dis troll do for ya?" },
        ["text"] = "Нехай духи будуть дужі з тобою, друже. Чим цей троль може тобі помогти?",
        ["npcs"] = { [1] = 3403 },
        ["roles"] = { ["greeting"] = true },
    },
    [856940532] = {
        ["english"] = { [1] = "All is not lost, Kharan!" },
        ["text"] = "Ще не все втрачено, Харане!",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [237090512] = {
        ["english"] = { [1] = "And find it he did. After quickly advancing through the ranks of the Cult, the Lich King himself granted Ras immortality. Thus was born Ras Frostwhisper, the lich.$B$BNow do you understand?" },
        ["text"] = "І він таки знайшов його. Швидко піднявшись у лавах Культу, Рас отримав безсмертя від самого Короля-ліча. Так народився Рас Крижешепіт, ліч.$B$BТепер розумієш?",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [3644587914] = {
        ["english"] = { [1] = "<Sergeant Stormpike salutes.>$B$BName, rank, and serial number, soldier! That's the only bit of information you'll ever give those dirty Frostwolf dogs!" },
        ["text"] = "<Сержант Грозової Вершини віддає честь.>$B$BІм'я, звання й особистий номер, солдате! Це єдине, що ти коли-небудь скажеш тим брудним псам Морозного Вовка!",
        ["npcs"] = { [1] = 13777 },
        ["roles"] = { ["greeting"] = true },
    },
    [1607905400] = {
        ["english"] = { [1] = "Because you've managed to replenish some of our supplies I can get back to cooking.  Now, what can I do for you?" },
        ["text"] = "Оскільки ти поповнив частину наших запасів, я можу знову готувати. То чим допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2517430149] = {
        ["english"] = { [1] = "Blacksmith?  Nope, our last one turned back into one of those mindless Scourge.  There's one in the Undercity though to the south of town though.  Undercity is underneath the Ruins of Lordaeron, clever name, huh?  Just take the elevators down at the back of the ruins and then you can talk to one of the Undercity Guardians.  They should be able to point you in the right direction." },
        ["text"] = "Коваль? Ні, наш останній знову став одним із тих бездумних Скверни. Але є коваль у Підмісті на південь звідси. Підмісто розташоване під руїнами Лордерону — кмітлива назва, еге ж? Просто спустися ліфтами в задній частині руїн, а там поговори з кимось із вартових Підміста. Вони покажуть потрібний напрямок.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1468022429] = {
        ["english"] = { [1] = "<Copy the schematic into your engineering notebook.>" },
        ["text"] = "<Перемалюйте схему до свого інженерного записника.>",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3711704904] = {
        ["english"] = { [1] = "Chapter on Frostwhisper's Embalming Fluid." },
        ["text"] = "Розділ про бальзамувальну рідину Морозошепота.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [185077109] = {
        ["english"] = { [1] = "As you approach the console the access crystal you have with you begins to hum softly and pulse with light.$B$BA rush of information flows into your mind and all of a sudden you're aware of the manaforge's energy production levels, its stability and its output to different pipelines.  The console awaits your command." },
        ["text"] = "Коли ви наближаєтеся до консолі, кристал доступу при вас починає тихо гудіти й пульсувати світлом.$B$BПотік інформації вливається у ваш розум, і раптом ви усвідомлюєте рівень виробництва енергії манакузні, її стабільність та обсяги подачі в різні трубопроводи. Консоль чекає вашої команди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2398031733] = {
        ["english"] = { [1] = "A true professional know his limitations, and I'm not ashamed to admit that your skills exceed mine. I want you to pay a visit to Kitta Firewind at the Tower of Azora. She is well-renowned, and with good reason." },
        ["text"] = "Справжній професіонал знає свої межі, і мені не соромно визнати, що твої навички перевершили мої. Навідайся до Кітти Вогневіт у Вежі Азори. Вона має чудову славу — і недаремно.",
        ["npcs"] = { [1] = 1317 },
        ["roles"] = { ["greeting"] = true },
    },
    [3578643300] = {
        ["english"] = { [1] = "$N!  I hardly recognized you in your new outfit.  Still have that tunic... or did you take the chausses... or was it the staff?   I can't recall, it was so long ago...$B$BWell, I'm glad you are here to help out again.  We could use all the help we can get.  $N, if you perform the way you did back in Westfall with the People's Militia, we have a chance.$B$BThese are dire times, if we don't win this battle, there may not be a Westfall to return to." },
        ["text"] = "$N! Я ледве впізнав тебе в новому вбранні. Ти ще маєш ту туніку... чи взяв поножі... а може, посох? Уже й не згадаю, стільки часу минуло...$B$BТа я радий, що ти знову тут і готовий допомагати. Нам справді потрібна кожна пара рук. $N, якщо ти покажеш себе так само, як колись у Західному краї з Народним ополченням, у нас є шанс.$B$BЧаси тяжкі. Якщо ми не виграємо цю битву, може статися, що повертатися до Західного краю вже не буде куди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2101108035] = {
        ["english"] = { [1] = "$966w Frostwolf Commander(s) and $964w Frostwolf Lieutenant(s), soldier." },
        ["text"] = "$966w командир(ів) Морозного Вовка та $964w лейтенант(ів) Морозного Вовка, солдате.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3739224638] = {
        ["english"] = { [1] = "Ah, mistletoe..." },
        ["text"] = "А, омела...",
        ["npcs"] = { [1] = 15760 },
        ["roles"] = { ["greeting"] = true },
    },
    [363497526] = {
        ["english"] = { [1] = "Cooking" },
        ["text"] = "Кулінарія",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [2909971633] = {
        ["english"] = { [1] = "Bonelashers, I hate them all!$B$BIf it weren't for the loss of my eye, and the fainting spells that I get sometimes, I'd be out there shooting them down all the time!" },
        ["text"] = "Костекрилів ненавиджу всіх до одного!$B$BЯкби не втрачене око й ці напади непритомності, я б постійно був там і збивав їх!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [260554061] = {
        ["english"] = { [1] = "Course I can show ye where Myolor is. Right over there near the anvil of the Great Forge, that's where he does his work. Listen to his words well $g lad:lass;, Myolor is as skilled as they come." },
        ["text"] = "Авжеж, покажу тобі, де Майолор. Он там, біля ковадла Великої кузні, він і працює. Слухай його уважно, $g хлопче:дівчино;, бо вправнішого за Майолора ще пошукати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3779971756] = {
        ["english"] = { [1] = "Agamath, the First Gate is breached and two of Kil'jaeden's lieutenants, Lady Sacrolash and Grand Warlock Alythess, must be destroyed.$B$BGather your friends, $c, and see to it! Rohendor, the Second Gate is our next target." },
        ["text"] = "Аґамат, Першу Браму, прорвано, і двох лейтенанток Кіл'джедена — леді Сакролаш та велику чорнокнижницю Алітесс — треба знищити.$B$BЗбери друзів, $c, і зроби це! Рогендор, Друга Брама, — наша наступна ціль.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [744082175] = {
        ["english"] = { [1] = "Acquire Higher Level Access Card" },
        ["text"] = "Отримати картку доступу вищого рівня",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [655258156] = {
        ["english"] = { [1] = "<Andorov looks at you grimly.>$B$BIf it bleeds, we can kill it." },
        ["text"] = "<Андоров похмуро дивиться на вас.>$B$BЯкщо воно кровоточить, ми можемо його вбити.",
        ["npcs"] = { [1] = 15471 },
        ["roles"] = { ["greeting"] = true },
    },
    [838554182] = {
        ["english"] = { [1] = "Alanna spends most of her day at the Oracle Glade where she practices her profession.  Should you wish to learn the Enchanter's profession you will need to go there to find her." },
        ["text"] = "Аланна більшу частину дня проводить у Галявині Оракула, де практикує своє ремесло. Якщо хочеш опанувати зачарування, доведеться йти туди й шукати її.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1468795821] = {
        ["english"] = { [1] = "Do you really want to bribe Olga?" },
        ["text"] = "Ти справді хочеш підкупити Ольгу?",
        ["npcs"] = {},
        ["roles"] = { ["box"] = true },
    },
    [4064212315] = {
        ["english"] = { [1] = "A very good question, $c. When last I had heard, the Alliance had managed to smelt $1997w out of $1998w copper bars, $2002w out of $2003w iron bars and $2011w out of $2012w thorium bars needed for the war effort." },
        ["text"] = "Дуже слушне запитання, $c. Востаннє я чув, що Альянс уже виплавив $1997w із потрібних $1998w мідних зливків, $2002w із $2003w залізних зливків і $2011w із $2012w торієвих зливків для воєнних потреб.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1909031618] = {
        ["english"] = { [1] = "As the toxins lurking within Maraudon seeped into my mind, I began to lose my grip on reality. Worried that it would be used for evil, my dryad sisters secretly took the scepter from me, breaking it into two parts and hiding it within the caverns.$B$BSoon they fell victim to the madness as well, and the two parts of the scepter, left unguarded, came to be in the possession of Vyletongue, himself. The satyr entrusted one part to Noxxion, an evil elemental, and the other he still has to this day." },
        ["text"] = "Коли токсини, що ховаються в Мародоні, просочилися в мій розум, я почав втрачати зв'язок із реальністю. Боячись, що скіпетр використають для зла, мої сестри-дріади таємно забрали його в мене, розламали надвоє й сховали в печерах.$B$BНевдовзі й вони стали жертвами божевілля, а дві частини скіпетра, залишені без нагляду, потрапили до рук самого Поганоязика. Сатир довірив одну частину Ноксіону, злому елементалю, а іншу досі тримає при собі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3679903953] = {
        ["english"] = { [1] = "<The arakkoa favors you with a haunted gaze and alternates between looking at you and looking through you.>$B$BWhat have our efforts wrought, but a greater abomination than we sought to prevent?" },
        ["text"] = "<Араккоа дивиться на вас примарним поглядом, то вдивляючись у вас, то наче крізь вас.>$B$BЩо породили наші зусилля, як не ще більшу потвору за ту, якій ми намагалися запобігти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [178473599] = {
        ["english"] = { [1] = "Bears are beautiful creatures.  Wild, strong and fierce in battle... much like us, sister." },
        ["text"] = "Ведмеді — прекрасні створіння. Дикі, сильні й люті в бою... дуже схожі на нас, сестро.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2628659948] = {
        ["english"] = { [1] = "$N, it's good to see veterans like you in the field!  I'm sorry to report that our supplies are currently too low to launch any large ground assaults against the Horde.$B$BSpeak with our quartermaster; he has supply missions available." },
        ["text"] = "$N, приємно бачити в бою таких ветеранів, як ти! На жаль, зараз у нас надто мало припасів, щоб розпочати великий наземний наступ проти Орди.$B$BПоговори з нашим квартирмейстером — у нього є завдання зі збору припасів.",
        ["npcs"] = { [1] = 13447 },
        ["roles"] = { ["greeting"] = true },
    },
    [3480309381] = {
        ["english"] = { [1] = "Do it... Do it now." },
        ["text"] = "Зроби це... Зроби зараз.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [3625168342] = {
        ["english"] = { [1] = "Come to train with the Theramore guard have you?" },
        ["text"] = "Прийшов тренуватися з вартою Терамора?",
        ["npcs"] = { [1] = 8141 },
        ["roles"] = { ["greeting"] = true },
    },
    [2589984413] = {
        ["english"] = { [1] = "Amazing to see little flowers persist in the cold of Dun Morogh...  but ye won't find any herbalists out here.  Ye'll have to go to Ironforge to get some training in that profession." },
        ["text"] = "Дивовижно, що ці маленькі квіти виживають у холоді Дун-Морога... але травників тут не знайдеш. За навчанням цієї професії доведеться йти до Стальгорна.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [331853088] = {
        ["english"] = { [1] = "Another supplicant seeking the favors of da Lich King?$b$bOnly da worthy be obtainin' da dark gifts...." },
        ["text"] = "Ще один прохач шукає ласки Короля-ліча?$b$bТемні дари отримують лише гідні...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [418160530] = {
        ["english"] = { [1] = "Ahhhhggg... this pain in my head is killing me.$B$BThey must've sent you to rescue me.  Took them long enough!  Do you have any idea of the things they do to prisoners here?" },
        ["text"] = "А-а-а-а... цей біль у голові мене вбиває.$B$BТебе, мабуть, прислали мене рятувати. Дочекалися! Ти хоч уявляєш, що вони тут роблять із полоненими?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3570280304] = {
        ["english"] = { [1] = "Buliwyf, the dwarven weapon master at the Timberline Arms in Ironforge, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.\010\010Bixi Wobblebonk, the gnome weapon master at the Timberline Arms in Ironforge, teaches crossbow, daggers and throwing weapons.\010\010Woo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff." },
        ["text"] = "Булівіф, дворф-майстер зброї в крамниці «Лісовий край» у Стальгорні, навчає кулачної зброї, рушниць, одноручних і дворучних сокир та одноручних і дворучних булав.\010\010Біксі Хитрокіст, гномка-майстриня зброї в «Лісовому краї» у Стальгорні, навчає арбалетів, кинджалів і метальної зброї.\010\010Ву Пін, людський майстер зброї в Арсеналі Веллера у Штормовії, навчає арбалетів, кинджалів, одноручних і дворучних мечів, древкової зброї та посохів.",
        ["npcs"] = { [1] = 11866 },
        ["roles"] = { ["greeting"] = true },
    },
    [1732910925] = {
        ["english"] = { [1] = "<The orc wolf's frozen, snarling mouth shivers your bones.>" },
        ["text"] = "<Замерзла в оскалі паща орчого вовка пробирає вас до кісток.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2340809239] = {
        ["english"] = { [1] = "Anya Maulray at inn on upper ring of Trade Quarter." },
        ["text"] = "Аня Молрей у таверні на верхньому кільці Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2822284190] = {
        ["english"] = { [1] = "Ah, Braenna Flintcrag.  She has magic hands, that one.  Braenna is the one to see about Priestly matters.  \010\010Ye'll want to travel north from the gates of Ironforge to the Hall of Mysteries.  That's where ye'll find her." },
        ["text"] = "А, Бренна Кремнескеля. У неї чарівні руки. Саме до Бренни треба звертатися з жрецьких справ.  \010\010Іди на північ від брами Стальгорна до Зали Таємниць. Там її й знайдеш.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2261323498] = {
        ["english"] = { [1] = "Do you need something, $c?  Perhaps I can assist you." },
        ["text"] = "Тобі щось потрібно, $c? Можливо, я зможу допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1291365715] = {
        ["english"] = { [1] = "All of our collections are completed, $c. That which we have assembled is in the process of being transported to Cenarion Hold in Silithus, and the last of it should take no more than a day to arrive. The Ahn'Qiraj War can then start once that is done and someone brave and foolish rings the gong right outside of the gates down there." },
        ["text"] = "Усі наші збори завершено, $c. Зібране перевозять до Кенарієвої цитаделі в Силітусі, й остання партія прибуде не пізніше ніж за день. Після цього війна за Ан'Кіраж почнеться, щойно хтось хоробрий і безрозсудний ударить у гонг просто біля брам.",
        ["npcs"] = { [1] = 15525 },
        ["roles"] = { ["greeting"] = true },
    },
    [2712426332] = {
        ["english"] = { [1] = "Do you mock me while I am unable to defend myself, bound to this ball of iron?" },
        ["text"] = "Ти глузуєш із мене, поки я не можу захиститися, прикутий до цієї залізної кулі?",
        ["npcs"] = { [1] = 2239 },
        ["roles"] = { ["greeting"] = true },
    },
    [1308150078] = {
        ["english"] = { [1] = "Bow in my presence, insect! Surely you can feel the power I hold over you." },
        ["text"] = "Схилися переді мною, комахо! Ти ж відчуваєш владу, яку я маю над тобою.",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["greeting"] = true },
    },
    [2378691110] = {
        ["english"] = { [1] = "But his son is dead." },
        ["text"] = "Але його син мертвий.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [1180999696] = {
        ["english"] = { [1] = "Bluegill Marsh north of Menethil Harbor in the Wetlands holds many locked boxes from the wrecks offshore that have washed ashore." },
        ["text"] = "У Синьожабровому болоті на північ від гавані Менетілів у Заболотті на берег винесло багато замкнених скринь із кораблетрощ неподалік.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4200870813] = {
        ["english"] = { [1] = "<The image's head blurs as it turns to take in its surroundings.>$B$BIf you had seen the Plains of Farahlon, you wouldn't believe this is the same place. Mere months ago, these fields would not have looked out of place in Westfall.$B$BAll that is gone now, but how and why?" },
        ["text"] = "<Голова зображення розмивається, коли воно озирається навколо.>$B$BЯкби ти бачив Рівнини Фаралону, то не повірив би, що це те саме місце. Ще кілька місяців тому ці поля цілком могли б бути частиною Західного краю.$B$BТепер усе це зникло. Але як і чому?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2777533063] = {
        ["english"] = { [1] = "Are ye sure, $g lad:lass;? Ye don't need another minute or two?" },
        ["text"] = "Ти певен, $g хлопче:дівчино;? Не хочеш іще хвилинку-другу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1523722781] = {
        ["english"] = { [1] = "<Angela coos to the felhunter again before turning her attention to you.>$B$BJir'see's always been smaller than all the other felhunters, but that's never bothered him. And Outland's going to change all that, right Jir'see?$B$BMomma's little angel is going to grow up to be a big, fierce felhunter, yes he is!" },
        ["text"] = "<Анжела знову воркує з гонча́ком Скверни, а тоді переводить погляд на вас.>$B$BДжір'сі завжди був меншим за інших гончаків Скверни, але його це ніколи не турбувало. А Позамежжя все змінить, правда ж, Джір'сі?$B$BМамин янголятко виросте великим і лютим гончаком Скверни, еге ж!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1606665576] = {
        ["english"] = { [1] = "And that's where we find ourselves now, $N.$B$BWe can't possibly deal with all of this by ourselves, and quite frankly, I feel a little out of my depth. Jinky knows what needs to be done. You should go see her now.$B$BI just hope you'll be able to get us out of this mess with our bodies intact." },
        ["text"] = "І ось де ми опинилися, $N.$B$BСамотужки нам із цим не впоратися, і, якщо чесно, я почуваюся не у своїй стихії. Джінкі знає, що робити. Тобі слід негайно піти до неї.$B$BСподіваюся лише, що ти витягнеш нас із цієї халепи цілими.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1522736982] = {
        ["english"] = { [1] = "Any friend of the animals is a friend of mine.  The Hunter's Hall is what you seek.  It sits atop the Hunter Rise." },
        ["text"] = "Друг тварин — мій друг. Тобі потрібна Зала Мисливців. Вона на Верхів'ї Мисливців.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3619934198] = {
        ["english"] = { [1] = "Do you like fish, $r? I have fish here. If you like fresh fish, the freshest, come and sample my wares." },
        ["text"] = "Любиш рибу, $r? У мене є риба. Якщо любиш свіжу рибу — найсвіжішу — підходь і скуштуй мого краму.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3807933450] = {
        ["english"] = { [1] = "Because you have aided me, I will tell you what I know of this land and of the things there are to see. My knowledge is not vast, but perhaps I can point out some things that might interest one such as yourself." },
        ["text"] = "Оскільки ти допоміг мені, я розповім, що знаю про цю землю й цікаві місця тут. Мої знання не безмежні, але, можливо, зможу вказати на щось, що зацікавить такого, як ти.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [3675410408] = {
        ["english"] = { [1] = "Darianna shows promise, but she is so full of energy that it is hard for her to stay still and listen. With her strength and agility, I fear it won't be long before she is called to fight. We must teach her quickly." },
        ["text"] = "Даріанна подає великі надії, але в ній стільки енергії, що їй важко всидіти на місці й слухати. З її силою та спритністю, боюся, недовго лишилося до того, як її покличуть до бою. Треба навчити її якнайшвидше.",
        ["npcs"] = { [1] = 11081 },
        ["roles"] = { ["greeting"] = true },
    },
    [1674448615] = {
        ["english"] = { [1] = "Do you know where I may find the Half Pendant of Aquatic Endurance?" },
        ["text"] = "Ти знаєш, де знайти половину Підвіски водної витривалості?",
        ["npcs"] = { [1] = 11798 },
        ["roles"] = { ["reply"] = true },
    },
    [4151544631] = {
        ["english"] = { [1] = "Do you know where I may find the Half Pendant of Aquatic Agility?" },
        ["text"] = "Ти знаєш, де знайти половину Підвіски водної спритності?",
        ["npcs"] = { [1] = 11800 },
        ["roles"] = { ["reply"] = true },
    },
    [2860755145] = {
        ["english"] = { [1] = "Continue please..." },
        ["text"] = "Продовжуй, будь ласка...",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["reply"] = true },
    },
    [1010206145] = {
        ["english"] = { [1] = "Do you know someone... or something, rather, by the name of Eranikus?" },
        ["text"] = "Ти знаєш когось... чи, радше, щось на ім'я Еранікус?",
        ["npcs"] = { [1] = 5353 },
        ["roles"] = { ["reply"] = true },
    },
    [2462138082] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke D, a security level delta terminal.$B$BRed punch card detected.  Access Granted.\010\01001001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-D, термінала рівня безпеки дельта.$B$BВиявлено червону перфокартку. Доступ дозволено.\010\01001001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3964837436] = {
        ["english"] = { [1] = "Be quiet 'bout what you hear and see around here, $r." },
        ["text"] = "Мовчи про те, що тут бачиш і чуєш, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1463077307] = {
        ["english"] = { [1] = "As a mage, you are one of a select group that can conjure a portal to transport you back to this very place.  I can teach you if you are ready." },
        ["text"] = "Як маг, ти належиш до небагатьох, хто може начаклувати портал і повернутися саме сюди. Я можу навчити тебе, якщо ти готовий.",
        ["npcs"] = { [1] = 2485, [2] = 2489, [3] = 2492, [4] = 4165, [5] = 5957, [6] = 5958 },
        ["roles"] = { ["greeting"] = true },
    },
    [2251596501] = {
        ["english"] = { [1] = "$N, it is good to see you.  Our war with the other elemental lords yet rages, but your efforts help ensure our victory." },
        ["text"] = "$N, радий тебе бачити. Наша війна з іншими володарями стихій досі триває, та твої зусилля допомагають наблизити перемогу.",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["greeting"] = true },
    },
    [3843642298] = {
        ["english"] = { [1] = "Aye, the Highlord Mograine: A founder of the original order of the Scarlet Crusade. A knight of unwavering faith and purity; Mograine would be betrayed by his own son and slain by Kel'Thuzad's forces inside Stratholme. It is how I ended up here..." },
        ["text"] = "Так, Верховний лорд Моґрейн — один із засновників первісного ордену Багряного Походу. Лицар непохитної віри й чистоти; його зрадив власний син, а сили Кел'Тузада вбили його в Стратгольмі. Саме так я опинився тут...",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [1412138048] = {
        ["english"] = { [1] = "\"Iron Eagle.\" Hmph. It's a passenger ship, not a warbird! But hey, a job's a job, and I'll humor Captain \"Bombast\" so long as the prince is paying.$b$bIn any case, welcome aboard." },
        ["text"] = "\"Залізний Орел\". Пхе. Це пасажирський корабель, а не бойовий птах! Та робота є робота, тож я терпітиму капітана \"Бомбаста\", доки принц платить.$b$bХай там як, ласкаво просимо на борт.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1558584591] = {
        ["english"] = { [1] = "Do not think for a second that your past accomplishments entitle you to anything, $N.  They don't.$B$BIf you want my respect you're going to have to earn it.  This means following my orders without question and fulfilling them... without exceptions." },
        ["text"] = "Навіть не думай, що твої минулі здобутки дають тобі якісь привілеї, $N. Не дають.$B$BЯкщо хочеш моєї поваги, доведеться її заслужити. А це означає беззаперечно виконувати мої накази... без винятків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1136274916] = {
        ["english"] = { [1] = "Come in, come in. Just don't sit too close to the stove. It hasn't exploded yet today, but just to be safe I think you should sit elsewhere." },
        ["text"] = "Заходь, заходь. Тільки не сідай надто близько до печі. Сьогодні вона ще не вибухала, але задля безпеки краще сядь деінде.",
        ["npcs"] = { [1] = 6791, [2] = 6807, [3] = 11118 },
        ["roles"] = { ["greeting"] = true },
    },
    [2821391138] = {
        ["english"] = { [1] = "<sniff, sniff> I can smell 'em, mon." },
        ["text"] = "<нюх, нюх> Я їх чую, мон.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1137163836] = {
        ["english"] = { [1] = "All of our collections are completed, $c. That which we have assembled is in the process of being transported to Cenarion Hold in Silithus, and the rest of it should take no more than $2113w days to arrive. The Ahn'Qiraj War can then start once that is done and someone brave and foolish rings the gong right outside of the gates down there." },
        ["text"] = "Усі наші збори завершено, $c. Зібране перевозять до Кенарієвої цитаделі в Силітусі, й решта прибуде не пізніше ніж за $2113w днів. Після цього війна за Ан'Кіраж почнеться, щойно хтось хоробрий і безрозсудний ударить у гонг просто біля брам.",
        ["npcs"] = { [1] = 15525 },
        ["roles"] = { ["greeting"] = true },
    },
    [142567432] = {
        ["english"] = { [1] = "Before the plague came, I knew nothing about leather. Now I know enough to teach others. Death's left me with a lot of time on my hands." },
        ["text"] = "До приходу чуми я нічого не знав про шкіру. Тепер знаю достатньо, щоб навчати інших. Смерть залишила мені багато вільного часу.",
        ["npcs"] = { [1] = 223, [2] = 3549 },
        ["roles"] = { ["greeting"] = true },
    },
    [2507804813] = {
        ["english"] = { [1] = "A closer inspection of the pylon leads you to find a small table containing red, blue, and green crystals arranged in what seems like a specific formation.$B$BA large red circle of crystals is flanked on either side by a smaller circle of blue crystals and another of green crystals.$B$BYou carefully take note of the colors of the crystals, knowing that J.D. would be very interested in hearing about what you have found." },
        ["text"] = "Уважніше оглянувши пілон, ви знаходите невеликий столик із червоними, синіми й зеленими кристалами, викладеними в певному порядку.$B$BВелике червоне коло кристалів з обох боків оточене меншими колами синіх і зелених кристалів.$B$BВи ретельно запам'ятовуєте кольори кристалів, знаючи, що Дж. Д. дуже зацікавиться вашою знахідкою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2236324143] = {
        ["english"] = { [1] = "Alrighty then! So I was down at the lava pits of the Molten Span, testing out my lava suit. Everything was going great. I was even able to swim around in that stuff without suffering a single injury!$B$BSo there I am, minding my own business, doing a few backstrokes, when out of nowhere this thing swallows me up whole! Had it not been for my lava suit and built in food pellet dispenser, I would have been done for!" },
        ["text"] = "От і чудово! Я був унизу, біля лавових ям Розплавленого Прольоту, й випробовував свій лавовий костюм. Усе йшло прекрасно. Я навіть міг плавати в тому вариві без жодної травми!$B$BІ от пливу собі на спині, нікого не чіпаю, аж раптом ця штука ковтає мене цілком! Якби не лавовий костюм і вбудований дозатор харчових гранул, мені був би кінець!",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [2390503543] = {
        ["english"] = { [1] = "Blackfathom Deeps can be found at the north end of Zoram Strand along the coast of Ashenvale." },
        ["text"] = "Чорноводні глибини розташовані на північному кінці узбережжя Зорам у Ясенедолі.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1110409322] = {
        ["english"] = { [1] = "Do you know of the Highborne? The Shen'dralar?" },
        ["text"] = "Ти знаєш про Високородних? Про Шен'дралар?",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["greeting"] = true },
    },
    [1749590976] = {
        ["english"] = { [1] = "Come back to me when you've had more training. Randal Worth over there can help you with that." },
        ["text"] = "Повертайся, коли ще трохи потренуєшся. Рендал Ворт он там може тобі з цим допомогти.",
        ["npcs"] = { [1] = 5564 },
        ["roles"] = { ["greeting"] = true },
    },
    [3554042263] = {
        ["english"] = { [1] = "As I was saying, what we saw out there defied explanation.$B$BMy people were nowhere to be found, but in their place was a veritable army of robots and androids going about their business!$B$BThe droids all looked like gnomes and they said that they'd been expecting us. In fact, in their own strange way, they acted like they knew us. We were surrounded and quickly taken to the top of the pumping station.$B$BThat's where we saw their leader and what he was doing to the surviving gnomes!" },
        ["text"] = "Як я й казав, те, що ми побачили там, не мало жодного пояснення.$B$BНаших людей ніде не було, а замість них ходила ціла армія роботів та андроїдів, займаючись своїми справами!$B$BУсі дроїди виглядали як гноми й казали, що чекали на нас. Ба більше, по-своєму вони поводилися так, ніби нас знали. Нас оточили й швидко відвели на вершину насосної станції.$B$BСаме там ми побачили їхнього ватажка й те, що він робив із гномами, які вижили!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3829909967] = {
        ["english"] = { [1] = "Do you have steel that needs shaping?" },
        ["text"] = "Маєш сталь, якій треба надати форми?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [618154399] = {
        ["english"] = { [1] = "Do you have any spiders or beetles, $C?  They scurry fast, but if you're faster then you'll find them quite a treat!" },
        ["text"] = "У тебе є павуки чи жуки, $C? Вони швидко бігають, але якщо ти швидший — це справжні ласощі!",
        ["npcs"] = { [1] = 14437 },
        ["roles"] = { ["greeting"] = true },
    },
    [2212576228] = {
        ["english"] = { [1] = "<Cyrus's eyes glow brightly>$B$BDo I devour you whole or do I allow you to live?$B$BPerhaps you could still be of some use...$B$BChallenge my minion, $r. Survive and return proof of your victory to me." },
        ["text"] = "<Очі Сайруса яскраво сяють>$B$BПроковтнути тебе цілком чи дозволити жити?$B$BМожливо, від тебе ще буде якась користь...$B$BКинь виклик моєму прислужнику, $r. Виживи й принеси мені доказ своєї перемоги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1745075459] = {
        ["english"] = { [1] = "Can't ya see I'm workin' here, $glad:lass;? Off with ya, afore Kowalski sees me jawin.'" },
        ["text"] = "Хіба не бачиш, я тут працюю, $gхлопче:дівчино;? Іди собі, поки Ковальскі не побачив, що я тут язиком чешу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2579433237] = {
        ["english"] = { [1] = "Da Cache of Mau'ari holds great secrets... The shards used ta make it are reflective, and you can use its shiny surface ta siphon power from other tings and den reflect it onto yourself.$B$BKeeping da charm in your inventory lets you collect e'ko, da spiritual power from the beasts you fight. Once you find e'ko, you bring it ta Mau'ari." },
        ["text"] = "У Сховку Мау'арі приховано великі таємниці... Уламки, з яких його зроблено, відбивають світло, і ти можеш використати їхню блискучу поверхню, щоб висмоктувати силу з інших речей, а тоді спрямовувати її на себе.$B$BЯкщо триматимеш оберіг у торбі, зможеш збирати е'ко — духовну силу звірів, із якими б'єшся. Знайдеш е'ко — неси його Мау'арі.",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["greeting"] = true },
    },
    [4085024981] = {
        ["english"] = { [1] = "Boys and girls - children of all ages - the Darkmoon Faire has arrived!  Huzzah!" },
        ["text"] = "Хлопчики й дівчатка — діти всіх віків — Ярмарок Молодика прибув! Ура!",
        ["npcs"] = { [1] = 14842 },
        ["roles"] = { ["greeting"] = true },
    },
    [2391482096] = {
        ["english"] = { [1] = "Do you have a story for me?" },
        ["text"] = "Маєш для мене якусь історію?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3329714993] = {
        ["english"] = { [1] = "Do you expect me to cower before the mighty legion of $N?$B$BYou are nothing to me. Less than nothing. Had I desired your head, it would have been presented to me on a pike.$B$BYou have made the mistake that all mortals make.$B$B<Lord Victor Nefarius sighs.>$B$BTime does strange things to those that use it as a form of currency.\010" },
        ["text"] = "Ти гадаєш, я тремтітиму перед могутнім легіоном $N?$B$BТи для мене — ніщо. Менше ніж ніщо. Якби я бажав твоєї голови, її вже принесли б мені на списі.$B$BТи припустився помилки, властивої всім смертним.$B$B<Лорд Віктор Нефарій зітхає.>$B$BЧас дивно впливає на тих, хто використовує його як валюту.\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2785353595] = {
        ["english"] = { [1] = "Do ye have the potential to be a skilled hunter?  Well $gladdie : lassie;, only time will tell.  Just don't ye go shooting at apples atop peoples' heads till ye've spoken with Regnus o'er in the Hall of Arms." },
        ["text"] = "Чи маєш ти хист стати вправним мисливцем? Що ж, $gхлопче : дівчино;, це покаже лише час. Тільки не стріляй у яблука на головах людей, доки не поговориш із Реґнусом у Залі зброї.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [4079188992] = {
        ["english"] = { [1] = "Do ye have some new treasures that ye want to keep safe n' sound?  Ye'll be wanting to store them at The Vault with the Stonemantles.  Ye'll find The Vault just a hammer's throw northeast from the entrance to Ironforge." },
        ["text"] = "Маєш нові скарби, які хочеш зберегти в безпеці? Тоді неси їх у Сховище до Кам'яномантій. Сховище — лише за один кидок молота на північний схід від входу до Стальгорна.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2512606791] = {
        ["english"] = { [1] = "Day in and day out all Mad Jonah Sterling wants me to do is swab the decks.$B$BSwab the decks?!$B$BI'm a mage, I don't DO swabbin'! At least not the mundane way." },
        ["text"] = "Щодня й без кінця той скажений Джона Стерлінґ змушує мене драїти палубу.$B$BДраїти палубу?!$B$BЯ маг, я НЕ ДРАЮ палуби! Принаймні не звичайним способом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1395375415] = {
        ["english"] = { [1] = "Do ye have some new treasures that ye want to keep safe n' sound?  Then ye'll be wanting to store them at The Vault with the Stonemantles.  \010\010Ye'll find The Vault just a hammer's throw northeast from the entrance to Ironforge." },
        ["text"] = "Маєш нові скарби, які хочеш зберегти в безпеці? Тоді неси їх у Сховище до Кам'яномантій.  \010\010Сховище — лише за один кидок молота на північний схід від входу до Стальгорна.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1999127288] = {
        ["english"] = { [1] = "'Netherstorm' was not always as you see it now.$B$BThere was a time when this crumbling land was known as the Plains of Farahlon. Little of those days has survived the evil that has taken hold here." },
        ["text"] = "\"Пустокрай\" не завжди був таким, яким ти бачиш його нині.$B$BКолись ця земля, що тепер розсипається на шматки, називалася Рівнинами Фаралону. Від тих часів майже нічого не вціліло після зла, що пустило тут коріння.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [933857952] = {
        ["english"] = { [1] = "Ah, $r... I possess great knowledge a' da world and how ta create charms a' great power. " },
        ["text"] = "А, $r... Я знаю багато про цей світ і про те, як створювати могутні обереги. ",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["greeting"] = true },
    },
    [2103767914] = {
        ["english"] = { [1] = "And what do you say?" },
        ["text"] = "І що ти на це скажеш?",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["reply"] = true },
    },
    [1520529407] = {
        ["english"] = { [1] = "Do we have Mining trainers here?  Where do ye think ye are!?  \010\010Why you'll find one o' the best miners in all Dun Morogh at the Deepmountain Mining Guild on the northern side of The Great Forge.  There, Geofram Bouldertoe will show ye the true art of mining." },
        ["text"] = "У нас є наставники гірництва? Та де, по-твоєму, ти знаходишся!?  \010\010Одного з найкращих гірників у всьому Дун-Морозі знайдеш у Гільдії гірників Глибокої Гори на північному боці Великої кузні. Там Джеофрам Валунопалець покаже тобі справжнє мистецтво гірництва.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1098583018] = {
        ["english"] = { [1] = "Do watch your step in the garden of Ysera, mortal. Things are not always as they seem." },
        ["text"] = "Дивись під ноги в саду Ізери, смертний. Не все тут таке, яким здається.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1465723840] = {
        ["english"] = { [1] = "Another way? Do tell..." },
        ["text"] = "Інший шлях? Розкажи...",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["reply"] = true },
    },
    [1536510381] = {
        ["english"] = { [1] = "Do not waste my time.  What is it you want?" },
        ["text"] = "Не марнуй мого часу. Чого тобі треба?",
        ["npcs"] = { [1] = 15165 },
        ["roles"] = { ["greeting"] = true },
    },
    [798962109] = {
        ["english"] = { [1] = "<Priestess Il'dinare eyes you suspiciously.>" },
        ["text"] = "<Жриця Іл'дінаре підозріло дивиться на вас.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3444656051] = {
        ["english"] = { [1] = "Do not waste my time, $c." },
        ["text"] = "Не марнуй мого часу, $c.",
        ["npcs"] = { [1] = 2119, [2] = 2131, [3] = 4593, [4] = 4594, [5] = 4595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2604701354] = {
        ["english"] = { [1] = "Alas, it always seems like it does.  I - as did the rest of the Cenarion Circle - had assumed that Milli's creation was destroyed during the War of the Ancients.  This, as I have come to learn, is far from correct.$B$BThe Fruit of Fertility survived... though now it is known as the Felvine.  It is being corrupted by the demonic lord of that section of Eldre'Thalas, Alzzin the Wildshaper." },
        ["text"] = "На жаль, так завжди й буває. Я, як і решта Кенарієвого Кола, вважав, що творіння Міллі було знищене під час Війни Древніх. Та, як я з'ясував, це далеко не так.$B$BПлід Родючості вцілів... хоча тепер його знають як Сквернолозу. Його осквернює демонічний володар тієї частини Елдре'Таласа — Алззін Перевертень.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3044583171] = {
        ["english"] = { [1] = "Arming the wards at the sanctum will help us secure it faster.  We don't want any Wretched getting in our way when we unleash a full scale attack on the Legion and Kael.$B$BWe are $3244w percent done with our goal." },
        ["text"] = "Активація оберегів у святилищі допоможе нам швидше його захистити. Не хочемо, щоб Знедолені заважали, коли ми почнемо повномасштабний наступ на Легіон і Келя.$B$BМи виконали $3244w відсотків нашої мети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1015892876] = {
        ["english"] = { [1] = "Do not turn your back on the Light, $c, it may be the one thing that saves you some day." },
        ["text"] = "Не відвертайся від Світла, $c. Одного дня воно може стати єдиним, що тебе врятує.",
        ["npcs"] = { [1] = 375, [2] = 376, [3] = 377, [4] = 5484, [5] = 5489 },
        ["roles"] = { ["greeting"] = true },
    },
    [1211855144] = {
        ["english"] = { [1] = "And you are?" },
        ["text"] = "А ти хто?",
        ["npcs"] = { [1] = 15165 },
        ["roles"] = { ["greeting"] = true },
    },
    [2255186533] = {
        ["english"] = { [1] = "<The archmage's image seems to look through you, rather than at you.>$B$BRibbons and currents of arcane energy ebb and flow here as if the area is awash in a sea of magical power. Not even the first cataclysm caused this kind of damage." },
        ["text"] = "<Зображення архімага, здається, дивиться не на вас, а крізь вас.>$B$BСтрічки й потоки арканічної енергії прибувають і відступають тут так, ніби ця місцевість затоплена морем магічної сили. Навіть перший катаклізм не завдав таких руйнувань.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4074101550] = {
        ["english"] = { [1] = "Blurglgr murbrgl... just kidding, I can understand you." },
        ["text"] = "Блурґлґр мурбрґл... жартую, я тебе розумію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2487491007] = {
        ["english"] = { [1] = "Do not interrupt Niby, fool! I shall rend the flesh from your bones and use your skeletal remains as a coat rack. Now where was I? Oh yes, so, Kroshius lasted nearly ten times longer than any ordinary infernal. I am not sure why but I am confident that with enough study, I could find out.$B$BI need you to recover Kroshius' Infernal Core." },
        ["text"] = "Не перебивай Нібі, дурню! Я здеру плоть із твоїх кісток, а твій скелет використаю як вішак для плащів. На чому я зупинився? А, так: Крошіус протримався майже вдесятеро довше за звичайного інфернала. Не знаю чому, але певен, що достатньо досліджень — і я з'ясую.$B$BМені потрібно, щоб ти повернув Інфернальне ядро Крошіуса.",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["greeting"] = true },
    },
    [519842993] = {
        ["english"] = { [1] = "Do not forget, $c, battles still rage in Azeroth. Will you return to help the Horde in Alterac Valley?" },
        ["text"] = "Не забувай, $c, на Азероті досі вирують битви. Повернешся допомогти Орді в Альтерацькій долині?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4163272552] = {
        ["english"] = { [1] = "$N, what are you waiting for?  Find Field Marshal Teravaine in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!" },
        ["text"] = "$N, чого ти чекаєш? Знайди фельдмаршала Теравейна на Полі Чвар і передай йому наказ про наступ. Щойно він його отримає, то разом із військами кинеться на Орду й не братиме полонених!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1654321064] = {
        ["english"] = { [1] = "Before beginning a hunt, it is wise to ask someone what you are looking for before you begin looking for it." },
        ["text"] = "Перш ніж починати полювання, мудро спершу запитати когось, що саме ти шукаєш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [737078805] = {
        ["english"] = { [1] = "Do not fight the enemy unprepared, $N.  I can provide you with very powerful items... provided you have proven yourself to us." },
        ["text"] = "Не вступай у бій непідготовленим, $N. Я можу забезпечити тебе дуже могутніми предметами... якщо ти довів нам свою відданість.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [224538415] = {
        ["english"] = { [1] = "Aspiring to join our ranks one day?  Sark Ragetotem can help you on your way.  He's in the Hunter's Hall." },
        ["text"] = "Мрієш колись вступити до наших лав? Сарк Лютий Тотем допоможе розпочати шлях. Він у Залі Мисливців.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2383402023] = {
        ["english"] = { [1] = "Do not bring it any closer, mortal. I can sense the evil coursing through the seal from where I stand.$B$BGive me a moment to inspect the item - hold it firmly." },
        ["text"] = "Не піднось це ближче, смертний. Я відчуваю зло, що струменить крізь печатку, навіть звідси.$B$BДай мені хвилину оглянути предмет — тримай його міцно.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [2126132809] = {
        ["english"] = { [1] = "Cairne has brought us to a land rich with possibilities for the future. We have been fortunate, and so in turn we pass on our good fortune to others. That is why I began teaching, $N." },
        ["text"] = "Керн привів нас у землю, сповнену можливостей для майбутнього. Нам пощастило, тож ми ділимося вдачею з іншими. Саме тому я почав навчати, $N.",
        ["npcs"] = { [1] = 3007 },
        ["roles"] = { ["greeting"] = true },
    },
    [1882453138] = {
        ["english"] = { [1] = "<Budd rolls his eyes as he sees you draw near>$b$bAhh, yes, the soon-to-be-famous $n!$b$bTo what do I owe the pleasure of your company?" },
        ["text"] = "<Бадд закочує очі, помітивши, як ви наближаєтеся>$b$bА-а, так, майбутня знаменитість $n!$b$bЧим завдячую приємності вашого товариства?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [236480927] = {
        ["english"] = { [1] = "Do my eyes deceive me? Is that really you, Brother Rokkaram, after all this time?$B$BIf you are looking for Sai'kkal, he walks among the crystals in the western part of the Vortex Pinnacle. He seems preoccupied with what he calls a brutish, primitive presence there, although nothing seems amiss." },
        ["text"] = "Очі мене обманюють? Невже це справді ти, брате Роккараме, після стількох років?$B$BЯкщо шукаєш Сай'ккала, він ходить серед кристалів у західній частині Вершини Вихору. Його непокоїть те, що він називає грубою, первісною присутністю, хоча нічого підозрілого не видно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3409808508] = {
        ["english"] = { [1] = "Do you possess the courage to face Malygos' elite drakes in their own realm, $r?" },
        ["text"] = "Чи вистачить тобі відваги зустрітися з елітними драками Маліґоса у їхньому власному царстві, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3061435066] = {
        ["english"] = { [1] = "As a culture we believe in letting nothing go to waste.  When we are forced to slay a creature we take what we can to make sure its sacrifice was not in vain.  \010\010If you wish to learn the proper way to take the skin of a slain beast, then seek out Eladriel in the Craftsmen's Terrace." },
        ["text"] = "У нашій культурі ми віримо, що нічого не повинно пропадати марно. Коли доводиться вбити істоту, ми беремо все корисне, щоб її жертва не була даремною.  \010\010Якщо хочеш навчитися правильно знімати шкуру з убитого звіра, знайди Еладріель на Терасі Ремісників.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2550032252] = {
        ["english"] = { [1] = "Clothing!?  That won't help you against good steel!  Bah, if you're sure you want to be a tailor go find Magar's Cloth Goods in The Drag." },
        ["text"] = "Одяг!? Він не врятує тебе від доброї сталі! Пхе, якщо вже твердо вирішив стати кравцем, шукай «Тканини Маґара» у Хитрому провулку.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3484217945] = {
        ["english"] = { [1] = "Do it, $c...Then... avenge me!" },
        ["text"] = "Зроби це, $c... А тоді... помстися за мене!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [888614782] = {
        ["english"] = { [1] = "Are you looking for reagents or poison supplies? If so, you've come to the right place!" },
        ["text"] = "Шукаєш реагенти чи припаси для отрут? Якщо так — ти за адресою!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1481087279] = {
        ["english"] = { [1] = "Archibald, da Undercity's weapon master train you in both one and two-handed swords, mon. He in da War Quarter." },
        ["text"] = "Арчибальд, майстер зброї Підміста, навчить тебе володіти одноручними й дворучними мечами, мон. Він у Військовому кварталі.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [737298762] = {
        ["english"] = { [1] = "$N, what are you waiting for?  Find Field Marshal in the Field of Strife and give him the assault orders.  Once he gets the orders, he and his troops will charge into the Horde and take no prisoners!" },
        ["text"] = "$N, чого ти чекаєш? Знайди фельдмаршала на Полі Чвар і передай йому наказ про наступ. Щойно він його отримає, то разом із військами кинеться на Орду й не братиме полонених!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [415055809] = {
        ["english"] = { [1] = "Black, grey and dark purple are the prescribed colors.  See to it that you don't stray onto the wrong side of fashion street friend.  Bowen Brisboise can help to see that you don't.  You'll find him inside Cold Hearth Manor on the other side of the bridge to the southwest of town." },
        ["text"] = "Чорний, сірий і темно-пурпуровий — належні кольори. Дивись, друже, не зверни на хибний бік вулиці моди. Бовен Брісбуаз допоможе цього уникнути. Знайдеш його в садибі Холодне Вогнище по той бік мосту на південний захід від містечка.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [4286632046] = {
        ["english"] = { [1] = "<The blood elf lies limp on the table.  While he's still breathing, he appears to have been the victim of potent sedative toxins.>" },
        ["text"] = "<Ельф крові безвладно лежить на столі. Він досі дихає, але, схоже, став жертвою сильних заспокійливих токсинів.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [270334047] = {
        ["english"] = { [1] = "$C, we have a great need for your help in Warsong Gulch against the Silverwing Sentinels.  And there is even greater honor and reputation with the Warsong Outriders to be gained as well!  Do you have the courage to enter battle?" },
        ["text"] = "$C, нам украй потрібна твоя допомога в Ущелині Пісні Війни проти Вартових Срібнокрилих. І тепер там можна здобути ще більше честі та репутації серед Вершників Пісні Війни! Чи вистачить тобі відваги вступити в бій?",
        ["npcs"] = { [1] = 15105 },
        ["roles"] = { ["greeting"] = true },
    },
    [2967877633] = {
        ["english"] = { [1] = "$962w Stormpike Commander(s) and $950w Stormpike Lieutenant(s).$b" },
        ["text"] = "$962w командир(ів) Грозової Вершини та $950w лейтенант(ів) Грозової Вершини.$b",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3090758348] = {
        ["english"] = { [1] = "$N!  I hope you're ready to get to work, because there is much for you to do here on Sunstrider Isle.$B$BEver since the destruction of the Sunwell by Arthas and the Scourge, we have been a race adrift on a sea of uncertainty.  We teeter on the edge of oblivion.  This will change, $c, and you will learn and aid our recovery at the same time.$B$BThe Outland awaits us!" },
        ["text"] = "$N! Сподіваюся, ти готовий до роботи, бо на острові Сонячного Блукача для тебе чимало справ.$B$BВідтоді як Артас і Скверна знищили Сонячний Колодязь, наш народ мов корабель, що дрейфує морем непевності. Ми балансуємо на краю забуття. Але це зміниться, $c, і водночас ти вчитимешся та допомагатимеш нашому відродженню.$B$BПозамежжя чекає на нас!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4158578474] = {
        ["english"] = { [1] = "Are you interested in exploring one of these dungeons?" },
        ["text"] = "Хочеш дослідити одне з цих підземель?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2351748723] = {
        ["english"] = { [1] = "Do I look to you like I cast spells?  Well, I did hear that Cain Firesong was hanging out on the upstairs landing of the Gallows' End Tavern at the southeast end of town.  Odd how he just stands there outside of Gretchen's room like that." },
        ["text"] = "Я що, схожий на чаклуна? Хоча чув, що Кейн Вогнеспів тиняється на верхньому майданчику таверни «Кінець Шибеника» на південно-східному краю міста. Дивно, як він просто стоїть там біля кімнати Ґретхен.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [426692441] = {
        ["english"] = { [1] = "Ansekhwa, the tauren weapon master, is on Thunder Bluff's lower rise.  He can train one and two-handed maces, staves and guns.\010\010Hanashi, standing next to me here, can instruct in the use of bows, one and two-handed axes, staves and all manner of thrown weapons.\010\010Archibald, the undead weapon master in the War Quarter of the Undercity, can teach the use of crossbows, daggers, one and two-handed swords and polearms." },
        ["text"] = "Ансеква, таурен-майстер зброї, стоїть на нижньому ярусі Громового Бескиду. Він навчає володінню одноручними й дворучними булавами, посохами та рушницями.\010\010Ганаші, що стоїть поруч зі мною, навчає користуватися луками, одноручними й дворучними сокирами, посохами та всілякою метальною зброєю.\010\010Арчибальд, майстер зброї невмерлих у Військовому кварталі Підміста, навчає арбалетів, кинджалів, одноручних і дворучних мечів та древкової зброї.",
        ["npcs"] = { [1] = 11868 },
        ["roles"] = { ["greeting"] = true },
    },
    [868653582] = {
        ["english"] = { [1] = "Do I look stupid to you, $r? I may as well sign her death warrant myself! Why should I trust you?$B" },
        ["text"] = "Я що, схожий на дурня, $r? Я з таким самим успіхом міг би власноруч підписати їй смертний вирок! Чому я маю тобі довіряти?$B",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [1138496866] = {
        ["english"] = { [1] = "$N, we have enough supplies to launch ground assaults into the Field of Strife.  If you want to send the orders, and your rank is high enough, then speak with Sergeant Yazra Bloodsnarl in Frostwolf Village." },
        ["text"] = "$N, у нас достатньо припасів, щоб розпочати наземні наступи на Поле Чвар. Якщо хочеш передати накази й твій ранг досить високий, поговори із сержантом Язрою Кровогриз у селищі Морозного Вовка.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3541723352] = {
        ["english"] = { [1] = "<Grumbles>  I guess those mountains came out of nowhere...  All five times!" },
        ["text"] = "<Бурчить> Гадаю, ті гори щоразу просто виникали нізвідки... Усі п'ять разів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4276845015] = {
        ["english"] = { [1] = "And lo, how the mighty fell trembling at its feet, fearful that it might direct its words upon them.$B$BBut still did these charlatans, these worshipping pretenders to a non-existent religion, rail against the inevitable in a vain attempt to control their 'god.'  Uncaring, and likely not even noticing them, Murmur yawned and they knew oblivion.$B$BYet one somehow managed to survive, and in his insanity found a way to bring Murmur into the world." },
        ["text"] = "І ось могутні падали, тремтячи біля його ніг, боячись, що воно зверне до них своє слово.$B$BТа ці шарлатани, ці поклонники вигаданої релігії, все одно опиралися неминучому, марно намагаючись контролювати свого «бога». Байдужий до них і, мабуть, навіть не помічаючи їх, Мурмур позіхнув — і вони пізнали небуття.$B$BТа один якимось чином вижив і у своєму божевіллі знайшов спосіб привести Мурмура у світ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3846790138] = {
        ["english"] = { [1] = "Ah, nothing better than a priest to cure what ails ye.  Of course a nice tall pint cures a lot of what ails ye too, but I don't think Braenna Flintcrag teaches brewing.  I guess ye'll have to settle for some priest training over in the Hall of Mysteries instead." },
        ["text"] = "Немає нічого кращого за жерця, щоб вилікувати те, що тебе мучить. Хоча високий кухоль елю теж лікує чимало недуг, та не думаю, що Бренна Кремнескеля навчає пивоваріння. Доведеться задовольнитися навчанням жреця в Залі Таємниць.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [4088364594] = {
        ["english"] = { [1] = "All three of the gates at the Sunwell Plateau have been brought down, $N.$B$BYou must marshal your forces and stop Kil'jaeden from entering Azeroth before all is lost!" },
        ["text"] = "Усі три брами на плато Сонячного Колодязя зруйновано, $N.$B$BТи мусиш зібрати сили й не дати Кіл'джедену потрапити до Азероту, доки не стало запізно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1532674117] = {
        ["english"] = { [1] = "$C, the Horde has gathered all that it needs for the Ahn'Qiraj War! Now we wait for the puny Alliance to catch up. When they do, we'll begin transporting everything to Silithus. It should not be long after the buildup there is completed that the war will begin!" },
        ["text"] = "$C, Орда зібрала все потрібне для війни за Ан'Кіраж! Тепер чекаємо, доки нікчемний Альянс нас наздожене. Коли це станеться, почнемо перевозити все до Силітуса. Щойно там завершать підготовку, війна невдовзі почнеться!",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [98410059] = {
        ["english"] = { [1] = "Do I look like I have the time or energy to coddle every tourist that wanders through my door? Tell me what you need, and make it quick." },
        ["text"] = "Я що, схожий на того, хто має час чи сили няньчитися з кожним туристом, що заходить у мої двері? Кажи, що тобі треба, і швидко.",
        ["npcs"] = { [1] = 5482 },
        ["roles"] = { ["greeting"] = true },
    },
    [3387985577] = {
        ["english"] = { [1] = "Anoint my head with a healing balm.  Do you like my crown of thorns?" },
        ["text"] = "Помаж мою голову цілющим бальзамом. Подобається моя корона з терня?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2745584863] = {
        ["english"] = { [1] = "A rare find, indeed.$B$B<Mathredis nods.>$B$B If you wish to continue, I will need the components." },
        ["text"] = "Справді рідкісна знахідка.$B$B<Матредіс киває.>$B$B Якщо хочеш продовжити, мені знадобляться компоненти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2637848935] = {
        ["english"] = { [1] = "Come in by the fire and rest, $r. I hope you don't mind the smell of fish." },
        ["text"] = "Заходь, сідай біля вогню й відпочинь, $r. Сподіваюся, запах риби тобі не завадить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2302915374] = {
        ["english"] = { [1] = "Ah, hello there, $r. As you can see, I'm not open for business quite yet. Now, if you'll excuse me, I'm very busy." },
        ["text"] = "А, вітаю, $r. Як бачиш, я ще не відкрив крамницю. А тепер, якщо дозволиш, я дуже зайнятий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4046263894] = {
        ["english"] = { [1] = "[PH] SD2 unknown text" },
        ["text"] = "[PH] SD2 невідомий текст",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2051475275] = {
        ["english"] = { [1] = "Blackrock Mountain lies between Searing Gorge in the north and Burning Steppes in the south." },
        ["text"] = "Чорнокамінна гора лежить між Випаленою ущелиною на півночі та Палаючим степом на півдні.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2018943876] = {
        ["english"] = { [1] = "All of these mouths to feed, and who has to do it? Me!$B$BAll the cooking, and the cleaning, and everything else!" },
        ["text"] = "Стільки ротів треба годувати, і хто це має робити? Я!$B$BІ готувати, і прибирати, і все інше!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [683476711] = {
        ["english"] = { [1] = "<Bodley looks at you dubiously, but continues...>$B$BThere we are, spellbook in hand, and Kormok, our two-headed ogre necromancer, gets this strange look in all four of his eyes. It was really creepy, because that second set of eyes always kind of looked dead, like a cow's eyes, you know? So, all of a sudden he just reaches out and rips this amulet off that Valthalak was wearing.$B$BThe rest of the company went crazy; some of us telling them to leave it alone, and others who wanted it for themselves." },
        ["text"] = "<Бодлі дивиться на вас із сумнівом, але продовжує...>$B$BСтоїмо ми, значить, із книгою заклять у руках, і раптом Кормок — наш двоголовий огр-некромант — дивиться на нас усіма чотирма очима якось дуже дивно. Було моторошно, бо друга пара його очей завжди виглядала трохи мертвою, знаєте, як у корови. І тут він раптом простягає руку та зриває амулет, який носив Вальталак.$B$BУся компанія збожеволіла: одні кричали, щоб він не чіпав його, а інші хотіли забрати собі.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [1271858709] = {
        ["english"] = { [1] = "Do I get a free mount?" },
        ["text"] = "Мені дадуть безкоштовного верхового?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2608018992] = {
        ["english"] = { [1] = "$N, was it? That is a mighty fine piece of work ye have there. I'll take ye on, train ye how to make armor fit fer King Magni himself." },
        ["text"] = "$N, так? Гарна робота, нічого не скажеш. Я візьму тебе в учні й навчу кувати обладунки, гідні самого короля Маґні.",
        ["npcs"] = { [1] = 5164 },
        ["roles"] = { ["greeting"] = true },
    },
    [2617311925] = {
        ["english"] = { [1] = "\"...\"$B$BThe body of the tauren druid lies still and unmoving.  It would seem as though he has finally passed from this world to his promised great beyond." },
        ["text"] = "\"...\"$B$BТіло друїда-таурена лежить нерухомо й безживно. Схоже, він нарешті покинув цей світ і вирушив у обіцяне велике потойбіччя.",
        ["npcs"] = { [1] = 10739 },
        ["roles"] = { ["greeting"] = true },
    },
    [4272759170] = {
        ["english"] = { [1] = "Are the Blasted Lands currently under attack?" },
        ["text"] = "Знівечені землі зараз атакують?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [19674522] = {
        ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as exalted must submit a combined total of 12 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 54 insignias.$B$BThose exalted in the eyes of the Dawn receive the greatest discounts.\010" },
        ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає звеличеними, мають здати загалом 12 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 54 відзнаки.$B$BТі, кого Світанок звеличує, отримують найбільші знижки.\010",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["greeting"] = true },
    },
    [2543284577] = {
        ["english"] = { [1] = "Do fish ever get thirsty?" },
        ["text"] = "Рибам коли-небудь хочеться пити?",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [1057459943] = {
        ["english"] = { [1] = "BOAR'S DUNG! Why must I stay here to guide others to Alterac Valley, when I could be fighting there myself? You! Have you come to fight the Alliance?" },
        ["text"] = "КАБАНЯЧЕ ЛАЙНО! Чому я маю стирчати тут і направляти інших до Альтерацької долини, коли сам міг би там битися? Ти! Прийшов битися з Альянсом?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3965929078] = {
        ["english"] = { [1] = "Dis ain't no game mon. Joo want to use da axe, joo got to say da line. Say it wif me???Say hello, to ma little friend." },
        ["text"] = "Це не гра, друже. Хочеш махати сокирою — мусиш сказати фразу. Повторюй за мною???Передай привіт моєму маленькому другові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3439911721] = {
        ["english"] = { [1] = "As I was saying, I held onto that scepter shard for a good five-hundred years and it was nothing but trouble. It attracted all kinds of attention - the wrong kind of attention. I want to be left alone to my studies not babysit some would be hero's ticket to glory. So... I gave it to the fish." },
        ["text"] = "Як я й казав, я зберігав той уламок скіпетра добрих п'ятсот років, і від нього були самі проблеми. Він привертав усіляку увагу — не ту, що треба. Я хочу, щоб мене лишили наодинці з дослідженнями, а не щоб я няньчив чийсь квиток до слави. Тож... я віддав його рибі.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [2295290969] = {
        ["english"] = { [1] = "Ah... a customer! Talk to my greatest invention, the Vendor-Tron 1000. He has all your needs... some of the rarest items you will ever find on the market anywhere in Kalimdor... not to mention that his programming will not allow any bargaining, so the price you see is the price you pay." },
        ["text"] = "А... покупець! Поговори з моїм найвидатнішим винаходом — ТоргоТроном 1000. У нього є все, що треба... одні з найрідкісніших товарів, які взагалі знайдеш на ринку будь-де в Калімдорі... і, до речі, його програма не дозволяє торгуватися, тож ціна на етикетці — остаточна.",
        ["npcs"] = { [1] = 11625 },
        ["roles"] = { ["greeting"] = true },
    },
    [3104207760] = {
        ["english"] = { [1] = "A great evil stirs, $r. Can you feel it?$B$BBah! Of course you cannot. Hand me your armor and weapons and I shall renew their vigor." },
        ["text"] = "Пробуджується велике зло, $r. Відчуваєш?$B$BБа! Авжеж ні. Дай мені свої обладунки й зброю, і я поверну їм силу.",
        ["npcs"] = { [1] = 15176 },
        ["roles"] = { ["greeting"] = true },
    },
    [3024274039] = {
        ["english"] = { [1] = "Director Riddlevox put me in charge of the Union's shredder development program. Few months on the job and I'm already in hot water! I could use your help, $n!" },
        ["text"] = "Директор Ріддлвокс поставив мене керувати програмою Спілки з розробки подрібнювачів. Лише кілька місяців на посаді, а я вже по вуха в халепі! Мені б не завадила твоя допомога, $n!",
        ["npcs"] = { [1] = 3442 },
        ["roles"] = { ["greeting"] = true },
    },
    [572020874] = {
        ["english"] = { [1] = "Can you train me how to use rogue skills?" },
        ["text"] = "Можеш навчити мене розбійницьких умінь?",
        ["npcs"] = { [1] = 915, [2] = 916, [3] = 917, [4] = 918, [5] = 1234, [6] = 1411, [7] = 3155, [8] = 3170, [9] = 3401, [10] = 3599, [11] = 4163, [12] = 4214, [13] = 4215, [14] = 13283 },
        ["roles"] = { ["reply"] = true },
    },
    [1190955991] = {
        ["english"] = { [1] = "Dire Maul" },
        ["text"] = "Страхомістя",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2387865313] = {
        ["english"] = { [1] = "Built twelve thousand years ago by a covert sect of night elf sorcerers, the ancient city of Eldre'Thalas was used to protect Queen Azshara's most prized arcane secrets. Though it was ravaged by the Great Sundering of the world, much of the wondrous city still stands as the imposing Dire Maul. The ruins' three distinct districts have been overrun by all manner of creatures - especially the spectral highborne, foul satyr and brutish ogres. \010" },
        ["text"] = "Стародавнє місто Елдре'Талас збудувала дванадцять тисяч років тому таємна секта чаклунів нічних ельфів, щоб берегти найцінніші арканічні таємниці королеви Азшари. Хоч Великий Розкол спустошив місто, значна частина його дивовиж залишається стояти як величне Страхомістя. Три окремі райони руїн захопили всілякі істоти — передусім примарні Високородні, мерзенні сатири та брутальні огри. \010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2534458145] = {
        ["english"] = { [1] = "Ah, nothing quite like a ride on a gryphon, is there?  The night elves can keep those hippo's of theirs, just give me a gryphon and the wind in me hair!  \010\010Well now, I won't keep ye any longer, just head over to Gryth Thurden on the east side of The Great Forge and he'll get ye on yer way." },
        ["text"] = "Немає нічого кращого за політ на грифоні, еге ж? Нічні ельфи хай залишають собі своїх гіпогрифів, а мені дай грифона й вітер у волоссі!  \010\010Ну, більше не затримуватиму. Іди до Ґрита Турдена на східному боці Великої Кузні — він відправить тебе куди треба.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [3473001312] = {
        ["english"] = { [1] = "Ach, it's hard enough keeping order around here without all these new troubles popping up!  I hope you have good news, $n..." },
        ["text"] = "Ох, і без того важко тримати тут порядок, а тепер ще й нові біди сиплються! Сподіваюся, в тебе добрі новини, $n...",
        ["npcs"] = { [1] = 240 },
        ["roles"] = { ["greeting"] = true },
    },
    [1274675590] = {
        ["english"] = { [1] = "Brandur Ironhammer would be the one ye'd want to see.  Ye can find him in the Hall of Mysteries north of the gates of Ironforge." },
        ["text"] = "Тобі потрібен Брандур Залізний Молот. Знайдеш його в Залі Таємниць на північ від брами Стальгорна.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [404671739] = {
        ["english"] = { [1] = "Dinner guests should show more respect!" },
        ["text"] = "Гості за вечерею повинні виявляти більше поваги!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [876358266] = {
        ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as revered must submit a combined total of 14 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 90 insignias.$B$BThose that are revered by the Dawn will find the cost of superior items quite reasonable! The cost for the more powerful items is still high.\010" },
        ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає вельмишановними, мають здати загалом 14 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 90 відзнак.$B$BТим, кого Світанок вельми шанує, вартість кращих предметів здасться цілком прийнятною! Та могутніші предмети все ще коштують дорого.\010",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["greeting"] = true },
    },
    [1180379512] = {
        ["english"] = { [1] = "Archibald is the master of the crossbow. He's the weapon master of the Undercity, located in the War Quarter." },
        ["text"] = "Арчибальд — майстер арбалета. Він майстер зброї Підміста, стоїть у Військовому кварталі.",
        ["npcs"] = { [1] = 11868, [2] = 11869 },
        ["roles"] = { ["greeting"] = true },
    },
    [3951993446] = {
        ["english"] = { [1] = "Ah, $c, good to see you. We need assistance here with gathering supplies in preparation for the impending war at Ahn'Qiraj. I've been asked to put together a great many first aid field kits, and the primary component I need is wool bandages. I already have some, $2079w to be exact, but I need to collect $2080w." },
        ["text"] = "А, $c, радий тебе бачити. Нам потрібна допомога зі збором припасів до майбутньої війни в Ан'Кіражі. Мені доручили зібрати багато польових наборів першої допомоги, а головний компонент — вовняні бинти. Дещо вже є, точніше $2079w, але треба зібрати $2080w.",
        ["npcs"] = { [1] = 15528 },
        ["roles"] = { ["greeting"] = true },
    },
    [3462538363] = {
        ["english"] = { [1] = "Class Trainer" },
        ["text"] = "Наставник класу",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3571, [7] = 4262, [8] = 5595, [9] = 6272, [10] = 6740, [11] = 8931, [12] = 12996, [13] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [2501661725] = {
        ["english"] = { [1] = "DIE!" },
        ["text"] = "ПОМРИ!",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["reply"] = true },
    },
    [494713799] = {
        ["english"] = { [1] = "A blacksmith, eh? Very well. What would you like to learn about, blacksmith?$B$B" },
        ["text"] = "Коваль, еге ж? Гаразд. Про що ти хочеш дізнатися, коваль?$B$B",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["greeting"] = true },
    },
    [739303236] = {
        ["english"] = { [1] = "Didn't we just break free of the Burning Legion, and here you are messing with demons again?  Seek out the Darkfire Enclave in the underground cavern known as the Cleft of Shadow.  You'll find a tunnel down into it from The Drag." },
        ["text"] = "Хіба ми щойно не звільнилися від Палаючого Легіону, а ти вже знову зв'язуєшся з демонами? Шукай Анклав Темного Вогню в підземній печері, відомій як Розколина Тіні. Тунель униз знайдеш у Хитрому провулку.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3930508950] = {
        ["english"] = { [1] = "Did you see?  That last firework almost caught that drawf's shirt on fire!  Hah!" },
        ["text"] = "Бачив? Той останній феєрверк ледь не підпалив сорочку того дворфа! Ха!",
        ["npcs"] = { [1] = 15908 },
        ["roles"] = { ["greeting"] = true },
    },
    [3792098552] = {
        ["english"] = { [1] = "A foul wind blows from the East, $c." },
        ["text"] = "Зі сходу дме лихий вітер, $c.",
        ["npcs"] = { [1] = 3418 },
        ["roles"] = { ["greeting"] = true },
    },
    [684414831] = {
        ["english"] = { [1] = "Behold, the Flames of Summer!" },
        ["text"] = "Погляньте — Полум'я Літа!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2741385484] = {
        ["english"] = { [1] = "All hail the exalted hero!" },
        ["text"] = "Слава звеличеному герою!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3983740214] = {
        ["english"] = { [1] = "<Tarsis's eyes light up.>$B$BI held it once... I held it despite the warnings of the Kirin Tor. I held it, mortal... Power unending. Power to do what I desired, as I desired. And just as quickly, it was taken from me. But I had tasted... And that taste was all that it took.  " },
        ["text"] = "<Очі Тарсіса спалахують.>$B$BЯ тримав його колись... Тримав, попри застереження Кірін-Тору. Тримав його, смертний... Безмежна сила. Сила робити все, чого я бажав, саме так, як бажав. І так само швидко його в мене відібрали. Але я скуштував цієї сили... І одного смаку виявилося досить.  ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3264966093] = {
        ["english"] = { [1] = "Are you... here to save me?" },
        ["text"] = "Ти... прийшов мене врятувати?",
        ["npcs"] = { [1] = 5843 },
        ["roles"] = { ["greeting"] = true },
    },
    [1778693516] = {
        ["english"] = { [1] = "Blue security card insertion successful.  Dispensing security level delta unit.\010\01001010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111" },
        ["text"] = "Синю картку безпеки вставлено успішно. Видається модуль рівня безпеки дельта.\010\01001010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2129945549] = {
        ["english"] = { [1] = "Between the light and the dark, there is shadow... and those shadows have powers you have yet to see." },
        ["text"] = "Між світлом і темрявою є тінь... і в цих тінях ховаються сили, яких ти ще не бачив.",
        ["npcs"] = { [1] = 4578, [2] = 9584 },
        ["roles"] = { ["greeting"] = true },
    },
    [1559712051] = {
        ["english"] = { [1] = "$N!  Our supplies are dwindling and until we get more we can't launch large ground assaults into the Field of Strife!$B$BSpeak with the Stormpike Quartermaster.  He'll tell you what you can do to resupply our assault forces." },
        ["text"] = "$N! Наші припаси тануть, і доки не поповнимо їх, не зможемо розпочати великі наземні наступи на Поле Чвар!$B$BПоговори з квартирмейстером Грозової Вершини. Він скаже, як ти можеш поповнити запаси наших штурмових сил.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3636201544] = {
        ["english"] = { [1] = "Arathi Basin was once our home, and will be again with your aid!  Will you help us $c?" },
        ["text"] = "Низина Араті колись була нашим домом і з твоєю допомогою стане ним знову! Допоможеш нам, $c?",
        ["npcs"] = { [1] = 857 },
        ["roles"] = { ["greeting"] = true },
    },
    [808560839] = {
        ["english"] = { [1] = "Did you just come out of a dungeon?  Did you get me anything?" },
        ["text"] = "Ти щойно з підземелля? Мені щось приніс?",
        ["npcs"] = { [1] = 14305 },
        ["roles"] = { ["greeting"] = true },
    },
    [4112067146] = {
        ["english"] = { [1] = "Did you forget your student's attire?  Do you think fashion is more vital than the Scourge's domination?" },
        ["text"] = "Ти забув учнівське вбрання? Невже мода для тебе важливіша за панування Скверни?",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [3625036525] = {
        ["english"] = { [1] = "$N, we have enough supplies to launch ground assaults.  If your standing with the Stormpike Guard is high enough, then speak with Corporal Noreg Stormpike." },
        ["text"] = "$N, у нас достатньо припасів, щоб розпочати наземні наступи. Якщо твоя репутація у Варти Грозової Вершини достатньо висока, поговори з капралом Нореґом Грозовою Вершиною.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1610117312] = {
        ["english"] = { [1] = "A rogue?  I'm not in the habit of referring people to those types, but I believe Jannok would be the one you're looking for.  You will find him at the Inn in Dolanaar." },
        ["text"] = "Розбійник? Я зазвичай не направляю людей до таких типів, але, гадаю, тобі потрібен Джаннок. Знайдеш його в таверні Доланаара.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [424140114] = {
        ["english"] = { [1] = "$g Hey there cutie, you looking for a ride to Grom'gol? I hear it gets mighty steamy down in those jungles, maybe I could join you for a short vacation, show you a real jungle cat. : Come, take a trip to the wonderful, gorgeous, tropical jungles of Stranglethorn. That's right, you too can be spending your time sunbathing by the crystal blue waters while I stand here in this unbearable heat with nothing to look at but my brother Frezza all day! Enjoy your trip!;" },
        ["text"] = "$g Привіт, красунчику! Шукаєш, як дістатися до Гром'ґола? Чула, у тих джунглях буває дуже спекотно. Може, я приєднаюся до тебе на коротку відпустку й покажу тобі справжню дику кішку. : Вирушай у чудові, прекрасні тропічні джунглі Тернистої долини! Саме так: ти теж можеш засмагати біля кришталево-блакитних вод, поки я стою тут у цій нестерпній спеці й цілий день бачу лише свого брата Фреззу! Приємної подорожі!;",
        ["npcs"] = { [1] = 12136 },
        ["roles"] = { ["greeting"] = true },
    },
    [2827193713] = {
        ["english"] = { [1] = "(Sniff, sniff) You smell that? Don't you just LOVE the smell of grease?" },
        ["text"] = "(Нюх, нюх) Відчуваєш? Хіба ти не ОБОЖНЮЄШ запах мастила?",
        ["npcs"] = { [1] = 10993 },
        ["roles"] = { ["greeting"] = true },
    },
    [4235831524] = {
        ["english"] = { [1] = "Ancient forces stir - forces that have not been seen or felt for thousands of years. The world weeps, $r. Perhaps a new sundering comes. A sickness born from within...$B$BThe foulness has begun to seep into our lands. From the Dream come nightmares. Nightmares to befoul us in our waking hours...\010" },
        ["text"] = "Пробуджуються давні сили — такі, яких не бачили й не відчували тисячі років. Світ плаче, $r. Можливо, насувається новий Розкол. Хвороба, народжена зсередини...$B$BСкверна вже просочується в наші землі. Із Сну приходять кошмари. Кошмари, що оскверняють нас навіть у години неспання...",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["greeting"] = true },
    },
    [289074450] = {
        ["english"] = { [1] = "<Lydros reaches into his robe and presents you with a dull, flat elven blade.>$B$BIn ages past, well before even the War of the Ancients, there existed this blade." },
        ["text"] = "<Лідрос сягає рукою під мантію й показує вам тьмяний плоский ельфійський клинок.>$B$BУ давні віки, задовго навіть до Війни Древніх, існував цей клинок.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [925009661] = {
        ["english"] = { [1] = "Did you bring your text books?  Can I look on with you?" },
        ["text"] = "Ти приніс підручники? Можна я дивитимуся разом із тобою?",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [610439106] = {
        ["english"] = { [1] = "Did they send you to find me? Well I'm not going back without my men." },
        ["text"] = "Тебе послали мене знайти? Що ж, без своїх людей я назад не повернуся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2481204888] = {
        ["english"] = { [1] = "<Lady Prestor glares at you.>" },
        ["text"] = "<Леді Престор люто дивиться на вас.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [474608803] = {
        ["english"] = { [1] = "<The lord-commander flashes a rictus grin, looking you up and down discerningly.>$B$BThat's what I wanted to hear." },
        ["text"] = "<Лорд-командир криво шкіриться, прискіпливо оглядаючи вас із голови до ніг.>$B$BСаме це я й хотів почути.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1657620394] = {
        ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as friendly must submit a combined total of 60 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 220 insignias.$B$BI must admit, the price is quite high for adventurers not favored by the Dawn.\010" },
        ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає дружніми, мають здати загалом 60 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 220 відзнак.$B$BМушу визнати, для тих, хто ще не здобув прихильності Світанку, ціна досить висока.\010",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["greeting"] = true },
    },
    [4266030945] = {
        ["english"] = { [1] = "Can I help you?", [2] = "Can I help you? " },
        ["text"] = "Чим можу допомогти?",
        ["npcs"] = { [1] = 7207 },
        ["roles"] = { ["greeting"] = true },
    },
    [1147834876] = {
        ["english"] = { [1] = "<Omarion grumbles something under his breath.>$B$BBut of course I can help you, dear $g boy:girl;. It is my dying wish... my final desire. Please, take this handbook. The information on its pages are a compilation of all that I know and have learned in the past 30 some-odd years of my miserable life. Give the handbook to that good for nothing apprentice of mine that's probably sitting on his fat duff at Light's Hope Chapel." },
        ["text"] = "<Омаріон щось бурмоче собі під ніс.>$B$BЗвісно, я можу тобі допомогти, $g любий хлопче : люба дівчино;. Це моє передсмертне бажання... моя остання воля. Прошу, візьми цей посібник. На його сторінках зібрано все, що я знаю і чого навчився за більш ніж тридцять років мого жалюгідного життя. Віддай посібник тому моєму нікчемному учневі, який, мабуть, просиджує товстий зад у каплиці Надії Світла.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2886443965] = {
        ["english"] = { [1] = "Did my sweet lass Kali send you down to me? The apple of my eye, she is." },
        ["text"] = "Моя люба Калі послала тебе до мене? Вона — зіниця мого ока.",
        ["npcs"] = { [1] = 1470 },
        ["roles"] = { ["greeting"] = true },
    },
    [3880218774] = {
        ["english"] = { [1] = "Araxes, come in....Are you there Araxes? Visibility is nil, Warp storms blocking us." },
        ["text"] = "Араксесе, відповідай... Араксесе, ти там? Видимість нульова, бурі викривлення глушать зв'язок.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [607742368] = {
        ["english"] = { [1] = "Did Crest send you?" },
        ["text"] = "Тебе Крест послав?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2938716910] = {
        ["english"] = { [1] = "Did Balandar Brightstar send you to rescue me?" },
        ["text"] = "Тебе Баландар Яснозір послав мене врятувати?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2455972602] = {
        ["english"] = { [1] = "Ah!  Please, if you see a survivor of Darrowshire, tell them I am free!" },
        ["text"] = "Ах! Прошу, якщо зустрінеш когось із уцілілих Дерроушира, скажи їм, що я вільний!",
        ["npcs"] = { [1] = 11064 },
        ["roles"] = { ["greeting"] = true },
    },
    [570439546] = {
        ["english"] = { [1] = "Dhugru Gorelust is hiding behind the barracks on the east side of town.  Don't let me find out that you're in league with the Burning Legion!" },
        ["text"] = "Дуґру Кровожад ховається за казармами на східному краю міста. Тільки не дай мені дізнатися, що ти в змові з Палаючим Легіоном!",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [917355029] = {
        ["english"] = { [1] = "Aww, what rotten luck! My skills aren't good enough to be of any use to you. Oh well. Talk to Fimble Finespindle over there by the loom. He's been working with leather for longer than I have." },
        ["text"] = "Ох, яка невдача! Моїх навичок недостатньо, щоб бути тобі корисним. Ну й гаразд. Поговори з Фімблом Тонкопрядом біля ткацького верстата. Він працює зі шкірою довше за мене.",
        ["npcs"] = { [1] = 1466 },
        ["roles"] = { ["greeting"] = true },
    },
    [364835799] = {
        ["english"] = { [1] = "As a representative of the Lower City, I'm here to put forward our case that Auchindoun must be cleared of its Shadow Council infestation.  That is, if we're to have any hope for a future and stave off the possibility of a cataclysm greater than the creation of the Bone Wastes!$B$BAll of our peoples have suffered too much already.  I am here to see to it that the suffering stops!" },
        ["text"] = "Як представник Нижнього Міста я тут, щоб довести: Акіндун необхідно очистити від зараження Радою Тіней. Інакше в нас не буде надії на майбутнє й ми не зможемо відвернути катаклізм, ще страшніший за появу Кістяної пустки!$B$BУсі наші народи вже надто багато страждали. Я тут, щоб цьому стражданню покласти край!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2059923271] = {
        ["english"] = { [1] = "Ar'tor's lifeless body remains suspended in mid-air by demonic magic. They take from him, even in death..." },
        ["text"] = "Безживне тіло Ар'тора зависло в повітрі, утримуване демонічною магією. Вони висмоктують його навіть після смерті...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3128095280] = {
        ["english"] = { [1] = "Despite their tragedy the Undead have come all this way to aid us.  I only hope that we can be as helpful to them.  Seek out Father Cobb near the Pools of Vision under the Spirit Rise." },
        ["text"] = "Попри свою трагедію, невмерлі подолали весь цей шлях, щоб допомогти нам. Сподіваюся лише, що й ми зможемо бути для них так само корисними. Знайди отця Кобба біля Ставків Видінь під Верхів'ям Духів.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2262971613] = {
        ["english"] = { [1] = "Desperate times call for desperate measures, $c." },
        ["text"] = "Відчайдушні часи потребують відчайдушних заходів, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [625016416] = {
        ["english"] = { [1] = "$N, I've come to find out how rampant the effects of Fel Moss are throughout Darkshore. The corruption of Teldrassil and our surrounding lands really concerns the druids of the Cenarian Circle, and all Night elves.$B$BIt is my goal to find out why this has happened and to put an end to it." },
        ["text"] = "$N, я прибув з'ясувати, наскільки далеко Темнобережжям поширився вплив скверномоху. Осквернення Тельдрассіла й навколишніх земель дуже непокоїть друїдів Кенарієвого Кола та всіх нічних ельфів.$B$BЯ маю з'ясувати, чому це сталося, й покласти цьому край.",
        ["npcs"] = { [1] = 3693 },
        ["roles"] = { ["greeting"] = true },
    },
    [4048413284] = {
        ["english"] = { [1] = "As acting Taskmaster of this here compound, it is my duty to make sure that there is a certain level of tedium involved with all forms of business, work, rest, and relaxation that may take place here.$B$BIf you find anything that you are asked to do to be too easy and hassle free, report to me immediately." },
        ["text"] = "Як виконувач обов'язків наглядача цього комплексу, я зобов'язаний стежити, щоб у будь-якій справі, роботі, відпочинку чи розвазі тут завжди було достатньо нудної мороки.$B$BЯкщо будь-яке доручення здасться тобі надто простим і безпроблемним — негайно доповідай мені.",
        ["npcs"] = { [1] = 14626 },
        ["roles"] = { ["greeting"] = true },
    },
    [574069995] = {
        ["english"] = { [1] = "<Archmage Vargoth favors you with a wry smile.>$B$BPlenty of room at the cursed Violet Tower.$B$BAny time of year, you can find me here." },
        ["text"] = "<Архімаг Варґот криво вам усміхається.>$B$BУ проклятій Фіолетовій Вежі місця вдосталь.$B$BБудь-якої пори року знайдеш мене тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2357943004] = {
        ["english"] = { [1] = "Derak Nightfall, at your service!" },
        ["text"] = "Дерак Ночепад, до ваших послуг!",
        ["npcs"] = { [1] = 2397 },
        ["roles"] = { ["greeting"] = true },
    },
    [3455191955] = {
        ["english"] = { [1] = "Alchemy" },
        ["text"] = "Алхімія",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [3796778485] = {
        ["english"] = { [1] = "Dem other ogres was dumb to attack you, boss!  Dat's why I'm still alive - I'm smart and stuff!" },
        ["text"] = "Ті інші огри дурні були, раз напали на тебе, босе! От чому я досі живий — я розумний і все таке!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [2481711295] = {
        ["english"] = { [1] = "Across the lands our fires burn strong and true!" },
        ["text"] = "По всіх землях наші вогні палають яскраво й незгасно!",
        ["npcs"] = { [1] = 16781 },
        ["roles"] = { ["greeting"] = true },
    },
    [3518741833] = {
        ["english"] = { [1] = "Crafted from the same vines as Razorfen Kraul, Razorfen Downs is the traditional capital city of the quilboar race. The sprawling, thorn-ridden labyrinth houses a veritable army of loyal quilboar as well as their high priests - the Death's Head tribe. Recently, however, a looming shadow has fallen over the crude den. Agents of the undead Scourge - led by the lich, Amnennar the Coldbringer - have taken control over the quilboar race and turned the maze of thorns into a bastion of undead might. \010\010" },
        ["text"] = "Сплетені з тих самих лоз, що й Лабіринти Гостробоких, Кургани Гостробоких є традиційною столицею раси свинобразів. Розлогий, пронизаний колючками лабіринт приховує справжню армію відданих свинобразів і їхніх верховних жерців — плем'я Мертвої Голови. Та нещодавно на це грубе лігво впала зловісна тінь. Агенти невмерлої Скверни на чолі з лічем Амненнаром Холодоносцем підкорили свинобразів і перетворили лабіринт колючок на бастіон сили невмерлих. \010\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1252277807] = {
        ["english"] = { [1] = "Deeprun Tram" },
        ["text"] = "Глибокобіжний трамвай",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 5595, [5] = 6272, [6] = 6740, [7] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [885133612] = {
        ["english"] = { [1] = "Come in out of the cold and rest your weary bones a while. Our hospitality is yours." },
        ["text"] = "Заходь із холоду й дай натрудженим кісткам перепочити. Наша гостинність — до твоїх послуг.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [417337785] = {
        ["english"] = { [1] = "Bah, that's goblin work!  Still, we have an orc here in Razor Hill that will teach you of such things.  Look for Mukdrak over near the forge." },
        ["text"] = "Ба, то гоблінська робота! Та все ж у Колючому Пагорбі є орк, який навчить тебе таких речей. Шукай Мукдрака біля кузні.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3555078705] = {
        ["english"] = { [1] = "$R, why would I want to talk to you? Your people probably caused this mess in the first place!" },
        ["text"] = "$R, навіщо мені з тобою говорити? Мабуть, саме твій народ і спричинив усе це лихо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [444598785] = {
        ["english"] = { [1] = "Belgaristrasz speaks the truth; the situation is grave indeed.  $B$BThe full power of your drakes has been unlocked.  Use their power to defeat Eregos!" },
        ["text"] = "Белґарістраз каже правду; ситуація справді тяжка. $B$BПовну силу твоїх драконів розблоковано. Скористайся нею, щоб перемогти Ереґоса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2314519343] = {
        ["english"] = { [1] = "Armand Cromwell always on dock in Magic Quarter.  Fish in green goo taste extra good.  You try." },
        ["text"] = "Арманд Кромвелл завжди на причалі в Магічному кварталі. Риба в зеленій гидоті смакує особливо добре. Спробуй.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3327380075] = {
        ["english"] = { [1] = "Burning Steppes - Tablet of the Seven" },
        ["text"] = "Палаючий степ — Скрижаль Сімох",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [424178002] = {
        ["english"] = { [1] = "<Goretooth spits.>$B$BI am a warrior of the Horde, $N. It fills me with rage to know that our enemies sit in a fortress, less than a day's ride from Kargath, plotting against us.$B$BHow I long to break free from the bonds of duty and destroy them all in the name of the Warchief.$B$BAlas, we all have roles we must fulfill.\010" },
        ["text"] = "<Горозуб спльовує.>$B$BЯ воїн Орди, $N. Мене лютить сама думка, що наші вороги сидять у фортеці менш ніж за день їзди від Карґата й плетуть змови проти нас.$B$BЯк же я прагну скинути пута обов'язку й знищити їх усіх в ім'я Воєвождя.$B$BТа, на жаль, кожен із нас має свою роль.\010",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["greeting"] = true },
    },
    [3268571192] = {
        ["english"] = { [1] = "A wondrous Winter's Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum." },
        ["text"] = "Чудового Зимового Покрову тобі... е-е... маленький $G хлопче : дівчино;. Чемні діти отримують особливі, е-е, знижки в будь-якого місцевого продавця Димного Лісу. Ням.",
        ["npcs"] = { [1] = 13444, [2] = 13445 },
        ["roles"] = { ["greeting"] = true },
    },
    [1096444254] = {
        ["english"] = { [1] = "Are you certain?$B$BThere is no turning back once I wipe the knowledge of the talents you have learned from your mind." },
        ["text"] = "Ти певен?$B$BНазад дороги не буде, щойно я зітру з твоєї пам'яті знання про вивчені таланти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2886179394] = {
        ["english"] = { [1] = "Aye, and which battleground be ye looking for?" },
        ["text"] = "Так, а яке поле бою тебе цікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3898592786] = {
        ["english"] = { [1] = "Death to Frostwolf!" },
        ["text"] = "Смерть Морозному Вовку!",
        ["npcs"] = { [1] = 13577 },
        ["roles"] = { ["greeting"] = true },
    },
    [412565914] = {
        ["english"] = { [1] = "Deadmines" },
        ["text"] = "Мертві копальні",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2918190628] = {
        ["english"] = { [1] = "A bank?  Well, the closest bank around here is The Stormwind Counting House.  It's just up the road in Stormwind not far from the gates." },
        ["text"] = "Банк? Найближчий банк тут — Рахункова палата Штормовію. Вона просто далі дорогою в Штормовії, неподалік від брами.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1866848414] = {
        ["english"] = { [1] = "$N, how may I further your training in the eyes of the Earth Mother?" },
        ["text"] = "$N, як я можу продовжити твоє навчання в очах Матері-Землі?",
        ["npcs"] = { [1] = 3034, [2] = 3036, [3] = 3060, [4] = 8142 },
        ["roles"] = { ["greeting"] = true },
    },
    [2665906554] = {
        ["english"] = { [1] = "<Eitrigg laughs.>$B$BYoung one, the world has not always been in such disarray. It was a time before the Scourge had sacked the land. Before those parts of Lordaeron were known as the Plaguelands.$B$BIt was there that Thrall rescued me from death and it was then that I joined the new Horde... but I digress. This is a story for another time. Yes, another time... Perhaps..." },
        ["text"] = "<Айтріґ сміється.>$B$BЮначе, світ не завжди був у такому безладі. Колись Скверна ще не сплюндрувала ці землі, а ті частини Лордерону ще не називали Чумнозем'ям.$B$BСаме там Тралл урятував мене від смерті, і тоді я приєднався до нової Орди... Та я відхилився від теми. Це історія на інший раз. Так, інший раз... Можливо...",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [2149239382] = {
        ["english"] = { [1] = "Aright *hic*... Say, you look familiar *hic*. Have I ever told you about the time me and Windsor fought off thir, er... a thous... a million orcs?$B$BOh settle down friend, this is a good one!" },
        ["text"] = "Добре *гик*... Слухай, ти мені когось нагадуєш *гик*. Я вже розповідав, як ми з Віндзором відбилися від три... е-е... тисячі... мільйона орків?$B$BТа заспокойся, друже, це гарна історія!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2136110201] = {
        ["english"] = { [1] = "<You nod slightly but do not complete the motion as the lord-commander narrows his eyes before he continues.>" },
        ["text"] = "<Ви ледь киваєте, але не завершуєте рух, коли лорд-командир примружує очі й продовжує.>",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3021504171] = {
        ["english"] = { [1] = "De Darkspears have a home again! An' we couldn't have done it wit'out ya helpin', $N. Now, we celebrate!" },
        ["text"] = "Темносписи знов мають дім! І ми б не впоралися без твоєї допомоги, $N. А тепер — святкуємо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3558231607] = {
        ["english"] = { [1] = "$C, Dame Auriferous has conveyed to me her great pleasure in the service that you have done us in the past. She wishes to extend to you her hope that you will continue to be a champion of sin'dorei interests here in the Ghostlands." },
        ["text"] = "$C, пані Авріферус передала мені, що надзвичайно задоволена твоєю попередньою службою. Вона сподівається, що ти й надалі захищатимеш інтереси сін'дорай тут, у Примарокраї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1046965070] = {
        ["english"] = { [1] = "10,000 years of recorded knowledge tends to draw the wrong element to the Athenaeum. Books are stolen, recovered and stolen again on a daily basis." },
        ["text"] = "10 000 років записаних знань мають звичку приваблювати до Читальні небажаних осіб. Книжки крадуть, повертають і знову крадуть щодня.",
        ["npcs"] = { [1] = 14381 },
        ["roles"] = { ["greeting"] = true },
    },
    [2762598474] = {
        ["english"] = { [1] = "All rewards for services rendered to be dispensed by Warcaller Sardon Truslice.$B$BPost no bills." },
        ["text"] = "Усі нагороди за виконану службу видає Закликач війни Сардон Правдоруб.$B$BОголошень не клеїти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3593651960] = {
        ["english"] = { [1] = "Dazalar is well known around Dolanaar for his hunting skill.  Why don't you talk to him and see what he can teach you?" },
        ["text"] = "Дазалар добре знаний у Доланаарі завдяки своїй мисливській майстерності. Чому б тобі не поговорити з ним і не дізнатися, чого він може тебе навчити?",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [4207881839] = {
        ["english"] = { [1] = "Day and night all I do is sit here and make ammo and restring crossbows.$B$BI suppose you want me to do something for you too?" },
        ["text"] = "День і ніч тільки й роблю, що сиджу тут, майструю боєприпаси та перетягую тятиви на арбалетах.$B$BГадаю, ти теж хочеш, щоб я щось для тебе зробив?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2558594886] = {
        ["english"] = { [1] = "<The Frostborn Scout attempts to rise to his feet as you approach, but stumbles back to the ground, clenching an obviously painful wound in his side.>" },
        ["text"] = "<Розвідник Морозородих намагається підвестися, коли ви наближаєтеся, але знову падає на землю, стискаючи явно болючу рану в боці.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1104580435] = {
        ["english"] = { [1] = "Can't you see that I'm busy! We'll never have this base ready in time for the Prince's return!" },
        ["text"] = "Хіба не бачиш, я зайнятий! Ми нізащо не встигнемо підготувати цю базу до повернення принца!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2858302175] = {
        ["english"] = { [1] = "Besides the Grunts outside, my brothers and I fought at the battle of Hyjal. Any who seek to steal from the bank must face us first." },
        ["text"] = "Крім бурмил надворі, ми з братами билися в битві за Гіджал. Кожен, хто захоче пограбувати банк, спершу матиме справу з нами.",
        ["npcs"] = { [1] = 3309, [2] = 3318, [3] = 3320 },
        ["roles"] = { ["greeting"] = true },
    },
    [1446560130] = {
        ["english"] = { [1] = "A thick red slash has been drawn across the words WANTED: Deathclaw.  \"This bounty has been claimed by the heroic $N, who has overcome the fearsome beast,\" declares more writing in the same red ink." },
        ["text"] = "Слова «РОЗШУКУЄТЬСЯ: Смертекіготь» перекреслено товстою червоною рискою. \"Цю нагороду забрав героїчний $N, який здолав страшного звіра\", — проголошує напис тим самим червоним чорнилом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [505597361] = {
        ["english"] = { [1] = "Be sure to tell Greatfather Winter what secret surprise you'd like to get this Winter Veil!" },
        ["text"] = "Не забудь сказати Дідусеві Зимі, який таємний сюрприз хочеш отримати цього Зимового Покрову!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [1079000324] = {
        ["english"] = { [1] = "Blurg awrurgle mrr?" },
        ["text"] = "Блурґ аврурґле мрр?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4087415460] = {
        ["english"] = { [1] = "Dat's da attitude! Grab a needle and thread and let's get jammin'!" },
        ["text"] = "Оце правильний настрій! Хапай голку з ниткою — і до роботи!",
        ["npcs"] = { [1] = 3484 },
        ["roles"] = { ["greeting"] = true },
    },
    [1436582816] = {
        ["english"] = { [1] = "And a good day to ya, brave $c.  I know ya be lookin' for a fine steed.  There's no finer steed than a raptor under your reigns, lemme tell you $g mon : sis;!  Take a look at the ones I got to offer - bred from the fiercest stock anywhere." },
        ["text"] = "І тобі доброго дня, хоробрий $c. Знаю, ти шукаєш доброго скакуна. Немає кращого скакуна, ніж раптор під сідлом, кажу тобі, $g друже : сестро;! Поглянь, що маю — вирощені з найлютішої крові.",
        ["npcs"] = { [1] = 7952 },
        ["roles"] = { ["greeting"] = true },
    },
    [3758850105] = {
        ["english"] = { [1] = "A clear voice rises from within the stone...$B$BYou come to us with title and so we will listen, but do not try our patience, $c.  The council has no time for idle gossip from one such as you." },
        ["text"] = "Із каменя лунає чистий голос...$B$BТи прийшов до нас із титулом, тож ми вислухаємо, але не випробовуй нашого терпіння, $c. Рада не має часу на порожні балачки з такими, як ти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2814403207] = {
        ["english"] = { [1] = "A fierce wind is coming - I can tell by the ache in my exposed knee.  I just hope we don't get caught up in it." },
        ["text"] = "Насувається лютий вітер — коліно, що стирчить назовні, аж ниє. Сподіваюся лише, що він нас не застане.",
        ["npcs"] = { [1] = 11057 },
        ["roles"] = { ["greeting"] = true },
    },
    [301733114] = {
        ["english"] = { [1] = "Can you believe this ethereal technology?!$B$BI'm sure glad they let me stay out here with them.  I'm gonna learn a lot... and maybe get some of it for myself, too!" },
        ["text"] = "Можеш повірити в цю ефіріальну технологію?!$B$BДобре, що вони дозволили мені лишитися тут із ними. Я стільки всього навчуся... і, може, щось собі привласню!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2220711827] = {
        ["english"] = { [1] = "Ameer, Over and out." },
        ["text"] = "Амір, кінець зв'язку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1281647425] = {
        ["english"] = { [1] = "Ah, it's you, $N! Welcome into our sanctuary. Rest and refresh yourself; you have more than earned it." },
        ["text"] = "А, це ти, $N! Ласкаво просимо до нашого святилища. Відпочинь і наберися сил — ти це більш ніж заслужив.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2080529609] = {
        ["english"] = { [1] = "A pure sample would be one that's uncorrupted by unintentional influences. We need to find the creatures in the most basic, normal environment we can.$B$BThat means somewhere devoid of civilization or the effects of the dominant races of Azeroth. Someplace... untouched." },
        ["text"] = "Чистий зразок — це той, що не був спотворений випадковими впливами. Треба знайти створінь у якнайпростішому, природному середовищі.$B$BТобто десь без цивілізації та впливу панівних рас Азероту. У місці... незайманому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3329258652] = {
        ["english"] = { [1] = "Come and take a look at my wares while you still can.  We're here all week, and then we're off to some far off land." },
        ["text"] = "Підійди та поглянь на мій крам, поки ще можеш. Ми тут увесь тиждень, а потім вирушаємо в якісь далекі краї.",
        ["npcs"] = { [1] = 14846 },
        ["roles"] = { ["greeting"] = true },
    },
    [2998997647] = {
        ["english"] = { [1] = "Darkmoon Faire Cards?  See the Professor here for those.  Come see me if you are a dealer in hard to come by antiquities and artifacts." },
        ["text"] = "Карти ярмарку Темного Місяця? За ними звертайся до тутешнього професора. А до мене приходь, якщо торгуєш рідкісними старожитностями й артефактами.",
        ["npcs"] = { [1] = 14846 },
        ["roles"] = { ["greeting"] = true },
    },
    [3612949853] = {
        ["english"] = { [1] = "$G Son : Young lady;, I'm not going to lie to you; things aren't pretty around here.  We're under constant assault by the bugs and our very way of life, our freedom, is at stake!$B$BAre you going to be a responsible citizen and help out?" },
        ["text"] = "$G Синку : Панночко;, не брехатиму: справи тут кепські. Жуки безперервно нас атакують, і сам наш спосіб життя, наша свобода — під загрозою!$B$BТи будеш відповідальним громадянином і допоможеш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3294116663] = {
        ["english"] = { [1] = "Darkmoon Dogs fresh off the grill.  Come and get em while they're hot!" },
        ["text"] = "Сосиски ярмарку Темного Місяця просто з вогню. Налітай, поки гарячі!",
        ["npcs"] = { [1] = 14845 },
        ["roles"] = { ["greeting"] = true },
    },
    [2782091796] = {
        ["english"] = { [1] = "Alas $N, I am much too busy to talk.  As I mentioned, I need time to think on the situation at hand.$B$BI wish you luck in your travels.  Good day." },
        ["text"] = "На жаль, $N, я надто зайнятий для розмов. Як я вже казав, мені потрібен час, щоб обдумати нинішню ситуацію.$B$BБажаю удачі в мандрах. До побачення.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3088000704] = {
        ["english"] = { [1] = "Ah, one of my favorite customers. You look to be of a warlock of some power, $N. I am pleased to meet you. If there is anything I can do for you, please, just ask.$B$BMy brother and I feel that it will be your kind who lead us into the next great era. One with such power... such control... it's only a matter of time before the Legion itself bends to your will.$B$BI am but a little envious." },
        ["text"] = "А, один із моїх улюблених клієнтів. Схоже, ти доволі могутній чорнокнижник, $N. Радий зустрічі. Якщо я можу чимось допомогти — просто скажи.$B$BМи з братом вважаємо, що саме такі, як ти, приведуть нас у нову велику епоху. З такою силою... таким контролем... це лише питання часу, коли сам Легіон схилиться перед твоєю волею.$B$BЯ навіть трохи заздрю.",
        ["npcs"] = { [1] = 2670 },
        ["roles"] = { ["greeting"] = true },
    },
    [1031552577] = {
        ["english"] = { [1] = "Do you know who we are, stranger? We are Mag'har - brown orcs, as I have heard your kind call us. The Mag'har are survivors: Survivors of a fallen dynasty; Survivors of the Red Pox; Survivors of a shattered world...$B$BI am Jorin, son of Kilrogg; last of the lineage of Deadeye: Warchief of the Bleeding Hollow Clan." },
        ["text"] = "Ти знаєш, хто ми, чужинцю? Ми — маґ'хари, бурі орки, як, я чув, нас називає твій народ. Маґ'хари — вцілілі: вцілілі після падіння династії; вцілілі після Червоної віспи; вцілілі після розколу світу...$B$BЯ — Джорін, син Кілроґґа; останній із роду Мертвого Ока, воєвождя клану Кривавої Очниці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2613274258] = {
        ["english"] = { [1] = "All is gathered, $c. All is being transported for final preparation to Silithus and should arrive within a day. All of our combined forces await the $g hero : heroine; that will complete the reunification of the Scepter of the Shifting Sands, ring the gong and begin the Ahn'Qiraj War." },
        ["text"] = "Усе зібрано, $c. Усе перевозять до Силітуса для останньої підготовки й мають доставити протягом дня. Усі наші об'єднані сили чекають на $g героя : героїню;, що завершить відновлення Скіпетра Мінливих Пісків, ударить у гонг і розпочне війну за Ан'Кіраж.",
        ["npcs"] = { [1] = 15453 },
        ["roles"] = { ["greeting"] = true },
    },
    [1021211072] = {
        ["english"] = { [1] = "Ah, yes, that... the name. Well... as they say, a good name, like good will, is got by many actions and lost by one. No need to go into the hows or whys; suffice to say, that is how I am named by some." },
        ["text"] = "А, так, це... ім'я. Ну... як кажуть, добре ім'я, як і добру славу, здобувають багатьма вчинками, а втрачають одним. Не будемо розбиратися, як і чому; досить сказати, що дехто називає мене саме так.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [359472295] = {
        ["english"] = { [1] = "A Rut'theran Ferry leaves for Auberdine from Rut'theran Village at the base of Teldrassil.  The portal in Darnassus will allow you to reach Rut'theran safely." },
        ["text"] = "Пором із Рут'терана відпливає до Аубердіна із селища Рут'теран біля підніжжя Тельдрассіла. Портал у Дарнасі дозволить безпечно дістатися Рут'терана.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [937989549] = {
        ["english"] = { [1] = "Dagger instruction can be sought from two weapon masters: Archibald in the War Quarter of the Undercity and Sayoc within the Valley of Honor in Orgrimmar." },
        ["text"] = "Навчитися володіти кинджалом можна у двох збройових майстрів: Арчибальда у Військовому кварталі Підміста та Сайока в Долині Честі в Орґріммарі.",
        ["npcs"] = { [1] = 11869 },
        ["roles"] = { ["greeting"] = true },
    },
    [252050111] = {
        ["english"] = { [1] = "Beware of entering Frostwolf territory, soldier. The whole damn place is booby trapped! Landmines galore! Speak with our explosives expert in the first tower on the front lines for more information. I am certain that he could teach you how to diffuse the situation." },
        ["text"] = "Обережно заходь на територію Морозного Вовка, солдате. Все те прокляте місце в пастках! Мін повно! Поговори з нашим фахівцем із вибухівки в першій вежі на передовій. Певен, він навчить тебе розряджати ситуацію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1292806323] = {
        ["english"] = { [1] = "Ah, as the title states I am an assassin for the Scarlet Crusade. I spend my days exterminating high priority targets and nights at the Gadgetzan discotheque. Dancing is my true calling. Assassination just pays the bills." },
        ["text"] = "Так, як і сказано в титулі, я вбивця Багряного Походу. Вдень я знищую особливо важливі цілі, а вночі танцюю на дискотеці Пристробляска. Танці — моє справжнє покликання. Убивства просто оплачують рахунки.",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [431157885] = {
        ["english"] = { [1] = "Dagger" },
        ["text"] = "Кинджал",
        ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11869 },
        ["roles"] = { ["reply"] = true },
    },
    [1901661624] = {
        ["english"] = { [1] = "By the grace of Elune, I am pleased to offer you the finest steed found anywhere in Teldrassil, and perhaps the world - the nightsaber.  For years, the Sentinel Army has relied on the value of these companions.$B$BTake your time friend and examine each one to your satisfaction.  I am sure you will not be disappointed." },
        ["text"] = "З ласки Елуни я радий запропонувати тобі найкращого скакуна на всьому Тельдрассілі, а може, й у світі — нічного шаблезуба. Роками армія Вартових покладається на цих вірних супутників.$B$BНе поспішай, друже, оглянь кожного як слід. Певен, ти не розчаруєшся.",
        ["npcs"] = { [1] = 4730 },
        ["roles"] = { ["greeting"] = true },
    },
    [2478377394] = {
        ["english"] = { [1] = "Another material $gboy : girl; are we?  Well, if you are obsessed with your precious items then you will probably want to store them at the Darnassus Bank in the center of our city." },
        ["text"] = "Ще один $gхлопче : дівчино;, одержимий речами? Якщо так дорожиш своїми скарбами, мабуть, захочеш зберігати їх у банку Дарнаса в центрі міста.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1494877540] = {
        ["english"] = { [1] = "Cyndra's knowledge in alchemy is somewhat limited, but I'm sure it would be sufficient to get you started.  She practices her craft just east of the Inn in Dolanaar." },
        ["text"] = "Знання Сіндри з алхімії дещо обмежені, але для початку цього цілком вистачить. Вона займається ремеслом трохи на схід від заїжджого двору в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1474051238] = {
        ["english"] = { [1] = "Bandages, anti-venoms and such things, these are the inevitable necessities of life on the plains.  Vira Younghoof can teach you this knowledge.  You can find her in the long house on the west side of Bloodhoof Village." },
        ["text"] = "Бинти, протиотрути та подібні речі — неминуча необхідність життя на рівнинах. Віра Молоде Копито може навчити тебе цього. Знайдеш її у довгому будинку на західному боці селища Криваве Копито.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [510803646] = {
        ["english"] = { [1] = "As I understand it dear, everything has been gathered and the final materiel is being assembled and shipped off to Cenarion Hold. The last of it should arrive in less than a day. Once our equipment and forces are all there, the bearer of the Scepter of the Shifting Sands can ring the gong near Ahn'Qiraj to open the gates. Then the war will begin." },
        ["text"] = "Наскільки я розумію, любий, усе вже зібрано, а останні припаси комплектують і відправляють до Кенарієвої цитаделі. Решта має прибути менш ніж за день. Коли все спорядження й сили будуть там, носій Скіпетра Мінливих Пісків зможе вдарити в гонг біля Ан'Кіражу й відкрити брами. Тоді почнеться війна.",
        ["npcs"] = { [1] = 15446 },
        ["roles"] = { ["greeting"] = true },
    },
    [2501073339] = {
        ["english"] = { [1] = "Curse? What's going on here, Fairbanks?" },
        ["text"] = "Прокляття? Що тут відбувається, Феєрбенксе?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [2607855156] = {
        ["english"] = { [1] = "Can you see them, mortal? No... I did not think you could. Sighted but sightless - it is your gift and your curse." },
        ["text"] = "Бачиш їх, смертний? Ні... я й не думав, що побачиш. Зрячий, але сліпий — це твій дар і твоє прокляття.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["greeting"] = true },
    },
    [2713938495] = {
        ["english"] = { [1] = "Bones... flesh... muscles... tendons... cartilage... it all comes together here under my hacksaw." },
        ["text"] = "Кістки... плоть... м'язи... сухожилля... хрящі... усе сходиться тут, під моєю ножівкою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3029114566] = {
        ["english"] = { [1] = "Axe" },
        ["text"] = "Сокира",
        ["npcs"] = { [1] = 11866, [2] = 11867, [3] = 11869, [4] = 11870, [5] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [3505225165] = {
        ["english"] = { [1] = "Crossbow" },
        ["text"] = "Арбалет",
        ["npcs"] = { [1] = 2704, [2] = 11865, [3] = 11866, [4] = 11868, [5] = 11869 },
        ["roles"] = { ["reply"] = true },
    },
    [661205112] = {
        ["english"] = { [1] = "A fellowship of kindred spirits can be a powerful force.  Krumn will help you to achieve this.  You will find him at the Thunder Bluff Civic Information center on the lower rise next to the lifts." },
        ["text"] = "Товариство споріднених душ може стати великою силою. Крумн допоможе тобі цього досягти. Знайдеш його в Центрі громадської інформації Громового Бескиду на нижньому ярусі біля підіймачів.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [78091021] = {
        ["english"] = { [1] = "\"It is too soon for you to control me, for you have recently left the game.\"" },
        ["text"] = "\"Ще зарано тобі керувати мною, адже ти нещодавно покинув гру.\"",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [688945805] = {
        ["english"] = { [1] = "\"Taurahe?\"$B$BThe tauren druid looks at you expectantly, but it is clear you cannot verbally communicate with her.  Undaunted, she points to herself and smiles.  She points at you and smiles once more.  She finally motions several times down the path to the south.$B$BPerhaps she is indicating that there is a druid you can speak to further down the road?\010" },
        ["text"] = "\"Таураге?\"$B$BДруїдка-тауренка очікувально дивиться на вас, але очевидно, що ви не можете порозумітися з нею словами. Не знітившись, вона вказує на себе й усміхається. Потім вказує на вас і знову всміхається. Насамкінець кілька разів показує вздовж стежки на південь.$B$BМожливо, вона натякає, що далі дорогою є друїд, з яким ви зможете поговорити?\010",
        ["npcs"] = { [1] = 9529 },
        ["roles"] = { ["greeting"] = true },
    },
    [498333285] = {
        ["english"] = { [1] = "A large humanoid hand print is embedded on the surface of the orb. Despite what appears to be constant manipulation and handling, the orb remains unmarred." },
        ["text"] = "На поверхні кулі відтиснута велика гуманоїдна долоня. Попри те, що кулю, схоже, постійно чіпають і крутять, на ній немає жодного пошкодження.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3226077997] = {
        ["english"] = { [1] = "As you wish, $N. The spirit hunter is ready." },
        ["text"] = "Як забажаєш, $N. Мисливець на духів готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4078643009] = {
        ["english"] = { [1] = "Delivering these barrels to the excavation site is hard work, but there are so many depending on us to get the blast powder there.$B$BWe must do what we can against the Dark Irons!" },
        ["text"] = "Доставляти ці бочки до місця розкопок — важка праця, але стільки людей покладаються на нас, щоб вибуховий порох потрапив туди.$B$BМи мусимо зробити все, що можемо, проти Темного Заліза!",
        ["npcs"] = { [1] = 2057 },
        ["roles"] = { ["greeting"] = true },
    },
    [2147978076] = {
        ["english"] = { [1] = "Captain Galvangar is the trusted aid to Drek'Thar.  He leads the Horde forces from the Iceblood Garrison, in the southern section of the the Field of Strife.$B$BCaptain Galvangar is currently in the Iceblood Garrison." },
        ["text"] = "Капітан Ґалванґар — довірений помічник Дрек'Тара. Він очолює сили Орди з гарнізону Крижаної Крові, у південній частині Поля Чвар.$B$BНаразі капітан Ґалванґар перебуває в гарнізоні Крижаної Крові.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1905018646] = {
        ["english"] = { [1] = "Are you mad? Look around you, mortal. Do you not see that you stand upon sundered earth? Leave this place lest you suffer as my people and I have..." },
        ["text"] = "Ти божевільний? Озирнися, смертний. Хіба не бачиш, що стоїш на розколотій землі? Іди звідси, інакше спіткає тебе те саме, що мене й мій народ...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [815237207] = {
        ["english"] = { [1] = "<Varnis coughs violently as the restorative draught takes effect.>$B$BThank you for rescuing me.  I must go back to Tranquillien at once!" },
        ["text"] = "<Варніс сильно кашляє, коли відновлювальний настій починає діяти.>$B$BДякую, що врятував мене. Я мушу негайно повернутися до Транквілієна!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1578196565] = {
        ["english"] = { [1] = "Could night elf saboteurs be behind this?  I doubt it.  With the load we've been putting on the West Sanctum it was only a matter of time until something went wrong." },
        ["text"] = "Невже за цим стоять диверсанти нічних ельфів? Сумніваюся. З таким навантаженням, яке ми давали Західному Святилищу, було лише питанням часу, коли щось піде не так.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3614043472] = {
        ["english"] = { [1] = "'Ello, $c!$b$bYa ready ta head on down to Venture Bay and crack some Horde skulls?" },
        ["text"] = "Привіт, $c!$b$bГотовий вирушити до Бухти Торгівців і натовкти кілька ординських черепів?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2361679979] = {
        ["english"] = { [1] = "Close, but no cigar! I'm afraid you'll have to talk to my sis, Jemma first. After she's gone over the basics with you, come see me and I'll show you the juicy stuff!" },
        ["text"] = "Майже, але не зовсім! Боюся, спершу доведеться поговорити з моєю сестрою Джеммою. Коли вона пояснить тобі основи, повертайся — і я покажу найцікавіше!",
        ["npcs"] = { [1] = 11029 },
        ["roles"] = { ["greeting"] = true },
    },
    [448176627] = {
        ["english"] = { [1] = "A battle?" },
        ["text"] = "Битва?",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["reply"] = true },
    },
    [558208050] = {
        ["english"] = { [1] = "Copy, Status report, Soldier." },
        ["text"] = "Прийнято. Доповідай обстановку, солдате.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1494541099] = {
        ["english"] = { [1] = "Copy that, Araxes. Backup is on the way. Hold your position. I repeat, Hold your Position" },
        ["text"] = "Прийнято, Араксесе. Підкріплення вже в дорозі. Тримай позицію. Повторюю: тримай позицію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3106129092] = {
        ["english"] = { [1] = "<The Tuskarr eyes you suspiciously.>$b$bDo not stay long. You do not understand our people, and I don't want trouble." },
        ["text"] = "<Калуак підозріло дивиться на вас.>$b$bНе затримуйся тут. Ти не розумієш наш народ, а мені не потрібні проблеми.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2033324338] = {
        ["english"] = { [1] = "After the fall of Karazhan, the Kirin Tor dispatched an assembly of mages to search the tower and seize all items of import... for the purposes of \"research.\" It was then that the fabled staff was discovered and brought back to Dalaran." },
        ["text"] = "Після падіння Каражану Кірін-Тор відрядив загін магів обшукати вежу й вилучити всі важливі предмети... задля «досліджень». Саме тоді легендарний посох знайшли й доправили до Даларана.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3763253144] = {
        ["english"] = { [1] = "All rewards to be paid by High Executor Wroth upon verification.$B$BSerious-minded individuals inquire within.$B$BNO SOLICITORS!" },
        ["text"] = "Усі нагороди виплачує верховний виконавець Рот після перевірки.$B$BСерйозні особи можуть звертатися всередині.$B$BБЕЗ ТОРГОВИХ АГЕНТІВ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3889944534] = {
        ["english"] = { [1] = "<As you place your apexis shards into the fel crystalforge and pull the lever, the device makes an unworldly sound as it grinds them into dust.  A few moments later your flask pops out of its 'mouth'.>" },
        ["text"] = "<Коли ви кладете уламки апекситу до кристалокузні Скверни й тягнете важіль, пристрій видає потойбічний звук, перемелюючи їх на порох. За кілька митей із його \"рота\" вискакує ваш флакон.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3077765398] = {
        ["english"] = { [1] = "A warlock?  Well, if I was a warlock, I would probably be in the darkest place around here... which would be the Lion's Pride Inn basement.  That's where you should look first." },
        ["text"] = "Чорнокнижник? Якби я був чорнокнижником, то, мабуть, сидів би в найтемнішому місці поблизу... тобто в підвалі таверни «Левова Гордість». Там і шукай спершу.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3555456661] = {
        ["english"] = { [1] = "Cool your heels!$B$B<Bodley grumbles something under his breath about the impatience of the living>$B$BAs I was saying, Lord Valthalak's spirit and spectral assassins, summoned forth through his necromantic dabbling, started to assail us. Let me tell you, at that point we weren't in any condition to fight back, so we ran. I can still remember Mor Grayhoof, one of our druids, slip and fall at one point into the lower reaches of the spire.$B$BThe rest as they say, is history." },
        ["text"] = "Не гарячкуй!$B$B<Бодлі бурмоче собі під ніс щось про нетерплячість живих>$B$BЯк я й казав, дух лорда Валталаку та примарні вбивці, яких він викликав своїми некромантськими дослідами, почали нападати на нас. Повір, тоді ми були зовсім не в стані дати відсіч, тож утекли. Я й досі пам'ятаю, як Мор Сиве Копито, один із наших друїдів, послизнувся й упав у нижні яруси шпиля.$B$BА решта, як то кажуть, уже історія.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3317936133] = {
        ["english"] = { [1] = "<Thrall laughs.>$B$BSo much to learn still, $r.$B$BYou are too young to remember the wars and bloodshed of ages past. Too young to remember the burden of the curse carried by our people.$B$BOur position with the Alliance right now is a tenuous one. Skirmishes and smaller battles do take place, but there is peace - something our people have not known for millennia. Would you give this up and plunge us into the maw of chaos again but against a new foe? One that will not rest until we are all destroyed?" },
        ["text"] = "<Тралл сміється.>$B$BТобі ще стільки всього треба дізнатися, $r.$B$BТи надто молодий, щоб пам'ятати війни й кровопролиття минулих епох. Надто молодий, щоб пам'ятати тягар прокляття, яке ніс наш народ.$B$BНаші відносини з Альянсом нині дуже крихкі. Сутички й невеликі битви трапляються, та все ж панує мир — те, чого наш народ не знав тисячоліттями. Невже ти відмовишся від цього й знову кинеш нас у пащу хаосу, цього разу проти нового ворога? Ворога, який не спочине, доки не знищить нас усіх?",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [80787670] = {
        ["english"] = { [1] = "$G Mister:Missy;, if I didn't know better, I'd think you were one of them 'special' peoples. We call em Troggs.$B$BWindsor didn't have no beef with the Dark Irons, after all, his great, great, grand pappy's best friend was a Dark Iron. Which is also probably why that army of Dark Irons didn't kill him on sight." },
        ["text"] = "$G Пане:Панно;, якби я не знав краще, подумав би, що ти з тих особливих. Ми їх звемо трогами.$B$BУ Віндзора не було ворожнечі з Темним Залізом — зрештою, найкращим другом його прапрапрадіда був дворф Темного Заліза. Мабуть, саме тому та армія Темного Заліза й не вбила його на місці.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [572261794] = {
        ["english"] = { [1] = "And now the war, it be comin' soon. All that be left is the sendin' of all these goods and weapons to the Cenarion Hold in Silithus, and that is gonna be done within a day. Then some brave soul is gonna have to be ringin' the gong near those Ahn'Qiraj gates to open 'em and start the war." },
        ["text"] = "А тепер війна вже близько. Лишилося тільки доправити всі ці товари й зброю до Кенарієвої цитаделі в Силітусі, і це буде зроблено протягом дня. Потім якась хоробра душа муситиме вдарити в гонг біля брам Ан'Кіражу, щоб відкрити їх і розпочати війну.",
        ["npcs"] = { [1] = 15469 },
        ["roles"] = { ["greeting"] = true },
    },
    [1637909271] = {
        ["english"] = { [1] = "$G Sir : Ma'am;! I'm here to assist and defend you.$B$BYour orders?" },
        ["text"] = "$G Пане : пані;! Я тут, щоб допомагати й захищати вас.$B$BВаші накази?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2656438762] = {
        ["english"] = { [1] = "<Isfar sighs.>$B$BA couple of treehouses don't make a home, but it was vast improvement over the Sethekk Halls.$B$BComfortable as it was in Shattrath, I can't bring myself to return to my true home in Skettis without my sister. She's still trapped in the Sethekk Halls, held prisoner by our older brother." },
        ["text"] = "<Ісфар зітхає.>$B$BКілька будиночків на деревах — ще не дім, але це було незрівнянно краще за Сетеккські зали.$B$BХоч у Шаттраті й було затишно, я не можу змусити себе повернутися до справжнього дому в Скеттісі без сестри. Вона досі в пастці в Сетеккських залах, у полоні нашого старшого брата.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1886256845] = {
        ["english"] = { [1] = "Ahhh... Ironfoe.", [2] = "Ahhh... Ironfoe.\010" },
        ["text"] = "А-а-а... Залізний Ворог.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["reply"] = true },
    },
    [1117632175] = {
        ["english"] = { [1] = "Continue..." },
        ["text"] = "Продовжуй...",
        ["npcs"] = { [1] = 9021, [2] = 10296, [3] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [2484952252] = {
        ["english"] = { [1] = "Blackfathom Deeps" },
        ["text"] = "Чорноводні глибини",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [3278090291] = {
        ["english"] = { [1] = "Come to buy from Hargus, you have?" },
        ["text"] = "До Гарґуса купувати прийшов?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3264839512] = {
        ["english"] = { [1] = "Capturing the Sun's Reach Sanctum was the first step in our battle plan.  Our orders are to take control of the armory next.$B$BWe are $3233w percent done with our goal." },
        ["text"] = "Захоплення Святилища Сонячного Краю було першим кроком нашого бойового плану. Тепер нам наказано взяти під контроль зброярню.$B$BМи виконали $3233w відсотків поставленої мети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [323932273] = {
        ["english"] = { [1] = "Armor like the kind you make could stop even the sharpest axe. I'm impressed $N, that doesn't happen often. Seek out an Orc named Shayis Steelfury, she makes the best armor outside of that cursed Dwarven stronghold." },
        ["text"] = "Обладунок такого рівня, як ти куєш, зупинить навіть найгострішу сокиру. Я вражений, $N, а це трапляється нечасто. Знайди орчиню на ім'я Шайїс Сталелють — вона кує найкращі обладунки поза тією проклятою дворфівською твердинею.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3867987899] = {
        ["english"] = { [1] = "<The falcon squawks hungrily for a grub.>" },
        ["text"] = "<Сокіл голодно скрикує, випрошуючи личинку.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2857578384] = {
        ["english"] = { [1] = "Continue with your story." },
        ["text"] = "Продовжуй свою розповідь.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [2954017461] = {
        ["english"] = { [1] = "Call me \"Boss\".  What have you got for me!" },
        ["text"] = "Називай мене «Бос». Що приніс?",
        ["npcs"] = { [1] = 14321 },
        ["roles"] = { ["reply"] = true },
    },
    [3557329400] = {
        ["english"] = { [1] = "Any news from home, $c?" },
        ["text"] = "Є новини з дому, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3439776471] = {
        ["english"] = { [1] = "A treasure hunter's life is a treacherous one. Don't be foolin' yerself." },
        ["text"] = "Життя шукача скарбів сповнене небезпек. Не обманюй себе.",
        ["npcs"] = { [1] = 6301 },
        ["roles"] = { ["greeting"] = true },
    },
    [1149709754] = {
        ["english"] = { [1] = "Continue please." },
        ["text"] = "Продовжуй, будь ласка.",
        ["npcs"] = { [1] = 8479, [2] = 8888, [3] = 16112, [4] = 16132 },
        ["roles"] = { ["reply"] = true },
    },
    [2077295980] = {
        ["english"] = { [1] = "Continue please, Fairbanks." },
        ["text"] = "Продовжуй, будь ласка, Феєрбенксе.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [4041693803] = {
        ["english"] = { [1] = "Conspiracies abound, I say.  There are those who lack vision in understanding what I do, and would seek to keep me shackled to obscurity!$B$BDon't step in the dirt." },
        ["text"] = "Змови всюди, кажу тобі. Є ті, кому бракує далекоглядності, щоб зрозуміти мою працю, і вони прагнуть навіки прикувати мене до забуття!$B$BТільки не наступи в багнюку.",
        ["npcs"] = { [1] = 9047 },
        ["roles"] = { ["greeting"] = true },
    },
    [2116975072] = {
        ["english"] = { [1] = "All that official business is handled up in Stormwind these days.  You could stop by the Stormwind Visitor's Center if you want to start a guild." },
        ["text"] = "Усі офіційні справи нині вирішують у Штормовії. Якщо хочеш заснувати гільдію, зайди до Центру відвідувачів Штормовію.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1185248156] = {
        ["english"] = { [1] = "A very sad tale. Thank you, spirit." },
        ["text"] = "Дуже сумна історія. Дякую тобі, духу.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [629726421] = {
        ["english"] = { [1] = "A thunderous voice bellows from the stone...$B$BGreetings, commander. What news of Silithus do you bring the Lords of the Council?" },
        ["text"] = "Із каменя гримить громовий голос...$B$BВітаю, командире. Які звістки із Силітуса ти приніс Володарям Ради?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1685239] = {
        ["english"] = { [1] = "A valuable skill First Aid is.  Our resident trainer, Nissa Firestone, can show ye how it's done.  Look for her on the southern side of The Great Forge at the Ironforge Physician." },
        ["text"] = "Перша допомога — дуже цінна навичка. Наша місцева наставниця Нісса Вогнекамінь покаже, як це робиться. Шукай її на південному боці Великої Кузні, у стальгорнського лікаря.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2949196802] = {
        ["english"] = { [1] = "Consider all of the suffering that the Scarlets have caused over the years. The torture, the zealotry, the murder.$B$BI won't allow that to continue. Will you?" },
        ["text"] = "Згадай усі страждання, яких Багряні завдали за ці роки. Катування, фанатизм, убивства.$B$BЯ не дозволю цьому тривати. А ти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1115079653] = {
        ["english"] = { [1] = "Commonly found on the lesser chromatic flight: Whelps, broodlings, lesser wyrmkin." },
        ["text"] = "Зазвичай трапляються серед молодших представників хроматичної зграї: дракончики, дитинчата та молодші драконолюди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [896206672] = {
        ["english"] = { [1] = "BOOM!$b$bThat's the last thing I remember..." },
        ["text"] = "БУМ!$b$bЦе останнє, що я пам'ятаю...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3929370782] = {
        ["english"] = { [1] = "Come, take a trip to the wonderful, gorgeous, tropical jungles of Stranglethorn. That's right, you too can be spending your time sunbathing by the crystal blue waters while I stand here in this unbearable heat with nothing to look at but my brother Frezza all day! Enjoy your trip!" },
        ["text"] = "Вирушай у подорож до дивовижних, прекрасних тропічних джунглів Тернистої долини. Саме так: ти теж зможеш засмагати біля кришталево-блакитних вод, поки я стирчатиму тут у цій нестерпній спеці й цілими днями дивитимусь лише на свого брата Фреззу! Щасливої подорожі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2660935893] = {
        ["english"] = { [1] = "Did the Scryers send you to contact me?  You do not look like a Scryer at all." },
        ["text"] = "Тебе Провидці послали зв'язатися зі мною? На Провидця ти зовсім не схожий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [771162316] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke B, a security level beta terminal.$B$BYou must posses a yellow punch card to access terminal functions.\010\01001000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-B, термінала рівня безпеки бета.$B$BДля доступу до функцій термінала потрібна жовта перфокартка.\010\01001000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3318118915] = {
        ["english"] = { [1] = "Come, Battle-Sister.$B$BFeast, sleep, so that you may fight with all your strength!" },
        ["text"] = "Підійди, бойова сестро.$B$BПоїж, поспи, щоб битися на повну силу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2866097272] = {
        ["english"] = { [1] = "Come, $r. What formula interests you today?" },
        ["text"] = "Підходь, $r. Яка формула цікавить тебе сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [452948063] = {
        ["english"] = { [1] = "Brother Wilhelm often trains with Lyria Du Lac out in back of the smithy in Goldshire.  You could probably learn a thing or two about being a paladin from him." },
        ["text"] = "Брат Вільгельм часто тренується з Лірією Дю Лак позаду кузні в Злотохресті. У нього можна дечого навчитися про шлях паладина.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [53378130] = {
        ["english"] = { [1] = "Come to make yourself useful?" },
        ["text"] = "Прийшов зробити щось корисне?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [776082951] = {
        ["english"] = { [1] = "Bandages? Why, do you intend to survive long enough to need them? Har! Very well, $r, I will tell you. Of the $2080w wool bandaged needed, we have collected $2079w. Also to date, we have taken in $2085w out of $2086w mageweave bandages, and $2089w of $2090w runecloth bandages asked for." },
        ["text"] = "Бинти? А ти збираєшся прожити достатньо довго, щоб вони знадобилися? Ха! Гаразд, $r, скажу. Із потрібних $2080w вовняних бинтів ми зібрали $2079w. Також маємо $2085w із $2086w бинтів із маготканини та $2089w із $2090w потрібних бинтів із рунічної тканини.",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [685496302] = {
        ["english"] = { [1] = "Ah, my sweet Brandy, I miss her so!" },
        ["text"] = "Ах, моя люба Бренді, як же я за нею сумую!",
        ["npcs"] = { [1] = 11316 },
        ["roles"] = { ["greeting"] = true },
    },
    [2054629376] = {
        ["english"] = { [1] = "Ah, a fellow ranger. What do you need?" },
        ["text"] = "А, колего-слідопите. Що тобі потрібно?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1583656545] = {
        ["english"] = { [1] = "$N, have ye any idea o' what we're up against in Alterac Valley?  Are ye ready to fight the Frostwolf Clan?" },
        ["text"] = "$N, ти хоч уявляєш, проти чого ми виступаємо в Альтерацькій долині? Готовий битися з кланом Морозного Вовка?",
        ["npcs"] = { [1] = 12197 },
        ["roles"] = { ["greeting"] = true },
    },
    [139153948] = {
        ["english"] = { [1] = "Come to learn, eh? Well I just might have some work for you, scrub." },
        ["text"] = "Учитися прийшов, еге ж? Що ж, може, і робота для тебе знайдеться, салаго.",
        ["npcs"] = { [1] = 13776 },
        ["roles"] = { ["greeting"] = true },
    },
    [3550011905] = {
        ["english"] = { [1] = "$950w, soldier." },
        ["text"] = "$950w, солдате.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1390925394] = {
        ["english"] = { [1] = "Ah, um, yes $g sir : ma'am;. It would appear that we have collected all of the medium leather that the Alliance feels is necessary for the war. I'm told that there may be others here though that still need your assistance with their collection efforts." },
        ["text"] = "А, е-е, так, $g пане : пані;. Схоже, ми зібрали всю середню шкіру, яку Альянс вважає необхідною для війни. Кажуть, тут іще є інші, кому потрібна твоя допомога зі зборами.",
        ["npcs"] = { [1] = 15448 },
        ["roles"] = { ["greeting"] = true },
    },
    [1106612212] = {
        ["english"] = { [1] = "Bite your tongue, $r, lest I rip it from your skull case and use it as a horn warmer." },
        ["text"] = "Прикуси язика, $r, поки я не вирвав його з твоєї черепної коробки й не використав як утеплювач для рога.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["greeting"] = true },
    },
    [3334043309] = {
        ["english"] = { [1] = "<Thrall laughs.>$B$BNoted... Now pay attention, $N. The Black Dragonflight brood mother, Onyxia, has been flushed out from her position of power in Stormwind. She has escaped, fleeing to her lair in Dustwallow Marsh.$B$BShe cannot be allowed to live in such close proximity to our capital cities. We must strike before being struck!$B$BI want her destroyed, $N. " },
        ["text"] = "<Тралл сміється.>$B$BЗрозуміло... А тепер слухай уважно, $N. Матір виводка Чорної драконячої зграї, Оніксію, викрили й вигнали з її владної позиції в Штормовії. Вона втекла до свого лігва в Бруднолипкій трясовині.$B$BНе можна дозволити їй жити так близько до наших столиць. Ми мусимо вдарити першими!$B$BЯ хочу, щоб її знищили, $N. ",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [2343517422] = {
        ["english"] = { [1] = "Brave soldier of the Horde, I salute you! We would have surely been destroyed by the Alliance gunship had it not been for you and your allies.$B$BTake a moment to rest before we begin our assault upon the upper reaches of the citadel." },
        ["text"] = "Хоробрий солдате Орди, віддаю тобі честь! Якби не ти й твої союзники, корабель Альянсу напевно знищив би нас.$B$BВідпочинь трохи перед тим, як ми почнемо штурм верхніх ярусів цитаделі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2008409221] = {
        ["english"] = { [1] = "Be careful around these parts, $r. The natives are ruthless." },
        ["text"] = "Обережніше тут, $r. Місцеві безжальні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1089250883] = {
        ["english"] = { [1] = "All of the preparations are complete now, $c. We await the last of the materiel to be sent to Silithus, which should be in less than $2113w day's time. Then once the organization there is done with, someone will have to come forward and ring the gong on the Scarab Dais with the Scepter of the Shifting Sands. That is when the Ahn'Qiraj War will begin. May the Earth Mother watch over all of us then." },
        ["text"] = "Уся підготовка завершена, $c. Чекаємо останніх припасів до Силітуса — вони мають прибути менш ніж за $2113w днів. Потім, коли там усе впорядкують, хтось муситиме вийти вперед і вдарити Скіпетром Мінливих Пісків у гонг на Помості Скарабея. Саме тоді почнеться війна за Ан'Кіраж. Нехай Матір-Земля береже нас усіх.",
        ["npcs"] = { [1] = 15532 },
        ["roles"] = { ["greeting"] = true },
    },
    [571040004] = {
        ["english"] = { [1] = "<Drawn out on this parchment is the schematic for a field repair robot.>" },
        ["text"] = "<На цьому пергаменті накреслено схему польового ремонтного робота.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1052735923] = {
        ["english"] = { [1] = "$C, we are not ashamed to say that we are in need of all of the assistance that we can get in our fight at Warsong Gulch.  But there is greater honor to be had now than at any time in the past if you so choose to lend us your skills.  As well, the Silverwing Sentinels are sure to look more favorably upon your efforts on our behalf.  Will you join the battle?" },
        ["text"] = "$C, ми не соромимося визнати, що в боротьбі в Ущелині Пісні Війни нам потрібна вся допомога, яку тільки можемо отримати. Та нині можна здобути більше честі, ніж будь-коли раніше, якщо ти вирішиш застосувати свої вміння на нашу користь. До того ж Вартові Срібнокрилих неодмінно прихильніше поставляться до твоїх зусиль заради нас. Приєднаєшся до битви?",
        ["npcs"] = { [1] = 15102 },
        ["roles"] = { ["greeting"] = true },
    },
    [3591846476] = {
        ["english"] = { [1] = "<The blood elf lies on the floor in some manner of induced torpor.>" },
        ["text"] = "<Ельф крові лежить на підлозі в неприродно глибокому заціпенінні.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2438038898] = {
        ["english"] = { [1] = "Come to learn from the master eh?" },
        ["text"] = "Прийшов учитися в майстра, еге ж?",
        ["npcs"] = { [1] = 6707 },
        ["roles"] = { ["greeting"] = true },
    },
    [4177822144] = {
        ["english"] = { [1] = "Come learn the ways of the hunter. Pride, honor, and tradition." },
        ["text"] = "Приходь пізнати шлях мисливця. Гордість, честь і традиції.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [710265194] = {
        ["english"] = { [1] = "Do you hear the call of the hunt, $c?  You must listen closely, but the call comes from deep within you.  It comes from deep within all of us." },
        ["text"] = "Чуєш поклик полювання, $c? Слухай уважно: цей поклик лунає з глибини тебе. З глибини кожного з нас.",
        ["npcs"] = { [1] = 12696 },
        ["roles"] = { ["greeting"] = true },
    },
    [3737031663] = {
        ["english"] = { [1] = "Ah, ye're an inquisitive one, are ye'? Excellent! Pay close attention, this just might save yer skin when the goin' gets rough!" },
        ["text"] = "А, допитливий ти, еге ж? Чудово! Слухай уважно — це може врятувати твою шкуру, коли справи підуть кепсько!",
        ["npcs"] = { [1] = 11065 },
        ["roles"] = { ["greeting"] = true },
    },
    [3798850665] = {
        ["english"] = { [1] = "Come in out of the ash and muck. Dry yourself a spell." },
        ["text"] = "Заходь, сховайся від попелу й багнюки. Трохи обсохни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2509880762] = {
        ["english"] = { [1] = "Do I know you?" },
        ["text"] = "Я тебе знаю?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [206345005] = {
        ["english"] = { [1] = "Come for some blacksmithing supplies, have ya?" },
        ["text"] = "Прийшов по ковальські припаси, еге ж?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [417121605] = {
        ["english"] = { [1] = "Come closer, young one; my ears aren't what they once were, and I care not for raising my voice." },
        ["text"] = "Підійди ближче, юний друже; слух у мене вже не той, а кричати я не люблю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3302415773] = {
        ["english"] = { [1] = "Away to Thunder Bluff to the north is where your journey takes you then friend.  Once there seek out the wisdom of one of the Bluffwatchers who can tell you directly where to find whom you seek." },
        ["text"] = "Твій шлях веде на північ до Громового Бескиду, друже. Коли дістанешся, знайди когось із Вартових Бескиду — він точно підкаже, де шукати потрібну людину.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [2367309348] = {
        ["english"] = { [1] = "After what seemed an eternity, the Vindicator lost consciousness. The torture was too much, even for him. The cruel one - Matis as I found out he was called - attempted to wake Saruan by splashing contagion laced water across his ravaged body. But Saruan did not wake.$B" },
        ["text"] = "Після того, що здавалося вічністю, оборонець знепритомнів. Навіть для нього тортури виявилися надто тяжкими. Жорстокий — я згодом дізнався, що його звали Матіс — спробував розбудити Саруана, обливаючи його понівечене тіло водою, зараженою пошестю. Але Саруан не прокинувся.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [885302548] = {
        ["english"] = { [1] = "Are you kidding me? You must be kidding me! Either that or you think I'm a clown here to amuse you. Is that what you think? That I'm a clown? Huh, is it! You think I'm a clown don't you!" },
        ["text"] = "Ти жартуєш? Ти, певно, жартуєш! Або вважаєш мене клоуном, який тут тебе розважає. Так думаєш? Що я клоун? Га, так?! Думаєш, я клоун, правда?!",
        ["npcs"] = { [1] = 2836 },
        ["roles"] = { ["greeting"] = true },
    },
    [2839427942] = {
        ["english"] = { [1] = "Ah, Stonebrow doesn't leave Ironforge much these days so if ye're looking to learn the tailor's profession ye'll have to go to see him up in Ironforge." },
        ["text"] = "А, Кам'янобровий нині майже не покидає Стальгорна, тож якщо хочеш опанувати кравецтво, доведеться піднятися до нього в Стальгорн.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [4253724420] = {
        ["english"] = { [1] = "[ph]Learn recipe..." },
        ["text"] = "[ph]Вивчити рецепт...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2464804487] = {
        ["english"] = { [1] = "Ah, to be young again, and to have discovered potions for the first time. Thank you for refreshing my memory, $N. Now go share that youthful enthusiasm with Milla Fairancora over there." },
        ["text"] = "Ах, знову б бути молодим і вперше відкрити для себе зілля. Дякую, що освіжив мою пам'ять, $N. А тепер поділися цим юнацьким запалом із Міллою Фейранкорою он там.",
        ["npcs"] = { [1] = 11042 },
        ["roles"] = { ["greeting"] = true },
    },
    [677781887] = {
        ["english"] = { [1] = "$C, hold your attack, this is just a disguise!  I'm a spy working for the Lower City coalition out of Shattrath City.$B$BI hope you're here to help!" },
        ["text"] = "$C, не нападай, це лише маскування! Я шпигун коаліції Нижнього Міста з Шаттрата.$B$BСподіваюся, ти тут, щоб допомогти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3929614009] = {
        ["english"] = { [1] = "Come again." },
        ["text"] = "Заходь ще.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [4110933061] = {
        ["english"] = { [1] = "About damn time someone came. What took you so long? Ah, nevermind. Cover me, soldier. I gotta make it back to base!" },
        ["text"] = "Нарешті хтось прийшов, хай йому грець. Чого так довго? Та байдуже. Прикрий мене, солдате. Мені треба повернутися на базу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3550807606] = {
        ["english"] = { [1] = "Collection of bandages is proceeding according to schedule. As far as linen bandages are concerned, we've gathered $2076w of $2077w. Silk bandages have been tallied at $2082w out of $2083w, and we have $2088w out of $2090w runecloth bandages needed." },
        ["text"] = "Збір бинтів іде за планом. Лляних бинтів ми зібрали $2076w із $2077w. Шовкових бинтів нараховано $2082w із $2083w, а бинтів із рунічної тканини — $2088w із потрібних $2090w.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [2759716812] = {
        ["english"] = { [1] = "Bixi Wobblebonk, the gnome weapon master, is wandering about in this shop.  She can teach crossbow, daggers and throwing weapons.\010\010Woo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff.\010\010Ilyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons." },
        ["text"] = "Біксі Хитрокіст, гномка-майстриня зброї, ходить десь у цій крамниці. Вона навчає арбалетів, кинджалів і метальної зброї.\010\010Ву Пін, людський майстер зброї в Арсеналі Веллера у Штормовії, навчає арбалетів, кинджалів, одноручних і дворучних мечів, древкової зброї та посохів.\010\010Іленія Місячний Вогонь, майстриня зброї нічних ельфів, мешкає на Терасі Воїнів у Дарнасі, де навчає луків, кинджалів, кулачної зброї, посохів і метальної зброї.",
        ["npcs"] = { [1] = 11865 },
        ["roles"] = { ["greeting"] = true },
    },
    [1538145352] = {
        ["english"] = { [1] = "Are you daft? Did you miss the BONY SKELETAL CREATURES littering the landscape on your way over here?$B$B<Rohan sighs.>$B$BIf you're the outdoor type, you'll find skeletal creatures all over both the Western and Eastern Plaguelands. Trust me, you can't miss 'em - they certainly won't miss you if they get the chance.$B$BIf you're a dungeon type, Stratholme and Scholomance are definitely the place to be for bone fragments." },
        ["text"] = "Ти що, дурний? Не помітив КІСТЛЯВИХ СКЕЛЕТНИХ ІСТОТ, якими всіяна земля дорогою сюди?$B$B<Роган зітхає.>$B$BЯкщо любиш полювати просто неба, скелетних істот повно і в Західному, і в Східному Чумнозем'ї. Повір, їх не пропустиш — і вони тебе теж не пропустять, якщо матимуть нагоду.$B$BЯкщо тобі до вподоби підземелля, то Стратгольм і Некроситет — саме те місце для уламків кісток.",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [3697762802] = {
        ["english"] = { [1] = "\"Pilgrim's Bounty.\" Hrm. I can understand the tauren's eagerness to express their sense of gratitude and comraderie to the Horde's warchief, but the Forsaken?$B$BI imagined they would have dropped such sentimental traditions long ago." },
        ["text"] = "\"Щедроти Пілігрима\". Гм. Я можу зрозуміти прагнення тауренів висловити вдячність і товариськість воєвождю Орди, але Відречені?$B$BЯ гадав, вони давно вже відкинули такі сентиментальні традиції.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3494803695] = {
        ["english"] = { [1] = "All of the food and war materiel we gathered is on its way to Silithus. It should be there in less than a day. Someone told me that once it's all assembled over near Cenarion Hold, someone's going to have to go ring the gong at the Scarab Dais to open the gates to Ahn'Qiraj and start the war." },
        ["text"] = "Уся їжа й воєнні припаси, які ми зібрали, вже прямують до Силітуса. Вони мають бути там менш ніж за день. Мені сказали, що коли все це зберуть біля Кенарієвої цитаделі, хтось муситиме піти до Помосту Скарабея й ударити в гонг, щоб відкрити брами Ан'Кіражу та розпочати війну.",
        ["npcs"] = { [1] = 15456 },
        ["roles"] = { ["greeting"] = true },
    },
    [1776223672] = {
        ["english"] = { [1] = "Clyde Kellen, the local bass master, has his favorite fishing spot just east of Brill at Brightwater Lake." },
        ["text"] = "Клайд Келлен, місцевий майстер ловлі окуня, має улюблене місце для риболовлі на схід від Брілля, біля Ясноводного озера.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [2190753884] = {
        ["english"] = { [1] = "<The apprentice occasionally looks over his shoulder, apparently responding to sounds that you can't hear.>$B$BGood day, $N. Pardon me if I seem distracted, but I'm in the middle of a job for Farmer Natin. I want to have all of his horses shoed by the time he returns from the town hall. What can I help you with?" },
        ["text"] = "<Учень час від часу озирається через плече, ніби реагуючи на звуки, яких ви не чуєте.>$B$BДобридень, $N. Даруйте, якщо я здаюся неуважним, але я саме виконую роботу для фермера Натіна. Хочу підкувати всіх його коней до того, як він повернеться з ратуші. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1097884478] = {
        ["english"] = { [1] = "Ameer might be worried about what the Ethereum are doing but I'm squarely focused on the real danger here: Dimensius." },
        ["text"] = "Аміра може непокоїти те, що робить Етерій, але я зосереджений на справжній небезпеці — Дименсіусі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1340579506] = {
        ["english"] = { [1] = "A clear voice rises from within the stone...$B$BWhere is your Medallion of Station, little one?  You may not speak with a Duke without proof of title..." },
        ["text"] = "Із каменя лунає чистий голос...$B$BДе твій Медальйон звання, малий? Ти не можеш говорити з герцогом без доказу титулу...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3965940659] = {
        ["english"] = { [1] = "Cloth is okay. Personally I prefer to work with human skin." },
        ["text"] = "Тканина — непогано. Але особисто я волію працювати з людською шкірою.",
        ["npcs"] = { [1] = 4576 },
        ["roles"] = { ["greeting"] = true },
    },
    [2074080738] = {
        ["english"] = { [1] = "Aye, ya never know who's gunna join next, or who be dyin' next for that matter.$b$bMy advice? Don't be gettin' too attached to anyone." },
        ["text"] = "Авжеж, ніколи не знаєш, хто приєднається наступним... чи хто наступним помре.$b$bМоя порада? Не прив'язуйся надто сильно ні до кого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [57088927] = {
        ["english"] = { [1] = "Can you tell me more about this place?" },
        ["text"] = "Можеш розповісти мені більше про це місце?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [2230260104] = {
        ["english"] = { [1] = "Can you hear it speaking in your mind?" },
        ["text"] = "Чуєш, як воно говорить у твоїй голові?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1340364681] = {
        ["english"] = { [1] = "<You are well versed in the creation and function of this robot.>" },
        ["text"] = "<Ви добре знаєте будову та принцип роботи цього робота.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2714402017] = {
        ["english"] = { [1] = "Arnok makes good bandages.  Find him at the Survival of the Fittest hut on the shore of the lake next to Spirit Lodge in the Valley of Spirits.  It's above and to the west of the Valley of Strength." },
        ["text"] = "Арнок робить добрі бинти. Знайдеш його в хатині «Виживає найсильніший» на березі озера біля Оселі Духів у Долині Духів. Це вище й на захід від Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [756862874] = {
        ["english"] = { [1] = "Correct. You've been listening! This minnow is really quite a terrible creature of my own creation. When I am relaxing I like to think of the unlucky fishermen who have run into this minnow and been devoured whole. I bet they were quite surprised!$B$B<Azuregos laughs.>" },
        ["text"] = "Правильно. Ти уважно слухав! Ця рибка — насправді жахливе створіння мого власного витвору. Коли я відпочиваю, люблю уявляти невдачливих рибалок, які натрапили на неї й були проковтнуті живцем. Ото вони, мабуть, здивувалися!$B$B<Азуреґос сміється.>",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [3987342446] = {
        ["english"] = { [1] = "Cleanse your hands before you begin any project. Staining the leather with blood or dirt would take away from its natural beauty." },
        ["text"] = "Вимий руки, перш ніж братися до будь-якої роботи. Кров чи бруд на шкірі зіпсують її природну красу.",
        ["npcs"] = { [1] = 3008 },
        ["roles"] = { ["greeting"] = true },
    },
    [413026438] = {
        ["english"] = { [1] = "Died? Are you cracked, $N? Excuse me, $g Mister:Miss; $N! Windsor wouldn't have died from no fifty orcs. As sure as Thelsamar blood sausage is the tastiest food the world may ever know, there he stood: He was covered in orc chunks from head to toe, drenched in about eighteen layers of their blood, but he was definitely alive... and really, really angry." },
        ["text"] = "Помер? Ти геть здурів, $N? Перепрошую, $g Пане:Панно; $N! Віндзор не загинув би від якихось п'ятдесяти орків. Так само певно, як телсамарська кров'яна ковбаса — найсмачніша їжа у світі, він стояв там: з ніг до голови вкритий шматками орків, залитий десь вісімнадцятьма шарами їхньої крові, але безперечно живий... і дуже, дуже розлючений.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3502108952] = {
        ["english"] = { [1] = "$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?" },
        ["text"] = "$C, нам потрібна твоя допомога в Ущелині Пісні Війни. Допоможеш нам у боротьбі проти Вершників Пісні Війни?",
        ["npcs"] = { [1] = 14982 },
        ["roles"] = { ["greeting"] = true },
    },
    [3969929059] = {
        ["english"] = { [1] = "Chu'a'lor's been saying good things about you, $N.  If you want, we have a couple of special ogre brews for sale.$B$BThey're really tasty!" },
        ["text"] = "Чу'а'лор добре про тебе відгукувався, $N. Якщо хочеш, у нас є на продаж кілька особливих огрячих напоїв.$B$BВони справді смачні!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1508690131] = {
        ["english"] = { [1] = "<Eris nods.>$B$BThe Eye has seen so many horrors and so many wonders.$B$BIt displays what it feels the one looking into it is most suited to see." },
        ["text"] = "<Еріс киває.>$B$BОко бачило стільки жахіть і стільки див.$B$BВоно показує те, що, на його думку, найкраще пасує тому, хто в нього дивиться.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3050585565] = {
        ["english"] = { [1] = "At last, the curse is lifted. Thank you, hero." },
        ["text"] = "Нарешті прокляття знято. Дякую тобі, герою.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [4091682561] = {
        ["english"] = { [1] = "Chief Bloodhoof, this may sound like an odd request... but I have a young ward who is quite shy.  You are a hero to him, and he asked me to get your hoofprint." },
        ["text"] = "Вождю Криваве Копито, це може прозвучати дивно... але в мене є юний підопічний, дуже сором'язливий. Ти для нього герой, і він попросив мене взяти відбиток твого копита.",
        ["npcs"] = { [1] = 3057 },
        ["roles"] = { ["reply"] = true },
    },
    [1298946490] = {
        ["english"] = { [1] = "... A message from Banehollow?  What message is that?  Does he have need of his great advisor and servant, Ulathek?  Does he require my presence?" },
        ["text"] = "... Послання від Бейнхоллоу? Яке ще послання? Невже йому потрібен його великий радник і слуга, Улатек? Він вимагає моєї присутності?",
        ["npcs"] = { [1] = 14523 },
        ["roles"] = { ["greeting"] = true },
    },
    [1557439066] = {
        ["english"] = { [1] = "Cherry pie is my favoritist food in all of Azeroth." },
        ["text"] = "Вишневий пиріг — моя найулюбленіша їжа в усьому Азероті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [188970803] = {
        ["english"] = { [1] = "Arathi Basin has been overrun by The Defilers.  Will you help us, $N?" },
        ["text"] = "Низину Араті захопили Осквернителі. Допоможеш нам, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3382213601] = {
        ["english"] = { [1] = "Ah, you seek Dark Cleric Beryl.  He's upstairs in the reading room at the Gallows' End Tavern.  Reading, praying, who knows what he's up to, and who would dare to ask?" },
        ["text"] = "А, ти шукаєш Темного клірика Берила. Він нагорі, в читальній кімнаті таверни «Кінець Шибеника». Читає, молиться — хто знає, що він там робить, і хто наважиться спитати?",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3223789535] = {
        ["english"] = { [1] = "Although I am flattered by your confidence in my abilities, teaching you is beyond my skill. You must go to the Craftsmen's Terrace in Darnassus, and speak with the night elf Ainethil. She can help you." },
        ["text"] = "Мені приємна твоя довіра до моїх здібностей, але навчати тебе вже понад мої сили. Іди на Терасу Ремісників у Дарнасі й поговори з нічною ельфійкою Айнетіль. Вона тобі допоможе.",
        ["npcs"] = { [1] = 3964 },
        ["roles"] = { ["greeting"] = true },
    },
    [881297538] = {
        ["english"] = { [1] = "At the southeast edge of town is the Gallows' End Tavern.  Go there and head upstairs, and you'll find Dark Cleric Beryl inside the reading room." },
        ["text"] = "На південно-східній околиці містечка стоїть таверна «Кінець Шибеника». Іди туди, піднімися нагору — у читальній кімнаті знайдеш Темного клірика Берила.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [157464682] = {
        ["english"] = { [1] = "Can you enchant my axe?  I'll want a permanent.  Maybe later then.  Find Godan's Runeworks on the west end of The Drag near the Valley of Wisdom." },
        ["text"] = "Можеш зачарувати мою сокиру? Хочу постійне зачарування. Гаразд, іншим разом. Шукай «Рунічні роботи Ґодана» на західному кінці Хитрого провулка біля Долини Мудрості.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3503829687] = {
        ["english"] = { [1] = "Check out Dawnstrider Enchanters on the middle rise then.  Teg will be more than happy to help you in whatever way he can." },
        ["text"] = "Тоді зазирни до «Зачарувань Світанкового Мандрівника» на середньому уступі. Теґ залюбки допоможе тобі, чим зможе.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2073808641] = {
        ["english"] = { [1] = "$N, it's good to see you again!  Are you having fun at the Faire?$B$BWant to arm wrestle?  No, of course not... you want to keep your arm!" },
        ["text"] = "$N, радий знову тебе бачити! Весело тобі на ярмарку?$B$BХочеш поборотися на руках? Ні, звісно ж ні... рука тобі ще знадобиться!",
        ["npcs"] = { [1] = 14832 },
        ["roles"] = { ["greeting"] = true },
    },
    [3428638129] = {
        ["english"] = { [1] = "Caught unaware? How?" },
        ["text"] = "Застали зненацька? Як?",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["reply"] = true },
    },
    [281559701] = {
        ["english"] = { [1] = "[In broken Common] It is time celebrate we do." },
        ["text"] = "[Ламаною повселюдною] Час святкувати нам настав.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [826460652] = {
        ["english"] = { [1] = " A former student of mine by the name of Krixix spent a lifetime attempting to make contact with the chained Gods of the underworld. He pursued that which would spring up from the ravaged earth... That which would form only as a result of the elements clashing in the titanic conflict.$B$BElementium as it would be known to mortals.$B$BOne day, nearly a decade ago, Krixix's pursuit lead to a fissure forming in this very gorge." },
        ["text"] = " Колишній мій учень на ім'я Кріксікс присвятив життя спробам установити зв'язок із закутими богами підземного світу. Він шукав те, що постане зі сплюндрованої землі... Те, що утворюється лише внаслідок зіткнення стихій у титанічному протистоянні.$B$BЕлементій — так назвали б його смертні.$B$BОдного дня, майже десять років тому, пошуки Кріксікса призвели до утворення тріщини саме в цій ущелині.",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["greeting"] = true },
    },
    [2872006923] = {
        ["english"] = { [1] = "Check around Old Town at the Barracks or the Pig and Whistle Tavern. If you go to the tavern, be sure to sample some of the fine brews. Puts the dwarven ales to shame, I tell ya." },
        ["text"] = "Пошукай у Старому місті — в казармах або в таверні «Свиня і Свисток». Якщо зайдеш до таверни, неодмінно скуштуй місцевого пива. Дворфійське йому й у підметки не годиться, кажу тобі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2585431277] = {
        ["english"] = { [1] = "Chapter on Skin of Shadow." },
        ["text"] = "Розділ про шкіру тіні.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [739694004] = {
        ["english"] = { [1] = "Certainly, $N. You only need to tell me what reputation you would like to know about.\010" },
        ["text"] = "Авжеж, $N. Просто скажи, про яку репутацію ти хочеш дізнатися.\010",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["greeting"] = true },
    },
    [3731319283] = {
        ["english"] = { [1] = "A mere three hundred years ago, a reckless dwarf named Thaurissan summoned the master from his fiery realm. His return to this paltry world devastated the surrounding lands and created this volcanic Core. Mighty Ragnaros has slept under this mountain ever since. \010" },
        ["text"] = "Лише три сотні років тому нерозважливий дворф на ім'я Тауріссан викликав Повелителя з його вогняного царства. Його повернення до цього жалюгідного світу спустошило навколишні землі й породило це вулканічне Ядро. Відтоді могутній Раґнарос спить під цією горою. \010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2165380585] = {
        ["english"] = { [1] = "Chapter on Enchanted Scarlet Thread." },
        ["text"] = "Розділ про зачаровану багряну нитку.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1348495512] = {
        ["english"] = { [1] = "<Kharan sighs.>$B$BI suppose... I suppose you are right.$B$BGor'shak told me that your Warchief has big plans. Plans that may change the way the Alliance and Horde interact. What do you know about this?" },
        ["text"] = "<Харан зітхає.>$B$BМабуть... Мабуть, ти маєш рацію.$B$BҐор'шак казав мені, що у твого Воєвождя великі плани. Плани, які можуть змінити відносини між Альянсом і Ордою. Що ти про це знаєш?",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [4094326378] = {
        ["english"] = { [1] = "Chapter on Arcane Crystals and Arcanite." },
        ["text"] = "Розділ про арканічні кристали та арканіт.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1963417938] = {
        ["english"] = { [1] = "Champion $N, it is good to see you again.$B$BHave you returned to Valhalas to assist a friend with their challenges?" },
        ["text"] = "Чемпіоне $N, радий знову тебе бачити.$B$BТи повернувся до Вальгаласа, щоб допомогти другові з його випробуваннями?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [771642889] = {
        ["english"] = { [1] = "Certainly, $N.$B$BAdventurers that the Dawn views as honored must submit a combined total of 40 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 150 insignias.$B$BI must admit, the price is high even for those honored amongst the Dawn.\010" },
        ["text"] = "Авжеж, $N.$B$BШукачі пригод, яких Світанок вважає шанованими, мають здати загалом 40 відзнак, щоб отримати доступ до кращих предметів. Для доступу до ще могутніших предметів потрібно здати загалом 150 відзнак.$B$BМушу визнати, ціна висока навіть для тих, кого Світанок шанує.\010",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["greeting"] = true },
    },
    [742275946] = {
        ["english"] = { [1] = "Come, come. If you've properly prepared your leather for once, I'll show you how to fashion serviceable items." },
        ["text"] = "Підійди, підійди. Якщо цього разу ти як слід підготував шкіру, я покажу, як робити з неї добротні речі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [898326413] = {
        ["english"] = { [1] = "Chapter on Frayed Abomination Stitchings." },
        ["text"] = "Розділ про розтріпані шви мерзотища.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1444550003] = {
        ["english"] = { [1] = "Certainly, $g sir:miss;. We were once servants of the house Barov: What is now known as the Scholomance.$B$BI was the head maid and Lucien was Master Barov's butler.$B$BWe had worked for the Barovs for decades, until...$B$B<Eva weeps.>" },
        ["text"] = "Авжеж, $g пане:панно;. Колись ми служили дому Барових — у тому місці, яке тепер називають Некроситетом.$B$BЯ була старшою покоївкою, а Люсьєн — дворецьким пана Барова.$B$BМи служили Баровим десятиліттями, аж поки...$B$B<Єва плаче.>",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [858636451] = {
        ["english"] = { [1] = "Central ring.  You go!" },
        ["text"] = "Центральне коло. Іди!",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [4117534529] = {
        ["english"] = { [1] = "A diary with yellowing pages lies open to the last entry:$B$B\"I don't know what's going to happen now that Harold's turned.  It took everything out of me to drag him into the only place I could find that'd lock him up tight and hold him.  I hid the key on me, and I pray it works...$B$BI hope I can get out of here, but I need money to do that.  Our stuff's all in the cabinet I think... and now that I think about it, doesn't Harold keep the key on him?$B$BI'll rest on it, I'm dead tired now.\"" },
        ["text"] = "Щоденник із пожовклими сторінками лежить розгорнутий на останньому записі:$B$B\"Не знаю, що тепер буде, відколи Гарольд перетворився. Я витратив усі сили, щоб затягти його в єдине місце, яке вдалося знайти, де його можна надійно замкнути. Ключ я сховав при собі й молюся, щоб це спрацювало...$B$BСподіваюся, мені вдасться звідси вибратися, але для цього потрібні гроші. Усі наші речі, здається, в шафі... хоча, якщо подумати, хіба Гарольд не носить ключ із собою?$B$BПосплю й вирішу. Я смертельно втомився.\"",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [23772924] = {
        ["english"] = { [1] = "Another lovely day on our beautiful island." },
        ["text"] = "Ще один чудовий день на нашому прекрасному острові.",
        ["npcs"] = { [1] = 11277 },
        ["roles"] = { ["greeting"] = true },
    },
    [935214775] = {
        ["english"] = { [1] = "Be gone!  I hold counsel with Dreadlords, and the matters we discuss are not your concern!" },
        ["text"] = "Геть! Я радюся з володарями жаху, і наші справи тебе не стосуються!",
        ["npcs"] = { [1] = 14523 },
        ["roles"] = { ["greeting"] = true },
    },
    [548268095] = {
        ["english"] = { [1] = "Budd's crew, ye mean? Aye, he be no respecter of persons. He'll take on anyone who can work a shovel.$b$b'cept them undead. Budd hates 'em. Scared of 'em, likely as not.$B" },
        ["text"] = "Команда Бадда, кажеш? Авжеж, йому байдуже, хто ти. Візьме будь-кого, хто може працювати лопатою.$b$bКрім невмерлих. Бадд їх ненавидить. А може, просто боїться.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2654365327] = {
        ["english"] = { [1] = "All has been gathered and is being sent to Silithus, $c. It should get there within $2113w days. I can only hope that after the gong is rung, and the gates opened, that our efforts here will make an impact and save many lives." },
        ["text"] = "Усе зібрано й відправляється до Силітуса, $c. Має прибути менш ніж за $2113w днів. Можу лише сподіватися, що коли вдарять у гонг і відкриють брами, наші зусилля справді щось змінять і врятують багато життів.",
        ["npcs"] = { [1] = 15528 },
        ["roles"] = { ["greeting"] = true },
    },
    [3532691572] = {
        ["english"] = { [1] = "Can you feel the evil to the south?  By the Hand, it must be cleansed!" },
        ["text"] = "Відчуваєш зло на півдні? Десницею, його треба очистити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [195596327] = {
        ["english"] = { [1] = "Can't help you. You know more about potions than I do. Besides, I have pots to watch. Talk to Yelmak over there. He knows a lot about potions." },
        ["text"] = "Не можу допомогти. Ти знаєш про зілля більше за мене. Та й мені треба стежити за казанами. Поговори он із Єлмаком. Він багато знає про зілля.",
        ["npcs"] = { [1] = 11046 },
        ["roles"] = { ["greeting"] = true },
    },
    [3512588601] = {
        ["english"] = { [1] = "As expected, the Horde has completed all of their preparations well in advance of you and your so-called Alliance. You are all holding us up as we cannot take final measures to begin the war until you finish your promised responsibilities.$B$BNow go and pull your weight, $r." },
        ["text"] = "Як і очікувалося, Орда завершила всі приготування задовго до тебе й твого так званого Альянсу. Ви всі нас затримуєте, бо ми не можемо перейти до останніх кроків перед війною, доки ви не виконаєте обіцяних обов'язків.$B$BА тепер іди й зроби свою частину, $r.",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [4016015911] = {
        ["english"] = { [1] = "Bronzebeard's gone missing again! That dwarf sure didn't get any of his brother's good senses." },
        ["text"] = "Бронзобородий знову зник! Цьому дворфу точно не дісталося здорового глузду його брата.",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [2525538869] = {
        ["english"] = { [1] = "...pan fried, deep fried, and stir fried..." },
        ["text"] = "...смажене на пательні, у фритюрі та у воку...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2114299008] = {
        ["english"] = { [1] = "Alegorn is a masterful chef who has had centuries with which to perfect his cooking.  You should consider yourself blessed should he decide to teach you.  If you believe you are worthy, you can find him in the Craftsmen's Terrace." },
        ["text"] = "Алегорн — майстерний кухар, який мав століття, щоб довести своє ремесло до досконалості. Якщо він погодиться тебе навчати — вважай себе благословенним. Якщо вважаєш себе гідним, знайдеш його на Терасі Ремісників.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [1503029911] = {
        ["english"] = { [1] = "Continue, please.", [2] = "Continue, please.\010" },
        ["text"] = "Продовжуй, будь ласка.",
        ["npcs"] = { [1] = 11286, [2] = 14347, [3] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [2650789877] = {
        ["english"] = { [1] = "<Volcor doesn't look at you at all as you get close to him. He seems to be concentrating on keeping his bandages from falling off. After a moment, he looks up at you, a little startled.>$B$BOh, sorry, $c. Now's not a good time. I hope you understand." },
        ["text"] = "<Волкор узагалі не дивиться на вас, коли ви наближаєтеся. Схоже, він зосередився на тому, щоб його бинти не сповзли. За мить він підводить на вас погляд, трохи здивований.>$B$BО, вибач, $c. Зараз не найкращий час. Сподіваюся, ти розумієш.",
        ["npcs"] = { [1] = 3692 },
        ["roles"] = { ["greeting"] = true },
    },
    [4220228815] = {
        ["english"] = { [1] = "Captain Selana has instructed me to assist you with your efforts here on the Sunwell Plateau." },
        ["text"] = "Капітан Селана наказала мені допомагати тобі в твоїх справах тут, на плато Сонячного Колодязя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [543245176] = {
        ["english"] = { [1] = "Another one, eh? You'll never make it..." },
        ["text"] = "Ще один, еге ж? Тобі не вижити...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [198900762] = {
        ["english"] = { [1] = "Captain Galvangar has been slain!  Honor our fallen captain, and unleash yourself again the Alliance!" },
        ["text"] = "Капітана Ґалванґара вбито! Вшануй нашого полеглого капітана й з новою люттю кинься на Альянс!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4098129812] = {
        ["english"] = { [1] = "Captain Balinda Stonehearth leads the front line Alliance forces.  She is based in the Stonehearth Outpost, in the northern section of the Field of Strife.$B$BBalinda is currently in Stonehearth Outpost." },
        ["text"] = "Капітан Балінда Кам'яне Вогнище очолює передові сили Альянсу. Вона перебуває на заставі Кам'яного Вогнища, у північній частині Поля Чвар.$B$BНаразі Балінда перебуває на заставі Кам'яного Вогнища.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [834256473] = {
        ["english"] = { [1] = "Candy! That's what I'm talking about; I just wish I didn't have to run around finding it!" },
        ["text"] = "Цукерки! Оце вже діло; шкода тільки, що за ними доводиться стільки бігати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3340506859] = {
        ["english"] = { [1] = "Can't you see we're trying to prepare for Uther's visit? Now get out of my way, I have much work to do!" },
        ["text"] = "Хіба не бачиш, ми готуємося до візиту Утера? А тепер геть з дороги, у мене багато роботи!",
        ["npcs"] = { [1] = 11277 },
        ["roles"] = { ["greeting"] = true },
    },
    [3505871595] = {
        ["english"] = { [1] = "A list... how intriguing.  Ah yes, the shipment of fireworks for Lord Saltheril.  He hasn't paid for them; are you here to purchase them on his behalf, $c?" },
        ["text"] = "Список... як цікаво. Ага, так, партія феєрверків для лорда Салтеріла. Він за них не заплатив; ти тут, щоб придбати їх від його імені, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [869174005] = {
        ["english"] = { [1] = "<Narain holds an unopened envelope to his forehead.>$B$BWhat is... Mmmm... Velvet!$B$BAm I right?" },
        ["text"] = "<Нарайн притискає нерозкритий конверт до чола.>$B$BЩо це... М-м-м... Оксамит!$B$BЯ вгадав?",
        ["npcs"] = { [1] = 11811 },
        ["roles"] = { ["greeting"] = true },
    },
    [1980681100] = {
        ["english"] = { [1] = "Can't you see that I've got places to go and people to see! Step aside, peasant!" },
        ["text"] = "Хіба не бачиш, у мене купа справ і людей, яких треба відвідати! З дороги, селюче!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1752245442] = {
        ["english"] = { [1] = "Can't you see I've got work to do here?" },
        ["text"] = "Хіба не бачиш, у мене тут роботи по горло?",
        ["npcs"] = { [1] = 14843, [2] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [368317300] = {
        ["english"] = { [1] = "Alright, I admit it, you've proven yourself and then some, $N.$B$BIf I was hard on you before it was because I saw the spark of a true Skyguard within you.  I dare say that you're the finest ace that we have!$B$BAnytime that you want to help out, I'll be more than proud to hand you another set of bombs." },
        ["text"] = "Гаразд, визнаю: ти довів свою силу й навіть більше, $N.$B$BЯкщо раніше я був суворий, то лише тому, що бачив у тобі іскру справжнього Небесного Вартового. Смію сказати, ти найкращий ас, який у нас є!$B$BКоли тільки захочеш допомогти, я з гордістю дам тобі ще один комплект бомб.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1296044288] = {
        ["english"] = { [1] = "Are you reporting for duty, $c? All of the war materiel for both the Horde and the Alliance is completed and being shipped to Silithus as we speak. It should all arrive in less than a day. I hope that someone has found the different pieces of the Scepter of the Shifting Sands and put them all together." },
        ["text"] = "Прибув на службу, $c? Усі воєнні припаси і для Орди, і для Альянсу вже готові й просто зараз відправляються до Силітуса. Усе має прибути менш ніж за день. Сподіваюся, хтось уже знайшов усі частини Скіпетра Мінливих Пісків і зібрав їх докупи.",
        ["npcs"] = { [1] = 15445 },
        ["roles"] = { ["greeting"] = true },
    },
    [3235852797] = {
        ["english"] = { [1] = "<The complicated schematics are too much for your meager engineering talents to discern.>" },
        ["text"] = "<Ці складні креслення надто заплутані для ваших скромних інженерних навичок.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3150771864] = {
        ["english"] = { [1] = "Can't you see I'm fishing here!" },
        ["text"] = "Хіба не бачиш, я рибалю!",
        ["npcs"] = { [1] = 4314 },
        ["roles"] = { ["greeting"] = true },
    },
    [1394220578] = {
        ["english"] = { [1] = "Alright. Where?" },
        ["text"] = "Гаразд. Де?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [3129163822] = {
        ["english"] = { [1] = "Before his banishment, Deathwing was attempting to create impure offspring. Half breeds that would not only be immune to the innate natural powers and abilities of their Aspects but also under the complete control of Deathwing.$B$BIt seems that where his father failed, Nefarian may have succeeded - at least partially.$B$BIt was Ysera, Aspect of Dreams, who saw the abominations and forced us to act. If these 'Chromatic' dragonkin exist, they must be destroyed." },
        ["text"] = "До свого вигнання Смертекрил намагався створити нечисте потомство. Напівкровок, які не лише були б несприйнятливі до природжених сил та здібностей своїх Аспектів, а й повністю підкорялися б Смертекрилу.$B$BСхоже, де його батько зазнав невдачі, Нефаріан міг досягти хоча б часткового успіху.$B$BСаме Ізера, Аспект Снів, побачила ці потвори й змусила нас діяти. Якщо ці «хроматичні» драконоїди існують, їх треба знищити.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [2013851181] = {
        ["english"] = { [1] = "Can't thank ya enough fer helpin' with the mines. Now, it's just a matter of convincing the miners to get back to work." },
        ["text"] = "Не можу достатньо подякувати тобі за допомогу з копальнями. Тепер лишилося тільки переконати шахтарів повернутися до роботи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1637276174] = {
        ["english"] = { [1] = "Careful, $N.  Where are your cultist robes?" },
        ["text"] = "Обережно, $N. Де твої шати культиста?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2126841009] = {
        ["english"] = { [1] = "$C, please listen to what I have to say. The Alliance and Horde are preparing for a war with the Silithid and their masters in Ahn'Qiraj. Any assistance that you can lend will be greatly appreciated. As you can see, I am collecting thorium bars here for the war effort. We need to gather $2012w in total, and currently we have $2011w." },
        ["text"] = "$C, вислухай мене. Альянс і Орда готуються до війни із силітидами та їхніми господарями в Ан'Кіражі. Будь-яка твоя допомога буде високо цінуватися. Як бачиш, я збираю торієві зливки для воєнних потреб. Загалом нам потрібно $2012w, а зараз маємо $2011w.",
        ["npcs"] = { [1] = 15432 },
        ["roles"] = { ["greeting"] = true },
    },
    [3076921376] = {
        ["english"] = { [1] = "Can't help ya, $n. I only train rogues." },
        ["text"] = "Не можу тобі помогти, $n. Я навчаю тільки розбійників.",
        ["npcs"] = { [1] = 916, [2] = 1234, [3] = 5165, [4] = 5166, [5] = 5167 },
        ["roles"] = { ["greeting"] = true },
    },
    [4203980979] = {
        ["english"] = { [1] = "Adele Fielder has made a name for herself as a leatherworker around Elwynn.  You can find her working out of her home up by Crystal Lake." },
        ["text"] = "Адель Філдер здобула собі ім'я як шкіряниця в Ельвині. Знайдеш її за роботою вдома біля Кришталевого озера.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3368750736] = {
        ["english"] = { [1] = "<The footman stand resolute, muscles tense.>" },
        ["text"] = "<Піхотинець стоїть непохитно, напруживши м'язи.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [552005146] = {
        ["english"] = { [1] = "A good club can make all the difference in the world." },
        ["text"] = "Добра дубина може вирішити все.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3060616808] = {
        ["english"] = { [1] = "Can ye hear it, stranger? The humming is gettin' louder with each passing day. These crystals must be what's driving these bugs crazy." },
        ["text"] = "Чуєш, чужинцю? Гудіння стає гучнішим щодня. Певно, саме ці кристали зводять жуків із розуму.",
        ["npcs"] = { [1] = 15183 },
        ["roles"] = { ["greeting"] = true },
    },
    [953364724] = {
        ["english"] = { [1] = "Can you tell me about this shard?" },
        ["text"] = "Розкажеш мені про цей уламок?",
        ["npcs"] = { [1] = 3442 },
        ["roles"] = { ["reply"] = true },
    },
    [1699829989] = {
        ["english"] = { [1] = "Can you spare an orange?" },
        ["text"] = "Не позичиш апельсин?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [691203737] = {
        ["english"] = { [1] = "Ah, another $c looking to be a gladiator, eh? Good!$B$BI sell the arena team charters you'll need to participate in ranking Steamwheedle Fighting Circuit matches." },
        ["text"] = "А, ще один $c хоче стати гладіатором, еге ж? Добре!$B$BЯ продаю статути команд арени, потрібні для участі в рейтингових матчах Бойового Контуру Хиткої Шестерні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1409438739] = {
        ["english"] = { [1] = "Acquire high level data card." },
        ["text"] = "Отримати високорівневу картку даних.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3324559189] = {
        ["english"] = { [1] = "Crystal Restore is a difficult item to acquire.$B$BI believe that it comes from Un'Goro Crater, so you'd best head there." },
        ["text"] = "«Кришталеве відновлення» — предмет, який важко здобути.$B$BЗдається, він походить із кратера Ун'Ґоро, тож тобі краще прямувати туди.",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["greeting"] = true },
    },
    [4207286453] = {
        ["english"] = { [1] = "A powerful human mage is rumored to live to the north; he keeps watch over the land for some unknown reason. I have not traveled there myself, but it is said that visitors are welcome and can even earn favor with him if they are willing to do errands for him." },
        ["text"] = "Кажуть, далеко на півночі живе могутній людський маг, який з невідомої причини наглядає за цими землями. Я сам там не був, але кажуть, він приймає відвідувачів, а ті, хто готовий виконувати його доручення, можуть навіть заслужити його прихильність.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [462061971] = {
        ["english"] = { [1] = "$962w, soldier." },
        ["text"] = "$962w, солдате.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3852167350] = {
        ["english"] = { [1] = "$C, I need more copper bars! There's a war brewing at the Gates of Ahn'Qiraj and we need supplies! The Alliance has collected $1997w and we need $1998w copper bars in total. If I don't get those copper bars, it's going to be my head on a platter!" },
        ["text"] = "$C, мені потрібно більше мідних зливків! Біля Брами Ан'Кіражу назріває війна, і нам потрібні припаси! Альянс уже зібрав $1997w, а загалом нам потрібно $1998w мідних зливків. Якщо я їх не дістану, моя голова опиниться на блюді!",
        ["npcs"] = { [1] = 15383 },
        ["roles"] = { ["greeting"] = true },
    },
    [285886581] = {
        ["english"] = { [1] = "Are you certain you want my help in the battle against Yogg-Saron?" },
        ["text"] = "Ти певен, що хочеш моєї допомоги в битві проти Йоґґ-Сарона?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2554529458] = {
        ["english"] = { [1] = "Can you not see that I am busy here?" },
        ["text"] = "Хіба не бачиш, що я зайнятий?",
        ["npcs"] = { [1] = 15165 },
        ["roles"] = { ["greeting"] = true },
    },
    [1867776229] = {
        ["english"] = { [1] = "Can you help me get down?" },
        ["text"] = "Допоможеш мені спуститися?",
        ["npcs"] = { [1] = 7772 },
        ["roles"] = { ["reply"] = true },
    },
    [2016037043] = {
        ["english"] = { [1] = "Can I offer you a drink? I promise you its aged like none other!" },
        ["text"] = "Запропонувати напій? Обіцяю, такого витриманого ти ще не куштував!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1082321199] = {
        ["english"] = { [1] = "But..." },
        ["text"] = "Але...",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [3302488996] = {
        ["english"] = { [1] = "Ah, to soar with the great birds of the sky.  Seek out Tal at the top of the Winder Rider Roost.  He will steer you toward where you're going." },
        ["text"] = "Ах, здійнятися в небо разом із великими птахами. Шукай Тала на вершині Гнізда Вітрових Вершників. Він направить тебе куди треба.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1859441565] = {
        ["english"] = { [1] = "Can you believe this place?  'Course, it's a mite stuffy up here if you ask me." },
        ["text"] = "Ти тільки поглянь на це місце! Хоча, як на мене, тут трохи задушливо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [535840158] = {
        ["english"] = { [1] = "Can you believe the nerve of that Elisara Sunstriker?  Thinking that she can catch the eye of Lord Saltheril?  And did you see what she's wearing?  So last season.  It's sad, really." },
        ["text"] = "Можеш повірити в нахабство тієї Елісари Сонцеударної? Думає, що зможе привернути увагу лорда Салтеріла? А ти бачив, що на ній? Мода минулого сезону. Просто сумно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1946630374] = {
        ["english"] = { [1] = "Be wary, for the plagued tendrils of the Lich King lurk close." },
        ["text"] = "Будь обережний: заражені щупальця Короля-ліча чатують зовсім близько.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3835932350] = {
        ["english"] = { [1] = "Begging your pardon" },
        ["text"] = "Перепрошую",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4150780038] = {
        ["english"] = { [1] = "Deathwing's brood... Ysera's benevolence raised the ire of Deathwing - patron of the black dragonflight. They attacked us in our sleep! Many died on the initial surge but the greens rose to protect us.$B$B<Prince Toreth points around the island.>$B$BThe bones are all that remain of the once great dragons. None were spared." },
        ["text"] = "Виводок Смертекрила... Доброзичливість Ізери розлютила Смертекрила — покровителя чорної драконячої зграї. Вони напали на нас уві сні! Багато хто загинув під час першого натиску, але зелені піднялися на наш захист.$B$B<Принц Торет вказує навколо острова.>$B$BЦі кістки — все, що лишилося від колись величних драконів. Не пощадили нікого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2156044615] = {
        ["english"] = { [1] = "Bad hang nail" },
        ["text"] = "Поганий задирок біля нігтя",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [1150293419] = {
        ["english"] = { [1] = "<Deathguard Simmer looks at you expectantly.>" },
        ["text"] = "<Страж смерті Сіммер очікувально дивиться на вас.>",
        ["npcs"] = { [1] = 1519 },
        ["roles"] = { ["greeting"] = true },
    },
    [3355201125] = {
        ["english"] = { [1] = "Can you tell me how I can get a Videre Elixir?" },
        ["text"] = "Можеш розповісти, як дістати еліксир Відіре?",
        ["npcs"] = { [1] = 7775 },
        ["roles"] = { ["reply"] = true },
    },
    [2166893745] = {
        ["english"] = { [1] = "Can I tire my ram out?" },
        ["text"] = "Чи можу я втомити свого барана?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3485536181] = {
        ["english"] = { [1] = "Can I show you what I have for sale?\010\010" },
        ["text"] = "Показати, що маю на продаж?\010\010",
        ["npcs"] = { [1] = 2393 },
        ["roles"] = { ["greeting"] = true },
    },
    [1321448484] = {
        ["english"] = { [1] = "Can you feel it?$B$BThe spirit world draws close during the Day of the Dead. This is why we decorate the graves of our dearly departed with flowers and candles and offerings: To welcome them back, even if only for a time.$B$BSo come! Dance with me! Let us cherish and honor those we have lost in their ghostly presence, so that they might eat and drink and smile and know that they are loved." },
        ["text"] = "Відчуваєш?$B$BУ День мертвих світ духів підходить ближче. Саме тому ми прикрашаємо могили дорогих померлих квітами, свічками й підношеннями — щоб привітати їхнє повернення, хай навіть ненадовго.$B$BТож іди! Танцюй зі мною! Вшануймо й бережімо пам'ять про тих, кого втратили, в їхній примарній присутності, щоб вони могли їсти, пити, усміхатися й знати, що їх люблять.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2565868651] = {
        ["english"] = { [1] = "Best keep yer head down, \"matey!\"  If ye know what I mean!$B$BYarrrr!" },
        ["text"] = "Краще пригни голову, «матросику»! Якщо розумієш, про що я!$B$BАр-р-р!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2956200440] = {
        ["english"] = { [1] = "Be gone, $c!  Leave us be, or we will enter you next and show you true despair!" },
        ["text"] = "Геть, $c! Залиш нас у спокої, інакше ми увійдемо в тебе наступним і покажемо справжній відчай!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4261698970] = {
        ["english"] = { [1] = "Can I get you anything?  My selection is a little limited, but that's to be expected... all things considered." },
        ["text"] = "Щось тобі принести? Вибір у мене трохи обмежений, але з огляду на обставини це й не дивно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3185102830] = {
        ["english"] = { [1] = "Continue with your story please." },
        ["text"] = "Продовжуй свою розповідь, будь ласка.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [3278849185] = {
        ["english"] = { [1] = "Busy, busy!  So much to do, so little time!$B$BNow where did I put that pyrospanner?  I know it's around here somewhere... I burned my fingers on it just a moment ago!" },
        ["text"] = "Зайнятий, зайнятий! Стільки справ, а часу так мало!$B$BКуди ж я поклав той піроключ? Знаю, він десь тут... я лише мить тому обпік об нього пальці!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3475341231] = {
        ["english"] = { [1] = "A cursory examination of the skeletal remains indicates that the flesh was seared off. Quite a grisly sight." },
        ["text"] = "Побіжний огляд скелетних решток показує, що плоть була випалена. Вельми моторошне видовище.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3282728746] = {
        ["english"] = { [1] = "Alexstrasza is  my answer." },
        ["text"] = "Моя відповідь — Алекстраза.",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["reply"] = true },
    },
    [2285424461] = {
        ["english"] = { [1] = "Do not be fooled by the ruins surrounding us, $c.  Dalaran is as powerful as ever." },
        ["text"] = "Не дай руїнам навколо обманути тебе, $c. Даларан могутній, як і раніше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2997096157] = {
        ["english"] = { [1] = "Burninate's the name, smithin's my game... and, erm... I sell a little food and water on the side. Care for some meat?" },
        ["text"] = "Ім'я — Паликруг, ремесло — ковальство... і, е-е... ще трохи їжі й води продаю збоку. М'яса не хочеш?",
        ["npcs"] = { [1] = 14624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3421806622] = {
        ["english"] = { [1] = "Ah, $N!  You're just the person I was hoping to see!  We have enough supplies to send a ground assault against the Horde!  Field Marshal Teravaine is waiting in the Field of Strife for orders...$B$BYou're a brave veteran who's proven himself time and again.  Do you want to deliver Teravaine the orders?" },
        ["text"] = "А, $N! Саме тебе я й сподівався побачити! У нас достатньо припасів, щоб розпочати наземний наступ проти Орди! Фельдмаршал Теравейн чекає наказів на Полі Чвар...$B$BТи хоробрий ветеран, який не раз доводив свою відвагу. Хочеш доставити Теравейну накази?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2765347523] = {
        ["english"] = { [1] = "<Use the transcription device to gather a rubbing.>" },
        ["text"] = "<Скористайтеся пристроєм для копіювання, щоб зробити відбиток.>",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2960281197] = {
        ["english"] = { [1] = "<Kaide hisses at you.>$B$BBe quiet, or you'll bring the orcs and the Alliance down on us, you clumsy oaf!$B$BThat's right, nod your head, and when we're done speaking, you'll walk away and forget you found me here." },
        ["text"] = "<Кайде шипить на вас.>$B$BТихіше, бо накличеш на нас орків і Альянс, незграбний телепню!$B$BОтак, кивай головою, а коли ми закінчимо говорити — підеш звідси й забудеш, що знайшов мене тут.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3173336293] = {
        ["english"] = { [1] = "Ah, you wish to train abroad? I will direct you. Tell me which weapon has sparked your interest." },
        ["text"] = "А, хочеш навчатися за кордоном? Я підкажу дорогу. Скажи, яка зброя тебе зацікавила.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3785716370] = {
        ["english"] = { [1] = "All members of the Horde are equal in my eyes, $N. We have all suffered many burdens, and if it were not for wisdom and honor, then we would be no better than the Scourge or my people while our blood was tainted by the demon Mannoroth.$B$BIt is your duty to aid the Horde and to defend our way of life. But it is also your duty to know when quarter and compassion should be given to friend and foe alike.$B$BUnderstand this well. This is the new Horde, not some demon-spawned army who lack freewill." },
        ["text"] = "В моїх очах усі члени Орди рівні, $N. Ми всі несли тяжкі тягарі, і якби не мудрість та честь, ми нічим не відрізнялися б від Скверни чи від мого народу, коли нашу кров осквернив демон Маннорот.$B$BТвій обов'язок — допомагати Орді й захищати наш спосіб життя. Але також твій обов'язок — знати, коли слід виявити милість і співчуття як до друга, так і до ворога.$B$BДобре це зрозумій. Це нова Орда, а не породжене демонами військо без власної волі.",
        ["npcs"] = { [1] = 4949 },
        ["roles"] = { ["greeting"] = true },
    },
    [3078152283] = {
        ["english"] = { [1] = "<The captured Sunhawk agent eyes you suspiciously.>$B$BI've never seen you before. Who are you?" },
        ["text"] = "<Полонений агент Сонячних Яструбів підозріло дивиться на вас.>$B$BЯ тебе раніше не бачив. Хто ти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3628673596] = {
        ["english"] = { [1] = "Agent Ya-six and I were given a high priority mission from Protectorate command to eradicate all signs of void creature infestation at Ultris. These were to be tactical strikes. Our last hit before returning to the Protectorate Watch Post was to be on a void lord named Arconus who had been getting fat off the fleshlings of the area.$B$BUnfortunately, we arrived a bit late. Ya-six and I got separated in the firefight with the flesh beasts. Now he's trapped inside, pinned down behind enemy lines.$B" },
        ["text"] = "Агенту Я-шостому й мені командування Протекторату доручило першочергову місію — викорінити всі ознаки зараження створіннями Порожнечі в Ультрісі. Це мали бути точкові удари. Останньою ціллю перед поверненням на заставу Протекторату був володар Порожнечі на ім'я Арконус, що жирів на місцевих плотниках.$B$BНа жаль, ми трохи запізнилися. Під час перестрілки з плотяними звірами ми з Я-шостим розділилися. Тепер він застряг усередині, затиснутий у тилу ворога.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2080915517] = {
        ["english"] = { [1] = "Be sure to stick around for the next firework show!  Starting at 6PM, they're every hour on the hour!" },
        ["text"] = "Не пропусти наступне шоу феєрверків! Починаючи з 18:00, вони відбуваються щогодини рівно о годині!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [422174214] = {
        ["english"] = { [1] = "All is completed, young $c. Even as we speak, both the Horde and the Alliance are in the process of transporting all final goods for the war into Silithus near Cenarion Hold, which should be complete in less than $2113w days. After that, the gong near the gates of Ahn'Qiraj can be rung, and the war will begin." },
        ["text"] = "Усе завершено, юний $c. Просто зараз і Орда, і Альянс перевозять останні припаси для війни до Силітуса, поблизу Кенарієвої цитаделі; це має завершитися менш ніж за $2113w днів. Після цього можна буде вдарити в гонг біля брам Ан'Кіражу, і війна почнеться.",
        ["npcs"] = { [1] = 15437 },
        ["roles"] = { ["greeting"] = true },
    },
    [1672847980] = {
        ["english"] = { [1] = "<The druid appears to be deep in sleep, oblivious to his surroundings.>" },
        ["text"] = "<Друїд, схоже, міцно спить і не помічає нічого довкола.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3321651423] = {
        ["english"] = { [1] = "Byancie has often lent her services to the sentinels who patrol the local wilds.  You should talk to her if you desire to learn First Aid." },
        ["text"] = "Баянсі часто допомагала вартовим, які патрулюють місцеві нетрі. Поговори з нею, якщо хочеш навчитися першої допомоги.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2916964317] = {
        ["english"] = { [1] = "<Bloodrose eyes you curiously.>$b$bI cannot help but wonder what makes you worthy of such attention.$b$bNo offense...." },
        ["text"] = "<Кривава Троянда з цікавістю дивиться на вас.>$b$bНе можу не дивуватися, чим ви заслужили стільки уваги.$b$bБез образ...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2518593537] = {
        ["english"] = { [1] = "By the will of Sylvanas, our enemies will fall." },
        ["text"] = "З волі Сільвани наші вороги падуть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4252492865] = {
        ["english"] = { [1] = "$N! Come here! Surely you know of the battle that rages within Alterac Valley. We need every able-bodied fighter we can muster. Fight with the Stormpike Guard and defeat the Frostwolves!" },
        ["text"] = "$N! Іди сюди! Ти ж напевно знаєш про битву, що вирує в Альтерацькій долині. Нам потрібен кожен боєздатний боєць. Бийся разом із Вартою Грозової Вершини та здолай Морозних Вовків!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2945591952] = {
        ["english"] = { [1] = "Ah, Alterac Valley, I have fine memories I tell ya.  <sigh>  Well, I cannot join ya, but do me proud just the same!  To get there you'll be wanting to speak with Glordrum Steelbeard at the Hall of Arms here in Ironforge." },
        ["text"] = "А, Альтерацька долина... Гарні спогади, кажу тобі. <зітхає> Я не можу піти з тобою, але зроби так, щоб я пишався! Щоб потрапити туди, поговори з Ґлордумом Сталебородим у Залі Зброї тут, у Стальгорні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [550963783] = {
        ["english"] = { [1] = "Da Forsaken weapon master Archibald know his way 'round da polearm. He train others in da War Quarter of da Undercity, mon." },
        ["text"] = "Збройовий майстер Відречених Арчибальд знає все про древкову зброю. Він навчає інших у Військовому кварталі Підміста, друже.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [1637126645] = {
        ["english"] = { [1] = "By Muradin's beard, $c. This land is on the brink of annihilation. I cannot imagine anyone survived here since the end of the second war." },
        ["text"] = "Бородою Мурадіна, $c. Ця земля на межі винищення. Не можу уявити, що тут хтось вижив від кінця Другої війни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3537008715] = {
        ["english"] = { [1] = "<The blood elf quickly regains consciousness as you pour the draught into his mouth.>$B$BI owe you my life, $c.  Without your help I would've succumbed to the Scourge's painful torture." },
        ["text"] = "<Ельф крові швидко приходить до тями, коли ви вливаєте настій йому до рота.>$B$BЯ завдячую тобі життям, $c. Без твоєї допомоги я б не витримав болісних тортур Скверни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [168011920] = {
        ["english"] = { [1] = "All right!  Party time!" },
        ["text"] = "Гаразд! Час гуляти!",
        ["npcs"] = { [1] = 15723 },
        ["roles"] = { ["greeting"] = true },
    },
    [819258636] = {
        ["english"] = { [1] = "By Bronzbeard's... um, beard! What are you talking about?" },
        ["text"] = "Бородою Бронзобородого... е-е, бородою! Про що ти говориш?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [1758331948] = {
        ["english"] = { [1] = "Buy somethin', will ya?" },
        ["text"] = "Купиш щось, га?",
        ["npcs"] = { [1] = 7775 },
        ["roles"] = { ["reply"] = true },
    },
    [1780427695] = {
        ["english"] = { [1] = "Ah, welcome back, hero. You have returned to protect the Guardian once more? Do not forget to take a chrono-beacon with you!" },
        ["text"] = "А, вітаю з поверненням, герою. Ти знову прийшов захищати Хранителя? Не забудь узяти хрономаяк!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2164618415] = {
        ["english"] = { [1] = "Be quiet!  Can't you see the master is speaking?" },
        ["text"] = "Тихо! Не бачиш, майстер говорить?",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [1436809158] = {
        ["english"] = { [1] = "Do you mean you are a dragon?" },
        ["text"] = "Ти хочеш сказати, що ти дракон?",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [2548111367] = {
        ["english"] = { [1] = "But Deathwing is gone now." },
        ["text"] = "Але Смертекрила вже немає.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["reply"] = true },
    },
    [1801687685] = {
        ["english"] = { [1] = "Are you here for training?  Or are you just here to waste a warrior's time." },
        ["text"] = "Ти прийшов тренуватися? Чи просто марнувати час воїна?",
        ["npcs"] = { [1] = 985, [2] = 3153, [3] = 3169, [4] = 3353, [5] = 3354 },
        ["roles"] = { ["greeting"] = true },
    },
    [2603547822] = {
        ["english"] = { [1] = "Cairne himself lives here, they say. Once I have finished crafting a fitting gift, I will seek him out. Perhaps he will have words of wisdom for me." },
        ["text"] = "Кажуть, тут живе сам Керн. Коли закінчу робити гідний подарунок, знайду його. Може, він поділиться зі мною мудрістю.",
        ["npcs"] = { [1] = 3008 },
        ["roles"] = { ["greeting"] = true },
    },
    [4080853939] = {
        ["english"] = { [1] = "Ah, well aren't you a sturdy-looking one? Perhaps you can assist me with a thing or two. Not much help around here except for green apprentices, and they've other things to worry about." },
        ["text"] = "О, який міцний вигляд! Може, допоможеш мені з кількома справами. Тут майже нема від кого чекати допомоги, крім зелених учнів, та й у них свої клопоти.",
        ["npcs"] = { [1] = 658 },
        ["roles"] = { ["greeting"] = true },
    },
    [410675714] = {
        ["english"] = { [1] = "Bank" },
        ["text"] = "Банк",
        ["npcs"] = { [1] = 727, [2] = 1423, [3] = 12996, [4] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [3851454375] = {
        ["english"] = { [1] = "Another Herbalist, hmm. I doubt your skill is as great as my own so perhaps I can train you in a few proper techniques." },
        ["text"] = "Ще один травник, гм. Сумніваюся, що твої навички кращі за мої, тож, можливо, я навчу тебе кількох правильних прийомів.",
        ["npcs"] = { [1] = 5566 },
        ["roles"] = { ["greeting"] = true },
    },
    [96577888] = {
        ["english"] = { [1] = "Can you believe it?  This ethereal does not have a single basilisk eye on him!$B$BAnd his leader has the gall to call himself \"the Smuggler Prince!\"" },
        ["text"] = "Можеш повірити? У цього ефіріала немає при собі жодного ока василіска!$B$BА його ватажок ще має нахабство називати себе «Принцом контрабандистів»!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2259141578] = {
        ["english"] = { [1] = "A Horde Commendation Signet is awarded to a $g hero : heroine; who goes above and beyond the call of duty to the Horde.  Various Commendation Officers for the factions of the Horde are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!$B$BBy the way, during the war effort here, if you'd rather receive a material reward for your signets instead of reputation, seek out Warlord Gorchuk." },
        ["text"] = "Почесний знак Орди вручають $g героєві : героїні;, що робить для Орди більше, ніж вимагає обов'язок. У всіх великих містах є офіцери відзнак різних фракцій Орди; поговори з представником тієї фракції, репутацію з якою хочеш підвищити, і віддай йому стільки знаків, скільки він попросить!$B$BДо речі, якщо під час цієї воєнної кампанії ти віддаєш перевагу матеріальній винагороді замість репутації, розшукай воєначальника Ґорчука.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3278800461] = {
        ["english"] = { [1] = "Below is the aptly named Deathforge. If left to their own devices, the Shadow Council would supply the Legion with an endless stream of infernals." },
        ["text"] = "Унизу лежить влучно названа Кузня Смерті. Якщо Раду Тіней не зупинити, вона постачатиме Легіону нескінченний потік інферналів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2948719299] = {
        ["english"] = { [1] = "Burning eyes within the prism fill your mind with a sense of dread... especially knowing that you don't have the thirty-five apexis shards needed to summon forth its demon." },
        ["text"] = "Палаючі очі всередині призми наповнюють ваш розум жахом... особливо коли ви знаєте, що у вас немає тридцяти п'яти уламків апекситу, потрібних для виклику її демона.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [663837530] = {
        ["english"] = { [1] = "$G Sir : Ma'am;, yes $g sir : ma'am;! Private Porter reporting for duty and ready to assist you with your medium leather collection needs. The Ahn'Qiraj War is coming and we need to be as prepared as we can be.$B$BAs you can see we have collected exactly $2063w pieces of medium leather, and I have been tasked with gathering a total of $2064w." },
        ["text"] = "$G Пане : пані;, так, $g пане : пані;! Рядовий Портер прибув на службу й готовий допомогти вам зі збором середньої шкіри. Війна за Ан'Кіраж наближається, і ми маємо підготуватися якнайкраще.$B$BЯк бачите, ми зібрали рівно $2063w шматків середньої шкіри, а мені доручено зібрати загалом $2064w.",
        ["npcs"] = { [1] = 15448 },
        ["roles"] = { ["greeting"] = true },
    },
    [1967895528] = {
        ["english"] = { [1] = "A happy Winter's Vale to you, friend!" },
        ["text"] = "Щасливого Зимового Покрову тобі, друже!",
        ["npcs"] = { [1] = 15760 },
        ["roles"] = { ["greeting"] = true },
    },
    [1608389800] = {
        ["english"] = { [1] = "Byancie's skill in First Aid has proven useful on numerous occasions.  You can find her just north of the Inn in Dolanaar if you wish to learn from her." },
        ["text"] = "Навички Баянсі з першої допомоги не раз ставали в пригоді. Якщо хочеш у неї вчитися, знайдеш її просто на північ від таверни в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2588408730] = {
        ["english"] = { [1] = "At first we repaired them to harvest the forests here, but ever since the alliance arrived and the fighting broke out we've been using them as war machines.$b$bBelieve me, $c. If you've got a key, you'd be crazy not to use it." },
        ["text"] = "Спершу ми полагодили їх, щоб заготовляти тут деревину, але відколи прибув Альянс і почалися бої, використовуємо їх як бойові машини.$b$bПовір мені, $c. Якщо маєш ключ — було б божевіллям ним не скористатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1511013501] = {
        ["english"] = { [1] = "An Alliance Commendation Signet is awarded to a $g hero : heroine; who goes above and beyond the call of duty to the Alliance.  Various Commendation Officers for the factions of the Alliance are located in all of the major cities; speak with the one with whom you'd like to raise your reputation, and give them the number of signets they ask for!$B$BBy the way, during the war effort here, if you'd rather receive a material reward for your signets in lieu of reputation, seek out Field Marshal Snowfall." },
        ["text"] = "Почесний знак Альянсу вручають $g героєві : героїні;, що робить для Альянсу більше, ніж вимагає обов'язок. У всіх великих містах є офіцери відзнак різних фракцій Альянсу; поговори з представником тієї фракції, репутацію з якою хочеш підвищити, і віддай йому стільки знаків, скільки він попросить!$B$BДо речі, якщо під час цієї воєнної кампанії ти віддаєш перевагу матеріальній винагороді замість репутації, розшукай фельдмаршала Снігопад.",
        ["npcs"] = { [1] = 15383, [2] = 15431, [3] = 15432, [4] = 15437, [5] = 15445, [6] = 15446, [7] = 15448, [8] = 15450, [9] = 15451, [10] = 15452, [11] = 15453, [12] = 15455, [13] = 15456, [14] = 15457 },
        ["roles"] = { ["greeting"] = true },
    },
    [1048641383] = {
        ["english"] = { [1] = "Buliwyf, the dwarven weapon master at the Timberline Arms in Ironforge, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.\010\010Bixi Wobblebonk, the gnome weapon master at the Timberline Arms in Ironforge, teaches crossbow, daggers and throwing weapons.\010\010Ilyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons." },
        ["text"] = "Булівіф, дворф-майстер зброї в крамниці «Лісовий край» у Стальгорні, навчає кулачної зброї, рушниць, одноручних і дворучних сокир та одноручних і дворучних булав.\010\010Біксі Хитрокіст, гномка-майстриня зброї в «Лісовому краї» у Стальгорні, навчає арбалетів, кинджалів і метальної зброї.\010\010Іленія Місячний Вогонь, майстриня зброї нічних ельфів, мешкає на Терасі Воїнів у Дарнасі, де навчає луків, кинджалів, кулачної зброї, посохів і метальної зброї.",
        ["npcs"] = { [1] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [2253063944] = {
        ["english"] = { [1] = "Ah yes, it is Seikwa that you must find.  I believe I saw her last standing out in front of the inn." },
        ["text"] = "Ага, тобі треба знайти Сейкву. Здається, востаннє я бачив її перед таверною.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3616511184] = {
        ["english"] = { [1] = "<The Baron lifts his manacles.>$B$BCome on then, $c. Do ye trust me?" },
        ["text"] = "<Барон підіймає закуті в кайдани руки.>$B$BНу ж бо, $c. Ти мені довіряєш?",
        ["npcs"] = { [1] = 3467 },
        ["roles"] = { ["greeting"] = true },
    },
    [2150353723] = {
        ["english"] = { [1] = "Are the Eastern Plaguelands currently under attack?" },
        ["text"] = "Східне Чумнозем'я зараз атакують?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [3105166682] = {
        ["english"] = { [1] = "<Greathmother Geyah laughs weakly.>$B$BOf course not, dear. But it's not me that has to believe...$B$BGarrosh can lead the Mag'har. He is strong and wise. All of the spirits approve of him. He just needs to believe in himself. He fears so much... He fears so deeply that if he lets himself go, his rage will consume him and all that would be near him." },
        ["text"] = "<Прабабуся Ґея слабко сміється.>$B$BАвжеж ні, любий. Але повірити має не я...$B$BҐаррош може очолити маґ'гарів. Він сильний і мудрий. Усі духи схвалюють його. Йому лише треба повірити в себе. Він так багато боїться... Він так глибоко боїться, що коли дасть собі волю, його лють поглине і його самого, і всіх, хто буде поруч.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2635285392] = {
        ["english"] = { [1] = "<The high abbot studies you a moment and then smiles.>$B$BVery well, I know a place, child. You just kiss my ring and let me know when you are ready." },
        ["text"] = "<Верховний абат якусь мить вивчає вас поглядом, а потім усміхається.>$B$BГаразд, дитя, я знаю одне місце. Просто поцілуй мій перстень і скажи, коли будеш готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1134801166] = {
        ["english"] = { [1] = "Another lovely, gloomy day here in Tranquillien, wouldn't you say, $c?$B$BWhat can I do for you?" },
        ["text"] = "Ще один чудовий, похмурий день у Транквілієні, чи не так, $c?$B$BЧим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [748798715] = {
        ["english"] = { [1] = "$n, I am pleased to see you. Our dwarven allies require our assistance in Alterac Valley. Will you help them?" },
        ["text"] = "$n, радий тебе бачити. Нашим союзникам-дворфам потрібна допомога в Альтерацькій долині. Допоможеш їм?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4241486809] = {
        ["english"] = { [1] = "Buliwyf, the dwarf weapon master within the Timberline Arms in Ironforge, can train you in the use of guns." },
        ["text"] = "Булівіф, дворф-майстер зброї в крамниці «Лісовий край» у Стальгорні, навчить тебе користуватися рушницями.",
        ["npcs"] = { [1] = 11866, [2] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [1428568217] = {
        ["english"] = { [1] = "And go where? It was all that we knew; all that we had known and all that we would ever know.$B$BEventually, we lost contact with the Barovs and ultimately, were separated from the household. We knew not what happened to the other servants, only that there were screams. Tortured screams.$B$BKnowing that we had nowhere to go, Lucien and I were forced to hide in our quarters. During the day, when the school was relatively quiet, Lucien would sneak out to scrounge up food and drink." },
        ["text"] = "І куди було йти? Це було все, що ми знали; усе, що мали, й усе, що, як нам здавалося, матимемо завжди.$B$BЗрештою ми втратили зв'язок із Баровими й остаточно відокремилися від маєтку. Ми не знали, що сталося з іншими слугами, лише чули крики. Мученицькі крики.$B$BРозуміючи, що йти нам нікуди, ми з Люсьєном сховалися у своїх покоях. Удень, коли школа трохи затихала, Люсьєн потай виходив шукати їжу й воду.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [1060296080] = {
        ["english"] = { [1] = "$C, through the efforts of many we have managed to gather up all of the runecloth bandages that the Alliance feels it needs for the upcoming conflict. Were I you, I would ask some of the others here to see if they still have collection tasks that need fulfilling." },
        ["text"] = "$C, завдяки зусиллям багатьох ми зібрали всі бинти з рунічної тканини, які, на думку Альянсу, знадобляться в прийдешньому протистоянні. На твоєму місці я б розпитав інших тут — можливо, їм іще потрібна допомога зі збором припасів.",
        ["npcs"] = { [1] = 15453 },
        ["roles"] = { ["greeting"] = true },
    },
    [3029234514] = {
        ["english"] = { [1] = "Aran has been defeated? Yes... I can sense his grip has loosened - if only just a little. But just enough to allow me to do my job as the doorman! Would you like me transport you to the Guardian's Library, $N?" },
        ["text"] = "Арана переможено? Так... я відчуваю, що його хватка ослабла — хай лише трохи. Але цього досить, щоб я міг виконати свою роботу швейцара! Хочеш, я перенесу тебе до Бібліотеки Хранителя, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [826952851] = {
        ["english"] = { [1] = "Archibald, Undercity's weapon master, can train you in both one and two-handed swords. He is in the War Quarter." },
        ["text"] = "Арчибальд, майстер зброї Підміста, навчить тебе володіти одноручними й дворучними мечами. Він у Військовому кварталі.",
        ["npcs"] = { [1] = 11868, [2] = 11869 },
        ["roles"] = { ["greeting"] = true },
    },
    [4177073924] = {
        ["english"] = { [1] = "Aye, you look the type to be a leader.  Here to organize a guild to fight for the Alliance?" },
        ["text"] = "Так, ти схожий на того, хто вміє вести інших. Прийшов заснувати гільдію, що битиметься за Альянс?",
        ["npcs"] = { [1] = 5130 },
        ["roles"] = { ["greeting"] = true },
    },
    [1556730363] = {
        ["english"] = { [1] = "$N, this came for you this morning." },
        ["text"] = "$N, це прийшло для тебе сьогодні вранці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [363909295] = {
        ["english"] = { [1] = "Alright, alright. Anyhow, so I sorta slipped into the shadows.$B$BThat didn't sit too well with Windsor, seeing as how he was already extra cranky. Well he started spinnin' old Ironfoe around and screaming like a mad man at the orcs. " },
        ["text"] = "Гаразд, гаразд. Коротше, я ніби ковзнув у тіні.$B$BВіндзорові це зовсім не сподобалося, бо він і так був страшенно злий. Тож він почав крутити старим Залізним Ворогом і верещати на орків, мов навіжений.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3414505782] = {
        ["english"] = { [1] = "Buliwyf can show you how to swing a mace properly, no matter the size. You can find him within the Timberline Arms in Ironforge." },
        ["text"] = "Булівіф покаже, як правильно махати булавою будь-якого розміру. Знайдеш його в крамниці «Лісовий край» у Стальгорні.",
        ["npcs"] = { [1] = 11866, [2] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [4053172611] = {
        ["english"] = { [1] = "Bodley, tell me what's going on." },
        ["text"] = "Бодлі, розкажи, що відбувається.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["reply"] = true },
    },
    [1467605584] = {
        ["english"] = { [1] = "Are you ready to begin the assault and win back the Undercity for the Horde, $N?" },
        ["text"] = "Ти готовий почати штурм і повернути Підмісто Орді, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3549022941] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke D, a security level delta terminal.$B$BYou must posses a red punch card to access terminal functions.\010\01001010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-D, термінала рівня безпеки дельта.$B$BДля доступу до функцій термінала потрібна червона перфокартка.\010\01001010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1538779960] = {
        ["english"] = { [1] = "Are you reporting for duty, $c? All of the war materiel for both the Horde and the Alliance is completed and being shipped to Silithus as we speak. It should all arrive in less than $2113w days. I hope that someone has found the different pieces of the Scepter of the Shifting Sands and put them all together." },
        ["text"] = "Прибув на службу, $c? Усі воєнні припаси і для Орди, і для Альянсу вже готові й просто зараз відправляються до Силітуса. Усе має прибути менш ніж за $2113w днів. Сподіваюся, хтось уже знайшов усі частини Скіпетра Мінливих Пісків і зібрав їх докупи.",
        ["npcs"] = { [1] = 15445, [2] = 15702, [3] = 15709 },
        ["roles"] = { ["greeting"] = true },
    },
    [3798510064] = {
        ["english"] = { [1] = "Ain't she a beauty? Want to take her for a spin?" },
        ["text"] = "Красуня, еге ж? Хочеш прокататися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3944097704] = {
        ["english"] = { [1] = "Are you ready to fight for the Alliance, $c?" },
        ["text"] = "Ти готовий битися за Альянс, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1809960033] = {
        ["english"] = { [1] = "Aren't you $N? I'd heard you were dead." },
        ["text"] = "Хіба ти не $N? Я чув, що ти загинув.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2745734629] = {
        ["english"] = { [1] = "Aye, you there!  If you want to earn the respect of the dwarves of Ironforge, then you can start by donating valuable resources!  Ironforge finds itself running low on cloth piece; textiles and bandages don't grow on trees, ya know!$B$BRather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the dwarven people of Ironforge!" },
        ["text"] = "Гей, ти! Якщо хочеш заслужити повагу дворфів Стальгорна, почни з пожертв цінних ресурсів! У Стальгорні бракує тканини; тканина й бинти на деревах не ростуть, знаєш!$B$BЗамість продавати шматки тканини, які знаходиш у мандрах, пожертвуй їх! Так ти здобудеш визнання дворфів Стальгорна!",
        ["npcs"] = { [1] = 14723 },
        ["roles"] = { ["greeting"] = true },
    },
    [1930854126] = {
        ["english"] = { [1] = "Boktar thinks this crash an unfortunate event, but I believe we're intended to learn something from it." },
        ["text"] = "Боктар вважає цю аварію нещасним випадком, але я думаю, ми мали щось із неї зрозуміти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3746448613] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke A, a security level alpha terminal.$B$BWhite punch card detected.  Access Granted.\010\01001010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-A, термінала рівня безпеки альфа.$B$BВиявлено білу перфокартку. Доступ дозволено.\010\01001010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [47206921] = {
        ["english"] = { [1] = "Aye, you there!  If you want to earn the respect of the Darkspear, then you can start by donating valuable resources for those in need!  Textiles and bandages don't grow on trees, ya know.$B$BRather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the Darkspear!" },
        ["text"] = "Гей, ти! Якщо хочеш заслужити повагу Темного Списа, почни з пожертв цінних ресурсів для тих, хто їх потребує! Тканина й бинти на деревах не ростуть, знаєш.$B$BЗамість продавати шматки тканини, які знаходиш у мандрах, пожертвуй їх! Так ти здобудеш визнання Темного Списа!",
        ["npcs"] = { [1] = 14727 },
        ["roles"] = { ["greeting"] = true },
    },
    [2900605580] = {
        ["english"] = { [1] = "Come to me again with such pathetic work and I will send you home in a small iron box that I tempered in goat urine. Now go see that idiot Ug'thok, he is better suited to your needs." },
        ["text"] = "Ще раз принесеш мені таку жалюгідну роботу — і я відправлю тебе додому в маленькій залізній коробці, загартованій у козячій сечі. А тепер іди до того бовдура Уґ'тока — він краще підходить для твоїх потреб.",
        ["npcs"] = { [1] = 1383 },
        ["roles"] = { ["greeting"] = true },
    },
    [3470011473] = {
        ["english"] = { [1] = "<High Inquisitor Fairbanks nods.>$B$BAye, the lesser Mograine, the one known as the Scarlet Commander, through - what I suspect - the dealings of the Grand Crusader. He led his father to the ambush like a lamb to the slaughter." },
        ["text"] = "<Верховний інквізитор Феєрбенкс киває.>$B$BТак, молодший Моґрейн, той, кого називають Багряним командиром, — через, як я підозрюю, підступи Великого хрестоносця. Він привів свого батька в засідку, мов ягня на заклання.",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [2914791523] = {
        ["english"] = { [1] = "Care to purchase some piratey items?" },
        ["text"] = "Хочеш придбати трохи піратського краму?",
        ["npcs"] = { [1] = 2663 },
        ["roles"] = { ["greeting"] = true },
    },
    [2331421682] = {
        ["english"] = { [1] = "Both the Horde and Alliance captains have taken to the field.  Our Captain Balinda Stonehearth directs the Stormpike forces from the Stonehearth Outpost, and the enemy Captain Galvangar barks orders from within Iceblood Garrison.$B$BTo battle!" },
        ["text"] = "Капітани і Орди, і Альянсу вийшли на поле бою. Наша капітан Балінда Кам'яне Вогнище командує силами Грозової Вершини із застави Кам'яного Вогнища, а ворожий капітан Ґалванґар гавкає накази з гарнізону Крижаної Крові.$B$BДо бою!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2183535780] = {
        ["english"] = { [1] = "$C, look what they've done to our beloved land. The Scourge must be destroyed!" },
        ["text"] = "$C, поглянь, що вони зробили з нашою любою землею. Скверну треба знищити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [357399920] = {
        ["english"] = { [1] = "Brom Killian teach you how dig up shiny for me.  Him on inner ring of War Quarter." },
        ["text"] = "Бром Кілліан навчить тебе викопувати для мене блискуче. Він на внутрішньому кільці Військового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1506711821] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke C, a security level chi terminal.$B$BYou must posses a blue punch card to access terminal functions.\010\01001010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-C, термінала рівня безпеки хі.$B$BДля доступу до функцій термінала потрібна синя перфокартка.\010\01001010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [935182182] = {
        ["english"] = { [1] = "<The hatchling looks at you as if trying to determine whether or not you're its mother.>" },
        ["text"] = "<Дитинча дивиться на вас так, ніби намагається зрозуміти, чи не ви його мати.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1064254093] = {
        ["english"] = { [1] = "An alchemist?  No trouble at all $c.  Ainethil, in all her labor and toil, has become the most accomplished alchemist in the Craftsmen's Terrace.  I would head over there on the double if I were you. On the double!  Now off with you!" },
        ["text"] = "Алхімік? Жодних проблем, $c. Айнетіль своєю працею стала найвидатнішою алхімічкою на Терасі Ремісників. На твоєму місці я б помчав туди негайно. Негайно! А тепер рушай!",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3433932922] = {
        ["english"] = { [1] = "Ah, The Gilded Rose... with its soft down beds and warm baths... just thinking about that Inn makes me want to... ::yawn:: Lucky you if you're heading over there...  you will find it in the west side of the Trade District.   ...nice soft pillows, warm blankets.  ::yawn::" },
        ["text"] = "А, «Позолочена Троянда»... м'які пухові ліжка, теплі ванни... сама думка про ту таверну змушує мене... ::позіхає:: Щастить тобі, якщо йдеш туди... знайдеш її в західній частині Торгового району. ...м'які подушки, теплі ковдри. ::позіхає::",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3630509952] = {
        ["english"] = { [1] = "A stack of papers and schematics are strewn here." },
        ["text"] = "Тут розкидана купа паперів і креслень.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [881135111] = {
        ["english"] = { [1] = "A faint whisper is heard from within the stone...$B$BGreetings, little one.  Do you have news for the Templar?" },
        ["text"] = "Зсередини каменя долинає ледь чутний шепіт...$B$BВітаю, малий. Маєш новини для храмовника?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1643772125] = {
        ["english"] = { [1] = "Brann taught me everything I know about exploring." },
        ["text"] = "Бранн навчив мене всього, що я знаю про дослідження світу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [444227791] = {
        ["english"] = { [1] = "Boys have cooties and girls have beauty!" },
        ["text"] = "У хлопців зараза, а в дівчат краса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2497563031] = {
        ["english"] = { [1] = "All in good time, mon. I be havin' more work for you to do soon...." },
        ["text"] = "Усьому свій час, мон. Скоро в мене буде для тебе ще робота...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3805213805] = {
        ["english"] = { [1] = "Do you have any sons, $c?$B$BLet us tell you something, we think we were much happier before we came to Ogri'la and the crystals made us more aware.  Before, we would have just bashed them over the head to get them to shut up.  Now all they do is bother us about the Sha'tari Skyguard.$B$BIgnorance is bliss!" },
        ["text"] = "У тебе є сини, $c?$B$BСкажімо так: ми, здається, були значно щасливіші до того, як прийшли в Оґріла й кристали зробили нас... свідомішими. Раніше ми просто били їх по головах, щоб замовкли. А тепер вони тільки й роблять, що набридають нам розмовами про Небесну варту Ша'тар.$B$BНевідання — благо!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3073321216] = {
        ["english"] = { [1] = "Both the Horde and Alliance captains have taken to the field.  Our Captain Galvangar directs the Frostwolves from Iceblood Garrison, and his rival, Captain Balinda Stonehearth, hides in her Stonehearth Outpost.$B$BThe battle has begun!" },
        ["text"] = "Капітани і Орди, і Альянсу вийшли на поле бою. Наш капітан Ґалванґар командує Морозними Вовками з гарнізону Крижаної Крові, а його суперниця, капітан Балінда Кам'яне Вогнище, ховається на своїй заставі Кам'яного Вогнища.$B$BБитва почалася!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1832170023] = {
        ["english"] = { [1] = "Both Lost Rigger Cove in Tanaris and the Bay of Storms in Azshara have boxes that can be picked to improve your skill." },
        ["text"] = "І Бухта Загубленого Такелажу в Танарісі, і Затока Штормів в Азшарі мають скрині, які можна розкривати, щоб покращити навичку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4231893809] = {
        ["english"] = { [1] = "All of the fish and everything else is on its way to Silithus, and should be there in less than a day. After that someone's going to have to ring that gong with the Scepter of the Shifting Sands to start the war." },
        ["text"] = "Уся риба та решта припасів уже прямують до Силітуса й мають прибути менш ніж за день. Після цього хтось муситиме вдарити Скіпетром Мінливих Пісків у гонг, щоб розпочати війну.",
        ["npcs"] = { [1] = 15455 },
        ["roles"] = { ["greeting"] = true },
    },
    [4106002766] = {
        ["english"] = { [1] = "Ahhh, Stormwind Visitor's Center is what you are looking for then. It's the first building on the left as you walk through the front gates from the Valley of Heroes." },
        ["text"] = "А-а, тоді тобі потрібен Центр відвідувачів Штормовію. Це перша будівля ліворуч, коли проходиш крізь головну браму з Долини Героїв.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2881498006] = {
        ["english"] = { [1] = "$N!  Thanks again for all the help." },
        ["text"] = "$N! Іще раз дякую за всю допомогу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2799916823] = {
        ["english"] = { [1] = "Both Hanashi and Sayoc can train you in the use of one and two-handed axes. They can be found in the Valley of Honor in Orgrimmar." },
        ["text"] = "І Ганаші, і Сайок можуть навчити тебе одноручних і дворучних сокир. Знайдеш їх у Долині Честі в Орґріммарі.",
        ["npcs"] = { [1] = 11869, [2] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [6096452] = {
        ["english"] = { [1] = "Bank of Ironforge" },
        ["text"] = "Банк Стальгорна",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["reply"] = true },
    },
    [2514761680] = {
        ["english"] = { [1] = "Borgrim might be correct.  Maybe we do need to take a break.$B$BBut now that we're here, I'm eager to get my hands dirty and study what this land has to offer." },
        ["text"] = "Можливо, Борґрім має рацію. Може, нам і справді варто перепочити.$B$BАле раз ми вже тут, мені кортить забруднити руки й дослідити все, що може запропонувати ця земля.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1383616295] = {
        ["english"] = { [1] = "All of the food and war materiel we gathered is on its way to Silithus. It should be there in less than $2113w days. Someone told me that once it's all assembled over near Cenarion Hold, someone's going to have to go ring the gong at the Scarab Dais to open the gates to Ahn'Qiraj and start the war." },
        ["text"] = "Уся їжа й воєнні припаси, які ми зібрали, вже прямують до Силітуса. Вони мають бути там менш ніж за $2113w днів. Мені сказали, що коли все це зберуть біля Кенарієвої цитаделі, хтось муситиме піти до Помосту Скарабея й ударити в гонг, щоб відкрити брами Ан'Кіражу та розпочати війну.",
        ["npcs"] = { [1] = 15456 },
        ["roles"] = { ["greeting"] = true },
    },
    [1809601680] = {
        ["english"] = { [1] = "<High Inquisitor Fairbanks shakes his head.>$B$BNo... He stood in the background, watching as the legion of undead descended upon us. Soon after, my powers were exhausted. I was the first to fall... Surely they would tear me limb from limb as I lay there unconscious; but they ignored me completely, focusing all of their attention on the Highlord. " },
        ["text"] = "<Верховний інквізитор Феєрбенкс хитає головою.>$B$BНі... Він стояв осторонь і дивився, як на нас насувається легіон невмерлих. Невдовзі мої сили вичерпалися. Я впав першим... Я був певен, що вони розірвуть мене на шматки, поки я лежав непритомний, але вони цілковито мене проігнорували, зосередивши всю увагу на Верховному лорді. ",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [2910181909] = {
        ["english"] = { [1] = "<Omarion grumbles something under his breath.>$B$BBut of course I can help you, dear $N. It is my dying wish... my final desire. Please, take this handbook. The information on its pages are a compilation of all that I know and have learned in the past 30 some-odd years of my miserable life. Give the handbook to that good for nothing apprentice of mine that's probably sitting on his fat duff at Light's Hope Chapel." },
        ["text"] = "<Омаріон щось бурмоче собі під ніс.>$B$BЗвісно, я можу тобі допомогти, любий $N. Це моє передсмертне бажання... моя остання воля. Прошу, візьми цей посібник. На його сторінках зібрано все, що я знаю і чого навчився за більш ніж тридцять років мого жалюгідного життя. Віддай посібник тому моєму нікчемному учневі, який, мабуть, просиджує товстий зад у каплиці Надії Світла.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["greeting"] = true },
    },
    [1280764901] = {
        ["english"] = { [1] = "Archibald who you look for.  He outside weapon merchant shop on inner ring of War Quarter." },
        ["text"] = "Тобі потрібен Арчибальд. Він стоїть біля крамниці торговця зброєю на внутрішньому кільці Військового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2056058751] = {
        ["english"] = { [1] = "Activating secondary defensive systems will result in the extermination of unauthorized life forms via orbital emplacements.$B$BYou are an unauthorized life form. Please confirm." },
        ["text"] = "Активація вторинних оборонних систем призведе до винищення несанкціонованих форм життя за допомогою орбітальних установок.$B$BВи є несанкціонованою формою життя. Підтвердьте.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [653057135] = {
        ["english"] = { [1] = "Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre'Thalas." },
        ["text"] = "Останнім часом зникають книги. Хранитель знань та його помічники в паніці. Вони підозрюють нечисту гру всередині Елдре'Таласа.",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [612250772] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke A, a security level alpha terminal.$B$BYou must posses a white punch card to access terminal functions.\010\01001000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-A, термінала рівня безпеки альфа.$B$BДля доступу до функцій термінала потрібна біла перфокартка.\010\01001000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1842479883] = {
        ["english"] = { [1] = "Bixi here can teach ye how to lob throwin' weapons.  If Darnassus is more yer speed, talk to Ilyenia Moonfire on the Warrior's Terrace there." },
        ["text"] = "Біксі тут навчить тебе правильно метати зброю. Якщо тобі більше до вподоби Дарнас, поговори там з Іленією Місячний Вогонь на Терасі Воїнів.",
        ["npcs"] = { [1] = 11865 },
        ["roles"] = { ["greeting"] = true },
    },
    [4099220953] = {
        ["english"] = { [1] = "Do not presume to speak to me as though you are my equal, $c. Sylvanas is my queen, and I will do as she bids.$B$BIf you do not show the proper respect, I assure you, we can find a more than suitable place for you in the Nether.$B$BBut there is no reason we cannot have words if you wish to aid the Dark Lady..." },
        ["text"] = "Не смій говорити зі мною так, ніби ми рівні, $c. Сильвана — моя королева, і я виконуватиму її волю.$B$BЯкщо не виявиш належної поваги, запевняю: ми знайдемо для тебе більш ніж гідне місце в Крутоверті Порожнечі.$B$BТа якщо хочеш допомогти Темній Пані, немає причини нам не поговорити...",
        ["npcs"] = { [1] = 2425 },
        ["roles"] = { ["greeting"] = true },
    },
    [2479089716] = {
        ["english"] = { [1] = "Aren't the patterns beautiful? Each one speaks with its own voice." },
        ["text"] = "Хіба візерунки не прекрасні? Кожен говорить власним голосом.",
        ["npcs"] = { [1] = 3004 },
        ["roles"] = { ["greeting"] = true },
    },
    [1672981062] = {
        ["english"] = { [1] = "<Cowlen sobs.>" },
        ["text"] = "<Коулен ридає.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2782167790] = {
        ["english"] = { [1] = "Ah, there you are. I was told to expect help, so please listen closely. The situation is this: I've been tasked with gathering $2055w purple lotus in preparation for the coming war in Ahn'Qiraj. To date we have $2054w.$B$BActually going into the field and collecting the flowers will be up to you and those like you. I am needed here to see that they are properly maintained and to find new, creative applications for their use against the silithid and whatever else awaits us there." },
        ["text"] = "А, ось і ти. Мені сказали чекати допомоги, тож слухай уважно. Ситуація така: мені доручили зібрати $2055w пурпурового лотоса до прийдешньої війни в Ан'Кіражі. Наразі маємо $2054w.$B$BВиходити в поле й збирати квіти доведеться тобі та таким, як ти. Я потрібен тут, щоб правильно їх зберігати й шукати нові творчі способи застосування проти силітидів і всього іншого, що чекає на нас там.",
        ["npcs"] = { [1] = 15512 },
        ["roles"] = { ["greeting"] = true },
    },
    [2294840258] = {
        ["english"] = { [1] = "Do you mean the Silvermoon City Inn, or the Wayfarer's Rest tavern." },
        ["text"] = "Ти маєш на увазі заїжджий двір Срібномісяця чи таверну «Притулок Подорожнього»?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [713941071] = {
        ["english"] = { [1] = "Did you know that alchemists can transmute certain gems?  Mar'nah and I have been talking about this.$B$BI'm convinced that given her prowess, once her lab is complete, she and I will be able to create gems that were thought to be lost in time." },
        ["text"] = "Ти знав, що алхіміки можуть трансмутувати певні самоцвіти? Ми з Мар'ною якраз про це говорили.$B$BЯ переконаний: з її майстерністю, щойно лабораторія буде готова, ми зможемо створювати самоцвіти, які вважали втраченими в часі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3664677784] = {
        ["english"] = { [1] = "Being part of the Explorers' League, I've been hunting for artifacts in the area. Winterspring is said to contain very magical items... Most are highly guarded." },
        ["text"] = "Як член Ліги дослідників, я шукаю артефакти в цих краях. Кажуть, у Зимоключі є дуже магічні предмети... Більшість із них добре охороняють.",
        ["npcs"] = { [1] = 10301 },
        ["roles"] = { ["greeting"] = true },
    },
    [3820695911] = {
        ["english"] = { [1] = "Before the Scourge came, I had a great business.  I bought and sold everything.  Everything!$B$BAnd my prices were INSANE!$B$BJust ask anyone.  Anyone who's not dead." },
        ["text"] = "До приходу Скверни в мене був чудовий бізнес. Я купував і продавав усе. УСЕ!$B$BА ціни були БОЖЕВІЛЬНІ!$B$BСпитай будь-кого. Будь-кого, хто ще не помер.",
        ["npcs"] = { [1] = 12384 },
        ["roles"] = { ["greeting"] = true },
    },
    [601366877] = {
        ["english"] = { [1] = "Blacksmithing" },
        ["text"] = "Ковальство",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 5595, [30] = 5624, [31] = 5725, [32] = 5953, [33] = 6272, [34] = 6740, [35] = 8931, [36] = 12996, [37] = 13076 },
        ["roles"] = { ["reply"] = true },
    },
    [2669124250] = {
        ["english"] = { [1] = "Ah, you must be the $glad : lass; assigned to show me around the Eversong Woods.  Took your sweet time getting here, didn't you?$B$BVery well, off we go.  Let us not waste one more minute." },
        ["text"] = "А, ти, мабуть, той $gхлопче : дівчино;, кому доручили показати мені Ліс Вічноспіву. Довгенько ти сюди діставався, еге ж?$B$BГаразд, рушаймо. Не марнуймо більше ні хвилини.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3666824438] = {
        ["english"] = { [1] = "All those official types reside in Ironforge.  Ye'll be wanting to check out the Ironforge Visitor's Center for guild creation papers." },
        ["text"] = "Усі ті офіційні типи сидять у Стальгорні. За паперами для створення гільдії йди до Центру відвідувачів Стальгорна.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [1973865273] = {
        ["english"] = { [1] = "Blackrock Spire" },
        ["text"] = "Чорнокамінний Шпиль",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [676597313] = {
        ["english"] = { [1] = "Blackrock Depths" },
        ["text"] = "Глибини Чорнокамінної гори",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [3741044899] = {
        ["english"] = { [1] = "Bixi Wobblebonk in this very shop can train ye in daggers. If ye're still looking abroad, anyone else - Woo Ping in Stormwind and Ilyenia Moonfire in Darnassus - can show ye a thing or two. Me, I was never one fer knife fights." },
        ["text"] = "Біксі Хитрокіст у цій самій крамниці може навчити тебе кинджалів. Якщо хочеш учитися деінде, Ву Пін у Штормовії та Іленія Місячний Вогонь у Дарнасі теж покажуть кілька прийомів. Я ж ніколи не любив ножові бійки.",
        ["npcs"] = { [1] = 11865 },
        ["roles"] = { ["greeting"] = true },
    },
    [2760809565] = {
        ["english"] = { [1] = "Big, sparkly, magic book help make Glyphs for spells and abilities. Always find near inscription trainer, in The Apothecarium." },
        ["text"] = "Велика, блискуча, магічна книга допомагає робити символи для заклять і здібностей. Завжди знайдеш біля наставника написання в Аптекаріумі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4079009557] = {
        ["english"] = { [1] = "A word to the wise, stranger, go back to wherever you're from.$b$bThis is no place for lighthearted adventurers. It'll chew up the likes of you and spit out your bones." },
        ["text"] = "Мудра порада, чужинцю: повертайся туди, звідки прийшов.$b$bЦе не місце для безтурботних шукачів пригод. Воно пережує таких, як ти, й виплюне самі кістки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1674991635] = {
        ["english"] = { [1] = "As a young night elf in Darkshore, I crossed paths with a group of unsavory individuals known as the Twilight's Hammer. A group of them befriended me and shamefully, I ended up eschewing my faith in Elune and embracing the vitriol of the Twilight's Hammer.$B$BIt was not until a vision came to me from Elune, that I woke up from the malaise that I had fallen into as a follower of the old gods.$B$BIn repentance, I began work on my prayer to Elune. " },
        ["text"] = "Коли я був молодим нічним ельфом у Темнобережжі, мені трапилася група сумнівних осіб, відомих як Молот Сутінків. Дехто з них удавав моїх друзів, і, на свій сором, я зрікся віри в Елуну й прийняв отруйну ненависть Молота Сутінків.$B$BЛише коли мені було видіння від Елуни, я прокинувся від заціпеніння, в яке впав як послідовник Старих Богів.$B$BНа знак каяття я почав працювати над молитвою до Елуни. ",
        ["npcs"] = { [1] = 8436 },
        ["roles"] = { ["greeting"] = true },
    },
    [986764953] = {
        ["english"] = { [1] = "Ah yes, Skinning.  There is no one finer in wielding a skinning knife than Yonn Deepcut.  You can find him in the great tent at the northwest corner of the village." },
        ["text"] = "А, так, зняття шкур. Ніхто не володіє ножем для зняття шкур краще за Йонна Глибокоріза. Знайдеш його у великому наметі в північно-західному кутку селища.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [991044163] = {
        ["english"] = { [1] = "As a mage, you are one of a select group that can conjure a portal to transport you back to this very place.  I can teach you if you are ready.$B$BAnd remember that you can always use the crystal behind me to teleport down to the ruins beneath Dalaran in Crystalsong Forest." },
        ["text"] = "Як маг, ти належиш до небагатьох, хто може начаклувати портал і повернутися саме сюди. Я можу навчити тебе, якщо ти готовий.$B$BІ пам'ятай: завжди можеш використати кристал позаду мене, щоб телепортуватися до руїн під Далараном у Лісі Кришталевої Пісні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1010832053] = {
        ["english"] = { [1] = "*GRRRR* *RUFF* *RUFF*" },
        ["text"] = "*ГРРРР* *ГАВ* *ГАВ*",
        ["npcs"] = { [1] = 14528 },
        ["roles"] = { ["greeting"] = true },
    },
    [322713801] = {
        ["english"] = { [1] = "Between the orange and the purple passageways near the doors to Maraudon, you will find a third path.$B$BThe scepter you hold in your hands is the key." },
        ["text"] = "Між помаранчевим і пурпуровим проходами біля дверей до Мародона знайдеш третій шлях.$B$BСкіпетр у твоїх руках — ключ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1765532796] = {
        ["english"] = { [1] = "Between the colors, a path.$B$BBlink across in light.$B$BFrom the water, you emerge." },
        ["text"] = "Між кольорами — шлях.$B$BМигни крізь світло.$B$BІз води ти постанеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1363658865] = {
        ["english"] = { [1] = "Between Bixi and Buliwyf, there ain't many weapons they haven't had the pleasure of slashing or smashing an orc with.  You can find them hanging out at the Timberline Arms weapon shop if ye need some training." },
        ["text"] = "Між Біксі та Булівіфом майже не лишилося зброї, якою вони не мали задоволення рубати чи трощити орків. Якщо потрібне навчання, знайдеш їх у крамниці зброї «Лісовий край».",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [4018565610] = {
        ["english"] = { [1] = "Are you a student of the medical sciences?" },
        ["text"] = "Ти вивчаєш медичні науки?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [956900521] = {
        ["english"] = { [1] = "<Grumbles>  You'd think it would be hard to crash a zeppelin into the ocean.  You'd think it'd be even harder to do it four separate times!" },
        ["text"] = "<Бурчить> Здавалося б, врізати дирижабль в океан непросто. А зробити це чотири різні рази — ще важче!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [506827580] = {
        ["english"] = { [1] = "<Grumbles> I wish I could say we've managed to avoid crash landing into lakes.  I wish I could say we've only crashed into a lake once... but we've managed to crash into four separate lakes, including Lordamere Lake!" },
        ["text"] = "<Бурчить> Хотів би сказати, що нам удавалося не падати в озера. Хотів би сказати, що ми впали в озеро лише раз... але ми примудрилися гепнутися в чотири різні озера, зокрема в озеро Лордамер!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3522094160] = {
        ["english"] = { [1] = "Betina, I'd like a replacement Seal of the Dawn please!" },
        ["text"] = "Бетіно, будь ласка, дай мені замінну Печатку Світанку!",
        ["npcs"] = { [1] = 11035 },
        ["roles"] = { ["reply"] = true },
    },
    [2539544950] = {
        ["english"] = { [1] = "<Morthis glances skyward.>$B$BIn a way, I envy the freedom Rook and Corvax enjoy. To be free of earthbound responsibilities is a great blessing indeed.$B$BThe future will see me on wing once more, but first there's a task I must complete." },
        ["text"] = "<Мортіс зводить погляд до неба.>$B$BПевною мірою я заздрю свободі, якою насолоджуються Рук і Корвакс. Бути вільним від земних обов'язків — справжнє благословення.$B$BКолись я знову здіймуся в небо, але спершу маю завершити одну справу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1677551852] = {
        ["english"] = { [1] = "After the makrura attack, we could see that the Gallant would not survive another.  So I and the few surviving sailors abandoned my ship.$B$BWe are now ashore and will soon strike out for the town of Nijel's Point, but much danger lies between us and sanctuary, and I fear Desolace will consume us.$B$BI write this now in hopes that someone will know our plight, and some day avenge us against the watery fiends who were our ruin." },
        ["text"] = "Після нападу макрур стало ясно, що «Галант» другого не переживе. Тож я й кілька вцілілих моряків покинули корабель.$B$BТепер ми на березі й незабаром вирушимо до містечка на Заставі Найджела, та між нами й безпекою лежить чимало небезпек, і я боюся, що Спустошище нас поглине.$B$BПишу це в надії, що хтось дізнається про нашу долю й колись помститься водяним почварам, які нас занапастили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4223075259] = {
        ["english"] = { [1] = "Betina, I'd like a replacement Rune of the Dawn please!" },
        ["text"] = "Бетіно, будь ласка, дай мені замінну Руну Світанку!",
        ["npcs"] = { [1] = 11035 },
        ["roles"] = { ["reply"] = true },
    },
    [2598353272] = {
        ["english"] = { [1] = "Best deals in all of Stormwind my friend, won't find any better. Now, what can I help you with?" },
        ["text"] = "Найкращі ціни в усьому Штормовії, друже, кращих не знайдеш. То чим допомогти?",
        ["npcs"] = { [1] = 277, [2] = 279, [3] = 338, [4] = 482, [5] = 483, [6] = 1257, [7] = 1275, [8] = 1285, [9] = 1286, [10] = 1287, [11] = 1289, [12] = 1291, [13] = 1294, [14] = 1295, [15] = 1297, [16] = 1298, [17] = 1299, [18] = 1301, [19] = 1316, [20] = 1402, [21] = 1427, [22] = 1428, [23] = 1431, [24] = 3518, [25] = 4959, [26] = 4981, [27] = 5386, [28] = 5494, [29] = 6174, [30] = 16105 },
        ["roles"] = { ["greeting"] = true },
    },
    [673348027] = {
        ["english"] = { [1] = "Bena works like one possessed. Day and night I have seen her bent over these potions, often going without sleep or food. I know our undead allies need help, but I begin to fear she will do herself an injury." },
        ["text"] = "Бена працює наче одержима. День і ніч я бачу її над цими зіллями, часто без сну й їжі. Знаю, нашим союзникам-невмерлим потрібна допомога, але вже боюся, що вона сама собі зашкодить.",
        ["npcs"] = { [1] = 11047 },
        ["roles"] = { ["greeting"] = true },
    },
    [3067546968] = {
        ["english"] = { [1] = "Another drink!" },
        ["text"] = "Ще випивки!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2532495034] = {
        ["english"] = { [1] = "Belgrom sent us here from Orgrimmar to aid him in an unwise Alliance, but if his gamble pays off, then it will be to the great benefit of all the Horde.$B$BToo many orcs have already perished because of his desire to please women, but he still commands us, and our honor dictates we make the best of this situation." },
        ["text"] = "Белґром прислав нас сюди з Орґріммара, щоб допомогти йому в нерозумному союзі, але якщо його ризик виправдається, уся Орда отримає велику користь.$B$BЗабагато орків уже загинуло через його прагнення догодити жінкам, але він усе ще нами командує, а честь велить нам зробити все можливе в цій ситуації.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [238893659] = {
        ["english"] = { [1] = "<Tarsis is badly injured.>" },
        ["text"] = "<Тарсіс тяжко поранений.>",
        ["npcs"] = { [1] = 16381 },
        ["roles"] = { ["greeting"] = true },
    },
    [625631711] = {
        ["english"] = { [1] = "Belgaristrasz speaks the truth; time is running out!$B$BThe full power of your drakes has been unlocked.  Use their power to defeat Eregos!" },
        ["text"] = "Белґарістраз каже правду; часу майже не залишилося!$B$BПовну силу твоїх драконів розблоковано. Скористайся нею, щоб перемогти Ереґоса!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3883915294] = {
        ["english"] = { [1] = "After the firework show, they'll put out goblets so we can raise a toast!" },
        ["text"] = "Після шоу феєрверків вони виставлять келихи, щоб ми могли підняти тост!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2695570874] = {
        ["english"] = { [1] = "<You cannot comprehend any of the technical mumbo jumbo on this scroll.>" },
        ["text"] = "<Ви не можете збагнути жодної технічної тарабарщини на цьому сувої.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [725153184] = {
        ["english"] = { [1] = "A miner?  Ye don't need to ask if $glad : lass;, only where!  Yarr is who yer looking for, and I think ye can find him hiding out over in Steelgrill's Depot." },
        ["text"] = "Шахтар? Не треба питати \"чи\", $gхлопче : дівчино;, лише \"де\"! Тобі потрібен Ярр, і, здається, він ховається на складі Сталегриля.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3069543871] = {
        ["english"] = { [1] = "Deathwing, or Neltharion as he was once known, was the Aspect that embodied the strength of the world - granted almost limitless power over this mortal realm by the Titan shaper known as Khaz'goroth: Forger of the world.$B$BThrough treachery and deceit, the foul one convinced the four other Aspects to imbue an item, known as the Demon Soul, with their powers - greatly weakening them, forcing a division among the once great Aspects. \010" },
        ["text"] = "Смертекрил, колись знаний як Нелтаріон, був Аспектом, що уособлював силу світу. Титан-коваль Каз'ґорот, Творець світу, наділив його майже безмежною владою над цим смертним царством.$B$BПідступом і обманом мерзотник переконав чотирьох інших Аспектів вкласти свої сили в предмет, відомий як Душа Демона, — тим самим значно послабивши їх і роз'єднавши колись єдиних великих Аспектів. \010\010",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [3301127543] = {
        ["english"] = { [1] = "<Demitrian falls to his knees.>$B$BYou have recovered my Master's eternal prison!$B$BOh long have I waited for this day and finally, it is realized.$B$BHe must be released!" },
        ["text"] = "<Демітріан падає навколішки.>$B$BТи повернув вічну в'язницю мого Повелителя!$B$BО, як довго я чекав цього дня — і нарешті він настав.$B$BЙого треба звільнити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1041806469] = {
        ["english"] = { [1] = "$964w, young $c." },
        ["text"] = "$964w, юний $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1332131824] = {
        ["english"] = { [1] = "As you wish, Eitrigg." },
        ["text"] = "Як забажаєш, Айтріґу.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [2777050784] = {
        ["english"] = { [1] = "$N, the Stormpike Guard is in need of your aid in the battle against the Frostwolf Clan in Alterac Valley, now more than ever.  The opportunities for honor and repute are greater than ever as well! Will you join the battle?" },
        ["text"] = "$N, Варті Грозової Вершини зараз як ніколи потрібна твоя допомога в битві проти клану Морозного Вовка в Альтерацькій долині. І можливостей здобути честь та славу теж більше, ніж будь-коли! Приєднаєшся до битви?",
        ["npcs"] = { [1] = 15103 },
        ["roles"] = { ["greeting"] = true },
    },
    [3294404391] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke B, a security level beta terminal.$B$BYellow punch card detected.  Access Granted.\010\01001001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-B, термінала рівня безпеки бета.$B$BВиявлено жовту перфокартку. Доступ дозволено.\010\01001001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3368046070] = {
        ["english"] = { [1] = "Archibald da master of da crossbow. He da weapon master of da Undercity, located in da War Quarter." },
        ["text"] = "Арчибальд — майстер арбалета. Він майстер зброї Підміста, стоїть у Військовому кварталі.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [236627726] = {
        ["english"] = { [1] = "Blrmrrgl gulrgl grr." },
        ["text"] = "Блрмррґл ґулрґл ґрр.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [182367125] = {
        ["english"] = { [1] = "Behind me is the Altar of Zanza, a sacred place for us Zandalar.  We pray here to bolster our resolve in preparation for war against the Blood God, Hakkar.$B$BProve yourself to the tribe by using the altar to destroy any of the Hakkari Bijous you might find inside Zul'Gurub.  Also, I will trade you Honor Tokens our tribe uses for sets of coins you may find in Zul'Gurub.  Bring me the coins that I seek, and you will be rewarded!" },
        ["text"] = "Позаду мене — Вівтар Занзи, священне місце для нас, зандаларців. Ми молимося тут, щоб зміцнити дух перед війною з Богом Крові, Гаккаром.$B$BДоведи свою цінність племені: використовуй вівтар, щоб знищувати будь-які біжу Гаккарі, які знайдеш у Зул'Ґурубі. Також я обмінюватиму жетони честі нашого племені на набори монет із Зул'Ґуруба. Принеси потрібні монети — і отримаєш нагороду!",
        ["npcs"] = { [1] = 15070 },
        ["roles"] = { ["greeting"] = true },
    },
    [2259433640] = {
        ["english"] = { [1] = "Begin your search to the north, $N. Our scouts have spotted the Warp Piston near the shoreline." },
        ["text"] = "Почни пошуки на півночі, $N. Наші розвідники помітили Поршень Викривлення біля берега.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3646904621] = {
        ["english"] = { [1] = "Accessing...    Void -- engineer <skill_level == n3wb>     01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010    ACCESS DENIED!" },
        ["text"] = "Доступ...    Порожнеча -- інженер <skill_level == n3wb>     01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010    ДОСТУП ЗАБОРОНЕНО!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [79172571] = {
        ["english"] = { [1] = "Befriending the Sunstriders has paid off; I get to conduct research with subjects I can only find in Outland and they get... my charming personality and rugged good looks." },
        ["text"] = "Дружба із Сонячними Блукачами окупилася: я можу досліджувати об'єкти, які трапляються лише в Позамежжі, а вони отримують... мою чарівну вдачу й мужню вроду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2793001408] = {
        ["english"] = { [1] = "$N, please make sure that you tell Gahruj of our success." },
        ["text"] = "$N, обов'язково розкажи Ґаруджу про наш успіх.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [36985810] = {
        ["english"] = { [1] = "Before we can overcome external obstacles like the Scourge and the Amani trolls, we must overcome obstacles from within.  The Wretched have been a nuisance for long enough; it is time we vanquished them." },
        ["text"] = "Перш ніж долати зовнішні загрози на кшталт Скверни та тролів Амані, ми мусимо здолати внутрішні. Знедолені надокучали нам досить довго; час їх винищити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2752183710] = {
        ["english"] = { [1] = "Death to Stormpike!" },
        ["text"] = "Смерть Грозовій Вершині!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2499629563] = {
        ["english"] = { [1] = "Can't you see I'm busy here?  Go north up the road to Orgrimmar and ask one of the grunts there.  You can't miss it." },
        ["text"] = "Хіба не бачиш, я зайнятий? Іди дорогою на північ до Орґріммара й запитай там когось із рубак. Не проминеш.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [4068128969] = {
        ["english"] = { [1] = "As we were making our way across the Burning Steppes, we were ambushed. It must have been a hundred of them... Dark Iron dwarves! They were shifting out of the walls, from the rocks in the Steppes; out of every crevice, nook, and cranny in sight. They swarmed us, overwhelming the guards and the few brave heroes that had agreed to assist us on this mission.$B$BOne thing was clear: This was a highly orchestrated ambush. It was as if they knew every move we would make before we made them..." },
        ["text"] = "Коли ми перетинали Палаючий степ, на нас напали із засідки. Їх, мабуть, була сотня... дворфів Темного Заліза! Вони вискакували зі стін, зі скель Степу — з кожної тріщини, шпарини й закутка. Вони ринули на нас і змели варту та кількох хоробрих героїв, які погодилися допомогти в цій місії.$B$BОдне було ясно: засідку ретельно спланували. Наче вони знали кожен наш крок ще до того, як ми його зробили...",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [964758132] = {
        ["english"] = { [1] = "A rogue?  Hmmm... well, I've heard that Keryn Sylvius hangs around those shady types.  You might want to talk to her and see what you can learn." },
        ["text"] = "Розбійник? Гм... чув, що Керін Сільвіус водиться з такими темними типами. Поговори з нею — може, чогось і навчишся.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3642485269] = {
        ["english"] = { [1] = "About five months ago, the Venture Co.'s Stranglethorn division got their hands on a special poison from a shady merchant in Booty Bay named Crank Fizzlebub. Fizzlebub had apparently stolen the poison from Zanzil!$B$BYes, Zanzil the Outcast - the troll that was exiled from his own tribe due to the nature of his 'experiments' in necromancy.$B$BNaturally, once they had the poison, they proceeded to test it on each other. The results were disastrous." },
        ["text"] = "Близько п'яти місяців тому підрозділ Торгової компанії в Тернистій долині дістав особливу отруту від підозрілого торговця з Бухти Наживи на ім'я Кренк Шипучепуз. Виявилося, Шипучепуз украв її в Занзіла!$B$BТак, у Занзіла Вигнанця — троля, якого вигнали з власного племені через характер його «експериментів» із некромантією.$B$BЗвісно, отримавши отруту, вони почали випробовувати її одне на одному. Наслідки були катастрофічні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3469565912] = {
        ["english"] = { [1] = "Are the Burning Steppes currently under attack?" },
        ["text"] = "Палаючий степ зараз атакують?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [3280758210] = {
        ["english"] = { [1] = "Because the blade can never be too sharp nor the armor too tough a talented enchanter will always be needed.  Such an enchanter is Taladan, who can show you how to properly weave enchantments to improve your weapons and armor.  Seek him out in the Craftsmen's Terrace." },
        ["text"] = "Бо клинок ніколи не буває надто гострим, а обладунок — надто міцним, талановитий заклинач завжди потрібен. Таким є Таладан, який покаже, як правильно вплітати чари в зброю та обладунки. Шукай його на Терасі Ремісників.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2817969367] = {
        ["english"] = { [1] = "Beats me, kid. I'm new to the crew.$b$bI've had my fill of troll-killin' and grog drinkin, I can tell ya that. Only thing left to see is the treasure Budd keeps promisin'....$B" },
        ["text"] = "Гадки не маю, малий. Я новенький у команді.$b$bТролів я вже навбивався, ґроґу напився — цього мені вистачило. Залишилося побачити тільки той скарб, який Бадд весь час обіцяє...$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1784792975] = {
        ["english"] = { [1] = "$N, the Sons of Lothar have fought here, on the Hellfire Peninsula, for two decades.  We are beset on all sides by indigenous orcs and hellish demons of the Burning Crusade, and though our hearts still beat fiercely, years of war have reduced our numbers.$B$BYou, and the influx of Azeroth's new generation of heroes, are a welcome sight indeed!" },
        ["text"] = "$N, Сини Лотара б'ються тут, на Півострові Пекельного Вогню, вже два десятиліття. Нас з усіх боків обступили місцеві орки та пекельні демони Палаючого Легіону, і хоч наші серця досі палають відвагою, роки війни сильно прорідили наші лави.$B$BТи й нове покоління героїв Азероту — справді довгоочікуване підкріплення!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1652100669] = {
        ["english"] = { [1] = "Do you prefer guns or bows?" },
        ["text"] = "Ти віддаєш перевагу рушницям чи лукам?",
        ["npcs"] = { [1] = 3040, [2] = 3061 },
        ["roles"] = { ["greeting"] = true },
    },
    [1956069775] = {
        ["english"] = { [1] = "A darkness had fallen over my eyes, but you tore me from my unholy reverie.  You saved me, $N.$B$BAnd now I beg you... to forgive me." },
        ["text"] = "Темрява застилала мені очі, але ти вирвав мене з нечестивого забуття. Ти врятував мене, $N.$B$BА тепер я благаю тебе... пробач мені.",
        ["npcs"] = { [1] = 10936 },
        ["roles"] = { ["greeting"] = true },
    },
    [3227913351] = {
        ["english"] = { [1] = "Be welcome amongst us, $c." },
        ["text"] = "Ласкаво просимо до нас, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [193034646] = {
        ["english"] = { [1] = "A long time ago, during my travels, I met a man that told me, \"Master using it and you can have this.\"$B$BWhat do you suppose that means? I didn't know then, and I still don't now, really..." },
        ["text"] = "Давно, під час мандрів, я зустрів чоловіка, який сказав мені: \"Опануєш це — отримаєш ось це.\"$B$BЯк гадаєш, що він мав на увазі? Я не знав тоді й, правду кажучи, досі не знаю...",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [903794587] = {
        ["english"] = { [1] = "A Sulfuron ingot?!??! Impossible! I must have it! I must! I must!$B$B$R, I am authorized to make you a grand deal for that ingot. Perhaps you would be interested to know the secrets of the Hand of Ragnaros? Sulfuras, idiot! The legendary hammer of the Firelord." },
        ["text"] = "Злиток сульфурону?! Неможливо! Він мусить бути моїм! Мусить! Мусить!$B$B$R, я уповноважений запропонувати тобі надзвичайну угоду за цей злиток. Можливо, тебе зацікавлять таємниці Десниці Раґнароса? Сульфурас, йолопе! Легендарний молот Володаря вогню.",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["greeting"] = true },
    },
    [3093852425] = {
        ["english"] = { [1] = "<Angela nods.>$B$BAfter the deaths, the Six decided that the best course of action was to seal the staff behind impenetrable barriers of magic and appoint a watcher: A guardian of the staff... I would be that watcher." },
        ["text"] = "<Анжела киває.>$B$BПісля смертей Шістка вирішила, що найкраще буде замкнути посох за непроникними магічними бар'єрами й призначити вартового — охоронця посоха... Цим вартовим мала стати я.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3369325059] = {
        ["english"] = { [1] = "Be wary, friends. The Betrayer meditates in the court just beyond." },
        ["text"] = "Будьте обережні, друзі. Зрадник медитує у дворі просто попереду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4024913636] = {
        ["english"] = { [1] = "Be wary, $c. The forest is full of hidden dangers and potential enemies." },
        ["text"] = "Будь обережний, $c. Ліс повний прихованих небезпек і можливих ворогів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2306514843] = {
        ["english"] = { [1] = "Based on the sample of the toxin you provided for us, we think you will need the following: an arcane quickener, five somatic intensifiers, and and four pieces of runecloth.  With the vitreous focuser in tow, acquire the intensifiers from zombie or ghoul undead here in the Plaguelands!$B$BOnce you have these items, you should be able to load the counter agent into that cauldron." },
        ["text"] = "За зразком токсину, який ти нам надав, ми вважаємо, що тобі знадобляться: арканічний прискорювач, п'ять соматичних підсилювачів і чотири шматки рунічної тканини. Візьми склоподібний фокусатор і добудь підсилювачі із зомбі або гулів тут, у Чумнозем'ї!$B$BКоли матимеш ці предмети, зможеш завантажити протиотруту в той котел.",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["greeting"] = true },
    },
    [733270722] = {
        ["english"] = { [1] = "According to the latest count we have all of the copper bars we're going to need for the war. If I were you I'd check with some of the other collectors here to see if they need your help." },
        ["text"] = "За останніми підрахунками, ми вже маємо всі мідні зливки, потрібні для війни. На твоєму місці я б перевірив, чи не потрібна допомога іншим збирачам тут.",
        ["npcs"] = { [1] = 15459 },
        ["roles"] = { ["greeting"] = true },
    },
    [1234498703] = {
        ["english"] = { [1] = "Be warned, mortal, it is exceptionally rare that one of the lesser clans in this citadel would hold such an item. Your search could take decades. I recommend you destroy these beasts without impunity." },
        ["text"] = "Попереджаю, смертний: вкрай рідко хтось із менших кланів у цій цитаделі володіє таким предметом. Пошуки можуть тривати десятиліттями. Раджу без жалю винищувати цих звірів.",
        ["npcs"] = { [1] = 10296, [2] = 10299 },
        ["roles"] = { ["greeting"] = true },
    },
    [1654276521] = {
        ["english"] = { [1] = "<One gets the sense that Oric is here only in a sorry attempt at comic relief and shouldn't be paid attention to, as it will only encourage him.>" },
        ["text"] = "<Складається враження, що Орік тут лише заради жалюгідної спроби комічної розрядки, і краще не звертати на нього уваги — це лише його заохотить.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1936880188] = {
        ["english"] = { [1] = "Be advised, $g Jackson : Princess; - I am in no mood for any comment that you think is cute or funny.  I am here to make sure that the Arch Druid's research proceeds as planned, and my orders are to weed out all non-hackers who do not pack the gear to serve in my beloved Cenarion Circle." },
        ["text"] = "Попереджаю, $g Джексоне : принцесо; — я не в настрої слухати твої милі чи смішні коментарі. Я тут, щоб дослідження архідруїда йшли за планом, а мої накази — відсіяти всіх нездар, які не мають потрібного спорядження для служби в моєму любому Кенарієвому Колі.",
        ["npcs"] = { [1] = 9076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2014691779] = {
        ["english"] = { [1] = "Data access granted.  Have a nice day!$b$b01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011" },
        ["text"] = "Доступ до даних надано. Гарного дня!$b$b01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1218463778] = {
        ["english"] = { [1] = "Be sure to catch all the amazing sights and wonders of the Darkmoon Faire when it comes to town!" },
        ["text"] = "Обов'язково оглянь усі дивовижні видовища й чудеса Ярмарку Молодика, коли він приїде до міста!",
        ["npcs"] = { [1] = 14843 },
        ["roles"] = { ["greeting"] = true },
    },
    [3523032648] = {
        ["english"] = { [1] = "Anything else?" },
        ["text"] = "Щось іще?",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["reply"] = true },
    },
    [2966048023] = {
        ["english"] = { [1] = "$N, the Silverwing Sentinels must be crushed!  Are you ready for Warsong Gulch?" },
        ["text"] = "$N, Вартових Срібнокрилих треба розтрощити! Готовий до Ущелини Пісні Війни?",
        ["npcs"] = { [1] = 10360 },
        ["roles"] = { ["greeting"] = true },
    },
    [3456667571] = {
        ["english"] = { [1] = "Ahh, you will need to make your way over to the Hunter's Hall then. Several great hunters like Holt Thunderhorn can be found there on the Hunter Rise." },
        ["text"] = "Тоді тобі треба до Зали Мисливців. Там, на Верхів'ї Мисливців, знайдеш кількох великих мисливців, зокрема Голта Громорога.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3046422364] = {
        ["english"] = { [1] = "Be silent!  I cannot afford to miss even a moment of this lecture!" },
        ["text"] = "Тихо! Я не можу дозволити собі пропустити бодай мить цієї лекції!",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [1835293093] = {
        ["english"] = { [1] = "Be silent!  Do you think our plagued dragons will hatch and train themselves?" },
        ["text"] = "Тихо! Думаєш, наші зачумлені дракони самі вилупляться й самі себе натренують?",
        ["npcs"] = { [1] = 10432 },
        ["roles"] = { ["greeting"] = true },
    },
    [1226702507] = {
        ["english"] = { [1] = "Do you have the understanding to continue, shaman?  Do you know why you are here?" },
        ["text"] = "Ти достатньо розумієш, щоб продовжити, шамане? Знаєш, навіщо ти тут?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2924344410] = {
        ["english"] = { [1] = "Careful, don't get burned!" },
        ["text"] = "Обережно, не обпечися!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2341011397] = {
        ["english"] = { [1] = "After a couple of days of silence, I sent a scouting party out to the platform. They never returned.$B$BI sent another group the next day with the same results, and lost a couple of flying machines out on aerial recon.$B$BAt that point I sent someone south to find help, and we hunkered down to prepare for the worst. We turned all of our attention to making armor, weapons and robots so that we could head out there in full force.$B$BWhen we did a few days ago, we couldn't believe our eyes!" },
        ["text"] = "Після кількох днів тиші я послав розвідувальний загін до платформи. Вони не повернулися.$B$BНаступного дня відправив ще одну групу — результат той самий. Ще й кілька літальних апаратів загубили під час повітряної розвідки.$B$BТоді я послав когось на південь по допомогу, а ми засіли тут і стали готуватися до найгіршого. Усі сили кинули на виготовлення обладунків, зброї й роботів, щоб вийти туди всім загоном.$B$BКоли кілька днів тому ми таки рушили, то не повірили власним очам!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1948027994] = {
        ["english"] = { [1] = "Ah, you must go to the great heights of Thunder Bluff to visit one of those.  Follow the path north out of Bloodhoof Village.  At the base of the bluffs is an elevator that will take you to the top.  When you get there ask for further directions from one of the Bluffwatchers." },
        ["text"] = "А, до такого доведеться піднятися на високі яруси Громового Бескиду. Іди стежкою на північ із селища Криваве Копито. Біля підніжжя бескидів є підіймач, що доставить нагору. Там попроси подальших вказівок у когось із Вартових Бескиду.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [3342737103] = {
        ["english"] = { [1] = "All is lost..." },
        ["text"] = "Усе втрачено...",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [3600453298] = {
        ["english"] = { [1] = "All is gathered, $c. All is being transported for final preparation to Silithus and should arrive within $2113w days. All of our combined forces await the $g hero : heroine; that will complete the reunification of the Scepter of the Shifting Sands, ring the gong and begin the Ahn'Qiraj War." },
        ["text"] = "Усе зібрано, $c. Усе перевозять до Силітуса для останньої підготовки й мають доставити протягом $2113w днів. Усі наші об'єднані сили чекають на $g героя : героїню;, що завершить відновлення Скіпетра Мінливих Пісків, ударить у гонг і розпочне війну за Ан'Кіраж.",
        ["npcs"] = { [1] = 15453 },
        ["roles"] = { ["greeting"] = true },
    },
    [2350836406] = {
        ["english"] = { [1] = "A terrible, dark energy emanates from this pile of skulls." },
        ["text"] = "Від цієї купи черепів випромінюється жахлива темна енергія.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [829691350] = {
        ["english"] = { [1] = "Be careful out in the desert, $c." },
        ["text"] = "Будь обережний у пустелі, $c.",
        ["npcs"] = { [1] = 16543 },
        ["roles"] = { ["greeting"] = true },
    },
    [727289260] = {
        ["english"] = { [1] = "A tailor is it?  Well, if you hang out here long enough you'll eventually hear word of mouth about Georgio Bolero.  He's been setting the trends for some months now.  If you wish to learn from him, you can find him over in the Mage Quarter in the outer rim." },
        ["text"] = "Кравець, еге ж? Якщо достатньо довго тут побудеш, рано чи пізно почуєш про Джорджіо Болеро. Уже кілька місяців саме він задає моду. Якщо хочеш у нього вчитися, знайдеш його в Кварталі магів на зовнішньому кільці.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [4154475320] = {
        ["english"] = { [1] = "Ahhh, you are looking for Dungar Longdrink. He has some of the fastest gryphons this side of Khaz Modan! You can find him up on the ramparts in the Trade District." },
        ["text"] = "А-а, ти шукаєш Дунґара Довгопива. У нього одні з найшвидших грифонів по цей бік Каз-Модана! Знайдеш його на мурах у Торговому районі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [887372503] = {
        ["english"] = { [1] = "Be careful among the ruins, $c. The Kirin Tor spirits you find there will not recognize you as a friend.$B$BThe custodian and I are the only ones whose spirits retained a strong enough tie to this place to preserve our full identities in death." },
        ["text"] = "Будь обережний серед руїн, $c. Духи Кірін-Тору, яких там зустрінеш, не впізнають у тобі друга.$B$BЛише дух доглядача й мій зберегли досить сильний зв'язок із цим місцем, щоб після смерті не втратити особистість.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1200563845] = {
        ["english"] = { [1] = "Arthur Moore in Rogues' Quarter inner ring is one who teach leatherworking." },
        ["text"] = "Артур Мур на внутрішньому кільці Кварталу розбійників навчає шкірництва.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3932147756] = {
        ["english"] = { [1] = "<sniff's himself, and winces>$b$bThat there be the smell of adventure, $c!" },
        ["text"] = "<нюхає себе й кривиться>$b$bОце, $c, і є запах пригод!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1617180597] = {
        ["english"] = { [1] = "Be sure to try our Dark Iron Ale.  I hear the dwarves around here can't get enough of it." },
        ["text"] = "Обов'язково скуштуй наш ель Темного Заліза. Чув, місцеві дворфи його просто обожнюють.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [253322801] = {
        ["english"] = { [1] = "Battlemaster" },
        ["text"] = "Воєвода",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 4262, [5] = 5595, [6] = 6272, [7] = 6740, [8] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [490263236] = {
        ["english"] = { [1] = "A self-inflicted wound, friend.  I could not bear to look upon a world where I'd committed so many horrors under the Lich King's grasp.$B$BIt was my first step towards redemption, and if my sins are unforgivable, then I will attempt to atone for them for the rest of my life." },
        ["text"] = "Рана, завдана власною рукою, друже. Я не міг дивитися на світ, у якому вчинив стільки жахіть під владою Короля-ліча.$B$BЦе був мій перший крок до спокути, і якщо мої гріхи непростимі, я намагатимуся спокутувати їх до кінця життя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3599574552] = {
        ["english"] = { [1] = "Ah, good ol' Brandur Ironhammer.  There's no doubt he'll provide ye with the guidance ye seek, $glad : lass;.  Ye'll find him in the Hall of Mysteries north of the gates of Ironforge." },
        ["text"] = "А, добрий старий Брандур Залізний Молот. Без сумніву, він дасть тобі потрібні настанови, $gхлопче : дівчино;. Знайдеш його в Залі Таємниць на північ від брами Стальгорна.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2616026548] = {
        ["english"] = { [1] = "Ahh, ya couldn't resist, could ya? Want to be better, stronger, faster? Each one of these amulets be guaranteed to do just what I say they be doin'. Step up and buy one of these miraculous baubles! Cheap at twice the price!" },
        ["text"] = "Ага, не втримався, еге ж? Хочеш стати кращим, сильнішим, швидшим? Кожен із цих амулетів гарантовано робить саме те, що я кажу. Підходь і купуй ці дивовижні дрібнички! За таку ціну — майже задарма!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [57279463] = {
        ["english"] = { [1] = "Bat man on upper level of Trade Quarter." },
        ["text"] = "Кажаняр на верхньому рівні Торгового кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [740010276] = {
        ["english"] = { [1] = "Are you lost? Most of the town's vendors are situated near the center of town." },
        ["text"] = "Заблукав? Більшість торговців містечка стоять біля центру.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2576159218] = {
        ["english"] = { [1] = "$966w, young $c." },
        ["text"] = "$966w, юний $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1939378553] = {
        ["english"] = { [1] = "All of the collecting is done and the finished goods are being shipped over to Silithus as they're being completed. Looks like less than $2113w days until all of it is over there. After that we just need to get someone to ring that gong and open the gates to Ahn'Qiraj. Then the real fun begins." },
        ["text"] = "Усі збори завершено, а готові припаси відправляють до Силітуса одразу після підготовки. Схоже, менш ніж за $2113w днів усе буде там. Потім треба лише знайти когось, хто вдарить у гонг і відкриє брами Ан'Кіражу. Ось тоді почнеться справжня забава.",
        ["npcs"] = { [1] = 15515 },
        ["roles"] = { ["greeting"] = true },
    },
    [3171103138] = {
        ["english"] = { [1] = "Based on the sample of the toxin you provided for us, we think you will need the following: an arcane quickener, four ectoplasmic resonators, and four pieces of runecloth.  With the vitreous focuser in tow, acquire the resonators from wraith and ghostly undead here in the Plaguelands!$B$BOnce you have these items, you should be able to load the counter agent into that cauldron." },
        ["text"] = "За зразком токсину, який ти нам надав, ми вважаємо, що тобі знадобляться: арканічний прискорювач, чотири ектоплазмові резонатори й чотири шматки рунічної тканини. Візьми склоподібний фокусатор і добудь резонатори з примарної невмерлі тут, у Чумнозем'ї!$B$BКоли матимеш ці предмети, зможеш завантажити протиотруту в той котел.",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["greeting"] = true },
    },
    [4029380848] = {
        ["english"] = { [1] = "Be wary of the Ethereum that surround us on all sides." },
        ["text"] = "Остерігайся Етерію, що оточує нас з усіх боків.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [399754343] = {
        ["english"] = { [1] = "Dirge Quikcleave of Gadgetzan is a master of the culinary arts.  To better yourself you will need to seek him out." },
        ["text"] = "Дірдж Швидкоріз із Пристробляска — справжній майстер кулінарного мистецтва. Якщо хочеш удосконалитися, тобі доведеться його знайти.",
        ["npcs"] = { [1] = 1355, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 2818, [6] = 3026, [7] = 3067, [8] = 3087, [9] = 3399, [10] = 4210, [11] = 4552, [12] = 5159, [13] = 6286, [14] = 8306 },
        ["roles"] = { ["greeting"] = true },
    },
    [556223217] = {
        ["english"] = { [1] = "Both Garrosh's Landing and Pal'ea were wiped out by the mist. We're the only ones crazy enough to stay here, buddy!" },
        ["text"] = "І Табір Ґарроша, і Пал'ея були знищені туманом. Ми єдині божевільні, які лишилися тут, друже!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2172291100] = {
        ["english"] = { [1] = "<Eralan appears to be chewing on some deathweed.>$b$bIf you're looking to make a love potion, you've got the wrong place.  Blinding, crippling, and killing is my business and hopefully yours." },
        ["text"] = "<Схоже, Ералан жує якусь смертетраву.>$b$bЯкщо шукаєш місце, де зварити любовне зілля, ти помилився адресою. Осліпити, скалічити чи вбити — ось моя справа і, сподіваюся, твоя теж.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4236624284] = {
        ["english"] = { [1] = "Ah, you seek the wisdom of Ansekhwa.  Look for him on the lower rise at Thunder Bluff Weapons." },
        ["text"] = "А, ти шукаєш мудрості Ансекви. Шукай його на нижньому ярусі, у Зброярні Громового Бескиду.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3641957454] = {
        ["english"] = { [1] = "\"Darnassae?\"$B$BThe night elf druid looks at you expectantly, but it is clear you cannot verbally communicate with her.  Undaunted, she points to herself and smiles.  She points at you and smiles once more.  She finally motions several times down the path to the north.$B$BPerhaps she is indicating that there is a druid you can speak to further up the road?" },
        ["text"] = "\"Дарнассе?\"$B$BДруїдка нічних ельфів очікувально дивиться на вас, але очевидно, що ви не можете порозумітися з нею словами. Не знітившись, вона вказує на себе й усміхається. Потім вказує на вас і знову всміхається. Насамкінець кілька разів показує вздовж стежки на північ.$B$BМожливо, вона натякає, що далі дорогою є друїд, з яким ви зможете поговорити?",
        ["npcs"] = { [1] = 9528 },
        ["roles"] = { ["greeting"] = true },
    },
    [1908839959] = {
        ["english"] = { [1] = "$C, even our hardiest warriors and scouts will need use of the healing arts in the war to come at Ahn'Qiraj. And when there is no magical healing available, they must rely upon our efforts here.$B$BTo date I have collected $2088w runecloth bandages, out of $2090w needed. If you are willing, we should speak further on how you can do your part." },
        ["text"] = "$C, у майбутній війні за Ан'Кіраж навіть нашим найвитривалішим воїнам і розвідникам знадобиться мистецтво зцілення. А коли магічне зцілення буде недоступне, їм доведеться покладатися на нашу працю.$B$BНаразі я зібрав $2088w бинтів із рунічної тканини з потрібних $2090w. Якщо ти готовий допомогти, поговорімо про те, що саме ти можеш зробити.",
        ["npcs"] = { [1] = 15453 },
        ["roles"] = { ["greeting"] = true },
    },
    [3859772483] = {
        ["english"] = { [1] = "Bank in Trade Quarter central tower.  You not miss it." },
        ["text"] = "Банк у центральній вежі Торгового кварталу. Не пропустиш.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3479444700] = {
        ["english"] = { [1] = "All muscle and no brain, that's what peons are! They're great when you can motivate them, but they have to be 'kick' started, if you know what I mean." },
        ["text"] = "Самі м'язи, а мозку нема — ось хто такі наймити! Вони чудово працюють, якщо їх мотивувати, але спершу треба добряче «підштовхнути», якщо розумієш, про що я.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [92473273] = {
        ["english"] = { [1] = "Are you the correspondent from the Gadgetzan Times? If you just follow me, I'll show you my experimental apparatus...$B$B<You tell the magus that you're not the reporter she's expecting.>$B$BOh, you're not? Well then, if you need reagents, find what you need and don't tarry. I'm expecting someone." },
        ["text"] = "Ти кореспондент «Пристробляських вістей»? Іди за мною, я покажу свою експериментальну установку...$B$B<Ви кажете магині, що ви не той репортер, на якого вона чекає.>$B$BО, ні? Тоді, якщо потрібні реагенти, бери що треба й не барися. Я чекаю на когось.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2192541392] = {
        ["english"] = { [1] = "Ah, a fellow warlock who has proven $ghis:her; worth to some degree.$B$BI am pleased to meet your acquaintance. My name is Menara Voidrender... and not without just cause.$B$BYou seem powerful and well-learned enough that other tools... more powerful tools... would be welcome and not foolishly imparted. If this is true, then speak to me further. If not, well then, you know your way  back to the docks and off into the ocean." },
        ["text"] = "А, колега-чорнокнижник, який уже певною мірою довів $gсвою:свою; цінність.$B$BПриємно познайомитися. Мене звати Менара Роздирачка Порожнечі... і недаремно.$B$BТи виглядаєш достатньо сильним і досвідченим, щоб інші знаряддя... могутніші знаряддя... стали тобі в пригоді й не були віддані дурневі. Якщо це так — поговори зі мною ще. Якщо ні, то дорогу назад до доків і просто в океан ти знаєш.",
        ["npcs"] = { [1] = 6266 },
        ["roles"] = { ["greeting"] = true },
    },
    [736136190] = {
        ["english"] = { [1] = "Back off or I'll cut you in half." },
        ["text"] = "Відступи, або я розрубаю тебе навпіл.",
        ["npcs"] = { [1] = 11193 },
        ["roles"] = { ["greeting"] = true },
    },
    [1681204051] = {
        ["english"] = { [1] = "A closer inspection of the pylon leads you to find a small table containing yellow, red, and green crystals arranged in what seems like a specific formation.$B$BA large yellow circle of crystals is flanked on either side by a smaller circle of red crystals and another of green crystals.$B$BYou carefully take note of the colors of the crystals, knowing that J.D. would be very interested in hearing about what you have found." },
        ["text"] = "Уважніше оглянувши пілон, ви знаходите невеликий столик із жовтими, червоними й зеленими кристалами, викладеними в певному порядку.$B$BВелике жовте коло кристалів з обох боків оточене меншими колами червоних і зелених кристалів.$B$BВи ретельно запам'ятовуєте кольори кристалів, знаючи, що Дж. Д. дуже зацікавиться вашою знахідкою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [363443993] = {
        ["english"] = { [1] = "Clothing the tribe is as important a job as any other.  You should look for Tepa inside Thunder Bluff Armorers.  She has a natural way with the needle." },
        ["text"] = "Одягати плем'я — робота не менш важлива за будь-яку іншу. Шукай Тепу в «Зброярах Громового Бескиду». Вона від природи вправна з голкою.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2542725402] = {
        ["english"] = { [1] = "Balai Lok'Wein of Brackenwall Village in Dustwallow Marsh sells a manual that you will need to study in order to improve your skills!" },
        ["text"] = "Балай Лок'Вейн із селища Папорохащі в Бруднолипкій трясовині продає посібник, який тобі треба вивчити, щоб покращити свої навички!",
        ["npcs"] = { [1] = 2798, [2] = 3373, [3] = 4591, [4] = 5759, [5] = 5939, [6] = 5943 },
        ["roles"] = { ["greeting"] = true },
    },
    [2832323551] = {
        ["english"] = { [1] = " Decipher the pattern and learn its content." },
        ["text"] = " Розшифруй викрійку та вивчи її вміст.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2841603231] = {
        ["english"] = { [1] = "Another student. Wonderful. This is why Lydon belongs to the Royal Society of Snobs and gets to do research, and I'm stuck being an instructor. If I win another teaching award, I'll never live it down!" },
        ["text"] = "Ще один учень. Чудово. Ось чому Лайдон належить до Королівського товариства снобів і займається дослідженнями, а я застряг тут наставником. Якщо отримаю ще одну нагороду за викладання, мені цього ніколи не забудуть!",
        ["npcs"] = { [1] = 2391 },
        ["roles"] = { ["greeting"] = true },
    },
    [174590013] = {
        ["english"] = { [1] = "Ah yes, another who will stoke the fires and forge the weapons of war. Of course I will teach you how." },
        ["text"] = "Ага, ще один, хто розпалюватиме горнило й куватиме зброю війни. Авжеж, я тебе навчу.",
        ["npcs"] = { [1] = 3557 },
        ["roles"] = { ["greeting"] = true },
    },
    [2864289641] = {
        ["english"] = { [1] = "Bah!  Mailboxes...  all I get is junk mail lately!  \010\010Increase the size of this... decrease the size of that... act now for your free Sword of Dragonslaying.  I have to change my mailbox number every other month!  \010\010Well, ye can't say I didn't warn ye.  If you're looking for the mailbox it's just outside the Stonefire Tavern." },
        ["text"] = "Ба! Поштові скриньки... останнім часом мені приходить самий непотріб!  \010\010Збільште розмір цього... зменште розмір того... замовте зараз і отримайте безкоштовний Меч Драконовбивства. Я вже через місяць змінюю номер поштової скриньки!  \010\010Ну, не кажи потім, що я не попереджав. Якщо шукаєш скриньку, вона просто біля таверни «Кам'яний Вогонь».",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1661194790] = {
        ["english"] = { [1] = "And did he?" },
        ["text"] = "І він це зробив?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [1577405263] = {
        ["english"] = { [1] = "Back to learn more, $N? Come over here and show me you are ready." },
        ["text"] = "Повернувся вчитися далі, $N? Підійди й покажи, що готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [613291035] = {
        ["english"] = { [1] = "Azure Templar! I hold your signet! Heed my call!" },
        ["text"] = "Лазуровий храмовнику! Твоя печатка в мене! Відгукнися на мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [146861603] = {
        ["english"] = { [1] = "A warlock, eh...  Well, if you've got a mind to be doing that sort of thing around here then ye best keep yer demons on a leash $gboyo : girlie;.  I don't like demons, but I love putting mah axe to them.  Ye get me?  \010\010Now you just leave me be and go get lost in The Forlorn Cavern.  That's where you'll find that warlock, Thistleheart." },
        ["text"] = "Чорнокнижник, еге ж... Ну, якщо надумав займатися таким тут, то краще тримай своїх демонів на повідку, $gхлопче : дівчино;. Я демонів не люблю, зате люблю знайомити їх зі своєю сокирою. Зрозумів?  \010\010А тепер лиши мене в спокої та забирайся до Закинутої печери. Там і знайдеш того чорнокнижника, Колючесерда.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [2435037417] = {
        ["english"] = { [1] = "A search of the corpse's clothing and equipment reveals the insignia you need, undamaged by the battle and foul environment." },
        ["text"] = "Обшукавши одяг і спорядження трупа, ви знаходите потрібний знак — неушкоджений битвою й огидним довкіллям.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1669577668] = {
        ["english"] = { [1] = "Buliwyf can teach you how to use axes! He's around this shop somewhere." },
        ["text"] = "Булівіф навчить тебе користуватися сокирами! Він десь тут, у цій крамниці.",
        ["npcs"] = { [1] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [3340246130] = {
        ["english"] = { [1] = "Ah, a young warrior to be no doubt!  I take it you are participating in Children's Week, yes?  It warms these weary bones to hear that you are setting the example by which others will be sure to follow.$B$BI'd be delighted to oblige you and the young lad.  Hrmm... what advice should I give to him?  Listen to the spirits, yes... maybe something about eating all of his vegetables too..." },
        ["text"] = "А, без сумніву, майбутній юний воїн! Ти береш участь у Тижні дітей, так? Старі кістки аж теплішають від думки, що ти подаєш приклад іншим.$B$BІз радістю допоможу тобі й хлопчині. Гм... яку ж пораду дати? Слухай духів, так... і, може, ще щось про те, щоб їсти всі овочі...",
        ["npcs"] = { [1] = 3057 },
        ["roles"] = { ["greeting"] = true },
    },
    [2466098035] = {
        ["english"] = { [1] = "Aye, that's her name, and a fine ship she is.$b$bThere's much to learn from such vessels, you know. A great poet once said: Ships that pass in the night, and speak each other in passing, only a signal shown, and a distant voice in the darkness; So on the ocean of life, we pass and speak one another, only a look and a voice, then darkness again and a silence." },
        ["text"] = "Так, саме так її звати, і корабель вона чудовий.$b$bВід таких суден можна багато чого навчитися. Один великий поет сказав: «Кораблі, що минають у ночі й перемовляються на ходу, лише сигнал у темряві та далекий голос; так і на океані життя ми минаємо одне одного, лише погляд і голос — а потім знову темрява й тиша».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3436584088] = {
        ["english"] = { [1] = "<As you place your apexis shards within the hollow of the Bash'ir crystalforge and pull the lever, the device literally disintegrates them.  A few moments later your flask appears at your feet.>" },
        ["text"] = "<Коли ви кладете уламки апекситу в заглибину кристалокузні Баш'іра й тягнете важіль, пристрій буквально розщеплює їх. За кілька митей біля ваших ніг з'являється флакон.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1328829589] = {
        ["english"] = { [1] = "Aye, I would love ta teach ye a thing or two about smithing. Grab an apron and a hammer and let's see what we can accomplish shall we?" },
        ["text"] = "Так, із радістю навчу тебе дечого про ковальство. Одягай фартух, бери молот і подивимося, чого зможемо досягти, гаразд?",
        ["npcs"] = { [1] = 5511, [2] = 10276 },
        ["roles"] = { ["greeting"] = true },
    },
    [2084450208] = {
        ["english"] = { [1] = "Alas... I am sorry to say I cannot currently give you your fortune, as you have recently received a fortune reading from me.$B$BReturn to me several hours from when you first received your fortune.  The forces of Fate will have properly recalibrated themselves, and I will be able to see into your future." },
        ["text"] = "На жаль... зараз я не можу передбачити твою долю, бо зовсім недавно вже робив це.$B$BПовернися через кілька годин після першого передбачення. Сили Долі належно переналаштуються, і я знову зможу зазирнути у твоє майбутнє.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1182920870] = {
        ["english"] = { [1] = "Aye, I did. Much to the dismay of the lesser Mograine, I made my way back to the Scarlet Monastery. I shouted and screamed. I told the tale to any that would listen. And I would be murdered in cold blood for my actions, dragged to this chamber - the dark secret of the order. But some did listen... some heard my words. Thus was born the Argent Dawn..." },
        ["text"] = "Так. На превеликий жаль молодшого Моґрейна, я повернувся до Багряного монастиря. Я кричав і волав. Розповідав правду всім, хто готовий був слухати. За це мене холоднокровно вбили й притягли до цієї кімнати — темної таємниці ордену. Але дехто таки слухав... дехто почув мої слова. Так народився Сріблястий Світанок...",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [3548864186] = {
        ["english"] = { [1] = "Aye, I could tell just by looking at you, $N. You remind me very much of myself as a young warrior of the Horde.$B$BYou will undoubtedly go far in life and even further in death.$B$B<Goretooth salutes.>" },
        ["text"] = "Так, я одразу це побачив, $N. Ти дуже нагадуєш мене самого, коли я був молодим воїном Орди.$B$BБез сумніву, ти далеко підеш у житті — і ще далі після смерті.$B$B<Горозуб віддає честь.>",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["greeting"] = true },
    },
    [3620900027] = {
        ["english"] = { [1] = "Aye, he had done what was thought to be impossible. Out from the fissure sprung an agent of Therazane!$B$BFrom my vantage point, I could see the goblin holding conversation with the agent of the Old God. What happened after that was terrible..." },
        ["text"] = "Так, він зробив те, що вважали неможливим. Із тріщини вирвався посланець Теразан!$B$BЗі свого місця я бачив, як гоблін розмовляв із посланцем Старого Бога. Те, що сталося потім, було жахливим...",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["greeting"] = true },
    },
    [3140814846] = {
        ["english"] = { [1] = "Aye, everyone wants to ride the tram, it's a real hoot and a half.  Well, if ye want to find the tram, it's located over in Tinker Town just east of the gates of Ironforge." },
        ["text"] = "Так, усі хочуть проїхатися трамваєм — весела штука. Якщо шукаєш його, він у Штукарівці, просто на схід від брами Стальгорна.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [3396704486] = {
        ["english"] = { [1] = "$n! I've been awaiting your return. What be takin' ya so long, mon?$b$bIt be time to complete da conversion of da Blightbloods.$b$bJoin me and witness the creation of our army!" },
        ["text"] = "$n! Я чекав на твоє повернення. Чого так довго, мон?$b$bНастав час завершити перетворення Крові Пошесті.$b$bПриєднуйся до мене й стань свідком народження нашої армії!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4129753641] = {
        ["english"] = { [1] = "Aye, but I know it by its true name - Eldre'Thalas.  It was a bastion of magical power for the night elves many, many years ago.$B$BYou know of Eldre'Thalas, young one?  One might say that is coincidental to my current plight... but I am one not to believe in coincidence." },
        ["text"] = "Так, але я знаю його справжню назву — Елдре'Талас. Багато-багато років тому це був осередок могутньої магії нічних ельфів.$B$BТи знаєш про Елдре'Талас, юначе? Можна сказати, що це випадково пов'язано з моєю нинішньою бідою... але я не вірю у випадковості.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1464573595] = {
        ["english"] = { [1] = "<High Inquisitor Fairbanks lifts up his tabard revealing several gruesome scars.>$B$BBecause I was there... I was the Highlord's most trusted advisor. I should have known... I felt that something was amiss yet I allowed it to happen. Would you believe that there were a thousand or more Scourge?" },
        ["text"] = "<Верховний інквізитор Феєрбенкс підіймає гербову накидку, відкриваючи кілька моторошних шрамів.>$B$BБо я був там... Я був найнадійнішим радником Верховного лорда. Я мав здогадатися... Я відчував, що щось не так, але все одно допустив це. Ти повіриш, що Скверни було тисяча, а може й більше?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [41850668] = {
        ["english"] = { [1] = "Before my death, I was a librarian; I had nothing to do with wars and plagues. I never asked to become this. On the other hand, now that my mind is my own again, I'm not about to surrender without a fight." },
        ["text"] = "До смерті я був бібліотекарем; я не мав нічого спільного з війнами й чумою. Я не просив, щоб зі мною це сталося. Та тепер, коли мій розум знову належить мені, я не збираюся здаватися без бою.",
        ["npcs"] = { [1] = 4588 },
        ["roles"] = { ["greeting"] = true },
    },
    [1050261036] = {
        ["english"] = { [1] = "A man can only live with himself and his shame for so long, $c, before he must take action to undo the mistakes he's made." },
        ["text"] = "Людина може жити із собою й власним соромом лише певний час, $c, а потім мусить діяти, щоб виправити свої помилки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2571093364] = {
        ["english"] = { [1] = "Come closer, young one.  In my time I could hear the flutter of a prey's beating heart, but now you must speak up if you want your words heard." },
        ["text"] = "Підійди ближче, юний друже. Колись я чув навіть тріпотіння серця здобичі, та тепер говори голосніше, якщо хочеш, щоб я тебе почув.",
        ["npcs"] = { [1] = 3052 },
        ["roles"] = { ["greeting"] = true },
    },
    [1805200886] = {
        ["english"] = { [1] = "Alas $c, you are not considered to be exalted to Darnassus and the night elves of Teldrassil.  Only when you prove yourself to us through deeds - not just mere words - will I then make available my selection of mounts for your perusal." },
        ["text"] = "На жаль, $c, тебе ще не вважають звеличеним Дарнасом і нічними ельфами Тельдрассіла. Лише коли доведеш відданість учинками, а не порожніми словами, я дозволю тобі оглянути моїх верхових тварин.",
        ["npcs"] = { [1] = 4730 },
        ["roles"] = { ["greeting"] = true },
    },
    [562449564] = {
        ["english"] = { [1] = "Awaiting orders!" },
        ["text"] = "Чекаю наказів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1708980577] = {
        ["english"] = { [1] = "Ah yes, I have read of you, $N." },
        ["text"] = "А, так, я читав про тебе, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3907096586] = {
        ["english"] = { [1] = "<Brann looks at you expectantly.>" },
        ["text"] = "<Бранн очікувально дивиться на вас.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1656364239] = {
        ["english"] = { [1] = "Awaiting orders from my superiors!" },
        ["text"] = "Чекаю наказів від начальства!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3408769971] = {
        ["english"] = { [1] = "Auction House" },
        ["text"] = "Аукціонний дім",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 4262, [5] = 5595, [6] = 6272, [7] = 6740, [8] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [543227100] = {
        ["english"] = { [1] = "All the fisherman have moved to Darnassus with the recent attacks around Lake Al'Ameth.  You should try looking for someone to train you there." },
        ["text"] = "Через недавні напади біля озера Ал'Амет усі рибалки перебралися до Дарнаса. Спробуй пошукати там когось, хто тебе навчить.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3267283746] = {
        ["english"] = { [1] = "Chromie, you and I both know what's going to happen in this time stream. We've seen this all before. Can you just skip us ahead to all the real action?" },
        ["text"] = "Хромі, ми обоє знаємо, що станеться в цьому плині часу. Ми вже все це бачили. Може, просто перенесеш нас одразу туди, де починається справжня дія?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [619033027] = {
        ["english"] = { [1] = "At last, my soul is free!" },
        ["text"] = "Нарешті моя душа вільна!",
        ["npcs"] = { [1] = 11064 },
        ["roles"] = { ["greeting"] = true },
    },
    [4294711292] = {
        ["english"] = { [1] = "$G Brother:Sister;, you are now considered bound by blood to the Netherwing. All of Netherwing will be behind you now! The time to strike at the heart of our enemies is now, friend! We must reclaim our lost heritage." },
        ["text"] = "$G Брате:Сестро;, віднині тебе вважають пов'язаним кров'ю з Крилом Порожнечі. Усе Крило Порожнечі стоятиме за тобою! Настав час ударити в саме серце наших ворогів, друже! Ми мусимо повернути втрачену спадщину.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2548079001] = {
        ["english"] = { [1] = "<The lord-commander fixes you with a stare before going on.>$B$BI was getting to that. Indeed, when High General Abbendis landed her forces on Northrend, she changed their name to the Scarlet Onslaught.$B$BIt was not long before Admiral Barean Westwind presented himself to her at New Hearthglen in the Dragonblight. From all accounts, she wasn't expecting him. Nor was she expecting that he would undermine her authority and take the reins of command away from her.$B$BLikely you were involved with her demise, but no matter. Once she was dead, the admiral made a mysterious exit and we lost track of him." },
        ["text"] = "<Лорд-командир свердлить вас поглядом і продовжує.>$B$BЯ саме до цього й веду. Коли верховний генерал Аббендіс висадила свої війська в Нортренді, вона перейменувала їх на Багряний Натиск.$B$BНевдовзі адмірал Бареан Західний Вітер з'явився перед нею в Новому Вогнеграді на Драконовому кладовищі. За всіма свідченнями, вона його не чекала. І вже точно не чекала, що він підірве її владу й перебере командування.$B$BІмовірно, ти був причетний до її загибелі, але це неважливо. Після її смерті адмірал загадково зник, і ми втратили його слід.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3237694498] = {
        ["english"] = { [1] = "Become a mentor for one of our orphans during the Week of the Wardens!  Huzzah!\010" },
        ["text"] = "Стань наставником для одного з наших сиріт під час Тижня Опікунів! Ура!\010",
        ["npcs"] = { [1] = 14450 },
        ["roles"] = { ["greeting"] = true },
    },
    [3828046316] = {
        ["english"] = { [1] = "A friend of the Zandalrian! You have ventured deep into the lair of the Blood God, $c. You will do well to listen to what I have to say.$B$BMany thousands of years ago, while the indigenous trolls of the Zul'Aman empire were battling the invading high elf heathens, great magic was stolen from Zanza. This magic was used by the high elves to enchant their weapons and armor to assist in conquering the trolls of the region." },
        ["text"] = "Друг зандаларців! Ти зайшов далеко в лігво Бога Крові, $c. Тобі варто уважно вислухати мене.$B$BБагато тисяч років тому, коли місцеві тролі імперії Зул'Аман билися проти загарбників-високих ельфів, у Занзи викрали могутню магію. Високі ельфи використали її, щоб зачарувати свою зброю й обладунки та завоювати тролів цього краю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4045266045] = {
        ["english"] = { [1] = "Ahoy, mon!  What be happenin', ye salty 'at steppa!$B$BDis place be all chacka-chacka, ye scallywag!" },
        ["text"] = "Йо-хо, мон! Шо коїться, ти солоний морський тупотун?$B$BТут усе суцільне чака-чака, пірате!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3503633581] = {
        ["english"] = { [1] = "A child of nature are we? Then you need look no further then the moonwell in the Park." },
        ["text"] = "Дитя природи, еге ж? Тоді тобі не треба шукати далі за місячний колодязь у Парку.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [767282492] = {
        ["english"] = { [1] = "Anyway, we needed to pump up lots of sand and oil for the machinery. The nearby pools proved to be perfect for that.$B$BSome of the sand even proved to have magical properties... can you say possibilities!? But that's a different tale.$B$BSo, we drained most of the water out and built the pumping station smack dab in the middle. Everything was going swimmingly until one day the main suction pipe got clogged." },
        ["text"] = "Коротше, нам треба було викачувати багато піску й нафти для машин. Навколишні ставки чудово для цього підходили.$B$BДеякий пісок навіть виявився магічним... уявляєш можливості!? Але це інша історія.$B$BТож ми спустили більшу частину води й збудували насосну станцію просто посередині. Усе йшло як по маслу, аж одного дня головна всмоктувальна труба забилася.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4289447332] = {
        ["english"] = { [1] = "All the bottles on this table are potions I brewed today. And they say a watched pot never boils. Ha!" },
        ["text"] = "Усі пляшки на цьому столі — зілля, які я зварив сьогодні. А кажуть, якщо дивитися на казан, він ніколи не закипить. Ха!",
        ["npcs"] = { [1] = 11046 },
        ["roles"] = { ["greeting"] = true },
    },
    [3800658565] = {
        ["english"] = { [1] = "As you inspect the cage and the Night elf inside, you get an odd sense of deja vu. For some reason she does not make eye contact with you--it is almost as if you are not there to her." },
        ["text"] = "Оглядаючи клітку й нічну ельфійку всередині, ви відчуваєте дивне дежавю. З якоїсь причини вона не зустрічається з вами поглядом — наче вас для неї взагалі не існує.",
        ["npcs"] = { [1] = 11016 },
        ["roles"] = { ["greeting"] = true },
    },
    [2755740791] = {
        ["english"] = { [1] = "*Whirr* *CLANK*\010\010I have been instructed to accept high quality rare fish and return valuable Nat Pagle fishing accessories.   Fish Requested.\010\010*THUMP* *Buzz*\010" },
        ["text"] = "*Вж-ж-ж* *КЛАНК*\010\010Мені наказано приймати рідкісну рибу високої якості й натомість видавати цінне рибальське спорядження Ната Пеґла. Потрібна риба.\010\010*ТУП* *Дз-з-з*\010",
        ["npcs"] = { [1] = 15079 },
        ["roles"] = { ["greeting"] = true },
    },
    [1427708790] = {
        ["english"] = { [1] = "<Tarsis groans.>$B$BThere may still be time... Listen closely, mortal.$B$BThrough time and across the Nether I have searched. Deals made with a host of evil and villainy so wretched...$B$B<Tarsis coughs blood into his hands.>$B$BWould you... would you believe that even Elune has turned her back on me, $r? To die here, in this manner now..." },
        ["text"] = "<Тарсіс стогне.>$B$BМожливо, ще є час... Слухай уважно, смертний.$B$BЯ шукав крізь час і по всій Крутоверті Порожнечі. Укладав угоди з таким сонмищем мерзенного зла й негідників...$B$B<Тарсіс кашляє кров'ю собі в долоні.>$B$BТи... ти повіриш, що навіть Елуна відвернулася від мене, $r? Померти тут, ось так, саме тепер...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1429339453] = {
        ["english"] = { [1] = "A leatherworker, eh? Very well. What would you like to learn about, leatherworker?$B$B" },
        ["text"] = "Шкіряник, еге ж? Гаразд. Про що ти хочеш дізнатися, шкірянику?$B$B",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["greeting"] = true },
    },
    [1503843521] = {
        ["english"] = { [1] = "Buliwyf, the dwarven weapon master right here at the Timberline Arms, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.\010\010Woo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff.\010\010Ilyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons." },
        ["text"] = "Булівіф, дворф-майстер зброї тут, у «Лісовому краї», навчає кулачної зброї, рушниць, одноручних і дворучних сокир та одноручних і дворучних булав.\010\010Ву Пін, людський майстер зброї в Арсеналі Веллера у Штормовії, навчає арбалетів, кинджалів, одноручних і дворучних мечів, древкової зброї та посохів.\010\010Іленія Місячний Вогонь, майстриня зброї нічних ельфів, мешкає на Терасі Воїнів у Дарнасі, де навчає луків, кинджалів, кулачної зброї, посохів і метальної зброї.",
        ["npcs"] = { [1] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1767722280] = {
        ["english"] = { [1] = "$C, you didn't happen to see a courier on your way here? We are awaiting word from Silvermoon City and their messenger is late!" },
        ["text"] = "$C, тобі часом не траплявся дорогою сюди кур'єр? Ми чекаємо звістки зі Срібномісяця, а наш посланець запізнюється!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2512092886] = {
        ["english"] = { [1] = "A restful sleep is sure to be had in the beds which Innkeeper Keldamyr keeps at the Inn in Dolanaar.  " },
        ["text"] = "У ліжках, які доглядає корчмар Келдамір у таверні Доланаара, тобі неодмінно добре відпочинеться.  ",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2471624421] = {
        ["english"] = { [1] = "At dis point you know as much as I do, mon. Maybe you go see Magar in Orgrimmar. He not be da happiest tailor around, but he help you anyway." },
        ["text"] = "Тепер ти знаєш стільки ж, скільки і я, мон. Може, сходиш до Маґара в Орґріммарі. Він не найвеселіший кравець, але все одно допоможе.",
        ["npcs"] = { [1] = 3484 },
        ["roles"] = { ["greeting"] = true },
    },
    [3998563038] = {
        ["english"] = { [1] = "<Mathredis gazes intently at the libram.>$B$BYou come for an amalgamation? Have you done as the libram instructed?" },
        ["text"] = "<Матредіс пильно вдивляється в лібрам.>$B$BТи прийшов по злиття? Ти зробив усе, як наказував лібрам?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [840483268] = {
        ["english"] = { [1] = "And you did..." },
        ["text"] = "І ти це зробив...",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [6112222] = {
        ["english"] = { [1] = "Are you interested in learning the intricacies of Jewelcrafting?" },
        ["text"] = "Хочеш пізнати тонкощі ювелірної справи?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2654407536] = {
        ["english"] = { [1] = "Crimson Templar! I hold your signet! Heed my call!" },
        ["text"] = "Багряний храмовнику! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2747848357] = {
        ["english"] = { [1] = "<As you place your apexis shards into the fel crystalforge and pull the lever, the device makes an unworldly sound as it grinds them into dust.  A few moments later your flasks pop out of its 'mouth'.>" },
        ["text"] = "<Коли ви кладете уламки апекситу до кристалокузні Скверни й тягнете важіль, пристрій видає потойбічний звук, перемелюючи їх на порох. За кілька митей із його \"рота\" вискакують ваші флакони.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2610508781] = {
        ["english"] = { [1] = "As you gain renown with our town, I can make more goods available to you, $N.  With equipment in such short supply we can only afford to provide it to those we trust." },
        ["text"] = "Чим більше слави ти здобуватимеш у нашому містечку, тим більше товарів я зможу тобі запропонувати, $N. Спорядження в страшенному дефіциті, тож ми можемо давати його лише тим, кому довіряємо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1802716652] = {
        ["english"] = { [1] = "<Put your hand on the sphere.>" },
        ["text"] = "<Покласти руку на сферу.>",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2208953291] = {
        ["english"] = { [1] = "As the wind on the plains, you are always welcome here." },
        ["text"] = "Як вітер над рівнинами, ти завжди тут бажаний гість.",
        ["npcs"] = { [1] = 3934, [2] = 6746, [3] = 6747, [4] = 7714, [5] = 7737, [6] = 9501, [7] = 11106, [8] = 11116 },
        ["roles"] = { ["greeting"] = true },
    },
    [228742574] = {
        ["english"] = { [1] = "Are you the reinforcements? The night elves have been routed!" },
        ["text"] = "Ви підкріплення? Нічних ельфів розгромлено!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1169792953] = {
        ["english"] = { [1] = "As the only apparent surviving 'Broken', it is both my duty and honor to carry on the shamanistic teachings of Farseer Nobundo." },
        ["text"] = "Як єдиний, схоже, вцілілий Зломлений, я маю і обов'язок, і честь продовжувати шаманські вчення Провидця Нобундо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2965945825] = {
        ["english"] = { [1] = "Ah, $N, don't cry. Lucky for you, when last you gave me the amulet, I attuned myself to it. I'll just summon it back from wherever you dropped it.$B$BTry looking in your bags now." },
        ["text"] = "Ну-ну, $N, не плач. На щастя, коли ти востаннє віддав мені амулет, я налаштувався на нього. Просто прикличу його назад, звідки б ти його не загубив.$B$BПеревір тепер свої сумки.",
        ["npcs"] = { [1] = 16033 },
        ["roles"] = { ["greeting"] = true },
    },
    [3033593245] = {
        ["english"] = { [1] = "As often as I can.  It's great exercise and it keeps me informed on what they're up to--which, from my experience, is always no good." },
        ["text"] = "Так часто, як можу. Це чудова вправа й допомагає знати, що вони задумують — а з мого досвіду, нічого доброго.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4110619401] = {
        ["english"] = { [1] = "Absolutely." },
        ["text"] = "Авжеж.",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["reply"] = true },
    },
    [3224787368] = {
        ["english"] = { [1] = "Are there any areas you can think of that would be so untouched?" },
        ["text"] = "Можеш пригадати якісь настільки незаймані місця?",
        ["npcs"] = { [1] = 9616 },
        ["roles"] = { ["reply"] = true },
    },
    [1755775703] = {
        ["english"] = { [1] = "And now the war, it be comin' soon. All that be left is the sendin' of all these goods and weapons to the Cenarion Hold in Silithus, and that is gonna be done within $2113w days. Then some brave soul is gonna have to be ringin' the gong near those Ahn'Qiraj gates to open 'em and start the war." },
        ["text"] = "А тепер війна вже близько. Лишилося тільки доправити всі ці товари й зброю до Кенарієвої цитаделі в Силітусі, і це буде зроблено протягом $2113w днів. Потім якась хоробра душа муситиме вдарити в гонг біля брам Ан'Кіражу, щоб відкрити їх і розпочати війну.",
        ["npcs"] = { [1] = 15469 },
        ["roles"] = { ["greeting"] = true },
    },
    [3371581698] = {
        ["english"] = { [1] = "Bank of Stormwind" },
        ["text"] = "Банк Штормовію",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [1998436420] = {
        ["english"] = { [1] = "And I wish I could join you $N.  Head over to Stormwind Keep.  You'll find Thelman Slatefist in the King's audience chamber.  He will aid you in getting to Alterac Valley.", [2] = "And I wish I could join you $N. Head over to Stormwind Keep. You'll find Thelman Slatefist in the King's audience chamber. He will aid you in getting to Alterac Valley." },
        ["text"] = "Хотів би я приєднатися до тебе, $N. Іди до фортеці Штормовію. У приймальній залі короля знайдеш Телмана Кам'яний Кулак. Він допоможе тобі дістатися Альтерацької долини.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3631949522] = {
        ["english"] = { [1] = "Bandages you say? Yes, well, if memory serves from the last time I was told, it would appear that the Alliance has created $2076w of $2077w linen bandages, $2082w of $2083w silk bandages and $2088w of $2090w runecloth bandages." },
        ["text"] = "Бинти, кажеш? Так, якщо пам'ять не зраджує, востаннє мені повідомляли, що Альянс виготовив $2076w із $2077w лляних бинтів, $2082w із $2083w шовкових бинтів і $2088w із $2090w бинтів із рунічної тканини.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [3076965258] = {
        ["english"] = { [1] = "As I said, we lost track of him, but this is something that I'm sure you will be able to figure out for me. My suspicion is that he's down there somewhere, but my spies that have returned haven't been able to place him anywhere on the island.$B$BThe Forsaken at Venomspite did a good job of sabotaging New Hearthglen, but the Onslaught forces that are present down there are the battle-hardened remnant from that place. Unfortunately, they picked up better equipment along the way, as well as gryphons taken from fools somewhere.$B$BWhat I'm trying to say is that this isn't going to be a stroll in the countryside, $N, even for you." },
        ["text"] = "Як я й казав, ми втратили його слід, але, певен, ти зможеш це з'ясувати. Підозрюю, він десь унизу, та мої шпигуни, які повернулися, так і не змогли знайти його на острові.$B$BВідречені в Злобній Отруті добре попрацювали, саботуючи Новий Вогнеград, але сили Натиску, що лишилися там, — загартовані в боях уцілілі з того місця. На жаль, дорогою вони розжилися кращим спорядженням, а ще десь відібрали в дурнів грифонів.$B$BЯ до того, що це не буде прогулянка сільською місцевістю, $N, навіть для тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [73937110] = {
        ["english"] = { [1] = "Do I look like I have the time to spend jawin?" },
        ["text"] = "Я що, схожий на того, хто має час базікати?",
        ["npcs"] = { [1] = 957 },
        ["roles"] = { ["greeting"] = true },
    },
    [476027261] = {
        ["english"] = { [1] = "<Dark magic ripples from the necrolyte.>" },
        ["text"] = "<Від некроліта розходяться хвилі темної магії.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [465788055] = {
        ["english"] = { [1] = "Bg'grrml brgl brm!" },
        ["text"] = "Бґ'ґррмл брґл брм!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [451192915] = {
        ["english"] = { [1] = "Ah, one of our own. It is good to see our numbers are growing so rapidly that I can no longer keep track of the faces of our members.$B$BThat fool Thrall thinks I am working hard to cleanse the image of warlocks and prove we are his servants. Idiot! The Burning Legion will make ash of this entire world after it drains it completely." },
        ["text"] = "А, один із наших. Приємно бачити, що нас стає так багато, що я вже не можу запам'ятати всі обличчя.$B$BТой дурень Тралл думає, що я тяжко працюю, аби очистити ім'я чорнокнижників і довести, що ми його слуги. Ідіот! Палаючий Легіон перетворить увесь цей світ на попіл, висмоктавши його досуха.",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["greeting"] = true },
    },
    [1479940130] = {
        ["english"] = { [1] = "Amazing! I've never spoken to a ghost. I wish to learn!" },
        ["text"] = "Неймовірно! Я ніколи не говорив із привидом. Хочу навчитися!",
        ["npcs"] = { [1] = 8888 },
        ["roles"] = { ["reply"] = true },
    },
    [3622108334] = {
        ["english"] = { [1] = "As a relative newcomer to Ogri'la, you don't have enough exposure to the crystals here to reap their full benefits.  Besides, you only have one head.$B$BWe, on the other hand, have been here a very long time.  So, as you can imagine, we're fairly well-versed in a great many things.$B$BOf late, we've taken a keen interest in the demons of the forge camps.  More specifically, we've devised a way to rid us of them for good.$B$BAt least, that's the theory." },
        ["text"] = "Ти відносно недавно в Оґрілі, тож ще не встиг достатньо насититися місцевими кристалами, щоб отримати від них повну користь. До того ж у тебе лише одна голова.$B$BМи ж, навпаки, живемо тут дуже давно. Тож, як можеш уявити, добре тямимо в багатьох речах.$B$BОстаннім часом нас особливо зацікавили демони з таборів кузні. Точніше, ми вигадали спосіб позбутися їх назавжди.$B$BПринаймні теоретично.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1535913998] = {
        ["english"] = { [1] = "Arxes! Send help! Im pinned down in the mines, I...Im not sure where iam exactly but i had the presence of mind to drop tracers on the gro8und behind me" },
        ["text"] = "Арксесе! Надішли допомогу! Мене притисли в шахтах, я... я не певен, де саме, але здогадався лишати позаду трасувальні мітки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3048216912] = {
        ["english"] = { [1] = "Argus is the resident blacksmith of Goldshire.  I'm sure he could teach you the Blacksmith's profession." },
        ["text"] = "Арґус — місцевий коваль Злотохрестя. Гадаю, він зможе навчити тебе ковальства.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [4156293297] = {
        ["english"] = { [1] = "Ah, a fellow Fisherman. Are you perhaps in need of a little training? Maybe I can show you a thing or two?" },
        ["text"] = "О, колега-рибалка. Може, тобі трохи повчитися? Гадаю, я зможу показати кілька хитрощів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2391025074] = {
        ["english"] = { [1] = "Arr!   There be nothin I like to see better than folks fightin to the death in the arena.   If you be here at the right time maybe you can be one of them!" },
        ["text"] = "Ар-р! Нема нічого кращого, ніж дивитися, як народ б'ється до смерті на арені. Якщо прийдеш у слушний час, може, й сам станеш одним із них!",
        ["npcs"] = { [1] = 14508 },
        ["roles"] = { ["greeting"] = true },
    },
    [1295783768] = {
        ["english"] = { [1] = "Always double-check your measurements before you begin to cut the leather. We cannot afford to waste materials." },
        ["text"] = "Завжди двічі перевіряй мірки, перш ніж різати шкіру. Ми не можемо дозволити собі марнувати матеріали.",
        ["npcs"] = { [1] = 3967 },
        ["roles"] = { ["greeting"] = true },
    },
    [1070136020] = {
        ["english"] = { [1] = "A fast learner is what ye are, and a good smith to boot. I would sign off on yer work any day of the week. But I sense ye still have some learnin in ye. Go talk to Bengus Deepforge, he's a hard taskmaster but he's also one of the best." },
        ["text"] = "Ти швидко вчишся, та ще й добрий коваль. Я будь-якого дня підписався б під твоєю роботою. Але відчуваю, що тобі ще є чого вчитися. Поговори з Бенґусом Глибококовачем — він суворий наставник, але й один із найкращих.",
        ["npcs"] = { [1] = 10276 },
        ["roles"] = { ["greeting"] = true },
    },
    [1946163181] = {
        ["english"] = { [1] = "<Nod>." },
        ["text"] = "<Кивнути>.",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["reply"] = true },
    },
    [2673001613] = {
        ["english"] = { [1] = "Arthas was once a human prince.  The army he led into Northrend suffered a horrible fate.$B$BMy brother, Thassarian, was a part of that army." },
        ["text"] = "Артас колись був людським принцом. Армію, яку він повів у Нортренд, спіткала жахлива доля.$B$BМій брат, Тассаріан, був частиною тієї армії.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2133137481] = {
        ["english"] = { [1] = "Aren't you a sight for sore eyes!$B$BThere's work to be done and not much time." },
        ["text"] = "Ох, як же я радий тебе бачити!$B$BЄ робота, а часу обмаль.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [83175838] = {
        ["english"] = { [1] = "Belgaristrasz speaks the truth; the situation is grave indeed.  $B$BI can grant you the power to call upon a drake from the Green Fight.  Speak to Belgaristrasz or Eternos if you prefer to draw on the power of the Red or the Bronze." },
        ["text"] = "Белґарістраз каже правду; ситуація справді тяжка. $B$BЯ можу дати тобі силу прикликати дракона із Зеленої зграї. Поговори з Белґарістразом або Етернос, якщо хочеш черпати силу Червоної чи Бронзової зграї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3676402982] = {
        ["english"] = { [1] = "<The captive crocolisk lets out a low growl as you approach.>" },
        ["text"] = "<Полонений кроколіск тихо гарчить, коли ви наближаєтеся.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [691932086] = {
        ["english"] = { [1] = "A fissure?" },
        ["text"] = "Тріщина?",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["reply"] = true },
    },
    [298676929] = {
        ["english"] = { [1] = "As I understand it dear, everything has been gathered and the final materiel is being assembled and shipped off to Cenarion Hold. The last of it should arrive in less than $2113w days. Once our equipment and forces are all there, the bearer of the Scepter of the Shifting Sands can ring the gong near Ahn'Qiraj to open the gates. Then the war will begin." },
        ["text"] = "Наскільки я розумію, любий, усе вже зібрано, а останні припаси комплектують і відправляють до Кенарієвої цитаделі. Решта має прибути менш ніж за $2113w днів. Коли все спорядження й сили будуть там, носій Скіпетра Мінливих Пісків зможе вдарити в гонг біля Ан'Кіражу й відкрити брами. Тоді почнеться війна.",
        ["npcs"] = { [1] = 15446, [2] = 15448 },
        ["roles"] = { ["greeting"] = true },
    },
    [1546310339] = {
        ["english"] = { [1] = "Death's Door is a portal that opens upon the world that the Burning Legion uses to breed their fel hounds and other canine-like terrors.  Any time that you see one of those creatures, that is where it came from, and it passes through here, first.$B$BLately, we became aware that the Burning Legion have ramped up their summoning of these creatures through the portal.$B$BYou must shut down Death's Door before it becomes an inexorable tide, and all is lost!" },
        ["text"] = "Брама Смерті — це портал у світ, де Палаючий Легіон розводить своїх скверногончаків та інших собакоподібних жахіть. Щоразу, коли бачиш одну з таких істот, знай: вона походить звідти й спершу проходить саме через цей портал.$B$BНещодавно ми помітили, що Палаючий Легіон значно посилив виклик цих створінь через портал.$B$BТи мусиш закрити Браму Смерті, перш ніж цей потік стане нестримним і все буде втрачено!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3925031883] = {
        ["english"] = { [1] = "Another student, eh? All right. I'll see what I can do to help you out." },
        ["text"] = "Ще один учень, еге ж? Гаразд. Подивимося, чим я можу допомогти.",
        ["npcs"] = { [1] = 3347 },
        ["roles"] = { ["greeting"] = true },
    },
    [2239207678] = {
        ["english"] = { [1] = "Brggl-brggl Mrgl-Mrgl! Gluk!" },
        ["text"] = "Брґґл-брґґл Мрґл-Мрґл! Ґлук!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1651817303] = {
        ["english"] = { [1] = "Are you ready to fight the Stormpike Guard in Alterac Valley, $n?" },
        ["text"] = "Ти готовий битися з Вартою Грозової Вершини в Альтерацькій долині, $n?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [726727755] = {
        ["english"] = { [1] = "'Tis the season for great bargains!  Fah la la la la!" },
        ["text"] = "Настала пора великих знижок! Фа-ла-ла-ла-ла!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [2475653237] = {
        ["english"] = { [1] = "Are you ready to fight for the Horde, $c?" },
        ["text"] = "Ти готовий битися за Орду, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2182851635] = {
        ["english"] = { [1] = "Another soldier on $ghis:her; way to Honor Hold... by Kurdran's beard, they can use the help!" },
        ["text"] = "Ще один солдат на $gсвоєму:своєму; шляху до Оплоту Честі... бородою Курдрана, їм точно потрібна допомога!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [223993845] = {
        ["english"] = { [1] = "Brzzzzt!$B$BWelcome to Matrix Punchograph 3005 stroke C, a security level chi terminal.$B$BBlue punch card detected.  Access Granted.\010\01001000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001" },
        ["text"] = "Брзззт!$B$BЛаскаво просимо до Матричного Пуаншографа 3005-C, термінала рівня безпеки хі.$B$BВиявлено синю перфокартку. Доступ дозволено.\010\01001000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3984597088] = {
        ["english"] = { [1] = "<Kharan clears his throat.>$B$BWe made our way through the Searing Gorge tunnel and into the ravaged wasteland comprising the gorge. In retrospect, things were eerily quiet. The only dangers we ran across were the wildlife of the region: Creatures that my men easily dispatched.$B$BWe reached Blackrock Mountain with relative ease and made our way through the stonewrought construction without so much as a hiccup." },
        ["text"] = "<Харан прокашлюється.>$B$BМи пройшли тунелем Випаленої ущелини й вийшли до спустошених пусток самої ущелини. Озираючись назад, усе було моторошно тихо. Єдина небезпека, яку ми зустріли, — місцеві звірі, з якими мої люди легко впоралися.$B$BМи без особливих труднощів дісталися Чорнокамінної гори й пройшли крізь кам'яні споруди без жодної пригоди.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [2336724137] = {
        ["english"] = { [1] = "<Old Icefin eyes you warily, his fishy eye blinking as he bobs his head up and down once in a curt dismissal.>" },
        ["text"] = "<Старий Льодоплав насторожено дивиться на вас, кліпає риб'ячим оком і раз коротко киває головою, відпускаючи вас.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2127269391] = {
        ["english"] = { [1] = "Are you mad? Do you know what manner of beast inhabit that place? The worst that can happen is that we'll have to scoop up your remains with a shovel. We've lost some good dwarves to those awful monsters.$B$BSo the answer is no. If you're bent on getting to the Searing Gorge, you'll have to find another way." },
        ["text"] = "Ти збожеволів? Ти знаєш, які почвари живуть у тому місці? У найкращому разі нам доведеться збирати твої рештки лопатою. Ми втратили там не одного доброго дворфа через тих жахливих чудовиськ.$B$BТож відповідь — ні. Якщо так уже рвешся до Випаленої ущелини, шукай інший шлях.",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["greeting"] = true },
    },
    [4131619582] = {
        ["english"] = { [1] = "Amongst the various pieces of parchment containing checklists and other information from the Farstriders, one stands out. It is a drawing of a hideous troll, perhaps the most fearsome creature that you have ever seen!" },
        ["text"] = "Серед численних пергаментів зі списками й іншими відомостями від Далекоходців один особливо впадає в око. На ньому намальований потворний троль — можливо, найстрашніша істота, яку ви коли-небудь бачили!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [92687708] = {
        ["english"] = { [1] = "Astaia has fished up some curious treasures over the ages she has spent fishing.  Why don't you go see her over in the Tradesman's terrace and have her show you some of them." },
        ["text"] = "За довгі роки риболовлі Астайя витягла з води чимало дивних скарбів. Чому б тобі не навідатися до неї на Терасі Ремісників і не попросити показати деякі?",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3548298846] = {
        ["english"] = { [1] = "Arathi Basin place to take from soft humans.  Sir Malory Wheeler send you there." },
        ["text"] = "Низина Араті — місце, яке треба відібрати в м'яких людей. Сер Мелорі Вілер відправить тебе туди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1970433877] = {
        ["english"] = { [1] = "Do I see them with weapons still?  Why you let them keep their weapons?!" },
        ["text"] = "Я досі бачу в них зброю? Навіщо ти дозволив їм залишити зброю?!",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["greeting"] = true },
    },
    [1794867496] = {
        ["english"] = { [1] = "Are you here to help with the delivery? Miran's just about ready." },
        ["text"] = "Ти прийшов допомогти з доставкою? Міран майже готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [791188020] = {
        ["english"] = { [1] = "All henchmen of da boss - Stomper Kreeg, all three of da Guards, Captain Kromcrush, and da Observer - give tribute to da new boss.  If you kill a henchman, then that henchman can't give tribute!  Each one you keep alive will give you more tribute.  Keep all of them alive and you get da BIG tribute!$B$BYeah!" },
        ["text"] = "Усі поплічники боса — Тупак Кріґ, усі троє вартових, капітан Кромкруш і Спостерігач — платять данину новому босові. Якщо вб'єш поплічника, він не зможе дати данину! Чим більше їх лишиш живими, тим більшу отримаєш данину. Залиш усіх живими — і буде ВЕЛИКА данина!$B$BАга!",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["greeting"] = true },
    },
    [2388856863] = {
        ["english"] = { [1] = "Are you here to fight for us at Warsong Gulch?  Lok'tar Ogar $c!" },
        ["text"] = "Ти тут, щоб битися за нас в Ущелині Пісні Війни? Лок'тар оґар, $c!",
        ["npcs"] = { [1] = 2804 },
        ["roles"] = { ["greeting"] = true },
    },
    [1375667725] = {
        ["english"] = { [1] = "All I ever wished for was to serve my king once again.  For humanity, against a common enemy.$B$BInstead, I find that our numbers have been infiltrated by cultist scum.... and all signs point to Naxxanar as the origin of this rot." },
        ["text"] = "Усе, чого я коли-небудь хотів, — знову служити своєму королю. Заради людства, проти спільного ворога.$B$BНатомість я бачу, що наші лави просочилися покидьками-культистами... і всі сліди ведуть до Наксанара як джерела цієї гнилі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3672283431] = {
        ["english"] = { [1] = "Are you daft? Who else would I be talking about? Yes, the girl - Mistress Mar'alith. Anyhow, she was back and not in too good of a mood. That's when the demands started flowing.\010" },
        ["text"] = "Ти що, дурний? Про кого ще я міг говорити? Так, про ту дівчину — пані Мар'аліт. Коротше, вона повернулася й була геть не в гуморі. Тоді й посипалися вимоги.\010",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["greeting"] = true },
    },
    [3708169201] = {
        ["english"] = { [1] = "Are you sure, $N? We must face the Scourge at full strength if we are to succeed. If you do not require more rest, we will begin." },
        ["text"] = "Ти певен, $N? Якщо хочемо перемогти, мусимо зустріти Скверну в повній силі. Якщо тобі не потрібен додатковий відпочинок, почнемо.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1054798757] = {
        ["english"] = { [1] = "Can you not sense the anguish of the Earth Mother for her lost children, the undead? Speak quickly, $N. Every second costs me dearly. We must help them find their way back to her!" },
        ["text"] = "Невже ти не відчуваєш муки Матері-Землі за її втраченими дітьми, невмерлими? Говори швидко, $N. Кожна секунда дорого мені коштує. Ми мусимо допомогти їм знайти шлях назад до неї!",
        ["npcs"] = { [1] = 3009 },
        ["roles"] = { ["greeting"] = true },
    },
    [1942914162] = {
        ["english"] = { [1] = "<sigh>... Do you think we could move out, $c?$b$bI'm losing fluid fast!" },
        ["text"] = "<зітхає>... Може, рушимо вже, $c?$b$bЯ швидко втрачаю рідину!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [306680266] = {
        ["english"] = { [1] = "Are you blind as well as insane?$B$BI am a ghost - a cruel reminder of a civilization that has long since ceased to exist - anchored to a land that I failed to protect.$B$BLong ago - ten-thousand years past - I was flesh and bone, just like you. I was prince of this land and a dragon rider, blessed by Ysera of the Dream." },
        ["text"] = "Ти сліпий чи ще й божевільний?$B$BЯ привид — жорстоке нагадування про цивілізацію, якої давно не існує, прикутий до землі, яку не зміг захистити.$B$BДавно, десять тисяч років тому, я був із плоті й крові, як ти. Я був принцом цієї землі й вершником дракона, благословенним Ізерою зі Сну.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1881088136] = {
        ["english"] = { [1] = "Ah, very good. I am satisfied that you are a worthy student. Now, your training with me may begin???" },
        ["text"] = "А, дуже добре. Я переконався, що ти гідний учень. Тепер можеш почати навчання в мене???",
        ["npcs"] = { [1] = 3011 },
        ["roles"] = { ["greeting"] = true },
    },
    [205867326] = {
        ["english"] = { [1] = "<The veteran gladiator speaks in halting Orcish.> What? You have a problem with me? Take it to the arena. I don't waste my time with your little \"hordes\" and \"alliances.\"" },
        ["text"] = "<Ветеран-гладіатор говорить ламаною орчою.> Що? Маєш до мене претензії? Іди на арену. Я не марную часу на ваші дрібні \"орди\" й \"альянси\".",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [472029605] = {
        ["english"] = { [1] = "Are we there yet?" },
        ["text"] = "Ми вже приїхали?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1096711030] = {
        ["english"] = { [1] = "Are these lands not beyond healing? They look pretty beat up." },
        ["text"] = "Невже ці землі вже неможливо зцілити? Виглядають вони добряче понівеченими.",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["reply"] = true },
    },
    [3214494984] = {
        ["english"] = { [1] = "<The commander stops his lesson and turns, his eyes appraising you, sizing you up.>$B$BI have use for one such as yourself, $c." },
        ["text"] = "<Командир перериває заняття й обертається, оцінюючи вас пильним поглядом.>$B$BТакий, як ти, може мені знадобитися, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2907384247] = {
        ["english"] = { [1] = "As long as those dwarves stay over there we'll have no trouble.  Where are you heading $N?" },
        ["text"] = "Поки ті дворфи лишаються там, проблем не буде. Куди прямуєш, $N?",
        ["npcs"] = { [1] = 3305 },
        ["roles"] = { ["greeting"] = true },
    },
    [2028664076] = {
        ["english"] = { [1] = "Become a mentor for one of our orphans during the Week of the Wardens!  For the Horde!" },
        ["text"] = "Стань наставником для одного з наших сиріт під час Тижня Опікунів! За Орду!",
        ["npcs"] = { [1] = 14451 },
        ["roles"] = { ["greeting"] = true },
    },
    [354028422] = {
        ["english"] = { [1] = "<Take this book for the good of Azeroth!>" },
        ["text"] = "<Візьми цю книгу заради Азероту!>",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [4075048198] = {
        ["english"] = { [1] = "Archmage Vargoth enstrusted me with his staff when he told me to flee from the blood elf attack on Violet Tower. I did as he told me, hoping to take refuge in the old draenei settlement of Arklon.$B$BThere was to be no respite. I had walked right into the leading edge of a Burning Legion force. The demons wrested the staff from me, but I managed to escape with my life.$B$BThough my master knows nothing of my failure, it still shames me." },
        ["text"] = "Архімаг Варґот довірив мені свій посох, коли наказав тікати від нападу ельфів крові на Фіолетову Вежу. Я виконав наказ, сподіваючись знайти прихисток у старому дренейському поселенні Арклон.$B$BТа перепочинку не було. Я вийшов просто на передній край сил Палаючого Легіону. Демони відібрали посох, але мені вдалося врятуватися.$B$BМій наставник нічого не знає про мою невдачу, та мені досі соромно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [571821032] = {
        ["english"] = { [1] = "A Hunter is it?  Well, then you will want to speak with Thorfin Stoneshield over in the Dwarven District.  \010\010Oh, and you be sure to tell him that if I step in his pet's business one more time, he's going to be training other hunters from behind bars in the Stockade!" },
        ["text"] = "Мисливець, еге ж? Тоді тобі треба поговорити з Торфіном Кам'яним Щитом у Дворфівському районі.  \010\010І неодмінно передай йому: якщо я ще раз наступлю в те, що лишає його вихованець, він тренуватиме мисливців уже з-за ґрат у В'язниці!",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1113473261] = {
        ["english"] = { [1] = "Archmage Alvareux once wrote a treatise exploring a fascinating theory.  He proposed the existence of an exact copy of Karazhan in a world other than our own and that both somehow shared the same space.$B$BHe went mad soon after.  A real pity." },
        ["text"] = "Архімаг Альваро колись написав трактат про захопливу теорію. Він припускав існування точної копії Каражану в іншому світі, яка якимось чином займає той самий простір.$B$BНевдовзі він збожеволів. Дуже прикро.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1768679884] = {
        ["english"] = { [1] = "Dig rats make some surprisingly tasty stew." },
        ["text"] = "З печерних щурів виходить напрочуд смачне рагу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [217143866] = {
        ["english"] = { [1] = "All rewards for services renedered to be dispensed by Warcaller Beersnout.$B$BPost no bills." },
        ["text"] = "Усі нагороди за виконану службу видає Закликач війни Пиворил.$B$BОголошень не клеїти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3242869239] = {
        ["english"] = { [1] = "Archibald is da master of da crossbow. He da weapon master of da Undercity, located in da War Quarter." },
        ["text"] = "Арчибальд — майстер арбалета. Він майстер зброї Підміста, стоїть у Військовому кварталі.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [3287285536] = {
        ["english"] = { [1] = "Cheers!" },
        ["text"] = "Будьмо!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [614548852] = {
        ["english"] = { [1] = "Apologies, $r, but only champions of Thunder Bluff may purchase what I have to offer." },
        ["text"] = "Перепрошую, $r, але лише чемпіони Громового Бескиду можуть купувати мої товари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [49673655] = {
        ["english"] = { [1] = "Do you like the new home that I've carved out for my so-called worshippers?$B$BIn the throes of my death, I cursed them all and dragged them along with me into this special underworld of my own creation.$B$BI think that I shall delight in their eternal torment, but what I really want is to exact revenge upon my former prophet!" },
        ["text"] = "Подобається нова домівка, яку я створив для своїх так званих поклонників?$B$BУ передсмертних муках я прокляв їх усіх і затягнув із собою в цей особливий підземний світ власного творіння.$B$BГадаю, їхні вічні муки принесуть мені насолоду, але найбільше я хочу помститися своєму колишньому пророкові!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1369382263] = {
        ["english"] = { [1] = "Any chance to fight against the Horde, especially orcs, is a good time if you ask me.  You'll find plenty of battle in Warsong Gulch, that you will.  Head on over to the Hall of Arms and speak with Lylandris.  She'll set you on your way.", [2] = "Any chance to fight against the Horde, especially orcs, is a good time if you ask me. You'll find plenty of battle in Warsong Gulch, that you will. Head on over to the Hall of Arms and speak with Lylandris. She'll set you on your way." },
        ["text"] = "Будь-яка нагода битися проти Орди, особливо орків, — добра нагода, як на мене. В Ущелині Пісні Війни боїв вистачає. Іди до Зали Зброї й поговори з Ліландріс. Вона відправить тебе куди треба.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [939596349] = {
        ["english"] = { [1] = "Ansekhwa, da tauren weapon master, is on da Thunder Bluff lower rise.  He teach one and two-handed maces, staves and guns.\010\010Archibald, da undead weapon master in da War Quarter of da Undercity, train good with crossbows, daggers, one and two-handed swords and polearms.\010\010Sayoc, da ugly orc right here, can teach da ways of bows, daggers, fist weapons, one and two-handed axes and thrown weapons mon." },
        ["text"] = "Ансеква, таурен-майстер зброї, стоїть на нижньому ярусі Громового Бескиду. Він навчає володінню одноручними й дворучними булавами, посохами та рушницями.\010\010Арчибальд, майстер зброї невмерлих у Військовому кварталі Підміста, навчає арбалетів, кинджалів, одноручних і дворучних мечів та древкової зброї.\010\010Сайок, той потворний орк прямо тут, може навчити луків, кинджалів, кулачної зброї, одноручних і дворучних сокир та метальної зброї, мон.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [1567530471] = {
        ["english"] = { [1] = "Ah, the beauty of Shadowglen never ceases to delight my senses!" },
        ["text"] = "Ах, краса Тінистої долини ніколи не перестає тішити мої чуття!",
        ["npcs"] = { [1] = 2079 },
        ["roles"] = { ["greeting"] = true },
    },
    [2695886173] = {
        ["english"] = { [1] = "Bah, rogues have done nothing but make our job here in Stormwind harder. I wish I could drag both Osborne and Mathias both out of Old Town and right to the Stockade." },
        ["text"] = "Ба, розбійники лише ускладнюють нам роботу тут, у Штормовії. Якби міг, витягнув би Осборна й Матіаса зі Старого міста просто до В'язниці.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [58420476] = {
        ["english"] = { [1] = "Another new face? It's so good to meet you. I'm Dellylah." },
        ["text"] = "Ще одне нове обличчя? Дуже приємно познайомитися. Я Делліла.",
        ["npcs"] = { [1] = 6091 },
        ["roles"] = { ["greeting"] = true },
    },
    [4086316897] = {
        ["english"] = { [1] = "Another interruption. How am I supposed to get any work done like this? Don't answer that; do I look as if I care what you have to say? Why don't you go bother Mr. High-And-Mighty instead?" },
        ["text"] = "Ще одне переривання. Як я маю щось робити в таких умовах? Не відповідай; хіба я виглядаю так, ніби мене цікавить твоя думка? Чому б тобі не піти й не надокучати пану Великому-Й-Могутньому?",
        ["npcs"] = { [1] = 2391 },
        ["roles"] = { ["greeting"] = true },
    },
    [3880632706] = {
        ["english"] = { [1] = "Agents of the Cenarion Circle have uncovered disturbing information pertaining to the current situation in Eldre'Thalas.  I am at an impasse as to what to do about it, and I will no doubt soon seek the aid of able bodied beings capable of handling themselves in a fight.$B$BTo properly take action in Eldre'Thalas, however, is to understand the lore of an object known as the Fruit of Fertility." },
        ["text"] = "Агенти Кенарієвого Кола виявили тривожні відомості про нинішню ситуацію в Елдре'Таласі. Я зайшов у глухий кут і не знаю, що робити, тож незабаром, без сумніву, шукатиму допомоги в дужих істот, здатних постояти за себе в бою.$B$BТа щоб діяти в Елдре'Таласі правильно, треба знати історію предмета, відомого як Плід Родючості.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3798202396] = {
        ["english"] = { [1] = "Another hero? The fates smile upon us on this day, $N. " },
        ["text"] = "Ще один герой? Доля усміхається нам сьогодні, $N. ",
        ["npcs"] = { [1] = 10540 },
        ["roles"] = { ["greeting"] = true },
    },
    [444118107] = {
        ["english"] = { [1] = "<Grumbles> I still don't know how we managed to snake through Thousand Needles without a scratch, only to crash and burn in the Shimmering Flats!" },
        ["text"] = "<Бурчить> Досі не розумію, як нам удалося без жодної подряпини прослизнути крізь Тисячу Шипів, а потім розбитися й згоріти на Мерехтливій рівнині!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2040753910] = {
        ["english"] = { [1] = "Do I look like a $c to you? Now run along before I feel the need to oil my blade... in your blood." },
        ["text"] = "Я схожий на $c? А тепер забирайся, поки мені не захотілося змастити свій клинок... твоєю кров'ю.",
        ["npcs"] = { [1] = 6707 },
        ["roles"] = { ["greeting"] = true },
    },
    [3108562334] = {
        ["english"] = { [1] = "Actually I prefer traditional medicines... leeches, maggots, bonesaws... that sort of thing.  Well to each their own.  You can find the our local Herbalism Trainer, Faruza, standing out front near the stables in Brill." },
        ["text"] = "Насправді я віддаю перевагу традиційній медицині... п'явки, личинки, кісткові пилки... ну, такі речі. Та кожному своє. Нашу місцеву наставницю травництва Фарузу знайдеш біля стаєнь у Бріллі.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [4001780463] = {
        ["english"] = { [1] = "Absolutely!" },
        ["text"] = "Авжеж!",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["reply"] = true },
    },
    [573202102] = {
        ["english"] = { [1] = "All the roguish types hang out in The Forlorn Cavern, north of the gates of Ironforge.  I'd wager ye'll find Fenthwick there, no doubt counting the coin of another cut purse.  I'll catch him one of these days!  \010\010In the meantime I'll have my eye on you as well, $glad : lass;." },
        ["text"] = "Усі шахраюваті типи зависають у Закинутій печері на північ від брами Стальгорна. Б'юся об заклад, Фентвіка знайдеш саме там — певно, рахує монети з чужого гаманця. Одного дня я його спіймаю!  \010\010А поки що й за тобою наглядатиму, $gхлопче : дівчино;.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [845721595] = {
        ["english"] = { [1] = "And you would be?" },
        ["text"] = "А ти, власне, хто?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3918369138] = {
        ["english"] = { [1] = "Dark times loom ahead, stranger..." },
        ["text"] = "Темні часи насуваються, чужинцю...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1939098406] = {
        ["english"] = { [1] = "And summon forth Murmur they did.$B$BPowerful magics of containment and silencing were employed, held together by the constant supply of souls being fed into them.  Yet still they could not control the beast, could not bend it to their will.$B$BThese mortals began to devise different strategies, and one after the other they all failed.  And in so doing, they weakened the rituals, accidentally giving Murmur the slightest modicum of freedom.$B$BIt was all that was needed." },
        ["text"] = "І вони таки викликали Мурмура.$B$BВони застосували могутню магію стримування й тиші, яку підтримував безперервний потік душ. Та навіть так не могли контролювати істоту, не могли схилити її до своєї волі.$B$BСмертні вигадували все нові стратегії, і кожна зазнавала невдачі. Тим самим вони послабили ритуали й випадково подарували Мурмуру крихту свободи.$B$BЦього було досить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1886636921] = {
        ["english"] = { [1] = "Buliwyf, in this very shop can train you in the use of fist weapons. If his training techniques aren't your style, I hear the night elf weapon master in Darnassus, Ilyenia Moonfire, knows her way around the weapon too! She's up on the Warrior's Terrace there." },
        ["text"] = "Булівіф у цій самій крамниці навчить тебе кулачної зброї. Якщо його методи не до вподоби, чув, що Іленія Місячний Вогонь, майстриня зброї нічних ельфів у Дарнасі, теж добре нею володіє! Вона на Терасі Воїнів.",
        ["npcs"] = { [1] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1561919331] = {
        ["english"] = { [1] = "Ack, ye've been busy now haven't ye?!  I canna thank ye enough for bombing them demons and resupplying us with mounts.$B$BYer making our job all the more easier.  Keep up the good work, $g laddy : lassie;!" },
        ["text"] = "Ого, та ти часу дарма не гаєш! Не знаю, як і дякувати тобі за бомбардування демонів і поповнення наших верхових тварин.$B$BТи неабияк полегшуєш нам роботу. Так тримати, $g хлопче : дівчино;!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4189965412] = {
        ["english"] = { [1] = "Cooking is a life long pursuit and I see we share the same passion!" },
        ["text"] = "Кулінарія — справа всього життя, і я бачу, що ми поділяємо цю пристрасть!",
        ["npcs"] = { [1] = 1355, [2] = 1382, [3] = 1430, [4] = 1699, [5] = 2818, [6] = 3026, [7] = 3067, [8] = 3087, [9] = 3399, [10] = 4210, [11] = 4552, [12] = 5159, [13] = 6286, [14] = 8306 },
        ["roles"] = { ["greeting"] = true },
    },
    [3208485988] = {
        ["english"] = { [1] = "<The grizzled gladiator speaks in halting Common.> What? You have a problem with me? Take it to the arena. I don't waste my time with your little \"hordes\" and \"alliances.\"" },
        ["text"] = "<Сивий гладіатор говорить ламаною повселюдною.> Що? Маєш до мене претензії? Іди на арену. Я не марную часу на ваші дрібні \"орди\" й \"альянси\".",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2445260397] = {
        ["english"] = { [1] = "And to which battleground do you wish to journey?" },
        ["text"] = "До якого поля бою ти хочеш вирушити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [488944762] = {
        ["english"] = { [1] = "Bah!  Do I look like I have time for idle chit-chat?$B$BDo I?$B$BBe quick about your business.  There are ogres to be killed!" },
        ["text"] = "Ба! Я схожий на того, хто має час на порожні балачки?$B$BСхожий?$B$BШвидше до справи. Є огри, яких треба вбити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1000074437] = {
        ["english"] = { [1] = "[There is a noticeable pause after you ask this question.]$B$BThe information you request is not currently available in this repository's data cycling.  I sincerely apologize for this omission.$B$BPlease request this information after a data cycling update has been performed on this information repository.  You may also request this information from another information repository located on Azeroth." },
        ["text"] = "[Після вашого запитання настає помітна пауза.]$B$BЗапитувана вами інформація наразі недоступна в циклі обробки даних цього сховища. Щиро перепрошую за цей недогляд.$B$BБудь ласка, повторіть запит після оновлення циклу обробки даних у цьому інформаційному сховищі. Ви також можете запитати ці відомості в іншому інформаційному сховищі на Азероті.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [2451521160] = {
        ["english"] = { [1] = "Did you finish yesterday's assignment?  If so, then sit by me!" },
        ["text"] = "Ти виконав учорашнє завдання? Якщо так — сідай поруч!",
        ["npcs"] = { [1] = 707, [2] = 708, [3] = 721, [4] = 724, [5] = 1064, [6] = 2544, [7] = 2832, [8] = 2846, [9] = 2848, [10] = 4624, [11] = 5119, [12] = 7390, [13] = 10475, [14] = 16096 },
        ["roles"] = { ["greeting"] = true },
    },
    [2770602022] = {
        ["english"] = { [1] = "Ah, you're the one who found the letter. Thank you for the... news, I suppose, about my family. You're welcome to what food and drink I can offer." },
        ["text"] = "А, то це ти знайшов листа. Дякую за... новини, мабуть, про мою родину. Можеш пригоститися їжею й напоями, які я маю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1276589630] = {
        ["english"] = { [1] = "All requests for my work must be made in person by the buyer. Orwin often asks me to reconsider, but my priorities lie here. Look around you: many of these fighters rely upon me for their armor." },
        ["text"] = "Усі замовлення на мою роботу покупець має робити особисто. Орвін часто просить мене передумати, але мої пріоритети тут. Озирнися: багато цих бійців покладаються на мене щодо обладунків.",
        ["npcs"] = { [1] = 11098 },
        ["roles"] = { ["greeting"] = true },
    },
    [433729365] = {
        ["english"] = { [1] = "<It's a giant, armored, saddle-bearing attack cat. Isn't that already silly enough without it talking, too?>" },
        ["text"] = "<Це велетенська броньована бойова кішка із сідлом. Невже цього недостатньо дивно й вона ще й говорити має?>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2772406884] = {
        ["english"] = { [1] = "An unspeakable horror dwells here, mortal.  C'Thun and his worshippers are not just an affront to nature, their existence presages destruction for Azeroth as we know it.$B$BMerithra sacrificed herself a thousand years ago along with Caelestrasz and Arygos because they knew this as well.  We're here because of our oath to return for them, but we're also here because C'Thun must be stopped!" },
        ["text"] = "Тут мешкає невимовний жах, смертний. К'Тун і його поклонники — не просто образа для природи, сама їхня присутність віщує знищення Азероту, яким ми його знаємо.$B$BТисячу років тому Мерітра пожертвувала собою разом із Келестразом та Аріґосом, бо вони це теж розуміли. Ми тут через присягу повернутися по них, але також тому, що К'Туна треба зупинити!",
        ["npcs"] = { [1] = 15504 },
        ["roles"] = { ["greeting"] = true },
    },
    [1580242295] = {
        ["english"] = { [1] = "$N, good to see you!$B$BOr is this the first time that we've met?$B$BI'm in so many places and times right now, I sometimes have a hard time keeping track of all of it." },
        ["text"] = "$N, радий тебе бачити!$B$BЧи ми зустрічаємося вперше?$B$BЯ зараз перебуваю в стількох місцях і часах водночас, що іноді сам гублюся в усьому цьому.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2789579408] = {
        ["english"] = { [1] = "An excellent question! We have many things for sale here at the faire. If you are interested in food and drink, then head over to Stamp and Sylannia's booth. My favorite is the Darkmoon Special Reserve.\010\010If you'd rather purchase something more exotic, then Lhara may have just the thing for you. She specializes in rarities from all over the world.\010\010And then there is Flik running around here somewhere. If you can grab him he sells balls for throwing and frogs to keep as pets.\010" },
        ["text"] = "Чудове запитання! На ярмарку в нас продається багато всього. Якщо тебе цікавлять їжа й напої, йди до ятки Стампа та Сіланії. Мій улюблений напій — Особливий запас Ярмарку Молодика.\010\010Якщо ж хочеш чогось екзотичнішого, у Лари може знайтися саме те, що треба. Вона спеціалізується на рідкісних товарах з усього світу.\010\010А ще десь тут бігає Флік. Якщо спіймаєш його, він продає м'ячики для кидання й жабок як вихованців.\010",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [688029061] = {
        ["english"] = { [1] = "An Emerald Drake at full power can perform Dream Funnel, which transfers the drake's own life energy to a friendly target, healing it.  Leeching Poison can be used to restore health lost when using this ability." },
        ["text"] = "Смарагдовий дракон на повній силі може застосувати «Воронку сну», передаючи власну життєву енергію дружній цілі та зцілюючи її. «Висмоктувальна отрута» допоможе відновити здоров'я, втрачене під час використання цієї здібності.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2546895899] = {
        ["english"] = { [1] = "After the fall of Dalaran, I took my leave from the Kirin Tor. I spent years watching over Atiesh, only to have my purpose amongst the Kirin Tor taken from me in one fell swoop. I would find the staff, though it might take a lifetime. That is how I came to join the Argent Dawn and why I am here now." },
        ["text"] = "Після падіння Даларана я залишив Кірін-Тор. Роками я охороняв Атієш, аж доки мою мету в Кірін-Торі не відібрали одним ударом. Я мав знайти посох, навіть якщо на це пішло б усе життя. Так я приєднався до Сріблястого Світанку — і саме тому я тут.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [929348319] = {
        ["english"] = { [1] = "<The Forsaken female is curled up on the floor, her face in a grimace.  She does not appear capable of getting up on her own at the moment.>" },
        ["text"] = "<Відречена згорнулася клубком на підлозі, її обличчя спотворене гримасою болю. Схоже, наразі вона не здатна підвестися самостійно.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3004458856] = {
        ["english"] = { [1] = "Among ethereals, certain members deal specifically with flesh and beings of flesh. Those individuals are known as flesh handlers." },
        ["text"] = "Серед ефіріалів є ті, хто спеціально працює з плоттю та плотськими істотами. Їх називають приборкувачами плоті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [318335996] = {
        ["english"] = { [1] = "Darmuk's incompetence be hinderin' us no more! Patience, mon. Dere soon be more for you to do...." },
        ["text"] = "Недолугість Дармука нам більше не заважатиме! Терпіння, друже. Скоро для тебе знайдеться ще робота....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4034865330] = {
        ["english"] = { [1] = "Balthus Stoneflayer is the one to see about Skinning.  If it can be skinned, he can teach ye how.  Just walk yerself over to Finespindle's Leather Goods on the northern side of The Great Forge." },
        ["text"] = "Щодо зняття шкур іди до Балтуса Шкуродера. Якщо з чогось можна зняти шкуру, він навчить як. Просто йди до крамниці «Шкіряні товари Тонкопряда» на північному боці Великої Кузні.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [4093346972] = {
        ["english"] = { [1] = "Amazing, aren't they? All these artifacts and remains.$B$BI'm not sure what I'm more impressed by, their size, or the stories that go along with them. There's so much to study and learn. And the connections we can make...$B$BDid you know rumor has it that many races have the same heritage as Night elves?" },
        ["text"] = "Вражає, правда? Усі ці артефакти й рештки.$B$BНе знаю, що захоплює мене більше — їхній розмір чи історії, пов'язані з ними. Тут стільки всього можна вивчити. І які зв'язки можна простежити...$B$BТи знав, що, за чутками, багато рас мають спільне походження з нічними ельфами?",
        ["npcs"] = { [1] = 9616 },
        ["roles"] = { ["greeting"] = true },
    },
    [1962576562] = {
        ["english"] = { [1] = "Amazing! Anatheron's defeat at your hands has delayed Archimonde from his objective, and brought us that much closer to victory. My forces cannot stay here, however. My troops and I are exhausted, and now is the time for retreat. If your strength has not waned, head east to Thrall's encampment. That is where we make another stand. Be well." },
        ["text"] = "Неймовірно! Перемога над Анетероном затримала Архімонда на шляху до мети й наблизила нас до перемоги. Але мої сили не можуть лишатися тут. Ми виснажені, і настав час відступити. Якщо твої сили ще не вичерпались, іди на схід до табору Тралла. Там ми дамо ворогові новий бій. Бережи себе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3261638343] = {
        ["english"] = { [1] = "Am I busy? What's that supposed to mean? Do you think I just stand here all day, twiddling my thumbs? If you're here to buy something, talk to Handor." },
        ["text"] = "Чи я зайнятий? Що це має означати? Думаєш, я весь день стою тут і кручу пальцями? Якщо хочеш щось купити — говори з Гандором.",
        ["npcs"] = { [1] = 3365 },
        ["roles"] = { ["greeting"] = true },
    },
    [4049387207] = {
        ["english"] = { [1] = "Although we call this land the Barrens, to one who knows where to look this place teems with life." },
        ["text"] = "Хоч ми й називаємо цю землю Степами, для того, хто знає, де шукати, тут вирує життя.",
        ["npcs"] = { [1] = 3387 },
        ["roles"] = { ["greeting"] = true },
    },
    [105739193] = {
        ["english"] = { [1] = "Although the coast of Darkshore is more dangerous than that of Teldrassil, many fishers find profit here." },
        ["text"] = "Хоч узбережжя Темнобережжя небезпечніше за Тельдрассіл, багато рибалок добре тут заробляють.",
        ["npcs"] = { [1] = 4200 },
        ["roles"] = { ["greeting"] = true },
    },
    [2274495862] = {
        ["english"] = { [1] = "Alterac Valley has been home to the Frostwolf Clan for years; we will not let the dwarves and their Alliance trespass!  And so we battle!$B$BTo win back Alterac, defeat their general Vanndar Stormpike, in Dun Baldar.$B$BFor the Horde!" },
        ["text"] = "Альтерацька долина вже багато років є домом клану Морозного Вовка; ми не дозволимо дворфам та їхньому Альянсу тут господарювати! Тож ми б'ємося!$B$BЩоб повернути Альтерак, здолай їхнього генерала Ванндара Грозову Вершину в Дун-Балдарі.$B$BЗа Орду!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2758202029] = {
        ["english"] = { [1] = "Alright, muffin man, show me your muffins!" },
        ["text"] = "Ну що, кексарю, показуй свої кекси!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [763660181] = {
        ["english"] = { [1] = "A follower of the arcane are you?  Hmph!  Very well then... you can find them around the Pools of Vision underneath the Spirit Rise." },
        ["text"] = "То ти прихильник арканічного мистецтва? Пхе! Гаразд уже... знайдеш їх біля Озер Видінь під Верхів'ям Духів.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [328126217] = {
        ["english"] = { [1] = "All will know of what has transpired here in this accursed temple, hero. It will be written about in history books - the tales told as legend from Azeroth to the far reaches of the Nether itself!" },
        ["text"] = "Усі дізнаються, що сталося тут, у цьому проклятому храмі, герою. Про це напишуть у книгах історії, а оповіді стануть легендами від Азероту до найвіддаленіших куточків самої Крутоверті Порожнечі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [806779633] = {
        ["english"] = { [1] = "As deadly as the silithid seem, they are but tame creatures compared to their Qiraji overlords." },
        ["text"] = "Якими б смертоносними не здавалися силітиди, порівняно зі своїми кіражськими володарями вони лише ручні звірята.",
        ["npcs"] = { [1] = 15613 },
        ["roles"] = { ["greeting"] = true },
    },
    [3793247832] = {
        ["english"] = { [1] = "All this free candy is just bad business, I tell you. Or... maybe it's just a loss leader... they get you in the inn, and then gouge you on the meat. It's brilliant!" },
        ["text"] = "Усі ці безкоштовні солодощі — поганий бізнес, кажу тобі. Або... може, це товар-приманка... заманюють у таверну, а потім деруть утридорога за м'ясо. Геній!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [653200737] = {
        ["english"] = { [1] = "Additional background information on the Earthen must be given to you before this question may be answered properly.$B$BProcessing.$B$BTo understand the anomalies of the Earthen, it is first important to understand what the Earthen represent in their design intent.  The Earthen represent the Creators' attempt at improving the survivability paradigm of the standard subterranean being matrix.  This was done by incorporating a resilient foundation of construction inherent to the world into said matrix." },
        ["text"] = "Перш ніж належно відповісти на це запитання, вам слід надати додаткові відомості про земельників.$B$BОбробка.$B$BЩоб зрозуміти аномалії земельників, спершу важливо збагнути, що вони мали уособлювати за задумом. Земельники — це спроба Творців удосконалити модель виживання стандартної підземної істоти. Для цього до матриці було включено міцну будівельну основу, притаманну самому світові.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [1541394913] = {
        ["english"] = { [1] = "Atiesh, Greatstaff of the Guardian. The staff handed down through the ages to each of the Guardians of Tirisfal. The staff corrupted by Sargeras. The staff of the last Guardian. The staff of Medivh.\010" },
        ["text"] = "Атієш, Великий посох Хранителя. Посох, що передавався крізь віки від одного Хранителя Тірісфалю до іншого. Посох, осквернений Сарґерасом. Посох останнього Хранителя. Посох Медіва.\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4160322995] = {
        ["english"] = { [1] = "Ah, that's sweet of you mon, but we already got all the heavy leather that we need. And here I'm sure that your knife is still sharp. Maybe you can put it to use helping the others with their collections, no?  Have a good one!" },
        ["text"] = "А, це мило з твого боку, мон, але всю потрібну щільну шкіру ми вже зібрали. А ніж у тебе, певно, ще гострий. Може, допоможеш іншим із їхніми зборами, га? Бувай!",
        ["npcs"] = { [1] = 15515 },
        ["roles"] = { ["greeting"] = true },
    },
    [1359254880] = {
        ["english"] = { [1] = "A priestess by the name of Laurna Morninglight calls Dolanaar home.  I believe she can be found just north of the Inn." },
        ["text"] = "Жриця на ім'я Лорна Ранкове Сяйво мешкає в Доланаарі. Здається, її можна знайти просто на північ від таверни.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1451923336] = {
        ["english"] = { [1] = "At last! I am finally free from this cell!$b$bThe Kirin Tor sent me from Dalaran to investigate Arugal's progress with the undead here in Silverpine Forest. Little did we know that the wizard had lost his grasp on sanity.$b$bI must report this mess at once! But before I leave, allow me to undo the magical lock on the courtyard door.$b$bYou defeated Rethilgore, perhaps you will survive what lies beyond...." },
        ["text"] = "Нарешті! Я вільний із цієї камери!$b$bКірін-Тор прислав мене з Даларана розслідувати успіхи Аруґала з невмерлими тут, у Срібнохвої. Ми й не підозрювали, що чарівник утратив розум.$b$bЯ мушу негайно доповісти про цей безлад! Але перед відходом дозволь зняти магічний замок із дверей у двір.$b$bТи переміг Ретілгора — можливо, виживеш і проти того, що чекає далі...",
        ["npcs"] = { [1] = 3850 },
        ["roles"] = { ["greeting"] = true },
    },
    [2237487884] = {
        ["english"] = { [1] = "All right, $c. You think you have what it takes to make it in the Steamwheedle Fighting Circuit's arena battlegrounds?" },
        ["text"] = "Гаразд, $c. Думаєш, у тебе є все потрібне, щоб вижити на аренах Бойового Контуру Хиткої Шестерні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3796887927] = {
        ["english"] = { [1] = "A far better blacksmith than I am, that's for sure. Though I'll deny it if you tell anyone I said that. You should go speak with Therum Deepforge. If anyone can teach you more, it's him." },
        ["text"] = "Він значно кращий коваль за мене, це вже точно. Хоча якщо комусь скажеш, що я це визнав, — я все заперечуватиму. Поговори з Терумом Глибококовачем. Якщо хтось і може навчити тебе більшого, то саме він.",
        ["npcs"] = { [1] = 957 },
        ["roles"] = { ["greeting"] = true },
    },
    [1482610270] = {
        ["english"] = { [1] = "an you train me how to use rogue skills?" },
        ["text"] = "можеш навчити мене користуватися здібностями розбійника?",
        ["npcs"] = { [1] = 4582, [2] = 4583, [3] = 4584 },
        ["roles"] = { ["reply"] = true },
    },
    [3961088813] = {
        ["english"] = { [1] = "All of us, working collectively, have accomplished a great task. Now an even greater one confronts us. We only await the completion of the Horde's gathering efforts and then we shall all confront the Silithid and their masters together." },
        ["text"] = "Працюючи разом, ми здійснили велику справу. Тепер перед нами ще більша. Лишилося дочекатися завершення зборів Орди, а тоді ми всі разом постанемо проти силітидів і їхніх господарів.",
        ["npcs"] = { [1] = 15457 },
        ["roles"] = { ["greeting"] = true },
    },
    [1084250796] = {
        ["english"] = { [1] = "All of the preparations are complete now, $c. We await the last of the materiel to be sent to Silithus, which should be in less than a day's time. Then once the organization there is done with, someone will have to come forward and ring the gong on the Scarab Dais with the Scepter of the Shifting Sands. That is when the Ahn'Qiraj War will begin. May the Earth Mother watch over all of us then." },
        ["text"] = "Уся підготовка завершена, $c. Чекаємо останніх припасів до Силітуса — вони мають прибути менш ніж за день. Потім, коли там усе впорядкують, хтось муситиме вийти вперед і вдарити Скіпетром Мінливих Пісків у гонг на Помості Скарабея. Саме тоді почнеться війна за Ан'Кіраж. Нехай Матір-Земля береже нас усіх.",
        ["npcs"] = { [1] = 15532 },
        ["roles"] = { ["greeting"] = true },
    },
    [1414069470] = {
        ["english"] = { [1] = "All of the material necessary for the Alliance's contribution to the war effort has been satisfied, $c. We await the Horde's labors to be finalized and then shall move on to transporting the war materiel to Silithus." },
        ["text"] = "Усі матеріали, потрібні для внеску Альянсу у воєнну кампанію, зібрано, $c. Чекаємо, доки Орда завершить свої справи, а тоді почнемо перевозити припаси до Силітуса.",
        ["npcs"] = { [1] = 15437 },
        ["roles"] = { ["greeting"] = true },
    },
    [4194262866] = {
        ["english"] = { [1] = "All of the Horde's war effort tasks are completed, young $c. Now we need but wait for the Alliance to also finish theirs and all will be ready for the Ahn'Qiraj War. Except perhaps for the gathering and reunification of the pieces to the Scepter of the Shifting Sands?" },
        ["text"] = "Усі завдання Орди з підготовки до війни завершено, юний $c. Тепер лишилося дочекатися, доки Альянс завершить свої, і все буде готове до війни за Ан'Кіраж. Хіба що ще треба зібрати й возз'єднати частини Скіпетра Мінливих Пісків?",
        ["npcs"] = { [1] = 15535 },
        ["roles"] = { ["greeting"] = true },
    },
    [2053904107] = {
        ["english"] = { [1] = "All of the fish and everything else is on its way to Silithus, and should be there in less than $2113w days. After that someone's going to have to ring that gong with the Scepter of the Shifting Sands to start the war." },
        ["text"] = "Уся риба та решта припасів уже прямують до Силітуса й мають прибути менш ніж за $2113w днів. Після цього хтось муситиме вдарити Скіпетром Мінливих Пісків у гонг, щоб розпочати війну.",
        ["npcs"] = { [1] = 15455 },
        ["roles"] = { ["greeting"] = true },
    },
    [2219522806] = {
        ["english"] = { [1] = "All of the collecting is done and the finished goods are being shipped over to Silithus as they're being completed. Looks like less than a day until all of it is over there. After that we just need to get someone to ring that gong and open the gates to Ahn'Qiraj. Then the real fun begins." },
        ["text"] = "Усі збори завершено, а готові припаси відправляють до Силітуса одразу після підготовки. Схоже, менш ніж за день усе буде там. Потім треба лише знайти когось, хто вдарить у гонг і відкриє брами Ан'Кіражу. Ось тоді почнеться справжня забава.",
        ["npcs"] = { [1] = 15515 },
        ["roles"] = { ["greeting"] = true },
    },
    [4250208902] = {
        ["english"] = { [1] = "Based on the sample of the toxin you provided for us, we think you will need the following: an arcane quickener, six osseous agitators, and four pieces of runecloth.  With the vitreous focuser in tow, acquire the agitators from skeletal undead here in the Plaguelands!$B$BOnce you have these items, you should be able to load the counter agent into that cauldron." },
        ["text"] = "За зразком токсину, який ти нам надав, ми вважаємо, що тобі знадобляться: арканічний прискорювач, шість кісткових збурювачів і чотири шматки рунічної тканини. Візьми склоподібний фокусатор і добудь збурювачі зі скелетної невмерлі тут, у Чумнозем'ї!$B$BКоли матимеш ці предмети, зможеш завантажити протиотруту в той котел.",
        ["npcs"] = { [1] = 11056, [2] = 11057 },
        ["roles"] = { ["greeting"] = true },
    },
    [161892154] = {
        ["english"] = { [1] = "All of Illidan's lieutenants have fallen, $N.  The way forward is open, if you're ready." },
        ["text"] = "Усі лейтенанти Іллідана полягли, $N. Шлях уперед відкритий, якщо ти готовий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2261101872] = {
        ["english"] = { [1] = "All of a sudden you're a 'Defender of the Alliance' are you?! Well, I suppose you'll be wanting to head to the Champions' Hall now. It's over in Old Town, but they won't let you in unless you're an officer, so you might just have to settle for talking to Officer Areyn outside. Move along now." },
        ["text"] = "То ти раптом «Захисник Альянсу»?! Ну, гадаю, тепер захочеш до Зали Чемпіонів. Вона в Старому місті, але всередину пускають лише офіцерів, тож доведеться задовольнитися розмовою з офіцером Арейн біля входу. А тепер рушай.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3975323690] = {
        ["english"] = { [1] = "Ah, I believe Gimble Thistlefuzz is who ye'll be needing if yer looking to learn the Enchanter's profession.  Ye'll find Gimble in his shop, Thistlefuzz Arcanery, right by the Gryphon Master at The Great Forge." },
        ["text"] = "Гадаю, тобі потрібен Ґімбл Будякопух, якщо хочеш опанувати ремесло зачарування. Знайдеш Ґімбла в його крамниці «Арканерія Будякопуха» біля майстра грифонів у Великій Кузні.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1233051477] = {
        ["english"] = { [1] = "Ah friend, I only help hunters and their pets." },
        ["text"] = "Друже, я допомагаю лише мисливцям та їхнім вихованцям.",
        ["npcs"] = { [1] = 543, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090 },
        ["roles"] = { ["greeting"] = true },
    },
    [335400691] = {
        ["english"] = { [1] = "Be gone, mortal! Your kind is unwelcome here..." },
        ["text"] = "Геть, смертний! Таким, як ти, тут не раді...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [292755914] = {
        ["english"] = { [1] = "Do not try to force your will upon the leather. Rather, let its natural tendencies dictate what form and function it will take. This is not a battle to be won. Work with the leather, not against it." },
        ["text"] = "Не намагайся нав'язати шкірі свою волю. Нехай її природні властивості самі підкажуть форму й призначення. Це не битва, яку треба виграти. Працюй разом зі шкірою, а не проти неї.",
        ["npcs"] = { [1] = 4212 },
        ["roles"] = { ["greeting"] = true },
    },
    [1255322190] = {
        ["english"] = { [1] = "Are you here to celebrate Pilgrim's Bounty with us?" },
        ["text"] = "Ти тут, щоб святкувати з нами Щедроти Пілігрима?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [613583038] = {
        ["english"] = { [1] = "$R! Yes, you! Why do you waste time dawdling in this wreck of a city when your rightful place is in Arathi Basin? The League of Arathor is ruthless in its assault; your contribution is needed, and you will be rewarded!" },
        ["text"] = "$R! Так, ти! Чого ти марнуєш час у цих руїнах міста, коли твоє місце — в Низині Араті? Ліга Аратора веде нещадний наступ; нам потрібна твоя допомога, і вона буде винагороджена!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2886155243] = {
        ["english"] = { [1] = "All has been gathered and is being sent to Silithus, $c. The last of it should get there within a day. I can only hope that after the gong is rung, and the gates opened, that our efforts here will make an impact and save many lives." },
        ["text"] = "Усе зібрано й відправляється до Силітуса, $c. Останнє має прибути менш ніж за день. Можу лише сподіватися, що коли вдарять у гонг і відкриють брами, наші зусилля справді щось змінять і врятують багато життів.",
        ["npcs"] = { [1] = 15528 },
        ["roles"] = { ["greeting"] = true },
    },
    [1712339259] = {
        ["english"] = { [1] = "<High Inquisitor Fairbanks shakes his head.>$B$BNo, $r; only one of his sons is dead. The other lives...$B$B<High Inquisitor Fairbanks points to the sky.>$B$BThe Outland... Find him there... " },
        ["text"] = "<Верховний інквізитор Феєрбенкс хитає головою.>$B$BНі, $r; загинув лише один із його синів. Інший живий...$B$B<Верховний інквізитор Феєрбенкс вказує на небо.>$B$BПозамежжя... Шукай його там... ",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["greeting"] = true },
    },
    [3089796484] = {
        ["english"] = { [1] = "Be on your guard. We are Theramore's first line of defense against its many enemies in the marsh." },
        ["text"] = "Будь напоготові. Ми — перша лінія оборони Терамора від численних ворогів у трясовині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [730817778] = {
        ["english"] = { [1] = "A mess, that's what this is!  All of these creatures sprung up out of nowhere, and are running around out of control!  And where've the Magister, and his apprentices, run off to?  Leaving me here all alone without as much as a, \"Hello there Wyllithen, would you like to come with?\"$B$BThe nerve!" },
        ["text"] = "Безлад — ось що це таке! Усі ці створіння виникли нізвідки й носяться тут без жодного контролю! І куди поділися магістр та його учні? Залишили мене самісінького, навіть не сказавши: \"Привіт, Віллітене, хочеш із нами?\"$B$BЯке нахабство!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3255672867] = {
        ["english"] = { [1] = "A closer inspection of the pylon leads you to find a small table containing blue, yellow, and green crystals arranged in what seems like a specific formation.$B$BA large blue circle of crystals is flanked on either side by a smaller circle of yellow crystals and another of green crystals.$B$BYou carefully take note of the colors of the crystals, knowing that J.D. would be very interested in hearing about what you have found." },
        ["text"] = "Уважніше оглянувши пілон, ви знаходите невеликий столик із синіми, жовтими й зеленими кристалами, викладеними в певному порядку.$B$BВелике синє коло кристалів з обох боків оточене меншими колами жовтих і зелених кристалів.$B$BВи ретельно запам'ятовуєте кольори кристалів, знаючи, що Дж. Д. дуже зацікавиться вашою знахідкою.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2096752996] = {
        ["english"] = { [1] = "Dark times make for strange friendships. It may be worth visiting old Lordaeron to watch the Forsaken burn their little man of wicker." },
        ["text"] = "Темні часи породжують дивні дружби. Можливо, варто навідатися до старого Лордерону й подивитися, як Відречені спалюють свого маленького плетеного чоловічка.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1925025819] = {
        ["english"] = { [1] = "Alanna Raveneye attributes part of her talent in enchanting to her communion with the spirits at the Oracle Glade.  You should be able to find her there now." },
        ["text"] = "Аланна Вороняче Око частково приписує свій талант у зачаруванні спілкуванню з духами в Галявині Оракула. Мабуть, і зараз знайдеш її там.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2119837597] = {
        ["english"] = { [1] = "Ahoy, $N! Not a pretty picture, is it?$B$BThe Horizon Scout at the bottom of the sea, my crew in shambles, and our cargo and passengers strewn about like so much debris that you'd think this was one of Stormwind's canals after a festival.$B$BAnd that's not where the trouble ends..." },
        ["text"] = "Йо-хо, $N! Картина невтішна, еге ж?$B$B«Розвідник Обрію» на морському дні, команда розбита, а вантаж і пасажири розкидані довкола, мов сміття в каналах Штормовію після свята.$B$BІ на цьому наші біди не закінчуються...",
        ["npcs"] = { [1] = 8380 },
        ["roles"] = { ["greeting"] = true },
    },
    [1508344882] = {
        ["english"] = { [1] = "Both Ilyenia Moonfire on the Warrior's Terrace of Darnassus and Bixi Wobblebonk of the Timberline Arms in Ironforge can show you how to use throwing weapons properly." },
        ["text"] = "Іленія Місячний Вогонь на Терасі Воїнів у Дарнасі та Біксі Хитрокіст у крамниці «Лісовий край» у Стальгорні можуть навчити тебе правильно користуватися метальною зброєю.",
        ["npcs"] = { [1] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [3802618802] = {
        ["english"] = { [1] = "Ah... another shaman seeks enlightenment, perhaps? Are the spirits speaking unclearly? Do you wish my help in seeing what lies before you?" },
        ["text"] = "А... ще один шаман шукає просвітлення? Духи говорять невиразно? Хочеш, щоб я допоміг побачити, що чекає попереду?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [144374892] = {
        ["english"] = { [1] = "Ah, this Darnassian fabric is the finest!" },
        ["text"] = "Ах, ця дарнаська тканина — найкраща!",
        ["npcs"] = { [1] = 5153 },
        ["roles"] = { ["greeting"] = true },
    },
    [1693924246] = {
        ["english"] = { [1] = "A Thunderbrew ale and a bit of Gremlock's cooking makes for a nice meal indeed.  Ye really should hit him up for some training if ye want to be a cook." },
        ["text"] = "Ель Громовара та трохи куховарства Ґремлока — чудова трапеза. Якщо хочеш стати кухарем, неодмінно попроси його тебе навчити.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2640812024] = {
        ["english"] = { [1] = "Ah, you're looking for Lucan Cordell.  He runs a shop on the outside of the Magic Quarter on your way to the Stockade.  " },
        ["text"] = "А, ти шукаєш Лукана Корделла. Він тримає крамницю на зовнішньому боці Магічного кварталу дорогою до В'язниці.  ",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2051173239] = {
        ["english"] = { [1] = "[PH] I desire an aqual quintessence, Duke Hydraxis." },
        ["text"] = "[PH] Я бажаю водної квінтесенції, герцогу Гідраксіс.",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["reply"] = true },
    },
    [3269164201] = {
        ["english"] = { [1] = "A lot you know...$b$bSome say they're just observing, some think they're altering our sea-life, and then others think they're here to take over Azeroth!$b$bOnce I take one down with my rocket propelled warheads I'll get the answers. You can believe that!" },
        ["text"] = "Та що ти знаєш...$b$bОдні кажуть, що вони просто спостерігають, інші — що змінюють наше морське життя, а ще хтось думає, що вони тут, аби захопити Азерот!$b$bЩойно я зіб'ю одного ракетними боєголовками — отримаю відповіді. Можеш не сумніватися!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2972300855] = {
        ["english"] = { [1] = "Ah - oddities and rarities. We specialize in Azeroth's more unique items for the discerning adventurer.$B$BSince you're speaking with me, you must already have an idea of what you're looking for. So, $N, which item are you interested in?" },
        ["text"] = "А, дивовижі й рідкісні речі. Ми спеціалізуємося на найнезвичайніших товарах Азероту для вибагливих шукачів пригод.$B$BЯкщо вже говориш зі мною, певно, знаєш, що шукаєш. То який предмет тебе цікавить, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1766600852] = {
        ["english"] = { [1] = "A pack of harpies came up from the valley. A big one named Sirana led them... I didn't have anywhere to escape. They haven't been this aggressive for a long time... I didn't expect it... I let my guard down.... it's my own fault." },
        ["text"] = "З долини налетіла зграя гарпій. Їх очолювала велика на ім'я Сірана... Мені не було куди тікати. Вони давно не були такими агресивними... Я не очікував... втратив пильність... сам винен.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [8845813] = {
        ["english"] = { [1] = "Check the bulletin board if you're looking for work, $r." },
        ["text"] = "Якщо шукаєш роботу, перевір дошку оголошень, $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [27973868] = {
        ["english"] = { [1] = "As you can see, I am but one man with a lumbering oaf of a squire. The might of the Dark Iron dwarves and the beasts held in the grip of Ragnaros would surely overwhelm me alone, but I have the utmost confidence that such a brave and ambitious adventurer such as you would have no problem handling the denizens of the cauldron. Should you choose to assist me, I shall reward you with riches and wealth beyond your wildest dreams." },
        ["text"] = "Як бачиш, я лише один чоловік із вайлуватим дурнем-зброєносцем. Сили дворфів Темного Заліза й звірі, підкорені Раґнаросом, напевно здолали б мене самого, але я цілком певен, що такий хоробрий і честолюбний шукач пригод, як ти, без проблем упорається з мешканцями котла. Якщо вирішиш допомогти, я винагороджу тебе багатствами, що перевершують найсміливіші мрії.",
        ["npcs"] = { [1] = 8479 },
        ["roles"] = { ["greeting"] = true },
    },
    [585198900] = {
        ["english"] = { [1] = "Come and I will show you how to ride the finest beasts you have ever seen. You... do have enough gold to cover the cost, I trust?" },
        ["text"] = "Підійди, і я покажу тобі, як їздити верхи на найкращих звірах, яких ти коли-небудь бачив. У тебе ж... вистачить золота на оплату, сподіваюся?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2570035777] = {
        ["english"] = { [1] = "Brek Stonehoof can be found at Stonehoof Geology on the lower rise and can teach you the proper way to harvest precious ores and gems." },
        ["text"] = "Брек Кам'яне Копито працює в «Геології Кам'яного Копита» на нижньому ярусі й навчить тебе правильно добувати дорогоцінні руди та самоцвіти.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [1258187636] = {
        ["english"] = { [1] = "A Ruby Drake at full power can perform Martyr, which shields friendly targets by redirecting all hostile magic to the Ruby Drake for a short time.  Evasive Maneuvers can still be performed during Martyr." },
        ["text"] = "Рубіновий дракон на повній силі може застосувати «Мучеництво», яке захищає дружні цілі, на короткий час перенаправляючи всю ворожу магію на Рубінового дракона. Під час «Мучеництва» все ще можна виконувати «Маневри ухилення».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4006658208] = {
        ["english"] = { [1] = "And modest too... Perhaps it is your time, then, $N.$B$BAre you prepared to enter the fortress of the Blackrock orcs? To wreak havoc? To tear asunder the foundation of the mountain citadel?" },
        ["text"] = "І ще й скромний... Можливо, твій час настав, $N.$B$BТи готовий увійти до фортеці орків Чорного Каменю? Посіяти хаос? Розірвати самі основи гірської цитаделі?",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["greeting"] = true },
    },
    [2822339293] = {
        ["english"] = { [1] = "<Greatmother Geyah smiles.>$B$BI am old. It is my time. When I pass, my spirit will move on to the spirit realm. It is there that I will stand with my ancestors. It is there that we will watch over our people.$B$BWhen Garad was alive Mother Kashur's duty was the same as my duty now." },
        ["text"] = "<Прабабуся Ґея усміхається.>$B$BЯ стара. Мій час настав. Коли я піду, мій дух перейде до царства духів. Там я стану поруч зі своїми предками. Там ми наглядатимемо за нашим народом.$B$BКоли Ґарад був живий, обов'язок Матері Кашур був таким самим, як мій нині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3995712110] = {
        ["english"] = { [1] = "<Chu'a'lor's left head says,>$B$BWe find your zeal to help us most appealing...$B$B<His right head concludes,>$B$B... and we want you to know that we greatly appreciate your efforts!" },
        ["text"] = "<Ліва голова Чу'алора каже:>$B$BНам дуже до вподоби твоє завзяття допомогти...$B$B<Права голова завершує:>$B$B...і ми хочемо, щоб ти знав: ми надзвичайно цінуємо твої зусилля!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [360222792] = {
        ["english"] = { [1] = "A mailbox?  You have a letter to send, or perhaps have received one?  I hope it's something good!  There's a mailbox right outside of the Bank in the center of Darnassus." },
        ["text"] = "Поштова скринька? Хочеш надіслати листа чи, може, отримав якогось? Сподіваюся, добрі новини! Скринька стоїть просто біля банку в центрі Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3281947621] = {
        ["english"] = { [1] = "And why would I speak with you, $r?" },
        ["text"] = "І чому я маю говорити з тобою, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1650958262] = {
        ["english"] = { [1] = "A thousand years ago, when the War of the Shifting Sands ended, three of our kin sacrificed themselves and held the Qiraji inside these halls while Anachronos and Staghelm sealed Ahn'Qiraj shut.$B$BEach of us vowed to look for Merithra, Arygos and Caelestrasz should the Scarab Wall ever fall.$B$BAnd fall it did... and so we came." },
        ["text"] = "Тисячу років тому, коли завершилася Війна Мінливих Пісків, троє наших родичів пожертвували собою й утримували кіражів у цих залах, доки Анахронос і Оленеріг запечатували Ан'Кіраж.$B$BКожен із нас присягнув розшукати Мерітру, Аріґоса й Келестраза, якщо Стіна Скарабея колись упаде.$B$BІ вона впала... тому ми прийшли.",
        ["npcs"] = { [1] = 15503 },
        ["roles"] = { ["greeting"] = true },
    },
    [1039073983] = {
        ["english"] = { [1] = "A profession trainer" },
        ["text"] = "Наставник професії",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953 },
        ["roles"] = { ["reply"] = true },
    },
    [3639412795] = {
        ["english"] = { [1] = "Ah, I suppose that I am getting ahead of myself. Ras Frostwhisper is the overseer of this school. The being responsible for training all of its Dark Masters. A lieutenant and favored pupil of Kel'Thuzad. He was once a hedge mage of Stromgarde: A rogue wizard that never received his formal training from Dalaran.$B$BWhen Kel'Thuzad opened the Cult, Ras was among the first to join his ranks. Ras knew that through dark magic, he would find immortality." },
        ["text"] = "А, здається, я забіг наперед. Рас Крижешепіт — наглядач цієї школи. Саме він навчає всіх її Темних магістрів. Лейтенант і улюблений учень Кел'Тузада. Колись він був сільським магом зі Стромґарда — чаклуном-відступником, який так і не пройшов формального навчання в Даларані.$B$BКоли Кел'Тузад заснував Культ, Рас одним із перших приєднався до нього. Рас знав, що завдяки темній магії знайде безсмертя.",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [1600015495] = {
        ["english"] = { [1] = "Ah, gentle Seriadne.  All animals are safe while in her care.  You can find her just outside the Inn in Dolanaar." },
        ["text"] = "А, лагідна Серіадна. Під її опікою всі тварини в безпеці. Знайдеш її просто біля таверни в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [1647802018] = {
        ["english"] = { [1] = "Ah, a good question.$B$BIf you prefer hunting in the great outdoors, there are elementals here in the Plaguelands, Azshara, Burning Steppes, Felwood, Silithus, Winterspring, and even Un'Goro Crater.$B$BIf you are the type that laughs in the face of danger, then perhaps you should visit Dire Maul. I have heard that a great many elemental abberations exist within its walls. You would also do well in seeking out the elementals employed by the Dark Iron dwarves of Blackrock Depths." },
        ["text"] = "А, гарне запитання.$B$BЯкщо любиш полювати просто неба, елементалів знайдеш тут, у Чумнозем'ї, а також в Азшарі, Палаючому степу, Скверноліссі, Силітусі, Зимоключі й навіть у Кратері Ун'Ґоро.$B$BЯкщо ти з тих, хто сміється небезпеці в обличчя, навідайся до Страхомістя. Я чув, у його стінах повно дивних елементальних створінь. Також не завадить пошукати елементалів на службі в дворфів Темного Заліза у Глибинах Чорнокамінної гори.",
        ["npcs"] = { [1] = 16116 },
        ["roles"] = { ["greeting"] = true },
    },
    [2375780365] = {
        ["english"] = { [1] = "$C, back on Azeroth, the Silverwing Sentinels hamper our progress in the woods. We need you there on the battlefront to push them back! You will earn great honor and reputation with the Warsong Outriders for helping us - join us now!" },
        ["text"] = "$C, на Азероті Вартові Срібнокрилих стримують наше просування в лісах. Ти потрібен нам на передовій, щоб відкинути їх! Допомагаючи нам, ти здобудеш велику честь і репутацію серед Вершників Пісні Війни — приєднуйся до нас!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2920860341] = {
        ["english"] = { [1] = "A fine display of worthiness. Your instruction may now continue." },
        ["text"] = "Гідний показ. Твоє навчання може продовжуватися.",
        ["npcs"] = { [1] = 5567 },
        ["roles"] = { ["greeting"] = true },
    },
    [1906842977] = {
        ["english"] = { [1] = "Ah am very surprised that one wit such a careless nature has gotten dis far...$B$BYah, you may have another charm, but Mau'ari is very displeased wit your actions!$B$BGo, now. " },
        ["text"] = "Я дуже дивований, шо хтось такий необережний зайшов аж так далеко...$B$BГаразд, можеш узяти ще один оберіг, але Мау'арі дуже незадоволена твоїми вчинками!$B$BІди вже. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [622423974] = {
        ["english"] = { [1] = "Ah a visitor! Must be an adventurer, we don't get many tourists down this way. Grab a chair and a drink, make yourself comfortable. Say, you look like you have some meat on your bones. You thinkin about competing in the cage matches?" },
        ["text"] = "О, відвідувач! Напевно, шукач пригод — туристи сюди майже не заходять. Бери стілець, напій і влаштовуйся зручніше. Гм, бачу, м'яса на кістках у тебе вистачає. Не думаєш позмагатися в боях у клітці?",
        ["npcs"] = { [1] = 7733 },
        ["roles"] = { ["greeting"] = true },
    },
    [2050758947] = {
        ["english"] = { [1] = "A time consuming, yet rewarding skill.  Speak with Astaia in the Tradesman's Terrace and maybe you'll learn something useful." },
        ["text"] = "Навичка потребує часу, але щедро винагороджує. Поговори з Астайєю на Терасі Ремісників — може, навчишся чогось корисного.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [597826115] = {
        ["english"] = { [1] = "Ah - oddities and rarities. We specialize in Azeroth's more unique items for the discerning adventurer.$B$BSince you're speaking with me, you must already have an idea of what you're looking for." },
        ["text"] = "А, дивовижі й рідкісні речі. Ми спеціалізуємося на найнезвичайніших товарах Азероту для вибагливих шукачів пригод.$B$BЯкщо вже говориш зі мною, певно, знаєш, що шукаєш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [995705441] = {
        ["english"] = { [1] = "Agreed. Budd's scraped together rif-raf from all over creation.$b$bSeems when there's free booze to be had, there be plenty of folk willin' to set aside their differences." },
        ["text"] = "Згоден. Бадд назбирав усілякого наброду з усього світу.$b$bСхоже, коли випивка безкоштовна, охочих відкласти розбіжності завжди вистачає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3532846212] = {
        ["english"] = { [1] = "After the Plaguelands and the Battle for Light's Hope Chapel, I didn't think that we would witness anything more horrible.$B$BI was wrong." },
        ["text"] = "Після Чумнозем'я й битви за каплицю Надії Світла я думав, що нічого жахливішого вже не побачимо.$B$BЯ помилявся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1036662120] = {
        ["english"] = { [1] = "An Alchemy trainer is what you need?  Well, I just came from there, I did.  Ye'll find Ms. Berryfizz over in Tinker Town where the gnomes gather." },
        ["text"] = "Тобі потрібен наставник алхімії? Я саме звідти. Пані Берріфіз знайдеш у Штукарівці, де збираються гноми.",
        ["npcs"] = { [1] = 5595 },
        ["roles"] = { ["greeting"] = true },
    },
    [1500853023] = {
        ["english"] = { [1] = "After countless failures of our agents to secure workable samples of Scourge blight for analysis, I've come up to the front lines myself to oversee the efforts. Like they say, if you want a job done right...." },
        ["text"] = "Після незліченних невдач наших агентів, які намагалися здобути придатні для аналізу зразки пошесті Скверни, я сам прибув на передову, щоб керувати роботою. Як кажуть, хочеш зробити добре...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1284940130] = {
        ["english"] = { [1] = "Can Zamja help you, $r?" },
        ["text"] = "Замджа може тобі допомогти, $r?",
        ["npcs"] = { [1] = 3399 },
        ["roles"] = { ["greeting"] = true },
    },
    [2498677458] = {
        ["english"] = { [1] = "A-ten-hut! All Ahn'Qiraj war materiel accounted for and in the process of being transported to Cenarion Hold $g sir : ma'am;! I am told that the last of it should arrive in less than a day. Once that is done, and someone rings that gong over there to open the gates, I guarantee that we'll give those bugs one heck of a fight!" },
        ["text"] = "Струнко! Усі воєнні припаси для Ан'Кіражу обліковано й перевозять до Кенарієвої цитаделі, $g пане : пані;! Кажуть, остання партія прибуде менш ніж за день. Коли це станеться й хтось ударить у той гонг, щоб відкрити брами, гарантую — ми дамо тим жукам добрячого прочухана!",
        ["npcs"] = { [1] = 15448 },
        ["roles"] = { ["greeting"] = true },
    },
    [2996694] = {
        ["english"] = { [1] = "About time you showed me some results! Now I'll show you results!" },
        ["text"] = "Нарешті ти показав якісь результати! А тепер я покажу свої!",
        ["npcs"] = { [1] = 2627, [2] = 3363 },
        ["roles"] = { ["greeting"] = true },
    },
    [3119499332] = {
        ["english"] = { [1] = "<hic>Lissen here, $r. Spend a day or two wrestlin' with wild trolls and then tell me how you smell!" },
        ["text"] = "<гик> Слухай сюди, $r. Проведи день-другий, борюкаючись із дикими тролями, а тоді розкажеш мені, як від тебе пахне!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [647698089] = {
        ["english"] = { [1] = "A mortal possessed of arcane and dark knowledge that none could surpass, he devised a method to enhance his summoning through the capture and use of souls untold.$B$BWhole civilizations were brought to extinction through his soul devices to fuel the ritual through which he and his conspirators would bring Murmur into their world." },
        ["text"] = "Смертний, що володів неперевершеними арканічними й темними знаннями, винайшов спосіб посилити свої виклики, полонячи й використовуючи незліченні душі.$B$BЦілі цивілізації винищувалися його пристроями для душ, щоб живити ритуал, за допомогою якого він і його спільники мали привести Мурмура у свій світ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3294238565] = {
        ["english"] = { [1] = "A-ten-hut! All Ahn'Qiraj war materiel accounted for and in the process of being transported to Cenarion Hold $g sir : ma'am;! I am told that the last of it should arrive in less than $2113w days. Once that is done, and someone rings that gong over there to open the gates, I guarantee that we'll give those bugs one heck of a fight!" },
        ["text"] = "Струнко! Усі воєнні припаси для Ан'Кіражу обліковано й перевозять до Кенарієвої цитаделі, $g пане : пані;! Кажуть, остання партія прибуде менш ніж за $2113w днів. Коли це станеться й хтось ударить у той гонг, щоб відкрити брами, гарантую — ми дамо тим жукам добрячого прочухана!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1991799377] = {
        ["english"] = { [1] = "A thunderous voice bellows from the stone...$B$BWhat is this?  I sense a little cultist scurrying about!  Run along, vermin, or face the wrath of the lords of the Council!" },
        ["text"] = "Із каменя гримить громовий голос...$B$BЩо це? Я відчуваю маленького культиста, що шастає поблизу! Геть звідси, паразите, або пізнаєш гнів Володарів Ради!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4203662394] = {
        ["english"] = { [1] = "A whisper may be heart from within the stone...$B$BGreetings, little one.  Do you have news for the Templar?" },
        ["text"] = "Зсередини каменя долинає шепіт...$B$BВітаю, малий. Маєш новини для храмовника?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [413825250] = {
        ["english"] = { [1] = "A thousand? For one man?" },
        ["text"] = "Тисяча? Заради одного чоловіка?",
        ["npcs"] = { [1] = 4542 },
        ["roles"] = { ["reply"] = true },
    },
    [2355086469] = {
        ["english"] = { [1] = "A thousand curses upon you, $r!  This prison will not hold me for long!" },
        ["text"] = "Тисяча проклять на тебе, $r! Ця в'язниця недовго мене триматиме!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1427655801] = {
        ["english"] = { [1] = "Be gone, infidel!  May the power of the Abyss smite you down!" },
        ["text"] = "Геть, невірний! Нехай сила Безодні зітре тебе!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2217113301] = {
        ["english"] = { [1] = "A tailor, eh? Very well. What would you like to learn about, tailor?$B$B" },
        ["text"] = "Кравець, еге ж? Гаразд. Про що ти хочеш дізнатися, кравцю?$B$B",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["greeting"] = true },
    },
    [2417582213] = {
        ["english"] = { [1] = "<The Major nods curtly.>" },
        ["text"] = "<Майор коротко киває.>",
        ["npcs"] = { [1] = 2439 },
        ["roles"] = { ["greeting"] = true },
    },
    [1415410158] = {
        ["english"] = { [1] = "A strong weapon is no good if you don't live long enough to wield it, $c." },
        ["text"] = "Сильна зброя нічого не варта, якщо ти не проживеш достатньо довго, щоб нею скористатися, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1393050784] = {
        ["english"] = { [1] = "Are you the Earthshaper capable of creating Elementium?" },
        ["text"] = "Ти той Землеформувач, що вміє створювати елементій?",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["reply"] = true },
    },
    [515777135] = {
        ["english"] = { [1] = "Damn those blood elves and their reckless magic!" },
        ["text"] = "Прокляті ельфи крові та їхня безрозсудна магія!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3912844029] = {
        ["english"] = { [1] = "(Continue.)" },
        ["text"] = "(Продовжити.)",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["reply"] = true },
    },
    [2537642521] = {
        ["english"] = { [1] = "At last! Someone to free me from this cell!$b$bHigh Executor Hadrec sent us to gather information on the Keep so that a plan could be formulated to overthrow Arugal once and for all.$b$bBut the old wizard has many tricks up his sleeve and we were detected by a magical ward. I was thrown in this prison. Vincent was not so lucky.$b$bI must return to Hadrec to debrief him at once. But first I will pick the lock to the courtyard door for you. Perhaps you can try your luck against the foes that lurk beyond." },
        ["text"] = "Нарешті! Хтось прийшов звільнити мене з цієї камери!$b$bВерховний виконавець Гадрек прислав нас зібрати відомості про фортецю, щоб скласти план остаточного повалення Аруґала.$b$bТа старий чарівник має багато трюків, і магічний оберіг нас викрив. Мене кинули до цієї в'язниці. Вінсенту пощастило менше.$b$bЯ мушу негайно повернутися до Гадрека й доповісти. Але спершу відімкну для тебе двері у двір. Можеш випробувати долю проти ворогів, що ховаються далі.",
        ["npcs"] = { [1] = 3849 },
        ["roles"] = { ["greeting"] = true },
    },
    [4089375980] = {
        ["english"] = { [1] = "Ah, Noblegarden. So amusing to watch others throw away their dignity in favor of hunting colored eggs. Still, they do have a curious magical aura to them..." },
        ["text"] = "А, Сад Чудес. Так кумедно дивитися, як інші відкидають гідність заради полювання на розфарбовані яйця. І все ж від них іде дивна магічна аура...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3689051529] = {
        ["english"] = { [1] = "Ah, Zaetar... <Celebras looks away.>$B$BMy father, Remulos, tried to stop him...$B$BZaetar was headstrong, and when he fell for an earthen elemental princess, my father knew that their union was cursed, but Zaetar refused to listen.$B$BThe centaur are the result of his mistake. They were born misshapen and hateful; my uncle Zaetar was killed by his own kin...$B$BThe evil princess, Theradras, still guards his remains here in the crystal caverns." },
        ["text"] = "Ах, Заетар... <Келебрас відводить погляд.>$B$BМій батько, Ремулос, намагався його зупинити...$B$BЗаетар був упертим, і коли він закохався в принцесу-елементаля землі, мій батько зрозумів, що їхній союз проклятий, але Заетар не слухав.$B$BКентаври — наслідок його помилки. Вони народилися потворними й сповненими ненависті; мого дядька Заетара вбили власні нащадки...$B$BЗла принцеса Терадрас досі стереже його останки тут, у кришталевих печерах.",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["greeting"] = true },
    },
    [53250192] = {
        ["english"] = { [1] = "A minnow? The oceans are filled with minnows! There could be a hundred million minnows out there!" },
        ["text"] = "Мальок? Та океани повні мальків! Їх там може бути сто мільйонів!",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [4288715717] = {
        ["english"] = { [1] = "$R, report! What news of significance do you bring? Be quick about your business... Dame Auriferous and I are in the middle of a strategic discussion." },
        ["text"] = "$R, доповідай! Які важливі новини ти приніс? Швидше до справи... пані Авріферус і я саме обговорюємо стратегію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3990397665] = {
        ["english"] = { [1] = "All barriers are now down, $N! Only Sindragosa stands between the Lich King and us. Justice comes soon..." },
        ["text"] = "Усі бар'єри впали, $N! Між нами й Королем-лічем залишилася лише Сіндраґоса. Справедливість уже близько...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [741695440] = {
        ["english"] = { [1] = "Away with you, $c!$B$BOnly champions of Undercity may purchase what I have to offer." },
        ["text"] = "Геть звідси, $c!$B$BЛише чемпіони Підміста можуть купувати мої товари.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [203888529] = {
        ["english"] = { [1] = "A mage... you seek to learn the magic of portals, yes?" },
        ["text"] = "Маг... ти хочеш опанувати магію порталів, так?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2425105902] = {
        ["english"] = { [1] = "A good brew, is a strong brew." },
        ["text"] = "Добрий напій — це міцний напій.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3393862840] = {
        ["english"] = { [1] = "A staple of the Thorium Brotherhood.$B$BArcanite crystals are harvested from rich thorium lodes. Through the alchemical prowess of powerful alchemists, arcanite bars are born.$B$BSeek out a miner, if you aren't one... and find a good alchemist! You'll need both." },
        ["text"] = "Основний матеріал Торієвого Братства.$B$BКристали арканіту добувають із багатих торієвих жил. Завдяки алхімічній майстерності могутніх алхіміків із них створюють арканітові зливки.$B$BЗнайди шахтаря, якщо сам ним не є... і хорошого алхіміка! Потрібні обидва.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [338908631] = {
        ["english"] = { [1] = "Around this reindeer's neck is a tag with the Smokywood Pastures logo on it and a name - \"Metzen\".$B$BMetzen looks at you with sad, forlorn eyes.  It is almost as if the reindeer has been immobilized by some unseen force." },
        ["text"] = "На шиї цього північного оленя висить бирка з логотипом Димного Лісу й ім'ям — «Метцен».$B$BМетцен дивиться на вас сумними, покинутими очима. Наче якась невидима сила скувала його на місці.",
        ["npcs"] = { [1] = 15664 },
        ["roles"] = { ["greeting"] = true },
    },
    [1475775693] = {
        ["english"] = { [1] = "Brash. Master Ravenholdt does not like brash." },
        ["text"] = "Зухвало. Майстер Крукгольд не любить зухвалості.",
        ["npcs"] = { [1] = 6766 },
        ["roles"] = { ["greeting"] = true },
    },
    [1165615114] = {
        ["english"] = { [1] = "A class trainer" },
        ["text"] = "Наставник класу",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 3084, [13] = 3212, [14] = 3215, [15] = 3217, [16] = 3218, [17] = 3219, [18] = 3220, [19] = 3221, [20] = 3222, [21] = 3223, [22] = 3224, [23] = 3296, [24] = 5624, [25] = 5725, [26] = 5953 },
        ["roles"] = { ["reply"] = true },
    },
    [436336014] = {
        ["english"] = { [1] = "A Bountiful Table is laid out with five Pilgrim's Bounty foods, one in front of each chair.$B$BWhile in a chair, you may eat as much of that food as you like, as well as pass servings of that food to the other chairs. Feast and share with friends!$B$BIf you eat enough of any one food, you'll gain benefits unique to that food.$B$BIn addition, if you eat enough of every food, you'll gain the Spirit of Sharing!" },
        ["text"] = "Щедрий стіл заставлено п'ятьма стравами Щедрот Пілігрима — по одній перед кожним стільцем.$B$BСидячи на стільці, ви можете їсти скільки завгодно цієї страви, а також передавати порції іншим гостям. Бенкетуйте й діліться з друзями!$B$BЯкщо з'їсти достатньо якоїсь однієї страви, ви отримаєте властиву лише їй перевагу.$B$BА якщо наїстися досхочу кожною зі страв, ви отримаєте Дух щедрості!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2770739223] = {
        ["english"] = { [1] = "'Talon King' Ikiss is one of the leaders of the Sethekk, along with my brother, Darkweaver Syth.$B$BIt was they who led the exodus of the Sethekk from Skettis to the ruins of Auchindoun. In the beginning, Ikiss was a charismatic leader, but he has descended into madness.$B$BNow, he openly proclaims that he is Terokk reborn! He truly expects the arakkoa to bend knee to him as their ruler. Can you believe his arrogance?" },
        ["text"] = "\"Король Кігтів\" Ікісс — один із ватажків сетекків разом із моїм братом, Темноткачем Ситом.$B$BСаме вони очолили вихід сетекків зі Скеттіса до руїн Акіндуна. Спершу Ікісс був харизматичним лідером, але згодом збожеволів.$B$BТепер він відкрито проголошує себе відродженим Терокком! Він справді чекає, що араккоа схилять перед ним коліна й визнають своїм правителем. Можеш повірити в таку пиху?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2832920233] = {
        ["english"] = { [1] = "At last, I am free of the corruption that once bound me to this place..." },
        ["text"] = "Нарешті я вільний від скверни, що колись прив'язувала мене до цього місця...",
        ["npcs"] = { [1] = 13716 },
        ["roles"] = { ["greeting"] = true },
    },
    [1609451108] = {
        ["english"] = { [1] = "Ah, so that is how they pushed the Dark Iron to the lower parts of the Spire." },
        ["text"] = "А, ось як вони відтіснили Темне Залізо до нижніх частин Шпиля.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [1547440941] = {
        ["english"] = { [1] = "All is completed, young $c. Even as we speak, both the Horde and the Alliance are in the process of transporting all final goods for the war into Silithus near Cenarion Hold, which should be complete in less than a day. After that, the gong near the gates of Ahn'Qiraj can be rung, and the war will begin." },
        ["text"] = "Усе завершено, юний $c. Просто зараз і Орда, і Альянс перевозять останні припаси для війни до Силітуса, поблизу Кенарієвої цитаделі; це має завершитися менш ніж за день. Після цього можна буде вдарити в гонг біля брам Ан'Кіражу, і війна почнеться.",
        ["npcs"] = { [1] = 15437 },
        ["roles"] = { ["greeting"] = true },
    },
    [1474969576] = {
        ["english"] = { [1] = "$N!  I remember your hunting prowess all too well.  You might have gotten off to a shaky start in Stranglethorn, but you stuck in there and became one o' the finest when you bagged old Bangalash.$B$BBut listen, $g lad : lass;, the prey out here in the Outland is the real deal.  And I've the scars to prove it!" },
        ["text"] = "$N! Я чудово пам'ятаю твою мисливську вправність. У Тернистій долині початок був непевний, але ти не здався й став одним із найкращих, коли вполював старого Бангалаша.$B$BТа слухай, $g хлопче : дівчино;, здобич тут, у Позамежжі, — це вже зовсім інша справа. І мої шрами тому доказ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [393437017] = {
        ["english"] = { [1] = "<Tarsis grabs you weakly by the collar. Even in death you see power unimaginable in his eyes.>$B$BAm I? Then listen closely, for more nonsense is about to escape my lips. Within this citadel you will find my life's work: The exact location of every fragment of the splintered staff." },
        ["text"] = "<Тарсіс слабко хапає вас за комір. Навіть на порозі смерті в його очах видно неймовірну силу.>$B$BСправді? Тоді слухай уважно, бо зараз із моїх уст вилетить іще більше нісенітниць. У цій цитаделі ти знайдеш працю всього мого життя: точне місцезнаходження кожного уламка розтрощеного посоха.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2523079278] = {
        ["english"] = { [1] = "<Take the letter>" },
        ["text"] = "<Взяти листа>",
        ["npcs"] = { [1] = 915, [2] = 916, [3] = 917, [4] = 918, [5] = 1234, [6] = 1411, [7] = 2122, [8] = 2130, [9] = 3155, [10] = 3170, [11] = 3327, [12] = 3328, [13] = 3401, [14] = 3594, [15] = 3599, [16] = 4163, [17] = 4214, [18] = 4215, [19] = 4582, [20] = 4583, [21] = 4584, [22] = 5165, [23] = 5166, [24] = 5167, [25] = 6707, [26] = 13283 },
        ["roles"] = { ["reply"] = true },
    },
    [2074018515] = {
        ["english"] = { [1] = "<sigh>...$b$bA little help here, perhaps?" },
        ["text"] = "<зітхає>...$b$bМоже, хоч трохи допоможете?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2034853388] = {
        ["english"] = { [1] = "Ah, what a beautiful day to blow something up!" },
        ["text"] = "Ах, який чудовий день, щоб щось підірвати!",
        ["npcs"] = { [1] = 11026 },
        ["roles"] = { ["greeting"] = true },
    },
    [2595715185] = {
        ["english"] = { [1] = "Be sure to visit Vixton Pinchwhistle in Netherstorm's Area 52. As the Steamwheedle Fighting Circuit's official Arena Vendor, he has all sorts of incredible items for sale to those with enough Arena Points." },
        ["text"] = "Обов'язково навідайся до Вікстона Щипосвиста в Зоні 52 у Пустокраї. Як офіційний продавець арени Бойового Контуру Хиткої Шестерні, він має безліч неймовірних товарів для тих, хто назбирав достатньо очок арени.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2964201399] = {
        ["english"] = { [1] = "<more>" },
        ["text"] = "<далі>",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["reply"] = true },
    },
    [1158430877] = {
        ["english"] = { [1] = "Another entrepreneur, eh? Well, the Auction House can be found in the Trade District.  Not far from the bank.", [2] = "Another entrepreneur, eh? Well, the Auction House can be found in the Trade District.  Not far from the bank.\010" },
        ["text"] = "Ще один підприємець, еге ж? Аукціонний дім у Торговому районі, неподалік від банку.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3883526216] = {
        ["english"] = { [1] = "$N smash warp-gate good, but da demons make it strong again.$B$B$N bring Gahk another darkrune and Gahk make special crystalforged darkrune for $N!" },
        ["text"] = "$N добре трощить браму викривлення, але демони знову роблять її міцною.$B$B$N принесе Ґаку ще одну темну руну, а Ґак зробить для $N особливу кристалоковану темну руну!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
}
